class TrainingMetricsPlot(QWidget):
    def __init__(self, title="", parent=None, value_range=None):
        super().__init__(parent)
        self.title = title
        self.value_range = value_range
        self.series = []
        self.hidden_series = set()
        self._legend_hit_rects = []
        self._hovered_series = ""
        self.setMinimumHeight(170)
        self.setMouseTracking(True)
        self.setToolTip("Click a legend item to show or hide that metric. Right-click the legend to show all.")
        self.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Expanding)

    def set_series(self, series, title=None, value_range=None):
        self.series = list(series or [])
        available = {str(item[0]) for item in self.series if item}
        self.hidden_series = {name for name in self.hidden_series if name in available}
        if title is not None:
            self.title = str(title)
        if value_range is not None:
            self.value_range = value_range
        self.update()

    def mouseMoveEvent(self, event):
        hovered = ""
        for name, rect in self._legend_hit_rects:
            if rect.contains(event.pos()):
                hovered = name
                break
        if hovered != self._hovered_series:
            self._hovered_series = hovered
            self.setCursor(Qt.PointingHandCursor if hovered else Qt.ArrowCursor)
            self.update()
        super().mouseMoveEvent(event)

    def leaveEvent(self, event):
        if self._hovered_series:
            self._hovered_series = ""
            self.setCursor(Qt.ArrowCursor)
            self.update()
        super().leaveEvent(event)

    def mousePressEvent(self, event):
        for name, rect in self._legend_hit_rects:
            if not rect.contains(event.pos()):
                continue
            if event.button() == Qt.RightButton:
                self.hidden_series.clear()
            elif event.button() == Qt.LeftButton:
                if name in self.hidden_series:
                    self.hidden_series.remove(name)
                else:
                    self.hidden_series.add(name)
            self.update()
            event.accept()
            return
        super().mousePressEvent(event)

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        self._legend_hit_rects = []
        rect = self.rect().adjusted(10, 8, -10, -10)
        painter.fillRect(rect, QColor(13, 17, 22))
        painter.setPen(QPen(QColor(52, 61, 71), 1))
        painter.drawRoundedRect(rect, 6, 6)

        title_rect = QRect(rect.left() + 10, rect.top() + 8, rect.width() - 20, 22)
        painter.setPen(QColor(235, 239, 245))
        painter.setFont(QFont(painter.font().family(), 9, QFont.Bold))
        painter.drawText(title_rect, Qt.AlignLeft | Qt.AlignVCenter, self.title or "Metrics")

        plot_rect = rect.adjusted(44, 38, -14, -42)
        if plot_rect.width() < 20 or plot_rect.height() < 20:
            return

        painter.setPen(QPen(QColor(45, 52, 61), 1))
        for i in range(5):
            y = plot_rect.top() + (plot_rect.height() * i / 4.0)
            painter.drawLine(plot_rect.left(), int(y), plot_rect.right(), int(y))
        painter.drawRect(plot_rect)

        usable_series = []
        all_values = []
        for name, values, color in self.series:
            numeric = []
            for value in values or []:
                try:
                    numeric.append(float(value))
                except Exception:
                    numeric.append(None)
            clean = [value for value in numeric if value is not None and math.isfinite(value)]
            if clean:
                usable_series.append((str(name), numeric, color))
                if str(name) not in self.hidden_series:
                    all_values.extend(clean)

        if not usable_series:
            painter.setPen(QColor(140, 151, 166))
            painter.setFont(QFont(painter.font().family(), 9))
            painter.drawText(plot_rect, Qt.AlignCenter, "No results.csv data yet")
            return

        visible_series = [
            (name, values, color)
            for name, values, color in usable_series
            if name not in self.hidden_series
        ]

        if not visible_series:
            painter.setPen(QColor(140, 151, 166))
            painter.setFont(QFont(painter.font().family(), 9))
            painter.drawText(plot_rect, Qt.AlignCenter, "All metrics hidden. Click legend items to show them.")
            self._draw_metrics_legend(painter, rect, plot_rect, usable_series)
            return

        if self.value_range:
            y_min, y_max = self.value_range
        else:
            y_min, y_max = min(all_values), max(all_values)
            if math.isclose(y_min, y_max):
                y_min -= 1.0
                y_max += 1.0
            padding = (y_max - y_min) * 0.08
            y_min -= padding
            y_max += padding

        if math.isclose(float(y_min), float(y_max)):
            y_max = y_min + 1.0

        painter.setPen(QColor(140, 151, 166))
        painter.setFont(QFont(painter.font().family(), 8))
        painter.drawText(QRect(rect.left() + 8, plot_rect.top() - 6, 34, 18), Qt.AlignRight | Qt.AlignVCenter, f"{y_max:.3g}")
        painter.drawText(QRect(rect.left() + 8, plot_rect.bottom() - 10, 34, 18), Qt.AlignRight | Qt.AlignVCenter, f"{y_min:.3g}")

        def point_at(index, value, count):
            x = plot_rect.left() if count <= 1 else plot_rect.left() + (plot_rect.width() * index / (count - 1))
            ratio = (float(value) - float(y_min)) / max(1e-9, float(y_max) - float(y_min))
            y = plot_rect.bottom() - (plot_rect.height() * max(0.0, min(1.0, ratio)))
            return QPointF(float(x), float(y))

        for name, values, color in visible_series[:8]:
            qcolor = color if isinstance(color, QColor) else QColor(str(color))
            points = [
                point_at(index, value, len(values))
                for index, value in enumerate(values)
                if value is not None and math.isfinite(float(value))
            ]
            if len(points) >= 2:
                path = QPainterPath(points[0])
                for point in points[1:]:
                    path.lineTo(point)
                painter.setPen(QPen(qcolor, 2))
                painter.drawPath(path)
            elif len(points) == 1:
                painter.setPen(QPen(qcolor, 4))
                painter.drawPoint(points[0])

        self._draw_metrics_legend(painter, rect, plot_rect, usable_series)

    def _draw_metrics_legend(self, painter, rect, plot_rect, series):
        legend_x = plot_rect.left()
        legend_y = plot_rect.bottom() + 10
        max_right = rect.right() - 8
        painter.setFont(QFont(painter.font().family(), 8))
        font_metrics = painter.fontMetrics()

        for name, _values, color in list(series or [])[:8]:
            qcolor = color if isinstance(color, QColor) else QColor(str(color))
            hidden = name in self.hidden_series
            hovered = name == self._hovered_series
            text_width = font_metrics.horizontalAdvance(name)
            item_width = max(94, min(190, text_width + 43))
            if legend_x + item_width > max_right and legend_x > plot_rect.left():
                legend_x = plot_rect.left()
                legend_y += 22

            item_rect = QRect(int(legend_x), int(legend_y - 2), int(item_width), 20)
            self._legend_hit_rects.append((name, item_rect))

            bg = QColor(22, 29, 37)
            if hovered:
                bg = QColor(34, 43, 54)
            if hidden:
                bg = QColor(15, 19, 25)
            painter.setPen(QPen(QColor(58, 69, 82), 1))
            painter.setBrush(QBrush(bg))
            painter.drawRoundedRect(item_rect, 4, 4)

            line_color = QColor(qcolor)
            text_color = QColor(216, 222, 230)
            if hidden:
                line_color.setAlpha(95)
                text_color = QColor(120, 130, 143)
            painter.setPen(QPen(line_color, 2))
            painter.drawLine(item_rect.left() + 9, item_rect.center().y(), item_rect.left() + 27, item_rect.center().y())
            painter.setPen(text_color)
            painter.drawText(QRect(item_rect.left() + 33, item_rect.top(), item_rect.width() - 38, item_rect.height()), Qt.AlignLeft | Qt.AlignVCenter, name)
            if hidden:
                painter.setPen(QPen(QColor(120, 130, 143), 1))
                y = item_rect.center().y()
                painter.drawLine(item_rect.left() + 33, y, item_rect.right() - 7, y)

            legend_x += item_width + 8


class TrainingEvaluatorActivityIndicator(QWidget):
    STATE_COLORS = {
        "idle": QColor("#637083"),
        "running": QColor("#42c6ff"),
        "success": QColor("#58d68d"),
        "warning": QColor("#f0d264"),
        "error": QColor("#ff6473"),
    }

    STATE_LABELS = {
        "idle": "Idle",
        "running": "Working",
        "success": "Ready",
        "warning": "Needs attention",
        "error": "Error",
    }

    def __init__(self, parent=None):
        super().__init__(parent)
        self._state = "idle"
        self._label = self.STATE_LABELS["idle"]
        self._detail = ""
        self._pulse = 0.0
        self._timer = QTimer(self)
        self._timer.setInterval(80)
        self._timer.timeout.connect(self._tick)
        self.setMinimumHeight(34)
        self.setMinimumWidth(172)
        self.setSizePolicy(QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)

    def sizeHint(self):
        return QtCore.QSize(190, 34)

    def set_state(self, state="idle", label="", detail=""):
        state = str(state or "idle").lower()
        if state not in self.STATE_COLORS:
            state = "idle"
        self._state = state
        self._label = str(label or self.STATE_LABELS.get(state, "Idle"))
        self._detail = str(detail or "")
        if state == "running":
            if not self._timer.isActive():
                self._timer.start()
        else:
            self._timer.stop()
            self._pulse = 0.0
        self.update()

    def _tick(self):
        self._pulse = (self._pulse + 0.08) % 1.0
        self.update()

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        rect = self.rect().adjusted(1, 1, -1, -1)
        color = QColor(self.STATE_COLORS.get(self._state, self.STATE_COLORS["idle"]))

        bg = QColor(18, 24, 31)
        border = QColor(color)
        border.setAlpha(150 if self._state != "idle" else 90)
        painter.setBrush(QBrush(bg))
        painter.setPen(QPen(border, 1))
        painter.drawRoundedRect(rect, 7, 7)

        center = QPointF(rect.left() + 18, rect.center().y())
        if self._state == "running":
            glow_alpha = int(45 + 70 * (0.5 + 0.5 * math.sin(self._pulse * math.tau)))
            glow = QColor(color)
            glow.setAlpha(glow_alpha)
            painter.setBrush(QBrush(glow))
            painter.setPen(Qt.NoPen)
            painter.drawEllipse(center, 13, 13)

        ring = QColor(color)
        ring.setAlpha(235)
        painter.setBrush(QBrush(QColor(12, 17, 23)))
        painter.setPen(QPen(ring, 2))
        painter.drawEllipse(center, 7, 7)
        painter.setBrush(QBrush(ring))
        painter.setPen(Qt.NoPen)
        painter.drawEllipse(center, 3, 3)

        text_rect = QRect(rect.left() + 35, rect.top() + 2, rect.width() - 42, rect.height() - 4)
        painter.setPen(QColor(235, 239, 245))
        painter.setFont(QFont(painter.font().family(), 8, QFont.Bold))
        painter.drawText(text_rect, Qt.AlignLeft | Qt.AlignVCenter, self._label)


class ZoomableImageView(QGraphicsView):
    def __init__(self, parent=None):
        super().__init__(parent)
        self._scene = QGraphicsScene(self)
        self._pixmap_item = QGraphicsPixmapItem()
        self._scene.addItem(self._pixmap_item)
        self.setScene(self._scene)
        self.setRenderHint(QPainter.Antialiasing)
        self.setRenderHint(QPainter.SmoothPixmapTransform)
        self.setDragMode(QGraphicsView.ScrollHandDrag)
        self.setTransformationAnchor(QGraphicsView.AnchorUnderMouse)
        self.setResizeAnchor(QGraphicsView.AnchorViewCenter)
        self.setBackgroundBrush(QBrush(QColor(12, 16, 21)))
        self.setFrameShape(QFrame.NoFrame)
        self._zoom = 0
        self._auto_fit = True

    def set_image(self, path):
        pixmap = QPixmap(path)
        if pixmap.isNull():
            return False
        self._pixmap_item.setPixmap(pixmap)
        self._scene.setSceneRect(QRectF(pixmap.rect()))
        self._zoom = 0
        self.resetTransform()
        self.fit_to_view()
        QTimer.singleShot(0, self.fit_to_view)
        return True

    def fit_to_view(self):
        pixmap = self._pixmap_item.pixmap()
        if pixmap.isNull():
            return
        self.resetTransform()
        self.fitInView(self._pixmap_item, Qt.KeepAspectRatio)
        self._zoom = 0
        self._auto_fit = True

    def actual_size(self):
        self.resetTransform()
        self._zoom = 0
        self._auto_fit = False

    def zoom_by(self, factor):
        pixmap = self._pixmap_item.pixmap()
        if pixmap.isNull():
            return
        self.scale(float(factor), float(factor))
        self._zoom += 1 if factor > 1 else -1
        self._auto_fit = False

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if self._auto_fit and not self._pixmap_item.pixmap().isNull():
            self.fit_to_view()

    def wheelEvent(self, event):
        if event.angleDelta().y() > 0:
            self.zoom_by(1.2)
        else:
            self.zoom_by(1 / 1.2)


class TrainingArtifactViewer(QDialog):
    def __init__(self, path, parent=None, paths=None):
        super().__init__(parent)
        self.path = os.path.abspath(str(path or ""))
        available_paths = []
        for candidate in list(paths or []):
            candidate = os.path.abspath(str(candidate or ""))
            if candidate and os.path.isfile(candidate) and candidate not in available_paths:
                available_paths.append(candidate)
        if self.path and self.path not in available_paths:
            available_paths.insert(0, self.path)
        self.paths = available_paths
        self.current_index = self.paths.index(self.path) if self.path in self.paths else 0
        self.setWindowTitle(os.path.basename(self.path) or "Training Visual")
        self.resize(1100, 780)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        toolbar = QHBoxLayout()
        toolbar.setSpacing(8)
        self.path_label = QLabel(self.path)
        self.path_label.setTextInteractionFlags(Qt.TextSelectableByMouse)
        self.path_label.setStyleSheet("color: #9aa4af;")

        self.previous_btn = QPushButton("Previous")
        self.next_btn = QPushButton("Next")
        self.position_label = QLabel("")
        self.position_label.setMinimumWidth(58)
        self.position_label.setAlignment(Qt.AlignCenter)
        fit_btn = QPushButton("Fit")
        actual_btn = QPushButton("100%")
        zoom_in_btn = QPushButton("+")
        zoom_out_btn = QPushButton("-")
        folder_btn = QPushButton("Folder")

        toolbar.addWidget(self.path_label, 1)
        toolbar.addWidget(self.previous_btn)
        toolbar.addWidget(self.position_label)
        toolbar.addWidget(self.next_btn)
        toolbar.addWidget(zoom_out_btn)
        toolbar.addWidget(zoom_in_btn)
        toolbar.addWidget(actual_btn)
        toolbar.addWidget(fit_btn)
        toolbar.addWidget(folder_btn)
        layout.addLayout(toolbar)

        self.view = ZoomableImageView(self)
        layout.addWidget(self.view, 1)

        fit_btn.clicked.connect(self.view.fit_to_view)
        actual_btn.clicked.connect(self.view.actual_size)
        zoom_in_btn.clicked.connect(lambda: self.view.zoom_by(1.2))
        zoom_out_btn.clicked.connect(lambda: self.view.zoom_by(1 / 1.2))
        folder_btn.clicked.connect(self.open_containing_folder)
        self.previous_btn.clicked.connect(lambda: self.show_image_at(self.current_index - 1))
        self.next_btn.clicked.connect(lambda: self.show_image_at(self.current_index + 1))
        self.previous_shortcut = QtWidgets.QShortcut(QtGui.QKeySequence(Qt.Key_Left), self)
        self.next_shortcut = QtWidgets.QShortcut(QtGui.QKeySequence(Qt.Key_Right), self)
        self.previous_shortcut.activated.connect(self.previous_btn.click)
        self.next_shortcut.activated.connect(self.next_btn.click)

        self.show_image_at(self.current_index)

    def show_image_at(self, index):
        if not self.paths:
            self.path_label.setText(f"Could not load: {self.path}")
            self.previous_btn.setEnabled(False)
            self.next_btn.setEnabled(False)
            self.position_label.setText("0 / 0")
            return
        index = max(0, min(int(index), len(self.paths) - 1))
        candidate = self.paths[index]
        if not self.view.set_image(candidate):
            self.path_label.setText(f"Could not load: {candidate}")
            return
        self.current_index = index
        self.path = candidate
        self.path_label.setText(self.path)
        self.path_label.setToolTip(self.path)
        self.setWindowTitle(os.path.basename(self.path) or "Training Visual")
        self.position_label.setText(f"{index + 1} / {len(self.paths)}")
        self.previous_btn.setEnabled(index > 0)
        self.next_btn.setEnabled(index < len(self.paths) - 1)

    def open_containing_folder(self):
        if not self.path or not os.path.exists(self.path):
            return
        try:
            if sys.platform.startswith("win"):
                subprocess.Popen(["explorer.exe", f"/select,{self.path}"])
            elif sys.platform == "darwin":
                subprocess.Popen(["open", "-R", self.path])
            else:
                subprocess.Popen(["xdg-open", os.path.dirname(self.path)])
        except Exception as e:
            QMessageBox.warning(self, "Open Folder", str(e))


class ValidationReviewImageView(ZoomableImageView):
    """Zoomable validation image with task-aware ground-truth/prediction overlays."""

    COLORS = {
        "ground_truth": QColor("#45d483"),
        "prediction": QColor("#ff5968"),
        "missed": QColor("#ff9f43"),
        "weak": QColor("#f0d264"),
        "matched": QColor("#42c6ff"),
    }

    def __init__(self, parent=None):
        super().__init__(parent)
        self.issue = {}
        self.show_ground_truth = True
        self.show_prediction = True

    @staticmethod
    def _pixel_points(item, width, height):
        return [
            QPointF(float(point[0]) * width, float(point[1]) * height)
            for point in (item or {}).get("points", [])
            if isinstance(point, (list, tuple)) and len(point) >= 2
        ]

    @staticmethod
    def _pixel_bbox(item, width, height):
        values = list((item or {}).get("bbox", []) or [])
        if len(values) < 4:
            return None
        return QRectF(
            float(values[0]) * width,
            float(values[1]) * height,
            max(1.0, (float(values[2]) - float(values[0])) * width),
            max(1.0, (float(values[3]) - float(values[1])) * height),
        )

    def _draw_object(self, painter, item, color, width, height, task):
        if not isinstance(item, dict):
            return
        fill = QColor(color)
        fill.setAlpha(45)
        painter.setPen(QPen(color, max(2, round(min(width, height) / 350))))
        painter.setBrush(QBrush(fill))
        points = self._pixel_points(item, width, height)
        if len(points) >= 3 and task in {"segment", "obb"}:
            painter.drawPolygon(QPolygonF(points))
        else:
            bounds = self._pixel_bbox(item, width, height)
            if bounds is not None:
                painter.drawRect(bounds)

        if task == "pose":
            painter.setBrush(QBrush(color))
            radius = max(2.5, min(width, height) / 220.0)
            for point in item.get("keypoints", []) or []:
                if len(point) < 2 or (len(point) >= 3 and float(point[2]) <= 0):
                    continue
                painter.drawEllipse(QPointF(float(point[0]) * width, float(point[1]) * height), radius, radius)

    def set_review_issue(self, issue):
        self.issue = dict(issue or {})
        image_path = str(self.issue.get("image_path", "") or "")
        pixmap = QPixmap(image_path)
        if pixmap.isNull():
            return False
        canvas = QPixmap(pixmap)
        painter = QPainter(canvas)
        painter.setRenderHint(QPainter.Antialiasing)
        task = str(self.issue.get("task", "detect") or "detect")
        issue_type = str(self.issue.get("type", "") or "")
        if self.show_ground_truth:
            gt_color = self.COLORS["missed"] if issue_type == "false_negative" else self.COLORS["ground_truth"]
            self._draw_object(painter, self.issue.get("ground_truth"), gt_color, canvas.width(), canvas.height(), task)
        if self.show_prediction:
            pred_color = self.COLORS["weak"] if issue_type in {"weak_localization", "poor_keypoints"} else self.COLORS["prediction"]
            self._draw_object(painter, self.issue.get("prediction"), pred_color, canvas.width(), canvas.height(), task)
        painter.end()
        self._pixmap_item.setPixmap(canvas)
        self._scene.setSceneRect(QRectF(canvas.rect()))
        self._zoom = 0
        self.resetTransform()
        self.fit_to_view()
        QTimer.singleShot(0, self.fit_to_view)
        return True

    def set_layer_visibility(self, ground_truth=None, prediction=None):
        if ground_truth is not None:
            self.show_ground_truth = bool(ground_truth)
        if prediction is not None:
            self.show_prediction = bool(prediction)
        if self.issue:
            self.set_review_issue(self.issue)


