def connect_weak_bound_signal(signal, callback):
    """Connect a Qt signal to a bound method without keeping the owner alive."""
    weak_callback = weakref.WeakMethod(callback)

    def wrapper(*args, **kwargs):
        method = weak_callback()
        if method is None:
            try:
                signal.disconnect(wrapper)
            except (TypeError, RuntimeError):
                pass
            return None

        try:
            owner = method.__self__
            if owner is None or sip.isdeleted(owner):
                try:
                    signal.disconnect(wrapper)
                except (TypeError, RuntimeError):
                    pass
                return None

            return method(*args, **kwargs)

        except RuntimeError:
            try:
                signal.disconnect(wrapper)
            except (TypeError, RuntimeError):
                pass
            return None

    signal.connect(wrapper)
    return wrapper


class DockHelpButtonController(QObject):
    """Place a working context-help button beside a dock's native controls."""

    def __init__(self, dock, callback, parent=None):
        super().__init__(parent or dock)
        self.dock = dock
        self.button = QtWidgets.QToolButton(dock)
        self.button.setText("?")
        self.button.setObjectName(f"{dock.objectName()}_help_button")
        self.button.setToolTip(f"About the {dock.windowTitle()} dock")
        self.button.setAccessibleName(f"Help for {dock.windowTitle()} dock")
        self.button.setAutoRaise(True)
        self.button.setCursor(Qt.PointingHandCursor)
        self.button.setFixedSize(20, 20)
        self.button.setStyleSheet(
            "QToolButton {"
            "font-weight: 700;"
            "border: 1px solid rgba(128, 144, 160, 120);"
            "border-radius: 4px;"
            "padding: 0;"
            "}"
            "QToolButton:hover {"
            "border-color: #38bdf8;"
            "background-color: rgba(56, 189, 248, 45);"
            "}"
        )
        self.button.clicked.connect(callback)
        dock.installEventFilter(self)
        dock.topLevelChanged.connect(self._on_top_level_changed)
        dock.windowTitleChanged.connect(self._on_title_changed)
        self.reposition()

    def _on_title_changed(self, title):
        self.button.setToolTip(f"About the {title} dock")
        self.button.setAccessibleName(f"Help for {title} dock")

    def _on_top_level_changed(self, floating):
        self.button.setVisible(not bool(floating))
        if not floating:
            QtCore.QTimer.singleShot(0, self.reposition)

    def reposition(self):
        if self.dock.isFloating():
            self.button.hide()
            return
        # Leave room for Qt's native float and close buttons.
        self.button.move(max(4, self.dock.width() - 70), 2)
        self.button.raise_()
        self.button.show()

    def eventFilter(self, watched, event):
        if watched is self.dock and event.type() in (
            QEvent.Resize,
            QEvent.Show,
            QEvent.LayoutRequest,
            QEvent.StyleChange,
        ):
            QtCore.QTimer.singleShot(0, self.reposition)
        return False


@contextlib.contextmanager
def blocked_signals(widget):
    """Temporarily block Qt signals and restore the previous state."""
    if widget is None or not hasattr(widget, "blockSignals"):
        yield widget
        return

    try:
        previous_state = widget.blockSignals(True)
    except RuntimeError:
        yield widget
        return

    try:
        yield widget
    finally:
        try:
            widget.blockSignals(previous_state)
        except RuntimeError:
            pass


def graphics_image_dimensions(owner, fallback_to_scene=True):
    """Return the active image dimensions for a graphics item or view."""
    main_window = getattr(owner, "main_window", None)
    image = getattr(main_window, "image", None) if main_window is not None else None
    if image is None:
        image = getattr(owner, "image", None)

    try:
        if image is not None and hasattr(image, "isNull"):
            if not image.isNull():
                return int(image.width()), int(image.height())
        elif image is not None and isinstance(image, np.ndarray) and image.ndim >= 2:
            return int(image.shape[1]), int(image.shape[0])
        elif image is not None and hasattr(image, "width") and hasattr(image, "height"):
            width = image.width() if callable(image.width) else image.width
            height = image.height() if callable(image.height) else image.height
            return int(width), int(height)
    except RuntimeError:
        pass
    except Exception:
        pass

    if fallback_to_scene and hasattr(owner, "scene"):
        try:
            scene = owner.scene()
            if scene is not None:
                return int(scene.width()), int(scene.height())
        except RuntimeError:
            pass
        except Exception:
            pass

    return 0, 0

