def ultralytics_kwargs_use_fp16(kwargs):
    args = kwargs or {}
    quantize = args.get("quantize")
    if isinstance(quantize, str):
        return quantize.strip().lower() in {"16", "fp16", "half", "float16"}
    if quantize == 16:
        return True
    return bool(args.get("half", False))


def get_color(class_id, num_classes, alpha=150, class_names=None):
    from PyQt5.QtGui import QColor

    if class_id is None or num_classes == 0:
        return QColor(255, 255, 255, alpha)

    class_keys = []
    if class_names and 0 <= class_id < len(class_names):
        class_keys.append(f"classColor_{class_names[class_id]}")
    class_keys.append(f"classColor_{class_id}")

    try:
        settings = read_json_file(APP_SETTINGS_PATH, {})
        last_dir = settings.get("last_dir", "")
        if last_dir:
            project_file = os.path.join(last_dir, PROJECT_SETTINGS_DIR, PROJECT_SETTINGS_FILE)
            settings.update(read_json_file(project_file, {}))

        for class_key in class_keys:
            hex_val = settings.get(class_key)
            if hex_val:
                custom_color = QColor(hex_val)
                if custom_color.isValid():
                    custom_color.setAlpha(alpha)
                    return custom_color
    except Exception as e:
        logging.getLogger("UltraDarkFusionLogger").debug(
            "Couldn't load custom color for class %s: %s",
            class_id,
            e,
        )

    hue_step = 360 / num_classes
    hue = (class_id * hue_step) % 360
    return QColor.fromHsv(int(hue), 255, 255, alpha)

def safe_update_class_name_item_font(drawer, value=None):
    try:
        if drawer is None or sip.isdeleted(drawer):
            return

        item = getattr(drawer, "class_name_item", None)
        if item is None or sip.isdeleted(item):
            return

        font = item.font()
        font.setPointSize(drawer.main_window.font_size_slider.value())
        item.setFont(font)

        if hasattr(drawer, "update_class_name_item"):
            drawer.update_class_name_item()

    except RuntimeError:
        return

def reflect_pad_pil(img, pad_right, pad_bottom):
    np_img = np.array(img)
    if pad_right > 0:
        right_pad = np.flip(np_img[:, -pad_right:], axis=1)
        np_img = np.concatenate((np_img, right_pad), axis=1)
    if pad_bottom > 0:
        bottom_pad = np.flip(np_img[-pad_bottom:, :], axis=0)
        np_img = np.concatenate((np_img, bottom_pad), axis=0)
    return Image.fromarray(np_img)


class TruncatingFormatter(logging.Formatter):

    def format(self, record):
        original = super().format(record)
        max_len = globals().get("MAX_LOG_LINE_LENGTH", 500)

        if len(original) > max_len:
            return original[:max_len] + "..."

        return original


def setup_logger():
    logger = logging.getLogger("UltraDarkFusionLogger")
    logger.setLevel(logging.DEBUG)
    logger.propagate = False

    if logger.hasHandlers():
        logger.handlers.clear()

    log_dir = "debug"
    os.makedirs(log_dir, exist_ok=True)
    log_file = os.path.join(log_dir, "my_app.log")

    # Truncate the log file if it gets too large at startup.
    MAX_STARTUP_SIZE = 64 * 1024
    if os.path.exists(log_file) and os.path.getsize(log_file) > MAX_STARTUP_SIZE:
        with open(log_file, "w", encoding="utf-8") as f:
            f.write("")
        print("Cleared large log file at startup")

    # Rotating file handler
    file_handler = RotatingFileHandler(
        filename=log_file,
        maxBytes=16 * 1024,
        backupCount=0,
        encoding="utf-8"
    )
    file_handler.setLevel(logging.DEBUG)
    file_formatter = TruncatingFormatter(
        "%(asctime)s - %(levelname)s - %(filename)s:%(lineno)d - %(message)s"
    )
    file_handler.setFormatter(file_formatter)

    # Console handler
    console_handler = logging.StreamHandler(sys.stdout)
    console_handler.setLevel(logging.INFO)
    console_formatter = TruncatingFormatter(
        "%(name)-20s: %(levelname)-8s %(message)s"
    )

    # UTF-8 fix for Windows
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except AttributeError:
        sys.stdout = codecs.getwriter("utf-8")(sys.stdout.buffer, "replace")

    console_handler.setFormatter(console_formatter)

    logger.addHandler(file_handler)
    logger.addHandler(console_handler)

    return logger

logger = setup_logger()


class FastFrameViewer(QtWidgets.QWidget):
    """Dedicated video/live frame surface with a pyqtgraph backend when available."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName("fast_frame_viewer")
        self.setAutoFillBackground(True)
        self.setAttribute(Qt.WA_OpaquePaintEvent, True)
        self.setAttribute(Qt.WA_NoSystemBackground, True)
        self.setStyleSheet("background-color: #000000;")

        self.backend_name = "qt-label"
        self._frame_ref = None
        self._frame_size = None
        self._label_pixmap = None
        self._label_scaled_size = None
        self._label_scaled_pixmap = None
        self._image_item = None
        self._view_box = None

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        if pg is not None:
            try:
                pg.setConfigOptions(imageAxisOrder="row-major")
                self._pg_widget = pg.GraphicsLayoutWidget(self)
                self._pg_widget.setBackground("k")
                self._pg_widget.setViewportUpdateMode(QtWidgets.QGraphicsView.BoundingRectViewportUpdate)
                self._pg_widget.setOptimizationFlag(QtWidgets.QGraphicsView.DontSavePainterState, True)
                self._pg_widget.setOptimizationFlag(QtWidgets.QGraphicsView.DontAdjustForAntialiasing, True)
                self._view_box = self._pg_widget.addViewBox(lockAspect=True)
                self._view_box.setMenuEnabled(False)
                self._view_box.setMouseEnabled(x=False, y=False)
                self._view_box.setDefaultPadding(0)
                self._view_box.invertY(True)
                self._image_item = pg.ImageItem(axisOrder="row-major")
                self._image_item.setAutoDownsample(True)
                self._view_box.addItem(self._image_item)
                layout.addWidget(self._pg_widget)
                self.backend_name = "pyqtgraph"
                return
            except Exception as e:
                logger.warning(f"pyqtgraph frame viewer unavailable, falling back to QLabel: {e}")
                self._image_item = None
                self._view_box = None

        self._label = QtWidgets.QLabel(self)
        self._label.setAlignment(Qt.AlignCenter)
        self._label.setStyleSheet("background-color: #000000;")
        self._label.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Expanding)
        layout.addWidget(self._label)

    def clear(self):
        self._frame_ref = None
        self._frame_size = None

        if self._image_item is not None:
            try:
                self._image_item.clear()
            except Exception:
                pass

        if hasattr(self, "_label"):
            self._label.clear()
            self._label_pixmap = None
            self._label_scaled_size = None
            self._label_scaled_pixmap = None

    def set_frame(self, frame):
        if frame is None or not isinstance(frame, np.ndarray) or frame.size == 0:
            return

        if frame.ndim == 2:
            frame = cv2.cvtColor(frame, cv2.COLOR_GRAY2RGB)
        elif frame.ndim == 3 and frame.shape[2] == 4:
            frame = cv2.cvtColor(frame, cv2.COLOR_RGBA2RGB)

        if frame.ndim != 3 or frame.shape[2] != 3:
            return

        if frame.dtype != np.uint8:
            if np.issubdtype(frame.dtype, np.floating):
                finite_values = frame[np.isfinite(frame)]
                if finite_values.size and float(np.nanmax(finite_values)) <= 1.0:
                    frame = frame * 255.0
                frame = np.nan_to_num(frame, nan=0.0, posinf=255.0, neginf=0.0)
            frame = np.clip(frame, 0, 255).astype(np.uint8)

        if not frame.flags.c_contiguous:
            frame = np.ascontiguousarray(frame)
        height, width = frame.shape[:2]
        frame_size = (width, height)
        self._frame_ref = frame

        if self._image_item is not None:
            self._image_item.setImage(frame, autoLevels=False, levels=(0, 255))

            if frame_size != self._frame_size:
                rect = QtCore.QRectF(0, 0, width, height)
                self._image_item.setRect(rect)
                if self._view_box is not None:
                    self._view_box.setRange(rect, padding=0)
                self._frame_size = frame_size
            return

        bytes_per_line = 3 * width
        image = QImage(frame.data, width, height, bytes_per_line, QImage.Format_RGB888)
        self._label_pixmap = QPixmap.fromImage(image)
        self._label_scaled_size = None
        self._label_scaled_pixmap = None
        self._refresh_label_pixmap()
        self._frame_size = frame_size

    def _refresh_label_pixmap(self):
        if not hasattr(self, "_label") or self._label_pixmap is None or self._label_pixmap.isNull():
            return

        target_size = self._label.size()
        if target_size.width() <= 1 or target_size.height() <= 1:
            self._label.setPixmap(self._label_pixmap)
            return

        if self._label_scaled_size != target_size:
            self._label_scaled_pixmap = self._label_pixmap.scaled(
                target_size,
                Qt.KeepAspectRatio,
                Qt.FastTransformation,
            )
            self._label_scaled_size = QtCore.QSize(target_size)

        self._label.setPixmap(self._label_scaled_pixmap)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, "_label"):
            self._refresh_label_pixmap()


class PanPuckSettingsDialog(QDialog):
    """Compact settings for the floating image-pan control."""

    def __init__(self, overlay, parent=None):
        super().__init__(parent)
        self.overlay = overlay
        self.setWindowTitle("Pan Control")
        self.setModal(True)
        self.setMinimumWidth(330)

        layout = QtWidgets.QVBoxLayout(self)
        form = QtWidgets.QFormLayout()
        form.setLabelAlignment(Qt.AlignRight)

        self.free_pan_check = QCheckBox("Allow free 360° and diagonal movement")
        self.free_pan_check.setChecked(bool(overlay.free_pan))
        form.addRow("Free pan:", self.free_pan_check)

        self.lock_check = QCheckBox("Lock the control in its current position")
        self.lock_check.setChecked(bool(overlay.position_locked))
        form.addRow("Position:", self.lock_check)

        self.always_show_check = QCheckBox("Show whenever Zoom Lock is enabled")
        self.always_show_check.setChecked(bool(overlay.always_show))
        self.always_show_check.setToolTip(
            "Normally the control appears only when the zoomed image is larger than the viewport."
        )
        form.addRow("Visibility:", self.always_show_check)

        self.speed_slider = QtWidgets.QSlider(Qt.Horizontal)
        self.speed_slider.setRange(2, 30)
        self.speed_slider.setValue(int(overlay.pan_speed))
        self.speed_value = QLabel()
        speed_row = QtWidgets.QHBoxLayout()
        speed_row.addWidget(self.speed_slider, 1)
        speed_row.addWidget(self.speed_value)
        form.addRow("Pan speed:", speed_row)

        self.opacity_slider = QtWidgets.QSlider(Qt.Horizontal)
        self.opacity_slider.setRange(25, 90)
        self.opacity_slider.setValue(int(round(overlay.panel_opacity * 100)))
        self.opacity_value = QLabel()
        opacity_row = QtWidgets.QHBoxLayout()
        opacity_row.addWidget(self.opacity_slider, 1)
        opacity_row.addWidget(self.opacity_value)
        form.addRow("Opacity:", opacity_row)

        self.size_slider = QtWidgets.QSlider(Qt.Horizontal)
        self.size_slider.setRange(96, 180)
        self.size_slider.setValue(int(overlay.control_size))
        self.size_value = QLabel()
        size_row = QtWidgets.QHBoxLayout()
        size_row.addWidget(self.size_slider, 1)
        size_row.addWidget(self.size_value)
        form.addRow("Control size:", size_row)

        layout.addLayout(form)

        hint = QLabel(
            "Drag the puck for continuous movement. Drag the dotted header to move the control "
            "when its position is unlocked."
        )
        hint.setWordWrap(True)
        hint.setStyleSheet("color: #9aa4af;")
        layout.addWidget(hint)

        buttons = QtWidgets.QDialogButtonBox(
            QtWidgets.QDialogButtonBox.Ok | QtWidgets.QDialogButtonBox.Cancel
        )
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        layout.addWidget(buttons)

        self.speed_slider.valueChanged.connect(
            lambda value: self.speed_value.setText(f"{int(value)} px")
        )
        self.opacity_slider.valueChanged.connect(
            lambda value: self.opacity_value.setText(f"{int(value)}%")
        )
        self.size_slider.valueChanged.connect(
            lambda value: self.size_value.setText(f"{int(value)} px")
        )
        self.speed_slider.valueChanged.emit(self.speed_slider.value())
        self.opacity_slider.valueChanged.emit(self.opacity_slider.value())
        self.size_slider.valueChanged.emit(self.size_slider.value())

    def accept(self):
        self.overlay.apply_user_settings(
            free_pan=self.free_pan_check.isChecked(),
            position_locked=self.lock_check.isChecked(),
            always_show=self.always_show_check.isChecked(),
            pan_speed=self.speed_slider.value(),
            panel_opacity=self.opacity_slider.value() / 100.0,
            control_size=self.size_slider.value(),
        )
        super().accept()


class FloatingPanPuck(QWidget):
    """Movable translucent joystick used to pan a zoomed graphics view."""

    HEADER_HEIGHT = 24
    FOOTER_HEIGHT = 36
    UI_MARGIN = 8

    def __init__(self, view):
        super().__init__(view.viewport())
        self.view = view
        self.main_window = getattr(view, "main_window", None)
        self.free_pan = True
        self.position_locked = False
        self.always_show = False
        self.pan_speed = 10
        self.panel_opacity = 0.58
        self.control_size = 124
        self._render_control_size = self.control_size
        self._direction = QPointF()
        self._joystick_active = False
        self._moving_overlay = False
        self._move_offset = QtCore.QPoint()
        self._restoring_position = False

        self.setObjectName("floatingPanPuck")
        self.setAttribute(Qt.WA_TranslucentBackground, True)
        self.setMouseTracking(True)
        view.viewport().installEventFilter(self)

        self.pin_button = QtWidgets.QToolButton(self)
        self.pin_button.setCheckable(True)
        self.pin_button.setText("●")
        self.pin_button.setToolTip("Lock/unlock the pan control position")
        self.pin_button.setCursor(Qt.PointingHandCursor)
        self.pin_button.toggled.connect(self.set_position_locked)

        self.gear_button = QtWidgets.QToolButton(self)
        self.gear_button.setText("⚙")
        self.gear_button.setToolTip("Pan control settings")
        self.gear_button.setCursor(Qt.PointingHandCursor)
        self.gear_button.clicked.connect(self.open_settings)

        button_style = """
            QToolButton {
                color: white;
                background: rgba(10, 15, 20, 150);
                border: 1px solid rgba(255, 255, 255, 70);
                border-radius: 9px;
                font-weight: 700;
            }
            QToolButton:hover {
                background: rgba(55, 125, 180, 205);
                border-color: rgba(255, 255, 255, 150);
            }
            QToolButton:checked {
                background: rgba(240, 180, 65, 210);
                color: #111820;
            }
        """
        self.pin_button.setStyleSheet(button_style)
        self.gear_button.setStyleSheet(button_style)

        self.pan_timer = QTimer(self)
        self.pan_timer.setInterval(16)
        self.pan_timer.timeout.connect(self._pan_tick)

        self.apply_saved_settings()
        self._apply_size()
        self.hide()

    def _settings(self):
        settings = getattr(self.main_window, "settings", None)
        return settings if isinstance(settings, dict) else {}

    def apply_saved_settings(self):
        settings = self._settings()
        self.free_pan = bool(settings.get("panOverlayFreePan", True))
        self.position_locked = bool(settings.get("panOverlayLocked", False))
        self.always_show = bool(settings.get("panOverlayAlwaysShow", False))
        self.pan_speed = max(2, min(30, int(settings.get("panOverlaySpeed", 10) or 10)))
        self.panel_opacity = max(
            0.25,
            min(0.90, float(settings.get("panOverlayOpacity", 0.58) or 0.58)),
        )
        self.control_size = max(
            96,
            min(180, int(settings.get("panOverlaySize", 124) or 124)),
        )
        with blocked_signals(self.pin_button):
            self.pin_button.setChecked(self.position_locked)
        self.pin_button.setToolTip(
            "Unlock pan control position" if self.position_locked else "Lock pan control position"
        )
        self._apply_size()
        self.restore_position()
        self.update_visibility()
        self.update()

    def apply_user_settings(
        self,
        *,
        free_pan,
        position_locked,
        always_show,
        pan_speed,
        panel_opacity,
        control_size,
    ):
        self.free_pan = bool(free_pan)
        self.always_show = bool(always_show)
        self.pan_speed = max(2, min(30, int(pan_speed)))
        self.panel_opacity = max(0.25, min(0.90, float(panel_opacity)))
        self.control_size = max(96, min(180, int(control_size)))
        self.set_position_locked(bool(position_locked))
        self._apply_size()
        self._clamp_to_viewport()
        self.persist_settings()
        self.update_visibility()
        self.update()

    def persist_settings(self):
        settings = self._settings()
        if not settings:
            return
        settings["panOverlayFreePan"] = bool(self.free_pan)
        settings["panOverlayLocked"] = bool(self.position_locked)
        settings["panOverlayAlwaysShow"] = bool(self.always_show)
        settings["panOverlaySpeed"] = int(self.pan_speed)
        settings["panOverlayOpacity"] = float(self.panel_opacity)
        settings["panOverlaySize"] = int(self.control_size)
        self.persist_position(queue_save=False)
        if hasattr(self.main_window, "queue_settings_save"):
            self.main_window.queue_settings_save()

    def _apply_size(self):
        parent = self.parentWidget()
        effective_size = int(self.control_size)
        if parent is not None:
            max_width = max(72, int(parent.width()) - self.UI_MARGIN * 2)
            max_height = max(
                72,
                int(parent.height()) - self.HEADER_HEIGHT - self.FOOTER_HEIGHT - self.UI_MARGIN * 2,
            )
            effective_size = max(72, min(effective_size, max_width, max_height))
        self._render_control_size = effective_size
        total_height = int(effective_size + self.HEADER_HEIGHT + self.FOOTER_HEIGHT)
        self.setFixedSize(effective_size, total_height)
        button_size = 20
        self.pin_button.setGeometry(self.width() - button_size - 5, 3, button_size, button_size)
        gear_size = 28
        self.gear_button.setGeometry(
            (self.width() - gear_size) // 2,
            self.height() - gear_size - 4,
            gear_size,
            gear_size,
        )

    def _joystick_center(self):
        return QPointF(
            self.width() / 2.0,
            self.HEADER_HEIGHT + self._render_control_size / 2.0,
        )

    def _joystick_radius(self):
        return max(22.0, self._render_control_size * 0.38)

    def _knob_radius(self):
        return max(10.0, self._render_control_size * 0.115)

    def paintEvent(self, _event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, True)

        alpha = int(round(255 * self.panel_opacity))
        panel_rect = QRectF(1, 1, self.width() - 2, self.height() - 2)
        painter.setPen(QPen(QColor(255, 255, 255, min(95, alpha)), 1.0))
        painter.setBrush(QBrush(QColor(8, 13, 18, alpha)))
        painter.drawRoundedRect(panel_rect, 16, 16)

        center = self._joystick_center()
        radius = self._joystick_radius()
        painter.setPen(QPen(QColor(210, 225, 238, min(125, alpha)), 1.5))
        painter.setBrush(QBrush(QColor(35, 48, 60, min(175, alpha))))
        painter.drawEllipse(center, radius, radius)

        painter.setPen(QPen(QColor(235, 244, 250, min(175, alpha)), 2.0))
        arrow_inner = radius * 0.48
        arrow_outer = radius * 0.73
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            start = QPointF(center.x() + dx * arrow_inner, center.y() + dy * arrow_inner)
            end = QPointF(center.x() + dx * arrow_outer, center.y() + dy * arrow_outer)
            painter.drawLine(start, end)

        knob_center = QPointF(
            center.x() + self._direction.x() * radius * 0.62,
            center.y() + self._direction.y() * radius * 0.62,
        )
        knob_radius = self._knob_radius()
        painter.setPen(QPen(QColor(255, 255, 255, 190), 1.5))
        painter.setBrush(QBrush(QColor(60, 155, 220, min(235, alpha + 55))))
        painter.drawEllipse(knob_center, knob_radius, knob_radius)

        painter.setPen(QPen(QColor(220, 230, 238, min(150, alpha)), 2.0))
        grip_y = 11
        for offset in (-10, 0, 10):
            painter.drawPoint(int(self.width() / 2 + offset), grip_y)

    def mousePressEvent(self, event):
        if event.button() != Qt.LeftButton:
            super().mousePressEvent(event)
            return

        center = self._joystick_center()
        delta = event.pos() - center.toPoint()
        distance = math.hypot(delta.x(), delta.y())
        if distance <= self._joystick_radius() + self._knob_radius():
            self._joystick_active = True
            self._update_direction(event.pos())
            if not self.pan_timer.isActive():
                self.pan_timer.start()
            event.accept()
            return

        if event.pos().y() <= self.HEADER_HEIGHT and not self.position_locked:
            self._moving_overlay = True
            self._move_offset = event.pos()
            self.setCursor(Qt.ClosedHandCursor)
            event.accept()
            return

        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._joystick_active:
            self._update_direction(event.pos())
            event.accept()
            return

        if self._moving_overlay and not self.position_locked:
            viewport_global = self.parentWidget().mapToGlobal(QtCore.QPoint(0, 0))
            new_pos = event.globalPos() - viewport_global - self._move_offset
            self.move(new_pos)
            self._clamp_to_viewport()
            event.accept()
            return

        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.LeftButton and self._joystick_active:
            self._joystick_active = False
            self._direction = QPointF()
            self.pan_timer.stop()
            self.update()
            event.accept()
            return

        if event.button() == Qt.LeftButton and self._moving_overlay:
            self._moving_overlay = False
            self.unsetCursor()
            self.persist_position()
            event.accept()
            return

        super().mouseReleaseEvent(event)

    def _update_direction(self, position):
        center = self._joystick_center()
        dx = float(position.x()) - center.x()
        dy = float(position.y()) - center.y()
        length = math.hypot(dx, dy)
        if length < 2.0:
            self._direction = QPointF()
        else:
            dx /= length
            dy /= length
            if not self.free_pan:
                angle = round(math.atan2(dy, dx) / (math.pi / 4.0)) * (math.pi / 4.0)
                dx, dy = math.cos(angle), math.sin(angle)
            strength = min(1.0, length / max(1.0, self._joystick_radius()))
            self._direction = QPointF(dx * strength, dy * strength)
        self.update()

    def _pan_tick(self):
        if not self._joystick_active:
            self.pan_timer.stop()
            return
        if abs(self._direction.x()) < 0.001 and abs(self._direction.y()) < 0.001:
            return
        self.view.pan_by_view_pixels(
            self._direction.x() * self.pan_speed,
            self._direction.y() * self.pan_speed,
        )

    def open_settings(self):
        dialog = PanPuckSettingsDialog(self, self)
        dialog.adjustSize()
        screen = QtWidgets.QApplication.screenAt(self.mapToGlobal(self.rect().center()))
        if screen is None:
            screen = QtWidgets.QApplication.primaryScreen()
        target = self.mapToGlobal(
            QtCore.QPoint((self.width() - dialog.width()) // 2, self.height() + 6)
        )
        if screen is not None:
            available = screen.availableGeometry()
            target.setX(max(available.left(), min(target.x(), available.right() - dialog.width() + 1)))
            target.setY(max(available.top(), min(target.y(), available.bottom() - dialog.height() + 1)))
        dialog.move(target)
        dialog.exec_()

    def set_position_locked(self, locked):
        self.position_locked = bool(locked)
        with blocked_signals(self.pin_button):
            self.pin_button.setChecked(self.position_locked)
        self.pin_button.setToolTip(
            "Unlock pan control position" if self.position_locked else "Lock pan control position"
        )
        self.persist_settings()
        self.update()

    def persist_position(self, queue_save=True):
        if self._restoring_position:
            return
        parent = self.parentWidget()
        settings = self._settings()
        if parent is None or not settings:
            return
        min_x, min_y, max_x, max_y = self._movement_bounds()
        travel_x = max(1, max_x - min_x)
        travel_y = max(1, max_y - min_y)
        settings["panOverlayPosition"] = [
            max(0.0, min(1.0, (self.x() - min_x) / travel_x)),
            max(0.0, min(1.0, (self.y() - min_y) / travel_y)),
        ]
        if queue_save and hasattr(self.main_window, "queue_settings_save"):
            self.main_window.queue_settings_save()

    def restore_position(self):
        parent = self.parentWidget()
        if parent is None:
            return
        position = self._settings().get("panOverlayPosition", [0.82, 0.70])
        try:
            x_ratio = max(0.0, min(1.0, float(position[0])))
            y_ratio = max(0.0, min(1.0, float(position[1])))
        except Exception:
            x_ratio, y_ratio = 0.82, 0.70
        min_x, min_y, max_x, max_y = self._movement_bounds()
        self._restoring_position = True
        try:
            self.move(
                int(round(min_x + (max_x - min_x) * x_ratio)),
                int(round(min_y + (max_y - min_y) * y_ratio)),
            )
            self._clamp_to_viewport()
        finally:
            self._restoring_position = False

    def _movement_bounds(self):
        parent = self.parentWidget()
        if parent is None:
            return 0, 0, 0, 0
        margin_x = min(self.UI_MARGIN, max(0, (parent.width() - self.width()) // 2))
        margin_y = min(self.UI_MARGIN, max(0, (parent.height() - self.height()) // 2))
        min_x = max(0, margin_x)
        min_y = max(0, margin_y)
        max_x = max(min_x, parent.width() - self.width() - margin_x)
        max_y = max(min_y, parent.height() - self.height() - margin_y)
        return min_x, min_y, max_x, max_y

    def _clamp_to_viewport(self):
        parent = self.parentWidget()
        if parent is None:
            return
        min_x, min_y, max_x, max_y = self._movement_bounds()
        x = max(min_x, min(self.x(), max_x))
        y = max(min_y, min(self.y(), max_y))
        if x != self.x() or y != self.y():
            self.move(x, y)

    def eventFilter(self, watched, event):
        if watched is self.parentWidget() and event.type() in (
            QEvent.Resize,
            QEvent.Show,
            QEvent.LayoutRequest,
        ):
            QTimer.singleShot(0, self.ensure_within_ui_bounds)
        return super().eventFilter(watched, event)

    def showEvent(self, event):
        self.ensure_within_ui_bounds()
        super().showEvent(event)

    def ensure_within_ui_bounds(self):
        self._apply_size()
        self._clamp_to_viewport()
        self.persist_position(queue_save=False)

    def update_visibility(self):
        zoom_locked = False
        if self.main_window is not None and hasattr(self.main_window, "is_zoom_locked"):
            zoom_locked = bool(self.main_window.is_zoom_locked())
        should_show = zoom_locked and (self.always_show or self.view.image_can_pan())
        self.setVisible(bool(should_show))
        if should_show:
            self.raise_()


class CustomGraphicsView(QGraphicsView):
    """
    A custom graphics view for displaying and interacting with images and bounding boxes.
    """

    def __init__(self, parent=None, main_window=None):
        super().__init__(parent)
        self.main_window = main_window

        self._setup_initial_state()
        self._setup_render_settings()

        self.sound_player = QMediaPlayer()


        if self.main_window is not None and hasattr(self.main_window, "settings"):
            self.sound_player.setMuted(
                bool(self.main_window.settings.get("muteAudio", True))
            )
        else:
            self.sound_player.setMuted(True)
        self.zoom_scale = 1.0
        self.fitInView_scale = 1.0
        self.auto_fit_enabled = True
        self.show_crosshair = False

        self.right_click_timer = QTimer(self)
        self.right_click_timer.setInterval(100)
        self.right_click_timer.timeout.connect(self.remove_item_under_cursor)

        self.setMouseTracking(True)
        self.setTransformationAnchor(QGraphicsView.AnchorUnderMouse)
        self.setDragMode(QGraphicsView.NoDrag)
        self.setRenderHints(
            QPainter.Antialiasing
            | QPainter.TextAntialiasing
        )
        self.fitInView(self.sceneRect(), Qt.KeepAspectRatio)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.setFrameShape(QGraphicsView.NoFrame)

        self.pan_overlay = FloatingPanPuck(self)
        self._pan_overlay_visibility_timer = QTimer(self)
        self._pan_overlay_visibility_timer.setInterval(250)
        self._pan_overlay_visibility_timer.timeout.connect(self.pan_overlay.update_visibility)
        self._pan_overlay_visibility_timer.start()

    def _setup_initial_state(self):
        self.drawing = False
        self.drawing_obb = False
        self.current_obb = None
        self.start_point = None
        self.current_bbox = None
        self.selected_bbox = None
        self.moving_view = False
        self.current_segmentation = None
        self.bboxes = []
        self.dragStartPos = None
        self.current_keypoint_drawer = None
        self.current_obb_drawer = None

        self.crosshair_position = QPointF()
        self.last_mouse_pos = None
        self.last_mouse_position = None

        self.graphics_scene = QGraphicsScene(self)
        self.auto_fit_enabled = False
        if self.main_window is not None and hasattr(self.main_window, "settings"):
            self.show_crosshair = bool(self.main_window.settings.get("showXYLines", False))

            saved_color = self.main_window.settings.get("crosshairColor", [255, 255, 0])
            if isinstance(saved_color, (list, tuple)) and len(saved_color) >= 3:
                self.crosshair_color_rgb = (
                    int(saved_color[0]),
                    int(saved_color[1]),
                    int(saved_color[2])
                )
            else:
                self.crosshair_color_rgb = (255, 255, 0)
        else:
            self.show_crosshair = False
            self.crosshair_color_rgb = (255, 255, 0)

        if self.main_window is not None and hasattr(self.main_window, "box_size"):
            self.main_window.box_size.valueChanged.connect(self.update_bbox_size)  # type: ignore

    def _setup_render_settings(self):
        self.setBackgroundBrush(QColor(0, 0, 0))
        self.setViewportUpdateMode(QGraphicsView.BoundingRectViewportUpdate)
        self.setOptimizationFlag(QGraphicsView.DontAdjustForAntialiasing, True)
        self.setOptimizationFlag(QGraphicsView.DontSavePainterState, True)

    def mute_player(self, state):
        self.sound_player.setMuted(state == Qt.Checked)  # type: ignore

    def set_sound(self, sound_path):
        self.sound_player.setMedia(QMediaContent(QUrl.fromLocalFile(sound_path)))

    def _get_image_dimensions(self):
        return graphics_image_dimensions(self)

    def safe_remove_item(self, item):
        if item is None:
            return

        try:
            if sip.isdeleted(item):
                return
        except Exception:
            return

        scene = item.scene()
        if scene and scene == self.scene():
            if item == self.selected_bbox:
                self.selected_bbox = None
            scene.removeItem(item)

    def remove_item_under_cursor(self):
        scene = self.scene()
        if scene is None:
            return

        cursor_pos = self.mapToScene(self.mapFromGlobal(QCursor.pos()))
        items_at_pos = scene.items(cursor_pos)

        candidate_items = []

        for item in items_at_pos:
            try:
                if sip.isdeleted(item):
                    continue
            except Exception:
                continue

            if isinstance(item, BoundingBoxDrawer):
                rect = item.rect().adjusted(-10, -10, 10, 10)
                if rect.contains(cursor_pos):
                    area = max(1.0, item.rect().width() * item.rect().height())
                    candidate_items.append((0, area, -item.zValue(), item))

            elif isinstance(item, SegmentationDrawer):
                local_pos = item.mapFromScene(cursor_pos)
                if item.contains(local_pos):
                    br = item.polygon.boundingRect()
                    area = max(1.0, br.width() * br.height())
                    candidate_items.append((1, area, -item.zValue(), item))

            elif isinstance(item, OBBDrawer):
                local_pos = item.mapFromScene(cursor_pos)
                if item.contains(local_pos):
                    br = item.boundingRect()
                    area = max(1.0, br.width() * br.height())
                    candidate_items.append((2, area, -item.zValue(), item))

        if not candidate_items:
            return

        candidate_items.sort(key=lambda x: (x[1], x[2]))
        chosen = candidate_items[0][-1]

        if chosen is self.current_obb_drawer:
            self.current_obb_drawer = None
            self.drawing_obb = False

    # This handles sound, scene removal, scene-save,
    # cache sync, blank overlay, and preview refresh.
        self._play_sound_and_remove_bbox(chosen)

    def update_bbox_size(self, value):
        BoundingBoxDrawer.MIN_SIZE = value
        if self.main_window is not None and hasattr(self.main_window, "max_label"):
            BoundingBoxDrawer.MAX_SIZE = self.main_window.max_label.value()

    def wheelEvent(self, event):
        zoom_in_factor = 1.15
        zoom_out_factor = 1 / zoom_in_factor
        old_pos = self.mapToScene(event.pos())

        self.setRenderHint(QPainter.SmoothPixmapTransform, True)

        if event.angleDelta().y() > 0:
            zoom_factor = zoom_in_factor
            self.zoom_scale *= zoom_in_factor
        else:
            min_zoom_scale = max(self.fitInView_scale, 0.1)
            if self.zoom_scale * zoom_out_factor < min_zoom_scale:
                self.setRenderHint(QPainter.SmoothPixmapTransform, False)
                return
            zoom_factor = zoom_out_factor
            self.zoom_scale *= zoom_out_factor

        self.scale(zoom_factor, zoom_factor)
        new_pos = self.mapToScene(event.pos())
        delta = new_pos - old_pos
        self.centerOn(self.mapToScene(self.viewport().rect().center()) - delta)

        self.setRenderHint(QPainter.SmoothPixmapTransform, False)

        if self.main_window is not None and hasattr(self.main_window, "capture_zoom_lock_state"):
            if self.main_window.is_zoom_locked():
                self.main_window.capture_zoom_lock_state()
        if hasattr(self, "pan_overlay"):
            self.pan_overlay.update_visibility()

    def resizeEvent(self, event):
        super().resizeEvent(event)

        if hasattr(self, "pan_overlay"):
            self.pan_overlay.ensure_within_ui_bounds()
            self.pan_overlay.update_visibility()

        if (
            self.main_window is not None
            and hasattr(self.main_window, "is_zoom_locked")
            and self.main_window.is_zoom_locked()
        ):
            self.main_window.restore_zoom_lock_state()
            return

        if self.auto_fit_enabled and self.scene():
            self.fitInView(self.scene().sceneRect(), Qt.KeepAspectRatio)
            self.fitInView_scale = self.transform().m11()

    def reset_zoom(self):
        if self.scene():
            self.fitInView(self.scene().sceneRect(), Qt.KeepAspectRatio)
            self.fitInView_scale = self.transform().m11()
            self.zoom_scale = 1.0
        if hasattr(self, "pan_overlay"):
            self.pan_overlay.update_visibility()

    def image_can_pan(self):
        scene = self.scene()
        if scene is None or scene.sceneRect().isEmpty():
            return False
        try:
            visible_scene_rect = self.mapToScene(self.viewport().rect()).boundingRect()
            scene_rect = scene.sceneRect()
            tolerance = 0.5
            return bool(
                visible_scene_rect.width() < scene_rect.width() - tolerance
                or visible_scene_rect.height() < scene_rect.height() - tolerance
            )
        except Exception:
            return bool(
                self.horizontalScrollBar().maximum() > self.horizontalScrollBar().minimum()
                or self.verticalScrollBar().maximum() > self.verticalScrollBar().minimum()
            )

    def pan_by_view_pixels(self, dx, dy):
        """Move the viewport center by screen-pixel deltas without changing zoom."""
        scene = self.scene()
        if scene is None:
            return
        scale = max(abs(float(self.transform().m11())), 0.0001)
        center = self.mapToScene(self.viewport().rect().center())
        self.centerOn(QPointF(center.x() + float(dx) / scale, center.y() + float(dy) / scale))
        if self.main_window is not None and hasattr(self.main_window, "capture_zoom_lock_state"):
            if self.main_window.is_zoom_locked():
                self.main_window.capture_zoom_lock_state()

    def _clear_bbox_selection(self):
        for bbox in list(self.bboxes):
            try:
                if not sip.isdeleted(bbox):
                    bbox.set_selected(False)
            except Exception:
                pass

    def _select_bbox(self, bbox):
        if bbox is None:
            return
        self._clear_bbox_selection()
        bbox.set_selected(True)
        self.selected_bbox = bbox

    def _sync_keypoint_visibility_ui(self, drawer):
        if not self.main_window.auto_sync_checkbox.isChecked():
            return

        flags = drawer.visibility_flags

        for i in range(self.main_window.keypoint_list.rowCount()):
            visible_cb = self.main_window.keypoint_list.cellWidget(i, 3)
            ignore_cb = self.main_window.keypoint_list.cellWidget(i, 4)

            if not visible_cb or not ignore_cb:
                continue

            visible_cb.blockSignals(True)
            ignore_cb.blockSignals(True)

            if self.main_window.keypoint_row_is_manually_ignored(i):
                visible_cb.setChecked(False)
                ignore_cb.setChecked(True)

                while len(drawer.points) <= i:
                    drawer.points.append((0.0, 0.0))
                while len(drawer.visibility_flags) <= i:
                    drawer.visibility_flags.append(0)

                drawer.points[i] = (0.0, 0.0)
                drawer.visibility_flags[i] = 0

            elif i < len(flags):
                v = int(flags[i])

                if v == 0:
                    visible_cb.setChecked(False)
                    ignore_cb.setChecked(True)

                elif v == 1:
                    visible_cb.setChecked(False)
                    ignore_cb.setChecked(False)

                elif v == 2:
                    visible_cb.setChecked(True)
                    ignore_cb.setChecked(False)

                else:
                    visible_cb.setChecked(True)
                    ignore_cb.setChecked(False)

            else:
                # Missing keypoint data means this box has not labeled this point yet.
                # Keep the current list state so a user's Ignore/Visible setup is not
                # wiped when selecting a fresh bbox.
                pass

            visible_cb.blockSignals(False)
            ignore_cb.blockSignals(False)

        drawer.update_points()
        self.main_window.rebind_keypoint_checkbox_signals()

    def _ensure_keypoint_drawer(self, bbox_item):
        if getattr(bbox_item, "keypoint_drawer", None) is not None:
            return bbox_item.keypoint_drawer

        drawer = KeypointDrawer(
            points=[],
            main_window=self.main_window,
            class_id=bbox_item.class_id,
            file_name=self.main_window.current_file,
        )
        drawer.setParentItem(bbox_item)
        bbox_item.keypoint_drawer = drawer

        bbox_data = getattr(bbox_item, "bbox_data", None)
        if bbox_data and getattr(bbox_data, "keypoints", None):
            drawer.points = [(x, y) for x, y, v in bbox_data.keypoints]
            drawer.visibility_flags = [int(v) for x, y, v in bbox_data.keypoints]
            drawer.update_points()
            drawer.update_class_name_item()

        return drawer

    def _advance_keypoint_row(self, row):
        next_row = self.main_window.next_labelable_keypoint_row(row, include_start=False)
        self.main_window.set_active_keypoint_row(next_row, getattr(self.selected_bbox, "keypoint_drawer", None))

        if self.selected_bbox and getattr(self.selected_bbox, "keypoint_drawer", None):
            self.selected_bbox.keypoint_drawer.current_index = next_row if next_row is not None else 0

    def _save_current_annotations(self):
        img_width, img_height = self._get_image_dimensions()
        if hasattr(self.main_window, "save_bounding_boxes"):
            self.main_window.save_bounding_boxes(
                self.main_window.current_file,
                img_width,
                img_height,
            )
        if hasattr(self.main_window, "refresh_annotation_preview_after_save"):
            self.main_window.refresh_annotation_preview_after_save(
                self.main_window.current_file
            )

    def _handle_keypoint_press(self, event, clicked_pos):
        if event.button() == Qt.RightButton:
            self._handle_right_button_press(event)
            return True

        found_box = False
        for item in self.scene().items(clicked_pos):
            if isinstance(item, BoundingBoxDrawer):
                is_new_selection = item != self.selected_bbox
                self._select_bbox(item)
                found_box = True

                drawer = self._ensure_keypoint_drawer(item)

                if is_new_selection:
                    self._sync_keypoint_visibility_ui(drawer)
                    if self.main_window.fast_label_checkbox.isChecked():
                        self.main_window.set_active_keypoint_row(
                            self.main_window.next_labelable_keypoint_row(0),
                            drawer,
                        )
                    else:
                        self.main_window.selected_keypoint_row = None
                        self.main_window.keypoint_list.clearSelection()
                break

        if not found_box:
            logger.debug("No bounding box selected under cursor.")
            return True

        bbox = self.selected_bbox
        drawer = bbox.keypoint_drawer
        row = self.main_window.selected_keypoint_row
        img_width, img_height = self._get_image_dimensions()

        if row is not None:
            ignore_cb = self.main_window.keypoint_list.cellWidget(row, 4)

            while len(drawer.points) <= row:
                drawer.points.append((0.0, 0.0))
            while len(drawer.visibility_flags) <= row:
                drawer.visibility_flags.append(0)

            if ignore_cb and ignore_cb.isChecked():
                self.main_window.mark_keypoint_row_ignored(row, drawer)
                drawer.update_points()
                drawer.update_class_name_item()
                self._advance_keypoint_row(row)
                self._save_current_annotations()
                return True

            if bbox.rect().contains(clicked_pos):
                x = clicked_pos.x() / img_width if img_width else 0.0
                y = clicked_pos.y() / img_height if img_height else 0.0
                drawer.points[row] = (x, y)

                visible_cb = self.main_window.keypoint_list.cellWidget(row, 3)
                drawer.visibility_flags[row] = 2 if visible_cb and visible_cb.isChecked() else 1

                drawer.update_points()
                drawer.update_class_name_item()

                self.main_window.keypoint_list.selectRow(row)
                self.main_window.clear_keypoint_highlight()
                self.main_window.highlight_keypoint_row(row)

                self._advance_keypoint_row(row)
                self._save_current_annotations()
            else:
                logger.debug("Clicked outside the selected bounding box.")
            return True

        if self.selected_bbox and self.selected_bbox.rect().contains(clicked_pos):
            if self.main_window.fast_label_checkbox.isChecked() and self.main_window.selected_keypoint_row is None:
                self.main_window.set_active_keypoint_row(
                    self.main_window.next_labelable_keypoint_row(0),
                    getattr(self.selected_bbox, "keypoint_drawer", None),
                )

            drawer.append_point(clicked_pos)
            self.scene().invalidate(self.scene().sceneRect(), QGraphicsScene.BackgroundLayer)
            self.viewport().update()
        return True

    def _handle_obb_press(self, event, scene_pos):
        try:
            if self.current_obb_drawer is not None and sip.isdeleted(self.current_obb_drawer):
                self.current_obb_drawer = None
                self.drawing_obb = False
        except Exception:
            self.current_obb_drawer = None
            self.drawing_obb = False

        if event.button() == Qt.LeftButton:
            # Ignore extra left presses while an OBB is already mid-draw
            if self.current_obb_drawer is not None:
                return

            if hasattr(self.main_window, "clear_blank_overlay"):
                self.main_window.clear_blank_overlay(self.scene())

            self.current_obb_drawer = OBBDrawer(self.main_window)

            current_file = getattr(self.main_window, "current_file", None)
            if current_file:
                self.current_obb_drawer.file_name = os.path.abspath(current_file).replace("\\", "/")

            self.current_obb_drawer.setAcceptedMouseButtons(Qt.NoButton)
            self.scene().addItem(self.current_obb_drawer)

            clamped = self.current_obb_drawer.clamp_point_to_image(scene_pos)
            self.current_obb_drawer.centerline_start = clamped
            self.current_obb_drawer.centerline_end = clamped
            self.current_obb_drawer.current_width = 0.0
            self.current_obb_drawer.current_state = "defining_centerline"
            self.drawing_obb = True

            color = get_color(
                self.current_obb_drawer.class_id,
                self.main_window.classes_dropdown.count(),
                alpha=255,
            )
            pen = QPen(color, 2)

            self.current_obb_drawer.centerline_item = self.scene().addLine(
                clamped.x(),
                clamped.y(),
                clamped.x(),
                clamped.y(),
                pen,
            )
            self.current_obb_drawer.centerline_item.setAcceptedMouseButtons(Qt.NoButton)
            self.current_obb_drawer.centerline_item.setZValue(1000)

            self.viewport().update()
            return

        if event.button() == Qt.RightButton:
            if self.current_obb_drawer is not None and self.current_obb_drawer.current_state != "bb_defined":
                self._clear_current_obb_drawer()
                self.viewport().update()
                return

            self._handle_right_button_press(event)
        return

    def mousePressEvent(self, event):
        scene_pos = self.mapToScene(event.pos())
        self.last_mouse_pos = event.pos()
        self.last_mouse_position = event.pos()

        if getattr(self.main_window, "train_view_active", False) and event.button() in (Qt.LeftButton, Qt.RightButton):
            event.accept()
            return

        if self.main_window.edit_mode_active():
            super().mousePressEvent(event)
            return

        if self.main_window.is_keypoint_mode():
            if self._handle_keypoint_press(event, scene_pos):
                return
            return

        if event.button() == Qt.RightButton:
            # Let an active OBB cancel on right click
            if self.current_obb_drawer is not None:
                self._handle_obb_press(event, scene_pos)
                return

            self._handle_right_button_press(event)
            return

        if event.button() == Qt.MiddleButton:
            self.setCursor(Qt.ClosedHandCursor)
            self.moving_view = True
            self.last_mouse_pos = event.pos()
            self.last_mouse_position = event.pos()
            return

        # OBB mode is exclusive
        if self.main_window.is_obb_mode():
            # If a stale OBB object exists but is not actively drawing, clear it
            if self.current_obb_drawer is not None:
                state = getattr(self.current_obb_drawer, "current_state", None)
                if state not in ("defining_centerline", "awaiting_width_point", "moving_bb"):
                    self._clear_current_obb_drawer()

            self._handle_obb_press(event, scene_pos)
            return

        # If user left OBB mode, clear any stale OBB drawer
        if self.current_obb_drawer is not None:
            self._clear_current_obb_drawer()

        if self.main_window.is_segmentation_mode():
            self._start_segmentation_drawing(event)
            self.update()
            return

        self._start_drawing(event)
        self.update()

    def mouseMoveEvent(self, event):
        scene_pos = self.mapToScene(event.pos())

        # If an OBB is active, keep driving it no matter what mode flags say
        if self.current_obb_drawer is not None:
            state = self.current_obb_drawer.current_state

            if state == "defining_centerline":
                clamped = self.current_obb_drawer.clamp_point_to_image(scene_pos)
                self.current_obb_drawer.centerline_end = clamped
                self.current_obb_drawer.drawing_in_progress = True
                if self.current_obb_drawer.centerline_item:
                    self.current_obb_drawer.centerline_item.setLine(
                        self.current_obb_drawer.centerline_start.x(),
                        self.current_obb_drawer.centerline_start.y(),
                        clamped.x(),
                        clamped.y(),
                    )
                return

            if state == "awaiting_width_point":
                self.current_obb_drawer.update_preview(scene_pos)
                return

            if state == "moving_bb":
                self.current_obb_drawer.update_position(scene_pos)
                return

        if self.main_window.edit_mode_active():
            super().mouseMoveEvent(event)
            return

        if self.main_window.is_segmentation_mode() and self.current_segmentation:
            self._handle_segmentation_drawing(event)
            return

        if self.drawing and self.current_bbox:
            self._handle_drawing_bbox(event)
            return

        if self.moving_view and event.buttons() & Qt.MiddleButton:
            delta = self.mapToScene(event.pos()) - self.mapToScene(self.last_mouse_pos)
            self.last_mouse_pos = event.pos()
            self.last_mouse_position = event.pos()
            self.translate(-delta.x(), -delta.y())

            if self.main_window is not None and hasattr(self.main_window, "capture_zoom_lock_state"):
                if self.main_window.is_zoom_locked():
                    self.main_window.capture_zoom_lock_state()

            return

        if self.show_crosshair:
            self._update_crosshair(event.pos())

        super().mouseMoveEvent(event)

    def _finalize_annotation_and_refresh(self, play_sound=True):
        img_width, img_height = self._get_image_dimensions()
        current_file = getattr(self.main_window, "current_file", None)

        if not current_file or not os.path.exists(current_file):
            logger.debug("Skipping save/refresh: no active dataset image.")
            return

        if getattr(self.main_window, "_loading_image", False):
            logger.debug("Skipping save/refresh: image is currently loading.")
            return

        scene = self.scene()

        if hasattr(self.main_window, "save_bounding_boxes"):
            self.main_window.save_bounding_boxes(
                current_file,
                img_width,
                img_height,
            )

        if hasattr(self.main_window, "sync_scene_annotation_cache"):
            self.main_window.sync_scene_annotation_cache(current_file)

        if hasattr(self.main_window, "update_blank_overlay_state"):
            self.main_window.update_blank_overlay_state(scene)

        if play_sound:
            self.set_sound("sounds/createcock.wav")
            self.sound_player.play()

        current_page = getattr(self.main_window, "current_page", 0)
        self.main_window.show_thumbnail_page(current_file, page=current_page)

        if scene:
            scene.update()

        self.viewport().update()

    def mouseReleaseEvent(self, event):
        # If an OBB is active, keep release handling on that OBB until finished
        if self.current_obb_drawer is not None:
            scene_pos = self.mapToScene(event.pos())

            if event.button() == Qt.LeftButton:
                if self.current_obb_drawer.current_state == "defining_centerline":
                    clamped = self.current_obb_drawer.clamp_point_to_image(scene_pos)
                    self.current_obb_drawer.centerline_end = clamped
                    self.current_obb_drawer.current_state = "awaiting_width_point"
                    self.drawing_obb = False

                    if self.current_obb_drawer.centerline_item:
                        self.scene().removeItem(self.current_obb_drawer.centerline_item)
                        self.current_obb_drawer.centerline_item = None
                        self.current_obb_drawer.setAcceptedMouseButtons(Qt.NoButton)
                        self.viewport().update()
                    self.viewport().update()
                    return

                elif self.current_obb_drawer.current_state == "awaiting_width_point":
                    poly = self.current_obb_drawer.polygon()

                    if poly.count() == 4 and self.current_obb_drawer.current_width > 0:
                        self.current_obb_drawer.finalize()
                        self._post_finalize_refresh_only(play_sound=True)
                    else:
                        self.current_obb_drawer.remove_self()

                        if hasattr(self.main_window, "update_blank_overlay_state"):
                            self.main_window.update_blank_overlay_state(self.scene())

                    self.current_obb_drawer = None
                    self.drawing_obb = False

                    if self.scene():
                        self.scene().update()

                    self.viewport().update()
                    return

            elif event.button() == Qt.RightButton:
                self.right_click_timer.stop()
                return

            elif event.button() == Qt.MiddleButton:
                self.current_obb_drawer.stop_moving()
                self.setCursor(Qt.ArrowCursor)
                self.moving_view = False
                return

        if self.main_window.edit_mode_active():
            super().mouseReleaseEvent(event)
            return

        if event.button() == Qt.LeftButton and self.drawing:
            if self.main_window.is_segmentation_mode() and self.current_segmentation:
                seg = self.current_segmentation

                self.current_segmentation = None
                self.drawing = False
                self.setCursor(Qt.ArrowCursor)

                if len(seg.points) >= 3:
                    seg.finalize()
                    self._post_finalize_refresh_only(play_sound=True)

                    seg.setFlag(QGraphicsItem.ItemIsMovable, False)
                    seg.setSelected(False)
                    seg.clearFocus()
                else:
                    if seg.scene():
                        self.scene().removeItem(seg)

                    if hasattr(self.main_window, "update_blank_overlay_state"):
                        self.main_window.update_blank_overlay_state(self.scene())

                if self.scene():
                    self.scene().clearSelection()
                    self.scene().update()

                self.viewport().update()
                event.accept()
                return

            elif self.current_bbox:
                self._finalize_bbox()
                self.drawing = False
                event.accept()
                return

        if event.button() == Qt.RightButton:
            self.right_click_timer.stop()

        if event.button() == Qt.MiddleButton:
            self.moving_view = False

        super().mouseReleaseEvent(event)
        self.setCursor(Qt.ArrowCursor)

    def _start_segmentation_drawing(self, event):
        self.drawing = True
        self.start_point = self.mapToScene(event.pos())

        if hasattr(self.main_window, "clear_blank_overlay"):
            self.main_window.clear_blank_overlay(self.scene())

        self.current_segmentation = SegmentationDrawer(
            points=[],
            main_window=self.main_window,
            class_id=self.main_window.get_current_class_id(),
        )

        current_file = getattr(self.main_window, "current_file", None)
        if current_file:
            self.current_segmentation.file_name = os.path.abspath(current_file).replace("\\", "/")

        self.current_segmentation.setZValue(20)
        self.scene().addItem(self.current_segmentation)
        self.scene().update()
        self.viewport().update()

    def _start_drawing(self, event):
        self.drawing = True
        self.start_point = self.mapToScene(event.pos())
        self.setCursor(Qt.CrossCursor)

        if hasattr(self.main_window, "clear_blank_overlay"):
            self.main_window.clear_blank_overlay(self.scene())

        self.current_bbox = BoundingBoxDrawer(
            self.start_point.x(),
            self.start_point.y(),
            0,
            0,
            main_window=self.main_window,
            class_id=self.main_window.get_current_class_id(),
        )

        current_file = getattr(self.main_window, "current_file", None)
        if current_file:
            self.current_bbox.file_name = os.path.abspath(current_file).replace("\\", "/")

        self.current_bbox.set_z_order(bring_to_front=True)
        self.current_bbox.setZValue(10)
        self.current_bbox.setVisible(True)
        self.current_bbox.setEnabled(True)

        self.scene().addItem(self.current_bbox)
        self.scene().update()
        self.viewport().update()

    def _handle_right_button_press(self, event):
        scene = self.scene()
        if scene is None:
            return

        click_pos = self.mapToScene(event.pos())
        tolerance = 10

        if self.main_window.rapid_del_checkbox.isChecked():
            self.right_click_timer.start()
            return

        items_at_pos = scene.items(click_pos)
        candidate_items = []

        for item in items_at_pos:
            try:
                if sip.isdeleted(item):
                    continue
            except Exception:
                continue

            if isinstance(item, BoundingBoxDrawer):
                hit_rect = item.rect().adjusted(-tolerance, -tolerance, tolerance, tolerance)
                if hit_rect.contains(click_pos):
                    area = max(1.0, item.rect().width() * item.rect().height())
                    candidate_items.append((0, area, -item.zValue(), item))

            elif isinstance(item, SegmentationDrawer):
                local_pos = item.mapFromScene(click_pos)
                if item.contains(local_pos):
                    br = item.polygon.boundingRect()
                    area = max(1.0, br.width() * br.height())
                    candidate_items.append((1, area, -item.zValue(), item))

            elif isinstance(item, OBBDrawer):
                local_pos = item.mapFromScene(click_pos)
                if item.contains(local_pos):
                    br = item.boundingRect()
                    area = max(1.0, br.width() * br.height())
                    candidate_items.append((2, area, -item.zValue(), item))

        if not candidate_items:
            return

        bbox_candidates = [
            entry[-1]
            for entry in candidate_items
            if isinstance(entry[-1], BoundingBoxDrawer)
        ]

        if self.selected_bbox in bbox_candidates:
            self._play_sound_and_remove_bbox(self.selected_bbox)
            return

        candidate_items.sort(key=lambda x: (x[1], x[2]))
        chosen = candidate_items[0][-1]

        if isinstance(chosen, OBBDrawer) and chosen is self.current_obb_drawer:
            self.current_obb_drawer = None
            self.drawing_obb = False

        self._play_sound_and_remove_bbox(chosen)

    def _play_sound_and_remove_bbox(self, item):
        try:
            if item is None or sip.isdeleted(item):
                return
        except Exception:
            return

        current_file = getattr(self.main_window, "current_file", None)
        annotation_scene_active = getattr(self.main_window, "annotation_scene_active", True)

        can_save_dataset = (
            current_file
            and annotation_scene_active
            and not self.main_window.is_placeholder_file(current_file)
            and os.path.exists(current_file)
        )

        self.set_sound("sounds/shotgun.wav")
        self.sound_player.play()

        if item == self.selected_bbox:
            self.selected_bbox = None

        if item in self.bboxes:
            self.bboxes.remove(item)

        if item is getattr(self, "current_bbox", None):
            self.current_bbox = None

        if item is getattr(self, "current_segmentation", None):
            self.current_segmentation = None

        if item is getattr(self, "current_obb_drawer", None):
            self.current_obb_drawer = None
            self.drawing_obb = False

        # Remove child label/badge/leader items if they exist.
        for attr_name in ("class_name_item", "label_badge_item", "label_leader_item"):
            child = getattr(item, attr_name, None)
            if child is not None:
                self.safe_remove_item(child)

        # Remove main annotation item from scene.
        self.safe_remove_item(item)

        if not can_save_dataset:
            logger.debug("Skipping save after deletion: no active dataset image.")
            if self.scene():
                self.scene().update()
            self.viewport().update()
            return

        # Save the current scene after removing the target annotation.
        scene = self.scene()

        if scene is not None and hasattr(self.main_window, "save_bounding_boxes"):
            self.main_window.save_bounding_boxes(
                current_file,
                scene.width(),
                scene.height(),
            )

        if hasattr(self.main_window, "sync_scene_annotation_cache"):
            self.main_window.sync_scene_annotation_cache(current_file)

        if hasattr(self.main_window, "update_blank_overlay_state"):
            self.main_window.update_blank_overlay_state(scene)

        current_page = getattr(self.main_window, "current_page", 0)
        self.main_window.show_thumbnail_page(current_file, page=current_page)

        if scene:
            scene.update()

        self.viewport().update()

    def _save_and_play_sound(self):
        current_file = getattr(self.main_window, "current_file", None)

        if not current_file or not os.path.exists(current_file):
            logger.warning("Cannot save bbox: no active dataset image.")
            return

        if self.current_bbox:
            self.current_bbox.file_name = os.path.abspath(current_file).replace("\\", "/")
            self.current_bbox.update_bbox()
            self.current_bbox.update_class_name_item()

        self.main_window.set_selected(None)
        self._finalize_annotation_and_refresh(play_sound=True)

    def _handle_segmentation_drawing(self, event):
        try:
            if not self.drawing:
                return

            if self.current_segmentation is None:
                self.drawing = False
                return

            try:
                if sip.isdeleted(self.current_segmentation):
                    self.current_segmentation = None
                    self.drawing = False
                    return
            except Exception:
                self.current_segmentation = None
                self.drawing = False
                return

            end_point = self.mapToScene(event.pos())
            img_width = self.scene().width()
            img_height = self.scene().height()

            clamped_x = max(0, min(img_width - 1, end_point.x()))
            clamped_y = max(0, min(img_height - 1, end_point.y()))
            clamped_point = QPointF(clamped_x, clamped_y)

            self.current_segmentation.append_point(clamped_point)
            self.current_segmentation.update_polygon()

        except RuntimeError as e:
            logger.error(f"Error while drawing segmentation: {e}")
            self.current_segmentation = None
            self.drawing = False
        except Exception as e:
            logger.error(f"Unexpected error in segmentation drawing: {e}")
            self.current_segmentation = None
            self.drawing = False

    def _update_crosshair(self, pos):
        self.crosshair_position = pos
        self.viewport().update()

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter(self.viewport())

        if self.show_crosshair:
            painter.setPen(QColor(*self.crosshair_color_rgb) if hasattr(self, "crosshair_color_rgb") else Qt.yellow)
            center_x = int(self.crosshair_position.x())
            center_y = int(self.crosshair_position.y())
            painter.drawLine(center_x, self.viewport().rect().top(), center_x, self.viewport().rect().bottom())
            painter.drawLine(self.viewport().rect().left(), center_y, self.viewport().rect().right(), center_y)

        painter.end()

    def _handle_drawing_bbox(self, event):
        try:
            end_point = self.mapToScene(event.pos())
            start_point = np.array([self.start_point.x(), self.start_point.y()], dtype=int)
            end_point_np = np.array([end_point.x(), end_point.y()], dtype=int)

            scene_rect = self.sceneRect()
            min_point = np.clip(
                np.minimum(start_point, end_point_np),
                [scene_rect.left(), scene_rect.top()],
                [scene_rect.right(), scene_rect.bottom()],
            ).astype(int)

            max_point = np.clip(
                np.maximum(start_point, end_point_np),
                [scene_rect.left(), scene_rect.top()],
                [scene_rect.right(), scene_rect.bottom()],
            ).astype(int)

            dimensions = np.maximum(max_point - min_point, 0)
            x, y = min_point
            width, height = dimensions
            self.current_bbox.setRect(x, y, width, height)
            self.current_bbox.normalize_rect()
            self.current_bbox.update_class_name_item()

        except RuntimeError as e:
            logger.error(f"Error drawing bbox: {e}")
        except Exception as e:
            logger.error(f"Unexpected bbox drawing error: {e}")

    def preprocess_roi_for_contours(self, roi):
        blurred = cv2.GaussianBlur(roi, (3, 3), 0)
        edges = cv2.Canny(blurred, 50, 150)
        return edges

    def snap_bbox_to_contour(self, gray_img, min_point, max_point):
        x1, y1 = min_point
        x2, y2 = max_point

        img_h, img_w = gray_img.shape[:2]
        x1, y1 = np.clip([x1, y1], [0, 0], [img_w - 1, img_h - 1])
        x2, y2 = np.clip([x2, y2], [0, 0], [img_w - 1, img_h - 1])

        roi = gray_img[y1:y2, x1:x2]
        processed_roi = self.preprocess_roi_for_contours(roi)

        contours, _ = cv2.findContours(processed_roi, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

        if contours:
            x, y, w, h = cv2.boundingRect(np.vstack(contours))
            snapped_min_point = np.array([x1 + x, y1 + y])
            snapped_max_point = snapped_min_point + [w, h]
            return snapped_min_point, snapped_max_point

        return min_point, max_point

    def _current_bbox_size_allowed(self):
        if not self.current_bbox:
            return False

        rect = self.current_bbox.rect().normalized()
        width = float(rect.width())
        height = float(rect.height())

        if width <= 0.0 or height <= 0.0:
            return False

        img_width, img_height = self._get_image_dimensions()
        if (
            self.main_window is not None
            and hasattr(self.main_window, "annotation_pixel_size_allowed")
            and img_width > 0
            and img_height > 0
        ):
            return self.main_window.annotation_pixel_size_allowed(width, height, img_width, img_height)

        return width >= BoundingBoxDrawer.MIN_SIZE and height >= BoundingBoxDrawer.MIN_SIZE

    def _discard_current_bbox(self):
        if not self.current_bbox:
            return

        scene = self.scene()
        class_name_item = getattr(self.current_bbox, "class_name_item", None)

        if self.current_bbox.scene() and scene:
            scene.removeItem(self.current_bbox)

        if class_name_item is not None and class_name_item.scene() and scene:
            scene.removeItem(class_name_item)

    def _finalize_bbox(self):
        try:
            if self.current_bbox and self._current_bbox_size_allowed():
                if self.main_window.outline_Checkbox.isChecked() and hasattr(self.main_window, "processed_image"):
                    image_np = self.main_window.processed_image

                    if image_np is not None and isinstance(image_np, np.ndarray) and image_np.size > 0:
                        rect = self.current_bbox.rect()

                        x1 = int(rect.x())
                        y1 = int(rect.y())
                        x2 = int(rect.x() + rect.width())
                        y2 = int(rect.y() + rect.height())

                        img_h, img_w = image_np.shape[:2]

                        x1 = max(0, min(x1, img_w - 1))
                        y1 = max(0, min(y1, img_h - 1))
                        x2 = max(0, min(x2, img_w - 1))
                        y2 = max(0, min(y2, img_h - 1))

                        snapped = None

                        if x2 > x1 and y2 > y1:
                            bbox_prompt = self.main_window.pad_bbox_xyxy(
                                [x1, y1, x2, y2],
                                img_w,
                                img_h,
                                pad_ratio=0.05
                            )

                            mask = self.main_window.sam_snap_bbox_to_mask(
                                image_np,
                                bbox_prompt,
                                imgsz=1036
                            )

                            class_name = self.main_window.get_current_class_name_safe(
                                getattr(self.current_bbox, "class_id", None)
                            )

                            if self.main_window.validate_sam_mask_for_bbox(
                                mask,
                                [x1, y1, x2, y2],
                                class_name=class_name
                            ):
                                snapped = self.main_window.mask_to_bbox_rect(mask)

                        if snapped:
                            sx, sy, sw, sh = snapped

                            self.current_bbox.setRect(int(sx), int(sy), int(sw), int(sh))
                            self.current_bbox.normalize_rect()
                            self.current_bbox.update_bbox()
                            self.current_bbox.update_class_name_item()

                            logger.debug("BBox snapped using SAM3.")

                        else:
                            gray_img = image_np

                            if len(gray_img.shape) == 3:
                                if gray_img.shape[2] == 3:
                                    gray_img = cv2.cvtColor(gray_img, cv2.COLOR_BGR2GRAY)
                                elif gray_img.shape[2] == 4:
                                    gray_img = cv2.cvtColor(gray_img, cv2.COLOR_BGRA2GRAY)

                            min_point = np.array([x1, y1], dtype=int)
                            max_point = np.array([x2, y2], dtype=int)

                            min_point, max_point = self.snap_bbox_to_contour(
                                gray_img,
                                min_point,
                                max_point
                            )

                            sx, sy = min_point
                            sw, sh = max_point - min_point

                            if sw > 1 and sh > 1:
                                self.current_bbox.setRect(int(sx), int(sy), int(sw), int(sh))
                                self.current_bbox.normalize_rect()
                                self.current_bbox.update_bbox()
                                self.current_bbox.update_class_name_item()

                                logger.debug("BBox snapped using edge fallback.")

                if not self._current_bbox_size_allowed():
                    self._discard_current_bbox()
                    return

                self._save_and_play_sound()

            else:
                self._discard_current_bbox()

        except RuntimeError as e:
            logger.error(f"Runtime error finalizing bounding box: {e}")

        except Exception as e:
            logger.error(f"Unexpected error finalizing bounding box: {e}")

        finally:
            self.drawing = False
            self.current_bbox = None
            self.clear_selection()
            self.setCursor(Qt.ArrowCursor)

    def clear_selection(self):
        if self.selected_bbox:
            try:
                if not sip.isdeleted(self.selected_bbox) and self.selected_bbox.boundingRect().isValid():
                    self.selected_bbox.set_selected(False)
            except Exception:
                pass
            self.selected_bbox = None

    def toggle_crosshair(self, checked):
        self.show_crosshair = bool(checked)

        if self.main_window is not None and hasattr(self.main_window, "settings"):
            self.main_window.settings["showXYLines"] = self.show_crosshair
            self.main_window.saveSettings()

        self.viewport().update()

    def _clear_current_obb_drawer(self):
        """Safely clear the active OBB drawer reference."""
        try:
            if self.current_obb_drawer is not None:
                try:
                    if not sip.isdeleted(self.current_obb_drawer):
                        if self.current_obb_drawer.scene() is not None:
                            self.current_obb_drawer.remove_self()
                except Exception:
                    pass
        finally:
            self.current_obb_drawer = None
            self.drawing_obb = False

    def _post_finalize_refresh_only(self, play_sound=True):
        """
        Refresh preview/cache/blank overlay after an annotation class finalized itself.
        Use this for SegmentationDrawer.finalize() and OBBDrawer.finalize()
        when those finalize methods already save internally.
        """
        current_file = getattr(self.main_window, "current_file", None)
        scene = self.scene()

        if not current_file or not os.path.exists(current_file):
            return

        if hasattr(self.main_window, "sync_scene_annotation_cache"):
            self.main_window.sync_scene_annotation_cache(current_file)

        if hasattr(self.main_window, "update_blank_overlay_state"):
            self.main_window.update_blank_overlay_state(scene)

        if play_sound:
            self.set_sound("sounds/createcock.wav")
            self.sound_player.play()

        current_page = getattr(self.main_window, "current_page", 0)
        self.main_window.show_thumbnail_page(current_file, page=current_page)

        if scene:
            scene.update()

        self.viewport().update()


class BoundingBoxDrawer(QGraphicsRectItem):
    MIN_SIZE = 6
    MAX_SIZE = 100

    def __init__(self, x, y, width, height, main_window, class_id=None, confidence=None, unique_id=None):
        super().__init__(x, y, width, height)
        self.unique_id = unique_id
        self.main_window = main_window
        self.class_id = 0 if class_id is None else class_id
        self.confidence = confidence
        self.dragStartPos = None
        self.final_pos = None
        self.keypoint_drawer = None
        self.true_line_index = getattr(self, "true_line_index", None)

        self.edit_mode = False
        self.vertex_handles = []
        self._is_hovered = False
        self.hover_opacity = 1.0
        self.normal_opacity = 0.6

        class_names = [
            main_window.classes_dropdown.itemText(i)
            for i in range(main_window.classes_dropdown.count())
        ]
        self._class_color = get_color(self.class_id, len(class_names), class_names=class_names)
        self._pen = QPen(self._class_color, 2)

        self.setFlags(
            QGraphicsItem.ItemIsSelectable
            | QGraphicsItem.ItemIsFocusable
            | QGraphicsItem.ItemSendsGeometryChanges
        )
        self.setAcceptHoverEvents(True)
        self.setPen(self._pen)

        self._text_pos = QPointF(5, 5)
        self._last_rect = self.rect()
        self.class_name_item = QGraphicsTextItem(self)
        self.label_leader_item = QGraphicsLineItem(self)
        self.label_leader_item.setZValue(4)

        self.label_badge_item = QGraphicsPathItem(self)
        self.label_badge_item.setZValue(5)

        self.class_name_item.setZValue(6)
        self.setOpacity(self.normal_opacity)

        self.flash_color = QColor(255, 0, 0)
        self.alternate_flash_color = QColor(0, 0, 255)
        self.flash_timer = QTimer()
        self.flash_timer.timeout.connect(self.toggle_flash_color)
        self.scroll_timer = QTimer()
        self.scroll_timer.setSingleShot(True)
        self.scroll_timer.timeout.connect(self.stop_flashing)

        self.normalize_rect()
        self.update_bbox()
        self.update_class_name_item()
        self.class_name_item.setVisible(not self.main_window.settings.get("hideLabels", False))
        self._font_size_connection = connect_weak_bound_signal(
            self.main_window.font_size_slider.valueChanged,
            self.update_class_name_item_font
        )
        self.set_z_order(bring_to_front=True)

    def set_z_order(self, bring_to_front=False):
        if bring_to_front:
            self.setZValue(1.0)
        elif self.zValue() < 1.0:
            self.setZValue(0.5)

    def normalize_rect(self):
        raw_rect = self.rect()
        normalized = QRectF(
            min(raw_rect.left(), raw_rect.right()),
            min(raw_rect.top(), raw_rect.bottom()),
            abs(raw_rect.width()),
            abs(raw_rect.height()),
        )
        super().setRect(normalized)

    def itemChange(self, change, value):
        if change in (QGraphicsItem.ItemPositionChange, QGraphicsItem.ItemTransformChange):
            self.normalize_rect()
            self.update_class_name_item()
            self.update_bbox()
        return super().itemChange(change, value)

    def hoverEnterEvent(self, event):
        if self._is_hovered:
            return

        scene = self.scene()
        if scene:
            scene_pos = self.mapToScene(event.pos())
            boxes = [item for item in scene.items(scene_pos) if isinstance(item, BoundingBoxDrawer)]
            boxes.sort(key=lambda x: x.zValue(), reverse=True)

            if boxes and boxes[0] == self:
                self.set_z_order(bring_to_front=True)

        self.setOpacity(self.hover_opacity)
        self._is_hovered = True
        super().hoverEnterEvent(event)

    def hoverLeaveEvent(self, event):
        if not self._is_hovered:
            return

        self.setOpacity(self.normal_opacity)
        self._is_hovered = False
        super().hoverLeaveEvent(event)

    def start_flashing(self, interval, duration):
        self.flash_timer.start(interval)
        QTimer.singleShot(duration, self.stop_flashing)

    def stop_flashing(self):
        self.flash_timer.stop()
        self.reset_color()

    def toggle_flash_color(self):
        current_color = self.pen().color()
        next_color = self.flash_color if current_color == self.alternate_flash_color else self.alternate_flash_color
        self.setPen(QPen(next_color, 2))

    def paint(self, painter, option, widget=None):
        super().paint(painter, option, widget)

        rect = self.rect()
        shade_value = self.main_window.shade_slider.value()
        color = self.pen().color()

        shade_value = max(0, min(int(shade_value), 255))

        shaded_color = QColor(
            color.red(),
            color.green(),
            color.blue(),
            shade_value
        )

        painter.setBrush(QBrush(shaded_color))
        painter.setPen(Qt.NoPen)
        painter.drawRect(rect)

    def update_class_name_item(self):
        rect = self.rect()
        self._last_rect = rect

        class_name = self.main_window.classes_dropdown.itemText(self.class_id)
        self.class_name_item.setPlainText(class_name)
        self.class_name_item.setDefaultTextColor(QColor(255, 255, 255))

        font = self.class_name_item.font()
        font.setPointSize(self.main_window.font_size_slider.value())
        self.class_name_item.setFont(font)

        self._update_label_badge()

        visible = not self.main_window.settings.get("hideLabels", False)
        self.class_name_item.setVisible(visible)

        if hasattr(self, "label_badge_item"):
            self.label_badge_item.setVisible(visible)

        if hasattr(self, "label_leader_item"):
            self.label_leader_item.setVisible(visible)

    def _update_label_badge(self):
        if not hasattr(self, "class_name_item") or self.class_name_item is None:
            return

        if not hasattr(self, "label_badge_item") or self.label_badge_item is None:
            self.label_badge_item = QGraphicsPathItem(self)
            self.label_badge_item.setZValue(5)

        if not hasattr(self, "label_leader_item") or self.label_leader_item is None:
            self.label_leader_item = QGraphicsLineItem(self)
            self.label_leader_item.setZValue(4)

        rect = self.rect()
        img_w, img_h = self._get_image_dimensions()
        if img_w <= 0 or img_h <= 0:
            return

        text_rect = self.class_name_item.boundingRect()
        badge_w = max(38, text_rect.width() + 12)
        badge_h = max(20, text_rect.height() + 6)

        anchor = QPointF(rect.center().x(), rect.top())

        gap = 10
        label_x = anchor.x() - badge_w / 2
        label_y = anchor.y() - badge_h - gap

        if label_y < 4:
            label_y = anchor.y() + gap

        label_x = max(4, min(label_x, img_w - badge_w - 4))
        label_y = max(4, min(label_y, img_h - badge_h - 4))

        self.class_name_item.setPos(label_x + 6, label_y + 2)

        badge_rect = QRectF(label_x, label_y, badge_w, badge_h)
        path = QPainterPath()
        path.addRoundedRect(badge_rect, 5, 5)

        color = self.pen().color()
        badge_color = QColor(color.red(), color.green(), color.blue(), 210)

        self.label_badge_item.setPath(path)
        self.label_badge_item.setBrush(QBrush(badge_color))
        self.label_badge_item.setPen(QPen(QColor(255, 255, 255, 210), 1.25))

        badge_anchor = QPointF(
            label_x + badge_w / 2,
            label_y + badge_h,
        )

        leader_pen = QPen(badge_color, 2)
        leader_pen.setCapStyle(Qt.RoundCap)

        self.label_leader_item.setLine(
            anchor.x(),
            anchor.y(),
            badge_anchor.x(),
            badge_anchor.y(),
        )
        self.label_leader_item.setPen(leader_pen)

    def update_class_color_and_position(self):
        self.update_class_name_item()

    def update_class_name_item_font(self, value=None):
        safe_update_class_name_item_font(self, value)

    def set_class_id(self, class_id):
        try:
            if sip.isdeleted(self):
                return
        except Exception:
            return

        self.class_id = class_id
        class_names = [
            self.main_window.classes_dropdown.itemText(i)
            for i in range(self.main_window.classes_dropdown.count())
        ]
        self._class_color = get_color(self.class_id, len(class_names), class_names=class_names)
        self._pen = QPen(self._class_color, 2)
        self.setPen(self._pen)
        self.update_bbox()
        self.update_class_name_item()

    def update_bbox(self):
        rect = self.rect()
        scene = self.scene()
        if not scene:
            return

        img_width = scene.width()
        img_height = scene.height()
        if img_width <= 0 or img_height <= 0:
            return

        x_center = (rect.x() + rect.width() / 2) / img_width
        y_center = (rect.y() + rect.height() / 2) / img_height
        width = rect.width() / img_width
        height = rect.height() / img_height

        self.bbox = BoundingBox(int(self.class_id), x_center, y_center, width, height, self.confidence)

        if self.keypoint_drawer and hasattr(self.keypoint_drawer, "visibility_flags"):
            self.bbox.keypoints = [
                (x, y, v)
                for (x, y), v in zip(self.keypoint_drawer.points, self.keypoint_drawer.visibility_flags)
            ]

    def refresh_keypoint_drawer(self):
        drawer = getattr(self, "keypoint_drawer", None)
        if drawer is None:
            return
        try:
            drawer.update_points()
            drawer.update_class_name_item()
            drawer.update()
        except RuntimeError:
            self.keypoint_drawer = None
        except Exception as e:
            logger.warning(f"Failed refreshing keypoint drawer after bbox update: {e}")

    def set_selected(self, selected):
        try:
            if sip.isdeleted(self):
                return
        except Exception:
            return

        self.setSelected(selected)
        self.set_z_order(bring_to_front=selected)

    def _get_image_dimensions(self):
        return graphics_image_dimensions(self)

    def _clamp_scene_point(self, point):
        img_width, img_height = self._get_image_dimensions()
        return QPointF(
            max(0, min(point.x(), img_width - 1)),
            max(0, min(point.y(), img_height - 1)),
        )

    def _rebuild_vertex_handles(self):
        if not self.scene():
            return

        for handle in self.vertex_handles:
            if handle.scene():
                handle.scene().removeItem(handle)
        self.vertex_handles = []

        rect = self.rect()
        corners = [
            QPointF(rect.left(), rect.top()),
            QPointF(rect.right(), rect.top()),
            QPointF(rect.right(), rect.bottom()),
            QPointF(rect.left(), rect.bottom()),
        ]

        for idx, pt in enumerate(corners):
            handle = BoxVertexHandle(self, idx)
            handle.setPos(pt)
            self.scene().addItem(handle)
            self.vertex_handles.append(handle)

    def _sync_vertex_handles(self):
        if not self.vertex_handles:
            return

        rect = self.rect()
        corners = [
            QPointF(rect.left(), rect.top()),
            QPointF(rect.right(), rect.top()),
            QPointF(rect.right(), rect.bottom()),
            QPointF(rect.left(), rect.bottom()),
        ]

        for idx, handle in enumerate(self.vertex_handles):
            handle.setPos(corners[idx])

    def enter_edit_mode(self):
        self.edit_mode = True
        self.setPen(QPen(QColor(0, 255, 0), 2))
        self._rebuild_vertex_handles()

    def finalize_edit_mode(self):
        self.edit_mode = False

        for handle in list(self.vertex_handles):
            try:
                if handle.scene():
                    handle.scene().removeItem(handle)
            except RuntimeError:
                pass

        self.vertex_handles = []

        self.normalize_rect()

        # SAM3 snap for edited boxes when Enable Snap is checked.
        # If it fails, keep the edited rectangle.
        self._try_sam_snap_edit_bbox()

        self.update_bbox()
        self.refresh_keypoint_drawer()
        self.update_class_name_item()
        self.reset_color()

        img_width, img_height = self._get_image_dimensions()

        self.main_window.save_bounding_boxes(
            self.main_window.current_file,
            img_width,
            img_height,
        )
        if hasattr(self.main_window, "refresh_annotation_preview_after_save"):
            self.main_window.refresh_annotation_preview_after_save(self.main_window.current_file)

    def _try_sam_snap_edit_bbox(self):
        """
        Refine this bbox with SAM3 during edit mode finalization.
        Uses the same Enable Snap checkbox as normal drawing.
        Falls back silently if SAM3 fails.
        """
        if not self.main_window.outline_Checkbox.isChecked():
            return False

        if not hasattr(self.main_window, "processed_image"):
            return False

        image_np = self.main_window.processed_image

        if image_np is None or not isinstance(image_np, np.ndarray) or image_np.size == 0:
            return False

        try:
            img_h, img_w = image_np.shape[:2]

            rect = self.rect()
            x1 = int(rect.x())
            y1 = int(rect.y())
            x2 = int(rect.x() + rect.width())
            y2 = int(rect.y() + rect.height())

            x1 = max(0, min(x1, img_w - 1))
            y1 = max(0, min(y1, img_h - 1))
            x2 = max(0, min(x2, img_w - 1))
            y2 = max(0, min(y2, img_h - 1))

            if x2 <= x1 or y2 <= y1:
                return False

            bbox_prompt = self.main_window.pad_bbox_xyxy(
                [x1, y1, x2, y2],
                img_w,
                img_h,
                pad_ratio=0.05
            )

            mask = self.main_window.sam_snap_bbox_to_mask(
                image_np,
                bbox_prompt,
                imgsz=1036
            )

            class_name = self.main_window.get_current_class_name_safe(
                getattr(self, "class_id", None)
            )

            if not self.main_window.validate_sam_mask_for_bbox(
                mask,
                [x1, y1, x2, y2],
                class_name=class_name
            ):
                return False

            snapped = self.main_window.mask_to_bbox_rect(mask)

            if not snapped:
                return False

            sx, sy, sw, sh = snapped

            if sw <= 1 or sh <= 1:
                return False

            self.setRect(int(sx), int(sy), int(sw), int(sh))
            self.normalize_rect()
            self.update_bbox()
            self.refresh_keypoint_drawer()
            self.update_class_name_item()
            self._sync_vertex_handles()

            logger.debug("Edited bbox snapped using SAM3.")
            return True

        except Exception as e:
            logger.warning(f"SAM3 bbox edit snap failed: {e}")
            return False

    def toggle_edit_mode(self):
        if not self.edit_mode:
            self.enter_edit_mode()
        else:
            self.finalize_edit_mode()

    def update_point(self, index, new_scene_pos):
        if index not in (0, 1, 2, 3):
            return

        point = self._clamp_scene_point(new_scene_pos)
        rect = self.rect()

        left = rect.left()
        top = rect.top()
        right = rect.right()
        bottom = rect.bottom()

        if index == 0:
            left = point.x()
            top = point.y()
        elif index == 1:
            right = point.x()
            top = point.y()
        elif index == 2:
            right = point.x()
            bottom = point.y()
        elif index == 3:
            left = point.x()
            bottom = point.y()

        new_rect = QRectF(QPointF(left, top), QPointF(right, bottom)).normalized()

        if new_rect.width() < self.MIN_SIZE or new_rect.height() < self.MIN_SIZE:
            return

        super().setRect(new_rect)
        self.normalize_rect()
        self.update_bbox()
        self.refresh_keypoint_drawer()
        self.update_class_name_item()
        self._sync_vertex_handles()

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.LeftButton and not self.main_window.is_keypoint_mode():
            self.toggle_edit_mode()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def reset_color(self):
        class_names = [
            self.main_window.classes_dropdown.itemText(i)
            for i in range(self.main_window.classes_dropdown.count())
        ]
        self._class_color = get_color(self.class_id, len(class_names), class_names=class_names)
        self.setPen(QPen(self._class_color, 2))

    def mouseMoveEvent(self, event):
        if self.edit_mode:
            super().mouseMoveEvent(event)
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        try:
            if sip.isdeleted(self):
                return
        except Exception:
            return

        self.set_z_order(bring_to_front=False)
        super().mouseReleaseEvent(event)


class BoxVertexHandle(QGraphicsEllipseItem):

    def __init__(self, drawer, index, radius=4):
        super().__init__(-radius, -radius, radius * 2, radius * 2)
        self.drawer = drawer
        self.index = index
        self.active_color = QColor(0, 255, 0)
        self.default_color = QColor(Qt.red)

        self.setBrush(QBrush(self.default_color))
        self.setPen(QPen(QColor(255, 255, 255), 1))
        self.setCursor(Qt.OpenHandCursor)
        self.setZValue(10)

        self.setFlag(QGraphicsItem.ItemIsMovable, True)
        self.setFlag(QGraphicsItem.ItemIsSelectable, True)
        self.setFlag(QGraphicsItem.ItemSendsScenePositionChanges, True)

    def mousePressEvent(self, event):
        self.setBrush(QBrush(self.active_color))
        self.setCursor(Qt.ClosedHandCursor)
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        super().mouseMoveEvent(event)
        self.drawer.update_point(self.index, self.scenePos())

    def mouseReleaseEvent(self, event):
        self.setBrush(QBrush(self.default_color))
        self.setCursor(Qt.OpenHandCursor)
        super().mouseReleaseEvent(event)

    def itemChange(self, change, value):
        if change == QGraphicsItem.ItemScenePositionHasChanged:
            self.drawer.update_point(self.index, value)
        return super().itemChange(change, value)


class KeypointDrawer(QGraphicsItem):
    SKELETON_CONNECTIONS = []

    def __init__(self, points, main_window, class_id=None, unique_id=None, file_name=None, visibility_flags=None):
        super().__init__()

        self.main_window = main_window
        self.class_id = class_id if class_id is not None else main_window.get_current_class_id()
        self.unique_id = unique_id
        self.file_name = file_name if file_name else main_window.current_file
        self.points = points if isinstance(points, list) else []
        self.visibility_flags = visibility_flags if visibility_flags else [2] * len(self.points)
        self.current_index = 0

        self.setFlag(QGraphicsItem.ItemIsSelectable, True)
        self.setFlag(QGraphicsItem.ItemIsFocusable, True)
        self.setAcceptHoverEvents(True)

        self._dot_size_connection = connect_weak_bound_signal(
            self.main_window.dot_size_slider.valueChanged,
            self.update_dot_radius
        )
        self._font_size_connection = connect_weak_bound_signal(
            self.main_window.font_size_slider.valueChanged,
            self.update_class_name_item_font
        )

        self.point_items = []
        self.class_name_item = QGraphicsTextItem(self)
        self.class_name_item.setDefaultTextColor(QColor(255, 255, 255))
        self.class_name_item.setFont(QFont("Arial", self.main_window.font_size_slider.value(), QFont.Bold))

        self.update_class_name_item()
        self.update_points()

    def _get_image_dimensions(self):
        return graphics_image_dimensions(self, fallback_to_scene=False)

    def _to_scene_point(self, normalized_point):
        img_width, img_height = self._get_image_dimensions()
        return QPointF(normalized_point[0] * img_width, normalized_point[1] * img_height)

    def _to_normalized_point(self, scene_point):
        img_width, img_height = self._get_image_dimensions()
        if img_width <= 0 or img_height <= 0:
            return 0.0, 0.0
        return scene_point.x() / img_width, scene_point.y() / img_height

    def update_dot_radius(self, value=None):
        self.update()

    def get_keypoint_string(self):
        keypoint_strs = []
        total_rows = self.main_window.keypoint_list.rowCount()
        num_points = len(self.points)
        num_flags = len(self.visibility_flags)

        for i in range(total_rows):
            x, y = self.points[i] if i < num_points else (0.0, 0.0)
            if i < num_flags:
                v = self.visibility_flags[i]
            else:
                v = 2 if (x != 0.0 or y != 0.0) else 0
            keypoint_strs.append(f"{x:.6f} {y:.6f} {v}")

        return " ".join(keypoint_strs)

    def boundingRect(self):
        if not self.points:
            return QRectF()

        scaled_points = [self._to_scene_point((x, y)) for x, y in self.points]
        min_x = min(p.x() for p in scaled_points)
        min_y = min(p.y() for p in scaled_points)
        max_x = max(p.x() for p in scaled_points)
        max_y = max(p.y() for p in scaled_points)
        return QRectF(min_x, min_y, max_x - min_x, max_y - min_y)

    def paint(self, painter, option, widget):
        painter.setRenderHint(QPainter.Antialiasing)

        fallback_color = get_color(self.class_id, self.main_window.classes_dropdown.count(), alpha=200)
        pen = QPen(fallback_color, 2)
        brush = QBrush(fallback_color)
        painter.setPen(pen)
        painter.setBrush(brush)

        def point_color(index, alpha=200):
            if hasattr(self.main_window, "pose_keypoint_color_qcolor"):
                return self.main_window.pose_keypoint_color_qcolor(
                    index,
                    alpha=alpha,
                    fallback=fallback_color,
                )
            return fallback_color

        img_width, img_height = self._get_image_dimensions()
        zoom_factor = max(self.main_window.screen_view.transform().m11(), 0.01)

        slider_value = self.main_window.dot_size_slider.value()
        base_radius = slider_value / 2.0
        radius = max(0.5, min(base_radius / zoom_factor, 6.0))

        connections = getattr(self.main_window, "current_skeleton_connections", None)

        if connections is None:
            connections = getattr(KeypointDrawer, "SKELETON_CONNECTIONS", [])

        for i1, i2 in connections:
            if i1 >= len(self.points) or i2 >= len(self.points):
                continue

            if i1 >= len(self.visibility_flags) or i2 >= len(self.visibility_flags):
                continue

            if self.visibility_flags[i1] == 0 or self.visibility_flags[i2] == 0:
                continue

            x1, y1 = self.points[i1]
            x2, y2 = self.points[i2]

            if (x1, y1) == (0.0, 0.0) or (x2, y2) == (0.0, 0.0):
                continue

            p1 = QPointF(x1 * img_width, y1 * img_height)
            p2 = QPointF(x2 * img_width, y2 * img_height)

            color_1 = point_color(i1, alpha=180)
            color_2 = point_color(i2, alpha=180)
            skeleton_color = QColor(
                (color_1.red() + color_2.red()) // 2,
                (color_1.green() + color_2.green()) // 2,
                (color_1.blue() + color_2.blue()) // 2,
                180,
            )
            skeleton_pen = QPen(skeleton_color, 1.5 / zoom_factor)
            skeleton_pen.setCapStyle(Qt.RoundCap)
            painter.setPen(skeleton_pen)
            painter.drawLine(p1, p2)

        for i, (x, y) in enumerate(self.points):
            if i < len(self.visibility_flags) and self.visibility_flags[i] == 0:
                continue
            color = point_color(i, alpha=200)
            painter.setPen(QPen(color, 2))
            painter.setBrush(QBrush(color))
            point = QPointF(x * img_width, y * img_height)
            painter.drawEllipse(point, radius, radius)

    def append_point(self, point):
        parent = self.parentItem()

        if isinstance(parent, BoundingBoxDrawer) and not parent.rect().contains(point):
            logger.warning("Cannot place keypoint outside bounding box.")
            return

        max_points = self.main_window.keypoint_list.rowCount()
        if max_points <= 0:
            logger.warning("No keypoints in keypoint list.")
            return

        if self.current_index < 0 or self.current_index >= max_points:
            self.current_index = 0

        next_index = self.main_window.next_labelable_keypoint_row(self.current_index)
        if next_index is None:
            self.main_window.set_active_keypoint_row(None, self)
            logger.info("No non-ignored keypoints are available to place.")
            return

        self.current_index = next_index

        normalized_point = self._to_normalized_point(point)

        while len(self.points) < max_points:
            self.points.append((0.0, 0.0))

        while len(self.visibility_flags) < max_points:
            self.visibility_flags.append(0)

        visible_cb = self.main_window.keypoint_list.cellWidget(self.current_index, 3)

        placed_index = self.current_index

        v = 2 if visible_cb and visible_cb.isChecked() else 1
        self.points[placed_index] = normalized_point
        self.visibility_flags[placed_index] = v

        self.main_window.keypoint_list.selectRow(placed_index)
        self.main_window.selected_keypoint_row = placed_index

        self.update_points()
        self.update_class_name_item()
        self.update()

        if self.scene():
            self.scene().update()

        if isinstance(parent, BoundingBoxDrawer):
            parent.update_bbox()

        next_index = self.main_window.next_labelable_keypoint_row(placed_index, include_start=False)
        self.main_window.set_active_keypoint_row(next_index, self)

        try:
            self.main_window.clear_keypoint_highlight()
            self.main_window.highlight_keypoint_row(placed_index)
        except Exception:
            pass

        try:
            label_item = self.main_window.keypoint_list.item(placed_index, 1)
            label_name = label_item.text() if label_item else f"pt{placed_index}"
            logger.info(
                f"Keypoint placed: label='{label_name}', "
                f"Index: {placed_index}, File: {os.path.basename(self.file_name)}"
            )
        except Exception:
            pass

        if hasattr(self.main_window, "save_bounding_boxes") and self.main_window.is_keypoint_mode():
            img_width, img_height = self._get_image_dimensions()
            self.main_window.save_bounding_boxes(self.file_name, img_width, img_height)
            if hasattr(self.main_window, "refresh_annotation_preview_after_save"):
                self.main_window.refresh_annotation_preview_after_save(self.file_name)

    def update_points(self):
        for item in self.point_items:
            if self.scene():
                self.scene().removeItem(item)
        self.point_items.clear()

        total_rows = self.main_window.keypoint_list.rowCount()
        zoom_factor = max(self.main_window.screen_view.transform().m11(), 0.01)

        slider_value = self.main_window.dot_size_slider.value()
        base_radius = slider_value / 2.0
        radius = max(0.5, min(base_radius / zoom_factor, 6.0))

        for i, (x, y) in enumerate(self.points):
            if i < len(self.visibility_flags) and self.visibility_flags[i] == 0:
                continue

            point = self._to_scene_point((x, y))
            ellipse = QGraphicsEllipseItem(-radius, -radius, 2 * radius, 2 * radius, self)
            ellipse.setPos(point)

            if i < total_rows:
                color_item = self.main_window.keypoint_list.item(i, 2)
                color = color_item.background().color() if color_item else QColor(255, 255, 255)
            else:
                color = QColor(255, 255, 255)

            ellipse.setBrush(QBrush(color))
            ellipse.setPen(QPen(color))
            self.point_items.append(ellipse)

    def update_class_name_item_font(self, value=None):
        safe_update_class_name_item_font(self, value)

    def update_class_name_item(self):
        if not self.points:
            self.class_name_item.setPlainText("")
            return

        point_index = max(0, min(len(self.points) - 1, self.main_window.keypoint_list.rowCount() - 1))
        try:
            point_label = self.main_window.keypoint_list.item(point_index, 1).text()
        except Exception:
            point_label = f"pt{point_index}"

        self.class_name_item.setPlainText(point_label)
        point = self._to_scene_point(self.points[-1])
        self.class_name_item.setPos(QPointF(point.x() + 6, point.y() - 12))

    def remove_self(self):
        if self.scene():
            self.scene().removeItem(self)

        parent = self.parentItem()
        if isinstance(parent, BoundingBoxDrawer):
            parent.keypoint_drawer = None
            parent.update_bbox()

        if (
            hasattr(self.main_window, "save_bounding_boxes")
            and getattr(self.main_window, "current_file", None)
            and self.main_window.is_keypoint_mode()
        ):
            img_width, img_height = self._get_image_dimensions()
            self.main_window.save_bounding_boxes(
                self.main_window.current_file,
                img_width,
                img_height
            )
            if hasattr(self.main_window, "refresh_annotation_preview_after_save"):
                self.main_window.refresh_annotation_preview_after_save(self.main_window.current_file)


class SegmentationDrawer(QGraphicsPolygonItem):

    def __init__(self, points, main_window, class_id=None, unique_id=None, file_name=None):
        super().__init__()

        self.main_window = main_window
        self.class_id = class_id if class_id is not None else main_window.get_current_class_id()
        self.unique_id = unique_id
        self.file_name = file_name if file_name else main_window.current_file
        self.points = points if isinstance(points, list) else []

        self.edit_mode = False
        self.vertex_handles = []
        self.dragStartPos = None
        self.startPolygonPos = QPointF()
        self._is_hovered = False

        self._is_flashing = False
        self._flashing_on = False
        self._flash_override_color = None
        self._flash_timer = QTimer()
        self._flash_timer.timeout.connect(self._toggle_flash)

        self.flash_color = QColor(255, 0, 0)
        self.alternate_flash_color = QColor(0, 0, 255)

        self.simplify_points()

        self.polygon = QPolygonF(self._build_scene_points(self.points))
        self.setPolygon(self.polygon)

        self._base_color = self._get_class_color(alpha=self._get_shade_alpha())
        self._outline_color = self._get_class_color(alpha=255)

        self.setPen(QPen(self._outline_color, 2))
        self.setBrush(QBrush(self._base_color))

        self.label_leader_item = QGraphicsLineItem(self)
        self.label_leader_item.setZValue(4)

        self.label_badge_item = QGraphicsPathItem(self)
        self.label_badge_item.setZValue(5)

        self.class_name_item = QGraphicsTextItem(self)
        self.class_name_item.setZValue(6)
        self.class_name_item.setDefaultTextColor(QColor(255, 255, 255))
        self.class_name_item.setFont(
            QFont(
                "Arial",
                self.main_window.font_size_slider.value(),
                QFont.Bold
            )
        )

        self.setAcceptHoverEvents(True)
        self.setFlag(QGraphicsItem.ItemIsSelectable, True)
        self.setFlag(QGraphicsItem.ItemIsFocusable, True)
        self.setFlag(QGraphicsItem.ItemSendsGeometryChanges, True)

        self._font_size_connection = connect_weak_bound_signal(
            self.main_window.font_size_slider.valueChanged,
            self.update_class_name_item_font
        )
        self._shade_connection = connect_weak_bound_signal(
            self.main_window.shade_slider.valueChanged,
            self.update_opacity
        )

        self.update_class_name_item()
        self.update_opacity()

        if self.file_name is None:
            logger.warning("Segmentation item has no file_name; save/remove operations may be skipped.")

        self.class_name_item.setVisible(not self.main_window.hide_labels)

        if hasattr(self, "label_badge_item"):
            self.label_badge_item.setVisible(not self.main_window.hide_labels)

        if hasattr(self, "label_leader_item"):
            self.label_leader_item.setVisible(not self.main_window.hide_labels)

    def _get_shade_alpha(self):
        try:
            shade_value = self.main_window.shade_slider.value()
            return max(0, min(int(shade_value), 255))
        except Exception:
            return 120

    def _get_class_color(self, alpha=None):
        if alpha is None:
            alpha = self._get_shade_alpha()

        class_names = [
            self.main_window.classes_dropdown.itemText(i)
            for i in range(self.main_window.classes_dropdown.count())
        ]

        return get_color(
            self.class_id,
            max(1, len(class_names)),
            alpha=alpha,
            class_names=class_names,
        )

    def _get_image_dimensions(self):
        return graphics_image_dimensions(self, fallback_to_scene=False)

    def _to_scene_point(self, point):
        img_width, img_height = self._get_image_dimensions()
        return QPointF(point[0] * img_width, point[1] * img_height)

    def _to_normalized_point(self, scene_point):
        img_width, img_height = self._get_image_dimensions()
        if img_width <= 0 or img_height <= 0:
            return 0.0, 0.0
        return scene_point.x() / img_width, scene_point.y() / img_height

    def _build_scene_points(self, normalized_points):
        return [self._to_scene_point((x, y)) for x, y in normalized_points]

    def _snap_scene_point_to_outline(self, point):
        if not (self.main_window.outline_Checkbox.isChecked() and hasattr(self.main_window, "processed_image")):
            return point

        try:
            processed = self.main_window.processed_image
            gray_img = cv2.cvtColor(processed, cv2.COLOR_BGR2GRAY) if len(processed.shape) == 3 else processed
            x, y = int(point.x()), int(point.y())
            roi_size = 30

            x_min = max(0, x - roi_size)
            y_min = max(0, y - roi_size)
            x_max = min(gray_img.shape[1], x + roi_size)
            y_max = min(gray_img.shape[0], y + roi_size)

            roi = gray_img[y_min:y_max, x_min:x_max]
            if roi.size == 0:
                return point

            blurred = cv2.GaussianBlur(roi, (3, 3), 0)
            edges = cv2.Canny(blurred, 50, 150)
            contours, _ = cv2.findContours(edges, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE)

            if not contours:
                return point

            min_dist = float("inf")
            nearest_point = (x, y)
            for contour in contours:
                for pt in contour:
                    cx, cy = pt[0]
                    global_x = cx + x_min
                    global_y = cy + y_min
                    dist = np.hypot(global_x - x, global_y - y)
                    if dist < min_dist:
                        min_dist = dist
                        nearest_point = (global_x, global_y)

            return QPointF(nearest_point[0], nearest_point[1])
        except Exception:
            return point

    def _rebuild_polygon_from_points(self):
        self.polygon = QPolygonF(self._build_scene_points(self.points))
        self.setPolygon(self.polygon)
        self.update_class_name_item()

    def _rebuild_vertex_handles(self):
        if not self.scene():
            return

        for handle in self.vertex_handles:
            self.scene().removeItem(handle)
        self.vertex_handles = []

        for idx, pt in enumerate(self.polygon):
            handle = VertexHandle(self, idx)
            handle.setPos(self.mapToScene(pt))
            handle.setCursor(Qt.OpenHandCursor)
            self.scene().addItem(handle)
            self.vertex_handles.append(handle)

    def _sync_vertex_handles(self):
        if not self.vertex_handles:
            return

        for idx, handle in enumerate(self.vertex_handles):
            if idx < len(self.polygon):
                handle.setPos(self.mapToScene(self.polygon[idx]))

    def start_flashing(self, interval=100, duration=1000):
        """
        Flash segmentation the same way bbox/OBB do, but compatible with custom paint().
        """
        if hasattr(self, "_flash_timer") and self._flash_timer.isActive():
            self._flash_timer.stop()

        self._is_flashing = True
        self._flashing_on = False
        self._flash_override_color = None
        self._flash_duration = duration
        self._flash_start_time = time.time()

        if not hasattr(self, "flash_color"):
            self.flash_color = QColor(255, 0, 0)

        self._base_color = self._get_class_color(alpha=self._get_shade_alpha())
        self._outline_color = self._get_class_color(alpha=255)

        if not hasattr(self, "_flash_timer") or self._flash_timer is None:
            self._flash_timer = QTimer()
            self._flash_timer.timeout.connect(self._toggle_flash)

        self._flash_timer.start(interval)

        self.set_z_order(bring_to_front=True)
        self.update()

    def _toggle_flash(self):
        elapsed_time = (time.time() - self._flash_start_time) * 1000

        if elapsed_time >= self._flash_duration:
            self.stop_flashing()
            return

        if self._flashing_on:
            self._flash_override_color = self._base_color
        else:
            flash_alpha = max(180, self._get_shade_alpha())
            self._flash_override_color = QColor(
                self.flash_color.red(),
                self.flash_color.green(),
                self.flash_color.blue(),
                flash_alpha
            )

        self._flashing_on = not self._flashing_on
        self.update()

        scene = self.scene()
        if scene is not None:
            scene.update()

    def stop_flashing(self):
        if hasattr(self, "_flash_timer") and self._flash_timer.isActive():
            self._flash_timer.stop()

        self._is_flashing = False
        self._flashing_on = False
        self._flash_override_color = None

        self._base_color = self._get_class_color(alpha=self._get_shade_alpha())
        self._outline_color = self._get_class_color(alpha=255)

        self.setBrush(QBrush(self._base_color))
        self.setPen(QPen(self._outline_color, 2))
        self.set_z_order(bring_to_front=False)

        self.update()

        scene = self.scene()
        if scene is not None:
            scene.update()

    def set_z_order(self, bring_to_front=False):
        if bring_to_front:
            self.setZValue(1.0)
        elif self.zValue() < 1.0:
            self.setZValue(0.5)

    def _set_label_hovered(self, hovered):
        if not hasattr(self, "label_badge_item") or self.label_badge_item is None:
            return

        color = self._get_class_color(alpha=255 if hovered else 225)

        if hovered:
            self.label_badge_item.setBrush(QBrush(color))
            self.label_badge_item.setPen(QPen(QColor(255, 255, 255, 255), 2.0))

            if hasattr(self, "class_name_item") and self.class_name_item:
                font = self.class_name_item.font()
                font.setBold(True)
                self.class_name_item.setFont(font)
                self.class_name_item.setDefaultTextColor(QColor(255, 255, 255))
        else:
            self._update_label_badge()

    def hoverEnterEvent(self, event):
        if self._is_hovered or not self.scene():
            super().hoverEnterEvent(event)
            return

        scene_pos = self.mapToScene(event.pos())
        overlapping = [
            item for item in self.scene().items(scene_pos)
            if isinstance(item, SegmentationDrawer)
        ]
        overlapping.sort(key=lambda x: x.zValue(), reverse=True)

        if overlapping and overlapping[0] == self:
            self.set_z_order(bring_to_front=True)

        self._is_hovered = True
        self._set_label_hovered(True)
        self.update()

        if self.scene():
            self.scene().update()

        super().hoverEnterEvent(event)

    def hoverLeaveEvent(self, event):
        self._is_hovered = False
        self._set_label_hovered(False)
        self.update()

        if self.scene():
            self.scene().update()

        super().hoverLeaveEvent(event)

    def update_class_name_item_font(self, value=None):
        safe_update_class_name_item_font(self, value)

    def update_class_name_item(self):
        class_name = self.main_window.classes_dropdown.itemText(self.class_id)
        self.class_name_item.setPlainText(class_name)

        font = self.class_name_item.font()
        font.setPointSize(self.main_window.font_size_slider.value())
        self.class_name_item.setFont(font)

        self._update_label_badge()

        visible = not self.main_window.hide_labels
        self.class_name_item.setVisible(visible)
        self.label_badge_item.setVisible(visible)

        if hasattr(self, "label_leader_item") and self.label_leader_item:
            self.label_leader_item.setLine(0, 0, 0, 0)
            self.label_leader_item.setVisible(False)

    def set_class_id(self, class_id):
        self.class_id = int(class_id)
        self.setPen(QPen(self._get_class_color(alpha=255), 2))
        self.update_opacity()
        self.update_class_name_item()
        self.update()

    def append_point(self, point):
        if self.edit_mode:
            return

        # Do NOT edge-snap every point while drawing.
        # Enable Snap now means SAM3 refine on finalize.
        self.points.append(self._to_normalized_point(point))
        self._rebuild_polygon_from_points()

    def update_polygon(self):
        self._rebuild_polygon_from_points()

    def remove_self(self):
        if self.scene():
            self.scene().removeItem(self)
        self.remove_segmentation_from_file()

    def remove_segmentation_from_file(self):
        if not self.file_name:
            logger.warning("Cannot remove segmentation: no file path is attached.")
            return

        label_file = os.path.splitext(self.file_name)[0] + ".txt"
        if not os.path.exists(label_file):
            logger.debug(f"Label file does not exist: {label_file}")
            return

        current_label = f"{self.class_id} " + " ".join(f"{x:.6f} {y:.6f}" for x, y in self.points)
        try:
            with open(label_file, "r", encoding="utf-8") as f:
                lines = f.readlines()

            updated_lines = [line for line in lines if line.strip() != current_label]

            with open(label_file, "w", encoding="utf-8") as f:
                f.writelines(updated_lines)

            logger.info(f"Segmentation removed from {label_file}")
        except Exception as e:
            logger.error(f"Failed to remove segmentation from {label_file}: {e}")

    def update_opacity(self, value=None):
        """
        Shade slider is always active.
        This updates the normal segmentation fill color.
        It does not interrupt an active flash.
        """
        self._base_color = self._get_class_color(alpha=self._get_shade_alpha())
        self._outline_color = self._get_class_color(alpha=255)

        if not getattr(self, "_is_flashing", False):
            self._flash_override_color = None
            self.setBrush(QBrush(self._base_color))
            self.setPen(QPen(self._outline_color, 2))

        self.update()

        scene = self.scene()
        if scene is not None:
            scene.update()

    def mousePressEvent(self, event):
        scene_pos = event.scenePos()

        if self.edit_mode:
            if event.button() == Qt.LeftButton:
                for handle in self.vertex_handles:
                    if handle.contains(handle.mapFromScene(scene_pos)):
                        handle.setCursor(Qt.ClosedHandCursor)
                        handle.mousePressEvent(event)
                        return

            elif event.button() == Qt.RightButton:
                nearest_index = self.find_nearest_edge_index(scene_pos)
                if nearest_index is not None:
                    self.insert_point_at(scene_pos, nearest_index)
                    return

        super().mousePressEvent(event)

    def find_nearest_edge_index(self, scene_pos, threshold=10):
        min_dist = float("inf")
        best_index = None

        for i in range(len(self.polygon)):
            p1 = self.polygon[i]
            p2 = self.polygon[(i + 1) % len(self.polygon)]

            x1, y1 = p1.x(), p1.y()
            x2, y2 = p2.x(), p2.y()
            px, py = scene_pos.x(), scene_pos.y()

            dx, dy = x2 - x1, y2 - y1
            if dx == 0 and dy == 0:
                continue

            t = max(0, min(1, ((px - x1) * dx + (py - y1) * dy) / (dx * dx + dy * dy)))
            proj_x = x1 + t * dx
            proj_y = y1 + t * dy
            dist = ((proj_x - px) ** 2 + (proj_y - py) ** 2) ** 0.5

            if dist < min_dist and dist <= threshold:
                min_dist = dist
                best_index = i + 1

        return best_index

    def insert_point_at(self, scene_pos, insert_index):
        local_pt = self.mapFromScene(scene_pos)
        norm_x, norm_y = self._to_normalized_point(local_pt)

        self.points.insert(insert_index, (norm_x, norm_y))
        self._rebuild_polygon_from_points()
        self._rebuild_vertex_handles()

    def mouseMoveEvent(self, event):
        if self.edit_mode:
            for handle in self.vertex_handles:
                if handle.cursor() == Qt.ClosedHandCursor:
                    handle.mouseMoveEvent(event)
                    return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self.edit_mode:
            super().mouseReleaseEvent(event)
            return

        self.setOpacity(1.0)
        self.setFlag(QGraphicsItem.ItemIsMovable, False)
        super().mouseReleaseEvent(event)

    def toggle_edit_mode(self):
        if not self.edit_mode:
            self.enter_edit_mode()
        else:
            self.finalize_edit_mode()

    def simplify_points(self, min_distance=6, angle_threshold=130):
        if len(self.points) < 3:
            return

        img_width, img_height = self._get_image_dimensions()
        pts = np.array(
            [[int(x * img_width), int(y * img_height)] for x, y in self.points],
            dtype=np.int32,
        )

        if len(pts) < 3:
            return

        def angle_between(a, b, c):
            ba = a - b
            bc = c - b
            cos_angle = np.dot(ba, bc) / (np.linalg.norm(ba) * np.linalg.norm(bc) + 1e-6)
            return np.degrees(np.arccos(np.clip(cos_angle, -1.0, 1.0)))

        simplified_pts = [pts[0]]
        last_kept = pts[0]

        for i in range(1, len(pts) - 1):
            current = pts[i]
            next_pt = pts[i + 1]
            dist = np.linalg.norm(current - last_kept)
            angle = angle_between(pts[i - 1], current, next_pt)

            if dist < 1.0:
                continue
            if angle > angle_threshold and dist < (min_distance * 1.2):
                continue

            simplified_pts.append(current)
            last_kept = current

        if not np.array_equal(simplified_pts[-1], pts[-1]):
            simplified_pts.append(pts[-1])

        if len(simplified_pts) < 3:
            logger.warning("Segmentation simplification produced too few points. Keeping original.")
            return

        self.points = [(pt[0] / img_width, pt[1] / img_height) for pt in simplified_pts]

    def enter_edit_mode(self):
        self.edit_mode = True
        self.simplify_points()
        self._rebuild_polygon_from_points()
        self._rebuild_vertex_handles()

    def paint(self, painter, option, widget=None):
        """
        Custom segmentation paint:
        - normal fill obeys shade_slider
        - flash fill overrides shade temporarily
        - hover makes outline thicker and fill slightly brighter
        """
        painter.setRenderHint(QPainter.Antialiasing)

        base_alpha = self._get_shade_alpha()
        base_color = self._get_class_color(alpha=base_alpha)
        outline_color = self._get_class_color(alpha=255)

        is_hovered = getattr(self, "_is_hovered", False)
        flash_color = getattr(self, "_flash_override_color", None)

        if flash_color is not None:
            fill_color = flash_color
            outline_width = 4 if is_hovered else 3
        elif is_hovered:
            hover_alpha = min(255, base_alpha + 60)
            fill_color = self._get_class_color(alpha=hover_alpha)
            outline_width = 4
        else:
            fill_color = base_color
            outline_width = 2

        self._base_color = base_color
        self._outline_color = outline_color

        painter.setBrush(QBrush(fill_color))
        painter.setPen(QPen(outline_color, outline_width))
        painter.drawPolygon(self.polygon)

    def finalize(self):
        if len(self.points) < 3:
            logger.warning(f"Cannot finalize segmentation: only {len(self.points)} point(s), need at least 3.")
            if self.scene():
                self.scene().removeItem(self)
            return

        self._rebuild_polygon_from_points()

        refined = self._try_sam_refine_segmentation(
            epsilon_ratio=0.0008,
            max_points=300
        )

        if not refined:
            self.simplify_points()
            self._rebuild_polygon_from_points()

        if len(self.points) < 3:
            logger.warning("Segmentation produced too few points after cleanup. Removing item.")
            if self.scene():
                self.scene().removeItem(self)
            return

        scene = self.main_window.screen_view.scene()
        if scene is not None and self.scene() is None:
            scene.addItem(self)

        self.update_class_name_item()

        self.main_window.save_bounding_boxes(
            self.file_name,
            self.main_window.image.width(),
            self.main_window.image.height(),
        )
        if hasattr(self.main_window, "refresh_annotation_preview_after_save"):
            self.main_window.refresh_annotation_preview_after_save(self.file_name)

        logger.info(f"Segmentation finalized and saved for {self.file_name}")

    def finalize_edit_mode(self):
        if len(self.points) < 3:
            logger.warning("Cannot finalize edit mode: segmentation has fewer than 3 points.")
            return

        self.edit_mode = False

        for handle in list(self.vertex_handles):
            try:
                if handle.scene():
                    handle.scene().removeItem(handle)
            except RuntimeError:
                pass

        self.vertex_handles = []

        self._rebuild_polygon_from_points()

        refined = self._try_sam_refine_segmentation(
            epsilon_ratio=0.0008,
            max_points=300
        )

        if not refined:
            self.simplify_points()
            self._rebuild_polygon_from_points()

        self.update_class_name_item()

        self.main_window.save_bounding_boxes(
            self.file_name,
            self.main_window.image.width(),
            self.main_window.image.height(),
        )
        if hasattr(self.main_window, "refresh_annotation_preview_after_save"):
            self.main_window.refresh_annotation_preview_after_save(self.file_name)

        if self.scene():
            self.scene().update()

        self.main_window.screen_view.viewport().update()

        logger.info(f"Segmentation edit finalized and saved for {self.file_name}")

    def update_point(self, index, new_scene_pos):
        if index >= len(self.points):
            logger.warning(
                f"Tried to update point at index {index}, but points has only {len(self.points)} items."
            )
            return

        snapped_scene_pos = self._snap_scene_point_to_outline(new_scene_pos)
        local_pt = self.mapFromScene(snapped_scene_pos)

        if index >= len(self.polygon):
            logger.warning(
                f"Polygon index {index} out of bounds. Polygon has {len(self.polygon)} points."
            )
            return

        self.polygon[index] = local_pt
        self.setPolygon(self.polygon)
        self.points[index] = self._to_normalized_point(local_pt)
        self.update_class_name_item()
        self._sync_vertex_handles()

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.toggle_edit_mode()
        super().mouseDoubleClickEvent(event)

    def _update_label_badge(self):
        if not hasattr(self, "class_name_item") or self.class_name_item is None:
            return

        if not self.polygon or len(self.polygon) == 0:
            return

        img_w, img_h = self._get_image_dimensions()
        if img_w <= 0 or img_h <= 0:
            return

        br = self.polygon.boundingRect()

        # Anchor badge near the top-most point of the segmentation,
        # close to the horizontal center of the polygon.
        anchor_local = min(
            [self.polygon[i] for i in range(len(self.polygon))],
            key=lambda p: (p.y(), abs(p.x() - br.center().x()))
        )

        anchor_scene = self.mapToScene(anchor_local)

        text_rect = self.class_name_item.boundingRect()
        badge_w = max(38, text_rect.width() + 12)
        badge_h = max(20, text_rect.height() + 6)

        gap = 8

        label_x = anchor_scene.x() - badge_w / 2
        label_y = anchor_scene.y() - badge_h - gap

        # If badge would go above image, place it below the anchor.
        if label_y < 4:
            label_y = anchor_scene.y() + gap

        label_x = max(4, min(label_x, img_w - badge_w - 4))
        label_y = max(4, min(label_y, img_h - badge_h - 4))

        self.class_name_item.setPos(label_x + 6, label_y + 2)

        badge_rect = QRectF(label_x, label_y, badge_w, badge_h)
        path = QPainterPath()
        path.addRoundedRect(badge_rect, 5, 5)

        color = self._get_class_color(alpha=225)
        self.label_badge_item.setPath(path)
        self.label_badge_item.setBrush(QBrush(color))
        self.label_badge_item.setPen(QPen(QColor(255, 255, 255, 210), 1.25))

        # Segmentation masks do NOT use leader lines.
        # Leader lines can stretch across large masks and look like bad polygon edges.
        if hasattr(self, "label_leader_item") and self.label_leader_item is not None:
            self.label_leader_item.setLine(0, 0, 0, 0)
            self.label_leader_item.setVisible(False)

        visible = self.class_name_item.isVisible()
        self.label_badge_item.setVisible(visible)

        if hasattr(self, "label_leader_item") and self.label_leader_item is not None:
            self.label_leader_item.setVisible(False)

    def _try_sam_refine_segmentation(self, epsilon_ratio=0.0008, max_points=300):
        """
        Refine the rough hand-drawn segmentation using SAM3 while preserving the
        user's polygon as the target guide.  The bounding rect is still used as
        the SAM prompt, but unrelated mask components are removed by comparing
        them with the drawn polygon before the result is accepted.
        """
        if not self.main_window.outline_Checkbox.isChecked():
            return False

        if not hasattr(self.main_window, "processed_image"):
            return False

        image_np = self.main_window.processed_image

        if image_np is None or not isinstance(image_np, np.ndarray) or image_np.size == 0:
            return False

        if not self.points or len(self.points) < 3:
            return False

        try:
            img_h, img_w = image_np.shape[:2]

            self._rebuild_polygon_from_points()
            polygon_rect = self.polygon.boundingRect()

            x1 = int(polygon_rect.left())
            y1 = int(polygon_rect.top())
            x2 = int(polygon_rect.right())
            y2 = int(polygon_rect.bottom())

            x1 = max(0, min(x1, img_w - 1))
            y1 = max(0, min(y1, img_h - 1))
            x2 = max(0, min(x2, img_w - 1))
            y2 = max(0, min(y2, img_h - 1))

            if x2 <= x1 or y2 <= y1:
                return False

            guide_mask = self.main_window.polygon_guide_mask(
                self.points,
                img_w,
                img_h,
            )
            if guide_mask is None:
                return False

            bbox_prompt = self.main_window.pad_bbox_xyxy(
                [x1, y1, x2, y2],
                img_w,
                img_h,
                pad_ratio=0.02
            )

            class_name = self.main_window.get_current_class_name_safe(
                getattr(self, "class_id", None)
            )

            # Polygon Snap only: ask SAM3 for the selected dropdown concept,
            # then use the hand-drawn polygon to choose the intended instance.
            mask = self.main_window.sam_snap_class_polygon_to_mask(
                image_np,
                bbox_prompt,
                class_name,
                guide_mask,
                imgsz=1036,
            )

            # Custom/unknown class names may not produce a semantic result.
            # Fall back to the existing visual bbox prompt without changing any
            # other snapping, auto-label, video, or inference workflow.
            if mask is None:
                mask = self.main_window.sam_snap_bbox_to_mask(
                    image_np,
                    bbox_prompt,
                    imgsz=1036
                )
                mask = self.main_window.select_sam_mask_for_polygon(mask, guide_mask)

            if mask is None:
                return False

            if not self.main_window.validate_sam_mask_for_bbox(
                mask,
                [x1, y1, x2, y2],
                class_name=class_name
            ):
                return False

            new_points = self.main_window.mask_to_polygon_points(
                mask,
                img_w,
                img_h,
                epsilon_ratio=epsilon_ratio,
                max_points=max_points,
                preserve_thin=True,
            )

            if not new_points or len(new_points) < 3:
                return False

            self.points = new_points
            self._rebuild_polygon_from_points()
            self.update_class_name_item()

            logger.debug(
                "Segmentation refined using polygon-guided SAM3 with %s points.",
                len(self.points),
            )
            return True

        except Exception as e:
            logger.warning(f"SAM3 segmentation refine failed: {e}")
            return False


class VertexHandle(QGraphicsEllipseItem):

    def __init__(self, drawer, index, radius=3):
        super().__init__(-radius, -radius, radius * 2, radius * 2)
        self.drawer = drawer
        self.index = index
        self.active_color = QColor(0, 255, 0)
        self.default_color = QColor(Qt.red)
        self.setBrush(QBrush(self.default_color))
        self.setPen(QPen(QColor(255, 255, 255), 1))
        self.setCursor(Qt.OpenHandCursor)
        self.setZValue(10)

        self.setFlag(QGraphicsItem.ItemIsMovable, True)
        self.setFlag(QGraphicsItem.ItemIsSelectable, True)
        self.setFlag(QGraphicsItem.ItemSendsScenePositionChanges, True)

    def mousePressEvent(self, event):
        self.setBrush(QBrush(self.active_color))
        self.setCursor(Qt.ClosedHandCursor)
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        super().mouseMoveEvent(event)
        self.drawer.update_point(self.index, self.scenePos())

    def mouseReleaseEvent(self, event):
        self.setBrush(QBrush(self.default_color))
        self.setCursor(Qt.OpenHandCursor)
        super().mouseReleaseEvent(event)

    def itemChange(self, change, value):
        if change == QGraphicsItem.ItemScenePositionHasChanged:
            try:
                self.drawer.update_point(self.index, value)
            except Exception:
                pass
        return super().itemChange(change, value)


class OBBDrawer(QGraphicsPolygonItem):

    def __init__(self, main_window, class_id=None, unique_id=None, file_name=None,
                 obb_points=None, angle=None):
        super().__init__()
        self.main_window = main_window
        self.class_id = class_id if class_id is not None else main_window.get_current_class_id()
        self.unique_id = unique_id
        self.file_name = file_name if file_name else main_window.current_file

        # Geometry state
        self.obb_points = obb_points.copy() if obb_points else []
        self.angle = float(angle) if angle is not None else 0.0
        self.centerline_start = None
        self.centerline_end = None
        self.current_width = 0.0
        self.drawing_in_progress = False
        self.current_state = "awaiting_centerline_start"
        self.drag_offset = QPointF()

        # Edit / hover state
        self.edit_mode = False
        self.vertex_handles = []
        self._is_hovered = False
        self.hover_opacity = 1.0
        self.normal_opacity = 0.6
        self.setOpacity(self.normal_opacity)
        self.setAcceptHoverEvents(True)
        self.setFlag(QGraphicsItem.ItemIsFocusable, True)
        self.setFlag(QGraphicsItem.ItemIsSelectable, True)


        # Label / callout
        self.label_leader_item = QGraphicsLineItem(self)
        self.label_leader_item.setZValue(4)

        self.label_badge_item = QGraphicsPathItem(self)
        self.label_badge_item.setZValue(5)

        self.class_name_item = QGraphicsTextItem(self)
        self.class_name_item.setZValue(6)
        self.class_name_item.setDefaultTextColor(QColor(255, 255, 255))
        self.class_name_item.setFont(QFont("Arial", self.main_window.font_size_slider.value(), QFont.Bold))
        self._shade_connection = connect_weak_bound_signal(
            self.main_window.shade_slider.valueChanged,
            self.update_opacity
        )
        self._font_size_connection = connect_weak_bound_signal(
            self.main_window.font_size_slider.valueChanged,
            self.update_class_name_item_font
        )
        self.setAcceptedMouseButtons(Qt.LeftButton | Qt.RightButton)
        # Visual state
        self.centerline_item = None
        color = self._get_class_color(alpha=255)
        self.setPen(QPen(color, 2))
        self.update_opacity()

        self.flash_color = QColor(255, 0, 0)
        self.alternate_flash_color = QColor(0, 0, 255)
        self.flash_timer = QTimer()
        self.flash_timer.timeout.connect(self.toggle_flash_color)
        self.scroll_timer = QTimer()
        self.scroll_timer.setSingleShot(True)
        self.scroll_timer.timeout.connect(self.stop_flashing)


        self.class_name_item.setZValue(6)


        if self.obb_points:
            self.restore_centerline_from_obb()
            self.render_from_points()
        else:
            self.update_class_name_item()

    def _try_sam_refine_obb(self, final_scene_points, img_w, img_h):
        """
        Refine OBB using SAM3.
        Uses the current OBB bounds as the SAM3 bbox prompt.
        Returns updated final_scene_points or None.
        """
        if not self.main_window.outline_Checkbox.isChecked():
            return None

        if not hasattr(self.main_window, "processed_image"):
            return None

        image_np = self.main_window.processed_image

        if image_np is None or not isinstance(image_np, np.ndarray) or image_np.size == 0:
            return None

        try:
            xs = [p.x() for p in final_scene_points]
            ys = [p.y() for p in final_scene_points]

            x1 = int(max(0, min(xs)))
            y1 = int(max(0, min(ys)))
            x2 = int(min(img_w - 1, max(xs)))
            y2 = int(min(img_h - 1, max(ys)))

            if x2 <= x1 or y2 <= y1:
                return None

            bbox_prompt = self.main_window.pad_bbox_xyxy(
                [x1, y1, x2, y2],
                img_w,
                img_h,
                pad_ratio=0.05
            )

            mask = self.main_window.sam_snap_bbox_to_mask(
                image_np,
                bbox_prompt,
                imgsz=1036
            )

            class_name = self.main_window.get_current_class_name_safe(
                getattr(self, "class_id", None)
            )

            if not self.main_window.validate_sam_mask_for_bbox(
                mask,
                [x1, y1, x2, y2],
                class_name=class_name
            ):
                return None

            obb_points = self.main_window.mask_to_obb_points(mask, img_w, img_h)

            if not obb_points or len(obb_points) != 4:
                return None

            scene_points = [
                QPointF(x * img_w, y * img_h)
                for x, y in obb_points
            ]

            logger.debug("OBB refined using SAM3.")
            return scene_points

        except Exception as e:
            logger.warning(f"SAM3 OBB refine failed: {e}")
            return None

    def _get_class_color(self, alpha=225):
        class_names = [
            self.main_window.classes_dropdown.itemText(i)
            for i in range(self.main_window.classes_dropdown.count())
        ]
        return get_color(
            self.class_id,
            len(class_names),
            alpha=alpha,
            class_names=class_names,
        )

    def _get_image_dimensions(self):
        return graphics_image_dimensions(self)

    def clamp_point_to_image(self, point):
        img_width, img_height = self._get_image_dimensions()
        if img_width <= 0 or img_height <= 0:
            return QPointF(point)
        return QPointF(
            max(0, min(point.x(), img_width - 1)),
            max(0, min(point.y(), img_height - 1)),
        )

    def _scene_points_from_normalized(self, points):
        img_w, img_h = self._get_image_dimensions()
        return [QPointF(x * img_w, y * img_h) for x, y in points]

    def _normalized_points_from_scene(self, points):
        img_w, img_h = self._get_image_dimensions()
        if img_w <= 0 or img_h <= 0:
            return []
        return [(pt.x() / img_w, pt.y() / img_h) for pt in points]

    def set_z_order(self, bring_to_front=False):
        if bring_to_front:
            self.setZValue(1.0)
        elif self.zValue() < 1.0:
            self.setZValue(0.5)

    def hoverEnterEvent(self, event):
        if self._is_hovered or not self.scene():
            super().hoverEnterEvent(event)
            return

        scene_pos = self.mapToScene(event.pos())
        overlapping = [
            item for item in self.scene().items(scene_pos)
            if isinstance(item, OBBDrawer)
        ]
        overlapping.sort(key=lambda x: x.zValue(), reverse=True)

        if overlapping and overlapping[0] == self:
            self.set_z_order(bring_to_front=True)

        self.setOpacity(self.hover_opacity)
        self._is_hovered = True
        super().hoverEnterEvent(event)

    def hoverLeaveEvent(self, event):
        if not self._is_hovered:
            return

        self.setOpacity(self.normal_opacity)
        self._is_hovered = False
        super().hoverLeaveEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.toggle_edit_mode()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def _rebuild_vertex_handles(self):
        if not self.scene():
            return

        for handle in self.vertex_handles:
            if handle.scene():
                handle.scene().removeItem(handle)
        self.vertex_handles = []

        poly = self.polygon()
        for idx in range(poly.count()):
            handle = VertexHandle(self, idx)
            handle.setPos(self.mapToScene(poly[idx]))
            handle.setCursor(Qt.OpenHandCursor)
            self.scene().addItem(handle)
            self.vertex_handles.append(handle)

    def _sync_vertex_handles(self):
        if not self.vertex_handles:
            return

        poly = self.polygon()
        for idx, handle in enumerate(self.vertex_handles):
            if idx < poly.count():
                handle.setPos(self.mapToScene(poly[idx]))

    def enter_edit_mode(self):
        if self.current_state != "bb_defined":
            return
        self.edit_mode = True
        self._rebuild_vertex_handles()

    def toggle_edit_mode(self):
        if not self.edit_mode:
            self.enter_edit_mode()
        else:
            self.finalize_edit_mode()

    def update_point(self, index, new_scene_pos):
        poly = self.polygon()
        if index >= poly.count():
            return

        clamped_scene = self.clamp_point_to_image(new_scene_pos)
        local_pt = self.mapFromScene(clamped_scene)
        poly[index] = local_pt
        self.setPolygon(poly)

        scene_points = [self.mapToScene(poly[i]) for i in range(poly.count())]
        self.obb_points = self._normalized_points_from_scene(scene_points)

        if poly.count() == 4:
            p0 = self.mapToScene(poly[0])
            p1 = self.mapToScene(poly[1])
            p2 = self.mapToScene(poly[2])
            p3 = self.mapToScene(poly[3])
            self.centerline_start = (p0 + p3) / 2
            self.centerline_end = (p1 + p2) / 2
            self.current_width = float(np.hypot(p0.x() - p3.x(), p0.y() - p3.y()))
            self.angle = self._compute_angle_from_centerline()

        self._sync_vertex_handles()
        self.update_class_name_item()
        if self.scene():
            self.scene().update()

    def start_flashing(self, interval, duration):
        self.flash_timer.start(interval)
        QTimer.singleShot(duration, self.stop_flashing)

    def stop_flashing(self):
        self.flash_timer.stop()
        self.reset_color()

    def update_opacity(self, value=None):
        shade_value = self.main_window.shade_slider.value()
        shade_value = max(0, min(int(shade_value), 255))

        color = self._get_class_color(alpha=shade_value)

        self._base_color = color
        self.setBrush(QBrush(color))
        self.setPen(QPen(self._get_class_color(alpha=255), 2))

        self.update()

    def toggle_flash_color(self):
        current_color = self.pen().color()

        next_color = (
            self.flash_color
            if current_color == self.alternate_flash_color
            else self.alternate_flash_color
        )

        self.setPen(QPen(next_color, self.pen().width()))

    def reset_color(self):
        class_names = [
            self.main_window.classes_dropdown.itemText(i)
            for i in range(self.main_window.classes_dropdown.count())
        ]
        base_color = get_color(self.class_id, len(class_names), class_names=class_names)
        self.setPen(QPen(base_color, 2))

    def update_class_name_item(self):
        poly = self.polygon()
        if poly.count() != 4:
            self.class_name_item.setPlainText("")
            if hasattr(self, "label_badge_item"):
                self.label_badge_item.setVisible(False)
            if hasattr(self, "label_leader_item"):
                self.label_leader_item.setVisible(False)
            return

        class_name = self.main_window.classes_dropdown.itemText(self.class_id)
        self.class_name_item.setPlainText(class_name)

        font = self.class_name_item.font()
        font.setPointSize(self.main_window.font_size_slider.value())
        self.class_name_item.setFont(font)

        self._update_label_badge()

        visible = not self.main_window.settings.get("hideLabels", False)
        self.class_name_item.setVisible(visible)
        self.label_badge_item.setVisible(visible)
        self.label_leader_item.setVisible(visible)

    def update_class_name_item_font(self, value=None):
        safe_update_class_name_item_font(self, value)

    def set_class_id(self, class_id):
        self.class_id = class_id
        color = self._get_class_color(alpha=255)
        self.setPen(QPen(color, 2))
        self.update_opacity()
        self.update_class_name_item()

    def render_from_points(self):
        if not self.obb_points or len(self.obb_points) != 4:
            self.setPolygon(QPolygonF())
            return

        polygon = QPolygonF(self._scene_points_from_normalized(self.obb_points))
        self.setPolygon(polygon)
        self.update_class_name_item()

    def update_preview(self, scene_pos):
        scene_pos = self.clamp_point_to_image(scene_pos)

        if self.centerline_start is None or self.centerline_end is None:
            return

        self.centerline_start = self.clamp_point_to_image(self.centerline_start)
        self.centerline_end = self.clamp_point_to_image(self.centerline_end)

        start = self.centerline_start
        end = self.centerline_end

        dx = end.x() - start.x()
        dy = end.y() - start.y()
        length = math.hypot(dx, dy)
        if length == 0:
            return

        nx = -dy / length
        ny = dx / length

        vx = scene_pos.x() - start.x()
        vy = scene_pos.y() - start.y()
        signed_width = vx * nx + vy * ny
        half_w = signed_width / 2.0

        p1 = self.clamp_point_to_image(QPointF(start.x() + nx * half_w, start.y() + ny * half_w))
        p2 = self.clamp_point_to_image(QPointF(end.x() + nx * half_w, end.y() + ny * half_w))
        p3 = self.clamp_point_to_image(QPointF(end.x() - nx * half_w, end.y() - ny * half_w))
        p4 = self.clamp_point_to_image(QPointF(start.x() - nx * half_w, start.y() - ny * half_w))

        poly = QPolygonF([p1, p2, p3, p4])
        self.setPolygon(poly)

        scene_points = [QPointF(poly[i].x(), poly[i].y()) for i in range(poly.count())]
        self.obb_points = self._normalized_points_from_scene(scene_points)
        self.current_width = abs(signed_width)
        self.update_class_name_item()

    def _compute_angle_from_centerline(self):
        if not self.centerline_start or not self.centerline_end:
            return 0.0
        dx = self.centerline_end.x() - self.centerline_start.x()
        dy = self.centerline_end.y() - self.centerline_start.y()
        return float(np.arctan2(dy, dx))

    def _snap_corners_to_contour(self, gray_img, corners, img_w, img_h):
        x1 = int(max(min(x for x, y in corners), 0))
        y1 = int(max(min(y for x, y in corners), 0))
        x2 = int(min(max(x for x, y in corners), img_w - 1))
        y2 = int(min(max(y for x, y in corners), img_h - 1))

        roi = gray_img[y1:y2, x1:x2]
        if roi.size == 0:
            return corners, None

        blurred = cv2.GaussianBlur(roi, (3, 3), 0)
        edges = cv2.Canny(blurred, 50, 150)
        contours, _ = cv2.findContours(edges, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

        if not contours:
            return corners, None

        biggest = max(contours, key=cv2.contourArea)
        rect = cv2.minAreaRect(biggest)
        (_, _), (_, _), angle_deg = rect
        box = cv2.boxPoints(rect)
        box[:, 0] += x1
        box[:, 1] += y1
        return [tuple(p) for p in box], float(np.deg2rad(angle_deg))

    def finalize(self):
        poly = self.polygon()

        if poly.count() != 4:
            logger.warning("Cannot finalize OBB: polygon does not have 4 points.")
            return

        clamped_scene_points = [
            self.clamp_point_to_image(self.mapToScene(poly[i]))
            for i in range(poly.count())
        ]

        local_poly = QPolygonF([self.mapFromScene(p) for p in clamped_scene_points])
        self.setPolygon(local_poly)

        img_w, img_h = self._get_image_dimensions()

        if img_w <= 0 or img_h <= 0:
            logger.warning("Cannot finalize OBB: invalid image dimensions.")
            return

        final_scene_points = [
            self.mapToScene(local_poly[i])
            for i in range(local_poly.count())
        ]

        processed_image = getattr(self.main_window, "processed_image", None)
        if (
            self.main_window.outline_Checkbox.isChecked()
            and isinstance(processed_image, np.ndarray)
            and processed_image.size > 0
        ):
            sam3_points = self._try_sam_refine_obb(final_scene_points, img_w, img_h)

            if sam3_points and len(sam3_points) == 4:
                final_scene_points = sam3_points
                self.setPolygon(QPolygonF([self.mapFromScene(p) for p in final_scene_points]))

                p0, p1, p2, p3 = final_scene_points
                self.centerline_start = (p0 + p3) / 2
                self.centerline_end = (p1 + p2) / 2
                self.angle = self._compute_angle_from_centerline()

            else:
                gray_img = processed_image

                if len(gray_img.shape) == 3:
                    if gray_img.shape[2] == 3:
                        gray_img = cv2.cvtColor(gray_img, cv2.COLOR_BGR2GRAY)
                    elif gray_img.shape[2] == 4:
                        gray_img = cv2.cvtColor(gray_img, cv2.COLOR_BGRA2GRAY)

                corners = [(pt.x(), pt.y()) for pt in final_scene_points]

                snapped_corners, snapped_angle = self._snap_corners_to_contour(
                    gray_img,
                    corners,
                    img_w,
                    img_h
                )

                final_scene_points = [
                    QPointF(float(x), float(y))
                    for x, y in snapped_corners
                ]

                self.angle = snapped_angle if snapped_angle is not None else self._compute_angle_from_centerline()
                self.setPolygon(QPolygonF([self.mapFromScene(p) for p in final_scene_points]))

                logger.debug("OBB snapped using edge fallback.")
        else:
            self.angle = self._compute_angle_from_centerline()

        self.obb_points = self._normalized_points_from_scene(final_scene_points)

        if len(self.obb_points) != 4:
            logger.warning("Failed to normalize finalized OBB.")
            return

        p0, p1, p2, p3 = final_scene_points

        self.centerline_start = (p0 + p3) / 2
        self.centerline_end = (p1 + p2) / 2
        self.current_width = float(np.hypot(p0.x() - p3.x(), p0.y() - p3.y()))
        self.current_state = "bb_defined"

        self.render_from_points()

        if self.scene():
            self.scene().update()

        self.main_window.screen_view.viewport().update()

        if hasattr(self.main_window, "save_bounding_boxes"):
            self.main_window.save_bounding_boxes(
                self.main_window.current_file,
                img_w,
                img_h
            )

        self.setAcceptedMouseButtons(Qt.LeftButton | Qt.RightButton)

    def start_moving(self, scene_pos):
        return

    def update_position(self, scene_pos):
        return

    def stop_moving(self):
        return

    def remove_self(self):
        self.remove_obb_from_file()

        scene = self.scene()
        if scene:
            if self.centerline_item:
                scene.removeItem(self.centerline_item)
                self.centerline_item = None

            if self.class_name_item and self.class_name_item.scene():
                scene.removeItem(self.class_name_item)

            for handle in self.vertex_handles:
                if handle.scene():
                    handle.scene().removeItem(handle)
            self.vertex_handles = []

            scene.removeItem(self)

        self.centerline_start = None
        self.centerline_end = None
        self.obb_points = []
        self.current_width = 0.0
        self.drawing_in_progress = False
        self.current_state = "awaiting_centerline_start"
        self.edit_mode = False

    def clear(self):
        self.centerline_start = None
        self.centerline_end = None
        self.current_width = 0.0
        self.drawing_in_progress = False
        self.setPolygon(QPolygonF())

    def remove_obb_from_file(self):
        if not self.file_name:
            logger.warning("Cannot remove OBB: no file path is attached.")
            return

        if not self.obb_points or len(self.obb_points) != 4:
            logger.warning("Cannot remove OBB: obb_points is not set.")
            return

        label_file = os.path.splitext(self.file_name)[0] + ".txt"
        if not os.path.exists(label_file):
            logger.debug(f"Label file not found: {label_file}")
            return

        target = [coord for pt in self.obb_points for coord in pt]

        try:
            with open(label_file, "r", encoding="utf-8") as f:
                lines = f.readlines()

            kept_lines = []
            removed = False

            for line in lines:
                parts = line.strip().split()

                if len(parts) != 9:
                    kept_lines.append(line)
                    continue

                try:
                    class_id = int(parts[0])
                    floats = list(map(float, parts[1:]))

                    if class_id == self.class_id and np.allclose(floats, target, atol=1e-6):
                        removed = True
                        continue
                except Exception:
                    pass

                kept_lines.append(line)

            with open(label_file, "w", encoding="utf-8") as f:
                f.writelines(kept_lines)

            if not removed:
                logger.debug("No exact OBB match found during remove.")
        except Exception as e:
            logger.error(f"Failed removing OBB: {e}")

    def restore_centerline_from_obb(self):
        try:
            if not self.obb_points or len(self.obb_points) != 4:
                logger.warning("Cannot restore centerline: obb_points is not set or invalid.")
                return

            pts = self._scene_points_from_normalized(self.obb_points)

            self.centerline_start = (pts[0] + pts[3]) / 2
            self.centerline_end = (pts[1] + pts[2]) / 2

            height_vec = np.array([pts[0].x() - pts[3].x(), pts[0].y() - pts[3].y()], dtype=float)
            self.current_width = float(np.linalg.norm(height_vec))
            self.current_state = "bb_defined"
        except Exception as e:
            logger.error(f"Failed to restore centerline: {e}")

    def _update_label_badge(self):
        poly = self.polygon()
        if poly.count() != 4:
            return

        img_w, img_h = self._get_image_dimensions()
        if img_w <= 0 or img_h <= 0:
            return

        scene_points = [self.mapToScene(poly[i]) for i in range(poly.count())]

        top_points = sorted(scene_points, key=lambda p: (p.y(), p.x()))[:2]
        anchor_scene = QPointF(
            (top_points[0].x() + top_points[1].x()) / 2,
            (top_points[0].y() + top_points[1].y()) / 2,
        )

        center_x = sum(p.x() for p in scene_points) / 4
        center_y = sum(p.y() for p in scene_points) / 4
        dx = anchor_scene.x() - center_x
        dy = anchor_scene.y() - center_y

        length = math.hypot(dx, dy)
        if length < 1:
            dx, dy = 0, -1
            length = 1

        nx = dx / length
        ny = dy / length

        text_rect = self.class_name_item.boundingRect()
        badge_w = max(38, text_rect.width() + 12)
        badge_h = max(20, text_rect.height() + 6)

        gap = 10
        label_x = anchor_scene.x() + nx * gap - badge_w / 2
        label_y = anchor_scene.y() + ny * gap - badge_h / 2

        label_x = max(4, min(label_x, img_w - badge_w - 4))
        label_y = max(4, min(label_y, img_h - badge_h - 4))

        self.class_name_item.setPos(label_x + 6, label_y + 2)

        badge_rect = QRectF(label_x, label_y, badge_w, badge_h)
        path = QPainterPath()
        path.addRoundedRect(badge_rect, 5, 5)

        color = self._get_class_color(alpha=225)
        self.label_badge_item.setPath(path)
        self.label_badge_item.setBrush(QBrush(color))
        self.label_badge_item.setPen(QPen(QColor(255, 255, 255, 210), 1.25))

        # Line stops at bottom-center of badge, not center of label/text.
        badge_anchor = QPointF(
            label_x + badge_w / 2,
            label_y + badge_h,
        )

        leader_pen = QPen(color, 2)
        leader_pen.setCapStyle(Qt.RoundCap)

        self.label_leader_item.setLine(
            anchor_scene.x(),
            anchor_scene.y(),
            badge_anchor.x(),
            badge_anchor.y(),
        )
        self.label_leader_item.setPen(leader_pen)


class BoundingBox:
    """
    Represents a bounding box for object detection.
    """

    EXPECTED_KEYPOINT_COUNT = None

    @staticmethod

    def _clip(val, minv=0.0, maxv=1.0):
        return max(minv, min(maxv, float(val)))

    def __init__(self, class_id, x_center, y_center, width, height, confidence=None,
                 segmentation=None, keypoints=None, obb=None):
        self.class_id = int(class_id)

        self.x_center = self._clip(x_center)
        self.y_center = self._clip(y_center)
        self.width = self._clip(width)
        self.height = self._clip(height)

        self.confidence = float(confidence) if confidence is not None else None
        self.segmentation = segmentation.copy() if segmentation is not None else []
        self.keypoints = keypoints.copy() if keypoints is not None else []
        self.obb = obb.copy() if obb is not None else []

    @classmethod

    def from_rect(cls, rect, img_width, img_height, class_id, confidence=None):
        x_center = (rect.x() + rect.width() / 2) / img_width
        y_center = (rect.y() + rect.height() / 2) / img_height
        width = rect.width() / img_width
        height = rect.height() / img_height
        return cls(class_id, x_center, y_center, width, height, confidence)

    def to_rect(self, img_width, img_height):
        x = self.x_center * img_width - self.width * img_width / 2
        y = self.y_center * img_height - self.height * img_height / 2
        width = self.width * img_width
        height = self.height * img_height
        return QRectF(x, y, width, height)

    @staticmethod

    def from_str(label_str, preferred_polygon_type=None):
        if not label_str.strip():
            logging.warning("Empty label string encountered.")
            return None

        parts = label_str.strip().split()

        if len(parts) < 2:
            logging.warning(f"Incomplete label string: {label_str}")
            return None

        try:
            class_id = int(float(parts[0]))
            floats = list(map(float, parts[1:]))
        except (ValueError, IndexError) as e:
            logging.warning(f"Failed to parse floats from label string '{label_str}': {e}")
            return None

        def is_normalized_bbox(vals):
            if len(vals) < 4:
                return False

            x_center, y_center, width, height = vals[:4]

            return (
                0.0 <= x_center <= 1.0 and
                0.0 <= y_center <= 1.0 and
                0.0 < width <= 1.0 and
                0.0 < height <= 1.0
            )

        def is_pose_keypoint_line(vals):
            expected_kpts = getattr(BoundingBox, "EXPECTED_KEYPOINT_COUNT", None)

            if expected_kpts is not None and expected_kpts > 0:
                expected_float_count = 4 + (expected_kpts * 3)

                if len(vals) != expected_float_count:
                    return False
            elif len(vals) <= 4 or (len(vals) - 4) % 3 != 0:
                return False

            if not is_normalized_bbox(vals):
                return False

            keypoint_values = vals[4:]

            for i in range(0, len(keypoint_values), 3):
                try:
                    x = float(keypoint_values[i])
                    y = float(keypoint_values[i + 1])
                    visibility_value = float(keypoint_values[i + 2])
                except Exception:
                    return False

                if not visibility_value.is_integer():
                    return False

                v = int(visibility_value)
                if v not in (0, 1, 2):
                    return False

                if v in (1, 2):
                    if not (0.0 <= x <= 1.0 and 0.0 <= y <= 1.0):
                        return False

            return True

        polygon_preference = str(preferred_polygon_type or "").strip().lower()

        if len(floats) == 8 and polygon_preference in {"seg", "segment", "segmentation"}:
            return BoundingBox(class_id, 0, 0, 0, 0, segmentation=floats)

        if len(floats) == 8:
            return BoundingBox(class_id, 0, 0, 0, 0, obb=floats)

        if len(floats) == 4:
            x_center, y_center, width, height = floats
            return BoundingBox(class_id, x_center, y_center, width, height)

        if len(floats) == 5:
            x_center, y_center, width, height, confidence = floats
            return BoundingBox(class_id, x_center, y_center, width, height, confidence=confidence)

        if is_pose_keypoint_line(floats):
            x_center, y_center, width, height = floats[:4]
            keypoints = [
                (floats[i], floats[i + 1], int(float(floats[i + 2])))
                for i in range(4, len(floats), 3)
            ]
            return BoundingBox(class_id, x_center, y_center, width, height, keypoints=keypoints)

        if len(floats) >= 6 and len(floats) % 2 == 0:
            return BoundingBox(class_id, 0, 0, 0, 0, segmentation=floats)

        logging.warning(f"Unrecognized label format: {label_str}")
        return None

    def to_str(self, remove_confidence=True):
        class_id_str = f"{int(self.class_id)}"

        if self.obb:
            obb_str = " ".join(f"{coord:.6f}" for coord in self.obb)
            return f"{class_id_str} {obb_str}"

        if self.segmentation:
            seg_str = " ".join(f"{coord:.6f}" for coord in self.segmentation)
            return f"{class_id_str} {seg_str}"

        bbox_str = f"{class_id_str} {self.x_center:.6f} {self.y_center:.6f} {self.width:.6f} {self.height:.6f}"

        if self.keypoints:
            kpt_str = " ".join(f"{x:.6f} {y:.6f} {v:d}" for x, y, v in self.keypoints)
            return f"{bbox_str} {kpt_str}"

        if self.confidence is not None and not remove_confidence:
            bbox_str += f" {self.confidence:.6f}"

        return bbox_str

    def to_dict(self):
        return {
            "class_id": self.class_id,
            "x_center": self.x_center,
            "y_center": self.y_center,
            "width": self.width,
            "height": self.height,
            "confidence": self.confidence,
            "segmentation": self.segmentation,
            "keypoints": self.keypoints,
            "obb": self.obb,
        }

    @property

    def confidence_safe(self):
        try:
            return float(self.confidence)
        except (TypeError, ValueError):
            return 0.0

    def num_visible_keypoints(self):
        return sum(
            1 for kp in self.keypoints
            if isinstance(kp, (list, tuple)) and len(kp) == 3 and kp[2] == 2
        )

    def iou(self, other):
        if not isinstance(other, BoundingBox):
            return 0.0

        x1_min = self.x_center - self.width / 2
        y1_min = self.y_center - self.height / 2
        x1_max = self.x_center + self.width / 2
        y1_max = self.y_center + self.height / 2

        x2_min = other.x_center - other.width / 2
        y2_min = other.y_center - other.height / 2
        x2_max = other.x_center + other.width / 2
        y2_max = other.y_center + other.height / 2

        inter_xmin = max(x1_min, x2_min)
        inter_ymin = max(y1_min, y2_min)
        inter_xmax = min(x1_max, x2_max)
        inter_ymax = min(y1_max, y2_max)

        inter_w = max(0.0, inter_xmax - inter_xmin)
        inter_h = max(0.0, inter_ymax - inter_ymin)
        inter_area = inter_w * inter_h

        area1 = (x1_max - x1_min) * (y1_max - y1_min)
        area2 = (x2_max - x2_min) * (y2_max - y2_min)
        union = area1 + area2 - inter_area

        if union <= 0:
            return 0.0

        return inter_area / union

    def to_polygon(self, image_width, image_height):
        if self.segmentation:
            points = [
                (self.segmentation[i] * image_width, self.segmentation[i + 1] * image_height)
                for i in range(0, len(self.segmentation), 2)
            ]
            return Polygon(points)

        if self.obb:
            points = [
                (self.obb[i] * image_width, self.obb[i + 1] * image_height)
                for i in range(0, 8, 2)
            ]
            return Polygon(points)

        rect = self.to_rect(image_width, image_height)
        return shapely_box(rect.x(), rect.y(), rect.x() + rect.width(), rect.y() + rect.height())

    def to_xyxy(self, img_width, img_height):
        x1 = (self.x_center - self.width / 2) * img_width
        y1 = (self.y_center - self.height / 2) * img_height
        x2 = (self.x_center + self.width / 2) * img_width
        y2 = (self.y_center + self.height / 2) * img_height
        return x1, y1, x2, y2

# Creates a graphical user interface (GUI) for the settings dialog.

class SettingsDialog(QtWidgets.QDialog):

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Settings")
        self.resize(940, 760)
        self.setMinimumSize(760, 620)
        parent_style = parent.styleSheet() if parent is not None else ""
        if parent_style:
            self.setStyleSheet(parent_style)

        self.classHotkeyInputs = {}
        self.classColorPickers = {}
        self.keybind_labels = {}

        self.tabs = QtWidgets.QTabWidget(self)
        self.keybinds_tab = QtWidgets.QWidget()
        self.general_tab = QtWidgets.QWidget()

        self.tabs.addTab(self.keybinds_tab, "Shortcuts")
        self.tabs.addTab(self.general_tab, "General")

        main_layout = QtWidgets.QVBoxLayout(self)
        main_layout.setContentsMargins(12, 12, 12, 12)
        main_layout.setSpacing(10)

        header_row = QtWidgets.QHBoxLayout()
        title_label = QtWidgets.QLabel("Settings")
        title_label.setStyleSheet("font-size: 15px; font-weight: 700;")
        header_row.addWidget(title_label)
        header_row.addStretch()

        dataset_dir = getattr(parent, "image_directory", "") if parent is not None else ""
        if dataset_dir:
            dataset_label = QtWidgets.QLabel(f"Dataset: {os.path.basename(dataset_dir) or dataset_dir}")
            dataset_label.setStyleSheet("color: #9aa4af;")
            dataset_label.setTextInteractionFlags(Qt.TextSelectableByMouse)
            header_row.addWidget(dataset_label)

        main_layout.addLayout(header_row)
        main_layout.addWidget(self.tabs)

        self.init_keybinds_tab()
        self.init_general_tab()

        buttons = QtWidgets.QDialogButtonBox(QtWidgets.QDialogButtonBox.Close)
        buttons.rejected.connect(self.accept)
        main_layout.addWidget(buttons)

    def save_xy_lines_setting(self, checked):
        self.parent().settings["showXYLines"] = bool(checked)
        self.parent().saveSettings()

        if hasattr(self.parent(), "screen_view") and hasattr(self.parent().screen_view, "toggle_crosshair"):
            self.parent().screen_view.toggle_crosshair(checked)

    def pick_crosshair_color_setting(self):
        saved_color = self.parent().settings.get("crosshairColor", [255, 255, 0])

        if isinstance(saved_color, (list, tuple)) and len(saved_color) >= 3:
            current_color = QColor(int(saved_color[0]), int(saved_color[1]), int(saved_color[2]))
        else:
            current_color = QColor(255, 255, 0)

        color = QColorDialog.getColor(current_color, self, "Pick Crosshair Color")

        if not color.isValid():
            return

        self.parent().settings["crosshairColor"] = [
            color.red(),
            color.green(),
            color.blue()
        ]
        self.parent().saveSettings()

        self.crosshair_color_btn.setStyleSheet(
            f"background-color: rgb({color.red()}, {color.green()}, {color.blue()}); border: 1px solid #333;"
        )

        if hasattr(self.parent(), "screen_view"):
            self.parent().screen_view.crosshair_color_rgb = (
                color.red(),
                color.green(),
                color.blue()
            )
            self.parent().screen_view.viewport().update()

    def _qcolor_from_setting(self, key, fallback):
        value = self.parent().settings.get(key, fallback)
        if isinstance(value, str):
            color = QColor(value)
            if color.isValid():
                return color
        if isinstance(value, (list, tuple)) and len(value) >= 3:
            try:
                return QColor(int(value[0]), int(value[1]), int(value[2]))
            except Exception:
                pass
        return QColor(int(fallback[0]), int(fallback[1]), int(fallback[2]))

    def _set_color_button_style(self, button, color):
        button.setStyleSheet(
            "QPushButton {"
            f"background-color: rgb({color.red()}, {color.green()}, {color.blue()});"
            "border: 1px solid #30363d;"
            "border-radius: 4px;"
            "}"
        )

    def pick_preview_color_setting(self, button, key, fallback, title):
        color = QColorDialog.getColor(
            self._qcolor_from_setting(key, fallback),
            self,
            title,
        )
        if not color.isValid():
            return

        self.parent().set_preview_flash_color(key, color)
        self._set_color_button_style(button, color)

    def save_preview_visible_setting(self, checked):
        if hasattr(self.parent(), "set_label_preview_visible"):
            self.parent().set_label_preview_visible(bool(checked))

    def save_preview_hover_zoom_setting(self, checked):
        if hasattr(self.parent(), "set_preview_hover_zoom_enabled"):
            self.parent().set_preview_hover_zoom_enabled(bool(checked))

    def save_preview_thumbnail_size_setting(self, value):
        if hasattr(self.parent(), "set_preview_thumbnail_size"):
            self.parent().set_preview_thumbnail_size(value)
        if hasattr(self, "preview_thumbnail_value_label"):
            self.preview_thumbnail_value_label.setText(f"{int(value)} px")

    def save_preview_batch_size_setting(self, value):
        if hasattr(self.parent(), "set_preview_batch_size"):
            self.parent().set_preview_batch_size(value)

    def save_preview_flash_time_setting(self, value):
        if hasattr(self.parent(), "set_preview_flash_time"):
            self.parent().set_preview_flash_time(value)

    def _copy_combo_items(self, source_combo, target_combo):
        target_combo.clear()
        if source_combo is None:
            return
        for index in range(source_combo.count()):
            target_combo.addItem(source_combo.itemText(index), source_combo.itemData(index))

    def save_theme_setting(self, text):
        parent = self.parent()
        combo = getattr(parent, "styleComboBox", None)
        if combo is None:
            return
        index = combo.findText(text)
        if index >= 0 and combo.currentIndex() != index:
            combo.setCurrentIndex(index)
        parent_gif_combo = getattr(parent, "gif_change", None)
        if parent_gif_combo is not None and hasattr(self, "gif_combo"):
            self.gif_combo.blockSignals(True)
            self.gif_combo.setCurrentText(parent_gif_combo.currentText())
            self.gif_combo.blockSignals(False)
        if hasattr(parent, "saveSettings"):
            parent.saveSettings()

    def save_gif_setting(self, text):
        parent = self.parent()
        combo = getattr(parent, "gif_change", None)
        if combo is None:
            return
        index = combo.findText(text)
        if index >= 0 and combo.currentIndex() != index:
            combo.setCurrentIndex(index)
        if hasattr(parent, "settings"):
            parent.settings["lastGif"] = text
        if hasattr(parent, "saveSettings"):
            parent.saveSettings()

    def save_language_setting(self, index):
        parent = self.parent()
        source_combo = getattr(parent, "language_dropdown", None)
        if source_combo is None or index < 0:
            return
        lang_code = self.language_combo.itemData(index)
        target_index = source_combo.findData(lang_code)
        if target_index >= 0 and source_combo.currentIndex() != target_index:
            source_combo.setCurrentIndex(target_index)
        if hasattr(parent, "settings"):
            parent.settings["languageCode"] = lang_code or "en"
        if hasattr(parent, "saveSettings"):
            parent.saveSettings()

    def update_ui_scale_controls(self):
        auto_scale = bool(self.auto_scale_ui_checkbox.isChecked())
        self.ui_scale_slider.setEnabled(not auto_scale)
        if auto_scale and hasattr(self.parent(), "recommended_ui_scale_percent"):
            percent = int(self.parent().recommended_ui_scale_percent())
            self.ui_scale_value_label.setText(f"{percent}% auto")
        else:
            self.ui_scale_value_label.setText(f"{int(self.ui_scale_slider.value())}%")

    def apply_ui_scale_setting(self):
        parent = self.parent()
        parent.settings["autoScaleUi"] = bool(self.auto_scale_ui_checkbox.isChecked())
        parent.settings["uiScalePercent"] = int(self.ui_scale_slider.value())
        if hasattr(parent, "apply_ui_scale"):
            parent.apply_ui_scale(persist=True)
        self.update_ui_scale_controls()

