    def saveSettings(self):
        self.collect_persistent_ui_state()
        self.settings.pop("language", None)

        if hasattr(self, "styleComboBox"):
            self.settings['lastTheme'] = self.styleComboBox.currentText()

        app_settings, project_settings = self.split_settings_for_storage(self.settings)
        project_path = self.project_settings_path()

        try:
            if not project_path:
                app_settings.update(project_settings)
                write_json_file_atomic(self.app_settings_path(), app_settings)
                return

            if project_settings:
                write_json_file_atomic(project_path, project_settings)

            write_json_file_atomic(self.app_settings_path(), app_settings)
        except Exception as e:
            logger.error(f"Failed saving settings: {e}")

    def save_project_settings_for_directory(self, directory, settings=None):
        if settings is None:
            self.collect_persistent_ui_state()
        settings = settings or getattr(self, "settings", {})
        _, project_settings = self.split_settings_for_storage(settings)
        if not project_settings:
            return

        project_path = self.project_settings_path(directory)
        if project_path:
            try:
                write_json_file_atomic(project_path, project_settings)
            except Exception as e:
                logger.error(f"Failed saving project settings for {directory}: {e}")

    def activate_project_settings(self, directory):
        directory = self.normalize_path(directory)
        self.collect_persistent_ui_state()
        current_settings = getattr(self, "settings", self.defaultSettings())
        previous_directory = (
            current_settings.get("last_dir", "")
            or getattr(self, "image_directory", "")
        )

        if previous_directory:
            self.save_project_settings_for_directory(previous_directory, current_settings)

        app_settings, _ = self.split_settings_for_storage(current_settings)
        app_settings["last_dir"] = directory

        self.settings = self.defaultSettings()
        self.settings.update(app_settings)
        self.settings.update(self.load_project_settings(directory))
        self.settings["last_dir"] = directory

    def normalize_path(self, path):
        try:
            if not path:
                return ""
            return os.path.abspath(str(path)).replace("\\", "/")
        except Exception:
            return str(path).replace("\\", "/")

    def get_saved_last_image_for_dir(self, directory):
        try:
            project_path = self.project_settings_path(directory)
            has_project_settings = bool(project_path and os.path.exists(project_path))
            settings = self.loadSettings(project_directory=directory)
            last_dir = self.normalize_path(settings.get("last_dir", ""))
            current_dir = self.normalize_path(directory)
            last_image = self.normalize_path(settings.get("lastImage", ""))

            if not last_image:
                return None

            if not has_project_settings and last_dir and last_dir != current_dir:
                return None

            if os.path.exists(last_image):
                return last_image

            # Fallback: match by basename in case folder moved or slash style changed.
            last_base = os.path.basename(last_image)
            for image_file in getattr(self, "image_files", []):
                if os.path.basename(image_file) == last_base:
                    return image_file

        except Exception as e:
            logger.warning(f"Failed getting saved last image: {e}")

        return None

    def save_current_dataset_position(self, image_file=None):
        try:
            if image_file is None:
                image_file = getattr(self, "current_file", "")

            if not image_file or self.is_placeholder_file(image_file):
                return

            self.settings["last_dir"] = self.normalize_path(getattr(self, "image_directory", ""))
            self.settings["lastImage"] = self.normalize_path(image_file)

            try:
                self.settings["lastImageIndex"] = int(getattr(self, "current_img_index", 0))
            except Exception:
                self.settings["lastImageIndex"] = 0

            self.saveSettings()

        except Exception as e:
            logger.warning(f"Failed saving current dataset position: {e}")

    def restore_current_image_after_load(self, preferred_image=None):
        try:
            target = self.normalize_path(preferred_image) if preferred_image else None

            search_list = getattr(self, "filtered_image_files", None) or getattr(self, "image_files", [])

            if target and target in search_list:
                self.current_file = target
                self.current_img_index = search_list.index(target)
                self.current_image_index = self.image_files.index(target) if target in self.image_files else self.current_img_index
                return True

            if target:
                target_base = os.path.basename(target)
                for image_file in search_list:
                    if os.path.basename(image_file) == target_base:
                        self.current_file = image_file
                        self.current_img_index = search_list.index(image_file)
                        self.current_image_index = self.image_files.index(image_file) if image_file in self.image_files else self.current_img_index
                        return True

            real_files = [f for f in search_list if not self.is_placeholder_file(f)]
            if real_files:
                self.current_file = real_files[0]
                self.current_img_index = search_list.index(self.current_file)
                self.current_image_index = self.image_files.index(self.current_file) if self.current_file in self.image_files else self.current_img_index
                return True

            if search_list:
                self.current_file = search_list[0]
                self.current_img_index = 0
                self.current_image_index = 0
                return True

        except Exception as e:
            logger.warning(f"Failed restoring current image after load: {e}")

        return False

    def set_sound(self, sound_path):
        self.sound_player.setMedia(
            QMediaContent(QUrl.fromLocalFile(sound_path)))
        self.sound_player.play()

    # -----------------------------
    # TRANSLATION AND VOICE CONTROLS
    # -----------------------------

    def change_language(self, index):
        if index < 0:
            return
        lang_code = self.language_dropdown.itemData(index)
        if hasattr(self, "settings"):
            self.settings["languageCode"] = lang_code or "en"
            self.saveSettings()
        logger.debug(f"Loading bundled UI language: {lang_code}")

        self.translation_cache = self.load_translations(lang_code)
        missing_keys = []
        for key, original_text in self.original_ui_texts.items():
            translated_text = self.translation_cache.get(key)
            if not translated_text:
                translated_text = original_text
                missing_keys.append(key)
            self.update_widget_by_key(key, translated_text)

        if missing_keys:
            logger.warning(
                "Bundled translation '%s' is missing %d entries; using English fallback.",
                lang_code,
                len(missing_keys),
            )
        else:
            logger.debug("Bundled UI language loaded without network translation.")

    def update_widget_by_key(self, key, translated_text):
        if '_item_' in key:
            widget_name, index = key.rsplit('_item_', 1)
            widget = self.findChild(QtWidgets.QComboBox, widget_name)
            if widget:
                widget.setItemText(int(index), translated_text)

        elif '_toolbox_' in key:
            widget_name, index = key.rsplit('_toolbox_', 1)
            widget = self.findChild(QtWidgets.QToolBox, widget_name)
            if widget:
                widget.setItemText(int(index), translated_text)

        elif '_header_' in key:
            widget_name, col = key.rsplit('_header_', 1)
            widget = self.findChild(QtWidgets.QTableWidget, widget_name)
            if widget:
                header_item = widget.horizontalHeaderItem(int(col))
                if header_item:
                    header_item.setText(translated_text)

        elif key.endswith("_tooltip"):
            base_key = key.rsplit('_tooltip', 1)[0]
            widget = self.findChild(QtWidgets.QWidget, base_key)
            if widget:
                widget.setToolTip(translated_text)

        elif key.endswith("_whatsthis"):
            base_key = key.rsplit('_whatsthis', 1)[0]
            widget = self.findChild(QtWidgets.QWidget, base_key)
            if widget:
                widget.setWhatsThis(translated_text)

        elif '_tab_' in key:
            widget_name, index = key.rsplit('_tab_', 1)
            widget = self.findChild(QtWidgets.QTabWidget, widget_name)
            if widget:
                widget.setTabText(int(index), translated_text)

        elif key == "window_title":
            self.setWindowTitle(translated_text)

        else:
            widget = self.findChild(QtWidgets.QWidget, key)
            if widget and hasattr(widget, 'setText'):
                widget.setText(translated_text)
            else:
                action = self.findChild(QtWidgets.QAction, key)
                if action:
                    action.setText(translated_text)
                else:
                    menu = self.findChild(QtWidgets.QMenu, key)
                    if menu:
                        menu.setTitle(translated_text)

    def get_translation_filepath(self, lang_code):
        translation_dir = Path(__file__).resolve().parent / "translations"
        return translation_dir / f"{lang_code}.json"

    def load_translations(self, lang_code):
        if lang_code in self.translations_memory_cache:
            return self.translations_memory_cache[lang_code]

        filepath = self.get_translation_filepath(lang_code)
        if filepath.exists():
            try:
                with open(filepath, "r", encoding="utf-8") as file:
                    self.translations_memory_cache[lang_code] = json.load(file)
                return self.translations_memory_cache[lang_code]
            except (OSError, json.JSONDecodeError) as exc:
                logger.warning("Could not load bundled translation '%s': %s", lang_code, exc)
        return {}

    def toggle_voice_mode(self, state):
        if state == Qt.Checked:
            existing_thread = getattr(self, "voice_thread", None)
            if existing_thread is not None and existing_thread.is_alive():
                return

            self.voice_thread_active = True
            self.voice_thread = threading.Thread(target=self.continuous_voice_loop, daemon=True)
            self.voice_thread.start()
            widget = getattr(self, "voice_mode_checkbox", None)
            if widget is not None:
                widget.setToolTip("Continuous voice class selection is active.")
            self.statusBar().showMessage("Voice labeling activated")
        else:
            self.voice_thread_active = False
            widget = getattr(self, "voice_mode_checkbox", None)
            if widget is not None:
                widget.setToolTip("Turn on continuous voice class selection.")
            self.statusBar().showMessage("Voice labeling stopped")

    def continuous_voice_loop(self):
        recognizer = sr.Recognizer()
        mic = sr.Microphone()

        with mic as source:
            recognizer.adjust_for_ambient_noise(source)

        while self.voice_thread_active:
            try:
                with mic as source:
                    self.statusBar().showMessage("🎙️ Listening for class...")
                    audio = recognizer.listen(source, phrase_time_limit=2)

                text = recognizer.recognize_google(audio).strip().lower()
                self.statusBar().showMessage(f"🔈 Heard: {text}")

                for i in range(self.classes_dropdown.count()):
                    class_name = self.classes_dropdown.itemText(i)

                    if text == class_name.lower() or self.keybind_matches_setting(class_hotkey_key(class_name), text):
                        self.classes_dropdown.setCurrentIndex(i)
                        self.statusBar().showMessage(f"✅ Selected class: {class_name}")
                        break
                else:
                    self.statusBar().showMessage("❌ No match for voice input")

            except sr.UnknownValueError:
                self.statusBar().showMessage("🤔 Didn't catch that...")
            except sr.RequestError:
                self.statusBar().showMessage("❌ Speech API error")
            except Exception as e:
                self.statusBar().showMessage(f"⚠️ Error: {str(e)}")

    def closeEvent(self, event):
        """
        Ensure annotations are saved safely before application closes.
        """

        try:
            if (
                hasattr(self, "save_bounding_boxes")
                and hasattr(self, "current_file")
                and self.current_file
                and not self.is_placeholder_file(self.current_file)
            ):
                scene = self.screen_view.scene() if hasattr(self, "screen_view") else None

                if scene:
                    logger.info(f"Saving before close: {self.current_file}")

                    self.save_bounding_boxes(
                        self.current_file,
                        scene.width(),
                        scene.height()
                    )

        except Exception as e:
            logger.error(f"Failed saving during closeEvent: {e}")

        try:
            self.save_current_dataset_position()
            self.saveSettings()
        except Exception as e:
            logger.error(f"Failed saving persistent UI state during closeEvent: {e}")

        self.cleanup_runtime_resources()
        event.accept()

    def _stop_and_delete_timer(self, attr_name):
        timer = getattr(self, attr_name, None)
        if timer is None:
            return

        try:
            timer.stop()
        except RuntimeError:
            pass

        try:
            timer.timeout.disconnect()
        except (TypeError, RuntimeError):
            pass

        try:
            timer.deleteLater()
        except RuntimeError:
            pass

        setattr(self, attr_name, None)

    def _release_capture(self):
        capture = getattr(self, "capture", None)
        if capture is None:
            return

        try:
            capture.release()
        except Exception as e:
            logger.warning(f"Failed releasing capture: {e}")

        self.capture = None

    def stop_live_collect_runtime(self, reset_input=False):
        """Stop video, stream, desktop, camera, and extraction runtime without clearing loaded models."""
        self.extracting_frames = False
        self.extract_mode_active = False
        self.playback_extraction_enabled = True
        self._live_timer_paused = False
        self.is_camera_mode = False
        self.is_playing = False
        self.slider_is_pressed = False
        self.stop_extraction(wait=False)
        self.stop_video_reader_thread()
        self.stop_video_inference_thread()

        for timer_attr in ("timer2", "forward_timer", "backward_timer"):
            timer = getattr(self, timer_attr, None)
            if timer is None:
                continue
            try:
                timer.stop()
            except RuntimeError:
                pass

        if getattr(self, "timer2", None) is not None:
            try:
                self.timer2.timeout.disconnect()
            except (TypeError, RuntimeError):
                pass

        self._release_capture()
        self._close_mss_resources()

        if hasattr(self, "play_video_button") and self.play_video_button is not None:
            self.play_video_button.setText("Play")

        if hasattr(self, "video_slider") and self.video_slider is not None:
            self.video_slider.setValue(0)
            self.video_slider.setEnabled(False)

        if hasattr(self, "time_label") and self.time_label is not None:
            self.time_label.setText("00:00 / 00:00")

        self._live_display_active = False
        self._live_display_size = None
        self.latest_video_overlay = None
        self._last_video_frame_bgr = None
        self.reset_video_performance_counters(update=False)
        self.update_video_frame_label(0)
        self.update_video_status_label(force=True)
        if reset_input:
            self.enter_image_annotation_mode(clear_video_surface=True)

        if reset_input and hasattr(self, "input_selection") and self.input_selection is not None:
            try:
                if self.input_selection.currentText() != "null":
                    with blocked_signals(self.input_selection):
                        self.input_selection.setCurrentText("null")
                self._active_input_source_text = "null"
            except RuntimeError:
                pass

        logger.info("Stopped live collect runtime.")

    def _close_mss_resources(self):
        for attr_name in ("_mss_instance", "sct"):
            instance = getattr(self, attr_name, None)
            if instance is None:
                continue

            try:
                instance.close()
            except Exception as e:
                logger.debug(f"Failed closing {attr_name}: {e}")

            setattr(self, attr_name, None)

        self._mss_monitors = None

    def _cleanup_worker_reference(self, attr_name, worker=None):
        worker = worker or getattr(self, attr_name, None)
        if worker is None:
            return

        try:
            if hasattr(worker, "isRunning") and worker.isRunning():
                QTimer.singleShot(100, lambda: self._cleanup_worker_reference(attr_name, worker))
                return
        except RuntimeError:
            pass

        try:
            worker.deleteLater()
        except RuntimeError:
            pass

        if getattr(self, attr_name, None) is worker:
            setattr(self, attr_name, None)

    def _cleanup_download_thread(self, thread):
        try:
            if thread in self.download_threads:
                self.download_threads.remove(thread)
        except Exception:
            pass

        try:
            thread.deleteLater()
        except RuntimeError:
            pass

    def cleanup_runtime_resources(self):
        self.metrics_thread_active = False
        self.voice_thread_active = False

        augmentation_job = getattr(self, "_augmentation_job", None)
        if augmentation_job is not None:
            augmentation_job["cancel_requested"] = True
            self._augmentation_job = None
            logger.info("Canceled the active augmentation job during application shutdown.")

        self.stop_live_collect_runtime(reset_input=True)

        dialog = getattr(self, "cuda_monitor_dialog", None)
        if dialog is not None:
            try:
                dialog.close_for_cleanup()
            except RuntimeError:
                pass
            self.cuda_monitor_dialog = None

        for attr_name in (
            "timer2",
            "_overlay_timer",
            "_thumbnail_timer",
            "process_timer",
            "next_timer",
            "prev_timer",
            "delete_timer",
            "forward_timer",
            "backward_timer",
            "auto_save_timer",
            "icon_timer",
            "console_output_timer",
            "timer",
        ):
            self._stop_and_delete_timer(attr_name)

        self._release_capture()
        self._close_mss_resources()
        self.stop_existing_workers()

        if hasattr(self, "threadpool") and self.threadpool is not None:
            self.threadpool.clear()

        for attr_name in ("metrics_thread", "voice_thread"):
            thread = getattr(self, attr_name, None)
            if thread is None:
                continue

            try:
                if thread.is_alive():
                    thread.join(timeout=0.2)
            except RuntimeError:
                pass

            try:
                if not thread.is_alive():
                    setattr(self, attr_name, None)
            except RuntimeError:
                setattr(self, attr_name, None)

        for thread in list(getattr(self, "download_threads", [])):
            try:
                if not thread.isRunning():
                    self._cleanup_download_thread(thread)
            except RuntimeError:
                self._cleanup_download_thread(thread)

        if hasattr(self, "movie") and self.movie is not None:
            self.movie.stop()

        if hasattr(self, "sound_player") and self.sound_player is not None:
            self.sound_player.stop()

        self._super_resolution_model = None
        self._super_resolution_model_path = None
        self._clarity_clahe = None

        if hasattr(self, "logger") and hasattr(self, "label_log_handler"):
            try:
                self.logger.removeHandler(self.label_log_handler)
            except Exception:
                pass

    #points.json and keypoint list management

    def ensure_points_json_exists(self):
        """
        Ensure points.json exists once for the dataset, then load it.
        """
        if not getattr(self, "image_directory", None):
            return

        default_keypoints = list(DEFAULT_POSE_KEYPOINT_LABELS)

        default_json_path = os.path.join(self.image_directory, "points.json")

        if not os.path.exists(default_json_path):
            keypoints = []
            for i, label in enumerate(default_keypoints):
                color = get_color(i, len(default_keypoints))
                keypoints.append({
                    "label": label,
                    "color": [color.red(), color.green(), color.blue(), 150],
                    "visible": True,
                    "ignore": False
                })

            skeleton = [list(pair) for pair in DEFAULT_POSE_SKELETON]
            flip_idx = list(DEFAULT_POSE_FLIP_IDX)

            json_data = {
                "kpt_shape": [len(keypoints), 3],
                "keypoints": keypoints,
                "skeleton": skeleton,
                "flip_idx": flip_idx
            }

            try:
                with open(default_json_path, "w", encoding="utf-8") as f:
                    json.dump(json_data, f, indent=4, separators=(",", ": "))
                logger.info(f"Created default keypoint list: {default_json_path}")
            except Exception as e:
                logger.error(f"Failed to create keypoint list: {e}")

        try:
            self.load_keypoint_list_from_path(default_json_path)
        except Exception as e:
            logger.error(f"Failed loading points.json: {e}")

    def add_keypoint_list_item(self):
        label_text = self.list_input.text().strip()
        if not label_text:
            return

        for row in range(self.keypoint_list.rowCount()):
            existing_label = self.keypoint_list.item(row, 1).text()
            if label_text.lower() == existing_label.lower():
                logger.warning("Duplicate label. Entry not added.")
                return

        row = self.keypoint_list.rowCount()
        self.keypoint_list.insertRow(row)

        index_item = QTableWidgetItem(str(row))
        index_item.setFlags(Qt.ItemIsEnabled)
        self.keypoint_list.setItem(row, 0, index_item)

        name_item = QTableWidgetItem(label_text)
        name_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
        self.keypoint_list.setItem(row, 1, name_item)

        total_rows = self.keypoint_list.rowCount()
        color = get_color(row, num_classes=total_rows)
        color_item = QTableWidgetItem()
        color_item.setBackground(QBrush(color))
        color_item.setFlags(Qt.ItemIsEnabled)
        self.keypoint_list.setItem(row, 2, color_item)

        checkbox = QCheckBox()
        checkbox.setChecked(True)
        checkbox.setStyleSheet("margin-left:10px;")
        self.keypoint_list.setCellWidget(row, 3, checkbox)

        ignore_checkbox = QCheckBox()
        ignore_checkbox.setChecked(False)
        ignore_checkbox.setStyleSheet("margin-left:10px;")
        self.keypoint_list.setCellWidget(row, 4, ignore_checkbox)

        checkbox.stateChanged.connect(lambda state, row=row: self.sync_ignore_visibility(row, source="visible"))
        ignore_checkbox.stateChanged.connect(lambda state, row=row: self.sync_ignore_visibility(row, source="ignore"))

        self.list_input.clear()
        self.reindex_keypoint_table()
        self.rebind_keypoint_checkbox_signals()
        self.sync_all_keypoint_drawers_to_table()
        self.autosave_keypoint_list_json()

    def clear_keypoint_highlight(self):
        for row in range(self.keypoint_list.rowCount()):
            for col in range(self.keypoint_list.columnCount()):
                # Skip color preview column.
                if col == 2:
                    continue

                item = self.keypoint_list.item(row, col)
                if item:
                    item.setBackground(QColor("white"))
                    item.setForeground(QColor("black"))

                widget = self.keypoint_list.cellWidget(row, col)
                if widget:
                    widget.setStyleSheet("")

    def highlight_keypoint_row(self, row):
        for col in range(self.keypoint_list.columnCount()):
            # Do not override the color preview column.
            if col == 2:
                continue

            item = self.keypoint_list.item(row, col)
            if item:
                item.setBackground(QColor("#FFDDDD"))
                item.setForeground(QColor("black"))

            widget = self.keypoint_list.cellWidget(row, col)
            if widget:
                widget.setStyleSheet("border: 2px solid red;")

    def load_keypoint_list_from_path(self, file_path=None):
        if file_path is None:
            # No path was supplied, so ask the user to pick a keypoint file.
            file_path, _ = QFileDialog.getOpenFileName(
                self,
                "Load Keypoint List",
                os.getcwd(),
                "JSON Files (*.json);;All Files (*)"
            )
            if not file_path:
                logger.info("User canceled keypoint list load.")
                return  # User cancelled manually

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception as e:
            QMessageBox.critical(self, "Load Failed", f"An error occurred while loading:\n{str(e)}")
            return

        self.current_keypoint_json_path = file_path
        self.load_keypoint_list_from_data(data, source_label=file_path)

    def load_keypoint_list_from_data(self, data, source_label=None, autosave=True):
        if not isinstance(data, dict):
            logger.warning("Invalid keypoint list data. Expected JSON object.")
            return

        self.load_skeleton_from_points_json_data(data)

        self.keypoint_list.setRowCount(0)
        self.manual_ignored_keypoint_rows = set()

        for idx, kp in enumerate(data.get("keypoints", [])):
            if not isinstance(kp, dict):
                kp = {"label": str(kp)}

            self.keypoint_list.insertRow(idx)

            index_item = QTableWidgetItem(str(idx))
            index_item.setFlags(Qt.ItemIsEnabled)
            self.keypoint_list.setItem(idx, 0, index_item)

            name_item = QTableWidgetItem(kp.get("label") or kp.get("name") or f"Keypoint {idx}")
            name_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            self.keypoint_list.setItem(idx, 1, name_item)

            fallback_color = get_color(idx, max(1, len(data.get("keypoints", []))))
            r, g, b, a = self._rgba_from_value(kp.get("color"), fallback=fallback_color)
            color = QColor(r, g, b, a)
            color_item = QTableWidgetItem()
            color_item.setBackground(QBrush(color))
            color_item.setFlags(Qt.ItemIsEnabled)
            self.keypoint_list.setItem(idx, 2, color_item)

            checkbox = QCheckBox()
            checkbox.setChecked(kp.get("visible", False))
            checkbox.setStyleSheet("margin-left:10px;")
            self.keypoint_list.setCellWidget(idx, 3, checkbox)

            ignore_checkbox = QCheckBox()
            ignore_checkbox.setChecked(kp.get("ignore", False))
            ignore_checkbox.setStyleSheet("margin-left:10px;")
            self.keypoint_list.setCellWidget(idx, 4, ignore_checkbox)

            if ignore_checkbox.isChecked():
                checkbox.setChecked(False)
                self.set_keypoint_row_manual_ignore(idx, True)

            # Bind row-specific callbacks without late-binding the loop index.
            checkbox.stateChanged.connect(functools.partial(self.sync_ignore_visibility, idx, source="visible"))
            ignore_checkbox.stateChanged.connect(functools.partial(self.sync_ignore_visibility, idx, source="ignore"))

        self.reindex_keypoint_table()
        self.rebind_keypoint_checkbox_signals()
        if autosave:
            self.autosave_keypoint_list_json()
        self.sync_all_keypoint_drawers_to_table()
        self.redraw_current_video_overlay()
        logger.info(f"Successfully loaded keypoint list from {source_label or 'data'}")

    def keypoint_row_is_ignored(self, row):
        if row is None or row < 0 or row >= self.keypoint_list.rowCount():
            return True
        if self.keypoint_row_is_manually_ignored(row):
            return True
        ignore_cb = self.keypoint_list.cellWidget(row, 4)
        return bool(ignore_cb and ignore_cb.isChecked())

    def set_keypoint_row_manual_ignore(self, row, ignored):
        if not hasattr(self, "manual_ignored_keypoint_rows"):
            self.manual_ignored_keypoint_rows = set()

        try:
            row = int(row)
        except (TypeError, ValueError):
            return

        if ignored:
            self.manual_ignored_keypoint_rows.add(row)
        else:
            self.manual_ignored_keypoint_rows.discard(row)

    def keypoint_row_is_manually_ignored(self, row):
        try:
            row = int(row)
        except (TypeError, ValueError):
            return False

        return row in getattr(self, "manual_ignored_keypoint_rows", set())

    def next_labelable_keypoint_row(self, start_row=0, include_start=True):
        total_rows = self.keypoint_list.rowCount()
        if total_rows <= 0:
            return None

        try:
            start_row = int(start_row)
        except (TypeError, ValueError):
            start_row = 0

        start_row = max(0, min(start_row, total_rows - 1))
        first_step = 0 if include_start else 1

        for step in range(first_step, first_step + total_rows):
            row = (start_row + step) % total_rows
            if not self.keypoint_row_is_ignored(row):
                return row

        return None

    def set_active_keypoint_row(self, row, drawer=None):
        if row is None:
            self.selected_keypoint_row = None
            self.keypoint_list.clearSelection()
            if drawer is not None:
                drawer.current_index = 0
            return

        self.selected_keypoint_row = row
        self.keypoint_list.selectRow(row)

        if drawer is not None:
            drawer.current_index = row

    def mark_keypoint_row_ignored(self, row, drawer=None):
        if row is None or row < 0:
            return False

        if drawer is None:
            selected_bbox = getattr(self.screen_view, "selected_bbox", None)
            drawer = getattr(selected_bbox, "keypoint_drawer", None) if selected_bbox else None

        if drawer is None:
            return False

        target_len = max(self.keypoint_list.rowCount(), row + 1)

        while len(drawer.points) < target_len:
            drawer.points.append((0.0, 0.0))

        while len(drawer.visibility_flags) < target_len:
            drawer.visibility_flags.append(0)

        drawer.points[row] = (0.0, 0.0)
        drawer.visibility_flags[row] = 0
        drawer.update_points()
        drawer.update_class_name_item()
        return True

    def sync_ignore_visibility(self, row, source, state=None):
        visible_cb = self.keypoint_list.cellWidget(row, 3)
        ignore_cb = self.keypoint_list.cellWidget(row, 4)

        if not visible_cb or not ignore_cb:
            return

        if source == "visible" and visible_cb.isChecked():
            self.set_keypoint_row_manual_ignore(row, False)
            ignore_cb.blockSignals(True)
            ignore_cb.setChecked(False)
            ignore_cb.blockSignals(False)

        elif source == "ignore":
            self.set_keypoint_row_manual_ignore(row, ignore_cb.isChecked())

        if source == "ignore" and ignore_cb.isChecked():
            visible_cb.blockSignals(True)
            visible_cb.setChecked(False)
            visible_cb.blockSignals(False)

            selected_bbox = getattr(self.screen_view, "selected_bbox", None)
            drawer = getattr(selected_bbox, "keypoint_drawer", None) if selected_bbox else None
            changed = self.mark_keypoint_row_ignored(row, drawer)

            if self.selected_keypoint_row == row:
                self.set_active_keypoint_row(
                    self.next_labelable_keypoint_row(row, include_start=False),
                    drawer,
                )

            if changed and hasattr(self, "save_bounding_boxes") and getattr(self, "current_file", None):
                scene = self.screen_view.scene()
                if scene is not None:
                    self.save_bounding_boxes(self.current_file, scene.width(), scene.height())

        self.autosave_keypoint_list_json()

    def store_selected_row(self, row, column):
        if row < 0 or row >= self.keypoint_list.rowCount():
            return

        self.selected_keypoint_row = row

        selected_bbox = getattr(self.screen_view, "selected_bbox", None)
        if selected_bbox and hasattr(selected_bbox, "keypoint_drawer"):
            drawer = selected_bbox.keypoint_drawer
            if drawer:
                drawer.current_index = row

                if row < len(drawer.points):
                    x, y = drawer.points[row]

                    if hasattr(self, "image") and self.image is not None and not self.image.isNull():
                        img_w = self.image.width()
                        img_h = self.image.height()
                    else:
                        img_w = self.screen_view.scene().width()
                        img_h = self.screen_view.scene().height()

                    if x != 0.0 or y != 0.0:
                        point_pos = QPointF(x * img_w, y * img_h)
                        self.screen_view.centerOn(point_pos)

    def lock_keypoint_checkboxes(self, locked=True):
        for i in range(self.keypoint_list.rowCount()):
            for col in [3, 4]:  # Visibility and Ignore
                cb = self.keypoint_list.cellWidget(i, col)
                if cb:
                    cb.setEnabled(not locked)

    def rebind_keypoint_checkbox_signals(self):
        for row in range(self.keypoint_list.rowCount()):
            visible_cb = self.keypoint_list.cellWidget(row, 3)
            ignore_cb = self.keypoint_list.cellWidget(row, 4)

            if visible_cb:
                try:
                    visible_cb.stateChanged.disconnect()
                except TypeError:
                    pass
                visible_cb.stateChanged.connect(lambda state, row=row: self.sync_ignore_visibility(row, source="visible"))

            if ignore_cb:
                try:
                    ignore_cb.stateChanged.disconnect()
                except TypeError:
                    pass
                ignore_cb.stateChanged.connect(lambda state, row=row: self.sync_ignore_visibility(row, source="ignore"))

    def reset_keypoint_checkboxes(self):
        self.manual_ignored_keypoint_rows = set()

        for i in range(self.keypoint_list.rowCount()):
            visible_cb = self.keypoint_list.cellWidget(i, 3)
            ignore_cb = self.keypoint_list.cellWidget(i, 4)

            if visible_cb:
                visible_cb.blockSignals(True)
                visible_cb.setChecked(True)
                visible_cb.blockSignals(False)

            if ignore_cb:
                ignore_cb.blockSignals(True)
                ignore_cb.setChecked(False)
                ignore_cb.blockSignals(False)

        self.rebind_keypoint_checkbox_signals()

    def remove_keypoint_list_item(self):
        if self.selected_keypoint_row is None:
            logger.warning("No row selected to remove.")
            return

        row = self.selected_keypoint_row
        old_keypoint_count = self.keypoint_list.rowCount()

        label_item = self.keypoint_list.item(row, 1)
        keypoint_name = label_item.text() if label_item else f"index {row}"

        msg = QMessageBox(self)
        msg.setIcon(QMessageBox.Warning)
        msg.setWindowTitle("Remove Keypoint From Dataset")
        msg.setText(f"Remove keypoint '{keypoint_name}'?")
        msg.setInformativeText(
            "This changes the keypoint schema.\n\n"
            "For training, every label file in the dataset should match the keypoint list.\n\n"
            "Choose how far to apply this change."
        )

        current_button = msg.addButton("Current Image Only", QMessageBox.ActionRole)
        dataset_button = msg.addButton("Entire Dataset", QMessageBox.DestructiveRole)
        cancel_button = msg.addButton(QMessageBox.Cancel)

        msg.setDefaultButton(cancel_button)
        msg.exec_()

        clicked = msg.clickedButton()

        if clicked == cancel_button:
            logger.info("Keypoint removal canceled.")
            return

        if clicked == current_button:
            apply_to_dataset = False
        elif clicked == dataset_button:
            apply_to_dataset = True
        else:
            logger.info("Keypoint removal canceled.")
            return

        if apply_to_dataset:
            confirm = QMessageBox.question(
                self,
                "Confirm Dataset Migration",
                (
                    f"This will remove keypoint '{keypoint_name}' at index {row} "
                    f"from every matching YOLO-pose label file in the dataset.\n\n"
                    "A backup folder will be created before files are rewritten.\n\n"
                    "Continue?"
                ),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No
            )

            if confirm != QMessageBox.Yes:
                logger.info("Dataset-wide keypoint removal canceled.")
                return

            migration_result = self.remove_keypoint_index_from_dataset_labels(
                remove_index=row,
                expected_old_keypoint_count=old_keypoint_count
            )

            if not migration_result.get("ok", False):
                QMessageBox.warning(
                    self,
                    "Dataset Migration Failed",
                    migration_result.get("message", "Dataset migration failed.")
                )
                return
            points_json_updated = self.remove_keypoint_index_from_points_json(row)

            if not points_json_updated:
                QMessageBox.warning(
                    self,
                    "points.json Not Updated",
                    "The label files were migrated, but points.json was not updated.\n\n"
                    "Do not train until points.json matches the label files."
                )
                return
        if apply_to_dataset:
            # Dataset files were already rewritten by remove_keypoint_index_from_dataset_labels().
            # Do NOT save the current scene here, because the scene still contains pre-migration
            # drawer/bbox state and can overwrite the corrected .txt file.
            points_json_path = self.get_points_json_path()
            self.load_keypoint_list_from_path(points_json_path)

            self.selected_keypoint_row = None
            self.keypoint_list.clearSelection()

            if getattr(self, "current_file", None):
                self.display_image(self.current_file, rebuild_preview=True)

        else:
            # Current-image-only path: edit scene and save just this image.
            self.remove_keypoint_index_from_current_scene(row)

            self.keypoint_list.removeRow(row)
            self.selected_keypoint_row = None
            self.reindex_keypoint_table()
            self.rebind_keypoint_checkbox_signals()
            self.keypoint_list.clearSelection()


            if hasattr(self, "save_bounding_boxes") and getattr(self, "current_file", None):
                scene = self.screen_view.scene()
                if scene is not None:
                    self.save_bounding_boxes(
                        self.current_file,
                        scene.width(),
                        scene.height()
                    )


        if apply_to_dataset:
            QMessageBox.information(
                self,
                "Dataset Migration Complete",
                (
                    f"Removed keypoint '{keypoint_name}' from the keypoint list.\n\n"
                    f"Files checked: {migration_result['checked']}\n"
                    f"Files changed: {migration_result['changed']}\n"
                    f"Lines changed: {migration_result['lines_changed']}\n"
                    f"Backup folder:\n{migration_result['backup_dir']}"
                )
            )
            logger.info(
                f"✔ Dataset-wide keypoint removal complete: "
                f"{migration_result['changed']} files changed, "
                f"{migration_result['lines_changed']} lines changed."
            )
        else:
            logger.info("Keypoint removed from table and current image annotations only.")

    def get_points_json_path(self):
        if getattr(self, "image_directory", None):
            return os.path.join(self.image_directory, "points.json")

        if getattr(self, "current_file", None):
            return os.path.join(os.path.dirname(self.current_file), "points.json")

        if getattr(self, "output_path", None):
            return os.path.join(self.output_path, "points.json")

        return os.path.join(os.getcwd(), "points.json")

    def remove_keypoint_index_from_points_json(self, remove_index):
        points_json_path = self.get_points_json_path()

        if not os.path.exists(points_json_path):
            logger.warning(f"points.json not found, cannot update schema: {points_json_path}")
            return False

        try:
            with open(points_json_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception as e:
            logger.error(f"Failed to read points.json: {e}")
            return False

        keypoints = data.get("keypoints", [])

        if remove_index < 0 or remove_index >= len(keypoints):
            logger.warning(f"Invalid keypoint index {remove_index} for points.json")
            return False

        removed = keypoints.pop(remove_index)

        old_skeleton = data.get("skeleton", [])
        new_skeleton = []

        for pair in old_skeleton:
            if not isinstance(pair, list) or len(pair) != 2:
                continue

            a, b = pair

            if a == remove_index or b == remove_index:
                continue

            if a > remove_index:
                a -= 1

            if b > remove_index:
                b -= 1

            if a >= 0 and b >= 0 and a < len(keypoints) and b < len(keypoints):
                new_skeleton.append([a, b])

        old_flip_idx = data.get("flip_idx", list(range(len(keypoints) + 1)))
        new_flip_idx = []

        for old_i, old_pair in enumerate(old_flip_idx):
            if old_i == remove_index:
                continue

            new_i = old_i - 1 if old_i > remove_index else old_i

            if old_pair == remove_index:
                new_pair = new_i
            elif old_pair > remove_index:
                new_pair = old_pair - 1
            else:
                new_pair = old_pair

            if 0 <= new_pair < len(keypoints):
                new_flip_idx.append(new_pair)
            else:
                new_flip_idx.append(new_i)

        data["keypoints"] = keypoints
        data["kpt_shape"] = [len(keypoints), 3]
        data["skeleton"] = new_skeleton
        data["flip_idx"] = new_flip_idx

        backup_path = points_json_path + ".bak"

        try:
            shutil.copy2(points_json_path, backup_path)

            with open(points_json_path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=4, separators=(",", ": "))

            logger.info(
                f"Removed keypoint '{removed.get('label', remove_index)}' from points.json "
                f"and rebuilt skeleton/flip_idx: {points_json_path}"
            )
            return True

        except Exception as e:
            logger.error(f"Failed to update points.json: {e}")
            return False

    def remove_keypoint_index_from_current_scene(self, remove_index):
        scene = self.screen_view.scene() if hasattr(self, "screen_view") else None
        if scene is None:
            return

        for item in scene.items():
            if not isinstance(item, BoundingBoxDrawer):
                continue

            drawer = getattr(item, "keypoint_drawer", None)
            if drawer is None:
                continue

            if remove_index < len(drawer.points):
                drawer.points.pop(remove_index)

            if remove_index < len(drawer.visibility_flags):
                drawer.visibility_flags.pop(remove_index)

            drawer.update_points()
            drawer.update_class_name_item()

    def remove_keypoint_index_from_dataset_labels(self, remove_index, expected_old_keypoint_count):
        label_files = self.collect_dataset_label_files_for_keypoint_migration()

        if not label_files:
            return {
                "ok": False,
                "message": "No label files were found for dataset migration."
            }

        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")

        base_dir = os.path.commonpath(label_files) if label_files else (
            os.path.dirname(self.current_file) if getattr(self, "current_file", None) else os.getcwd()
        )

        if os.path.isfile(base_dir):
            base_dir = os.path.dirname(base_dir)
        backup_dir = os.path.join(base_dir, "keypoint_migration_backups", timestamp)
        os.makedirs(backup_dir, exist_ok=True)

        checked = 0
        changed_files = 0
        changed_lines = 0
        skipped_lines = 0
        error_files = []

        for label_file in label_files:
            checked += 1

            try:
                with open(label_file, "r", encoding="utf-8") as f:
                    original_lines = f.readlines()
            except UnicodeDecodeError:
                try:
                    with open(label_file, "r", encoding="latin-1", errors="ignore") as f:
                        original_lines = f.readlines()
                except Exception as e:
                    error_files.append((label_file, str(e)))
                    continue
            except Exception as e:
                error_files.append((label_file, str(e)))
                continue

            new_lines = []
            file_changed = False

            for line in original_lines:
                stripped = line.strip()

                if not stripped:
                    new_lines.append(line)
                    continue

                new_line, did_change, did_skip = self.remove_keypoint_index_from_label_line(
                    stripped,
                    remove_index,
                    expected_old_keypoint_count
                )

                if did_change:
                    changed_lines += 1
                    file_changed = True
                    new_lines.append(new_line + "\n")
                else:
                    if did_skip:
                        skipped_lines += 1
                    new_lines.append(line)

            if not file_changed:
                continue

            try:
                rel_path = os.path.relpath(label_file, base_dir)
                backup_path = os.path.join(backup_dir, rel_path)
                os.makedirs(os.path.dirname(backup_path), exist_ok=True)
                shutil.copy2(label_file, backup_path)

                with open(label_file, "w", encoding="utf-8") as f:
                    f.writelines(new_lines)

                changed_files += 1

            except Exception as e:
                error_files.append((label_file, str(e)))

        logger.info(
            f"🔧 Keypoint dataset migration checked={checked}, "
            f"changed_files={changed_files}, changed_lines={changed_lines}, "
            f"skipped_lines={skipped_lines}, errors={len(error_files)}"
        )

        if error_files:
            logger.warning(f"Dataset migration had {len(error_files)} file errors.")
            for path, err in error_files[:10]:
                logger.warning(f"{path}: {err}")

        return {
            "ok": True,
            "checked": checked,
            "changed": changed_files,
            "lines_changed": changed_lines,
            "skipped_lines": skipped_lines,
            "errors": error_files,
            "backup_dir": backup_dir,
        }

    def remove_keypoint_index_from_label_line(self, line, remove_index, expected_old_keypoint_count):
        parts = line.split()

        expected_len = 5 + (expected_old_keypoint_count * 3)

        if len(parts) != expected_len:
            return line, False, True

        try:
            class_id = int(float(parts[0]))
            x_center = float(parts[1])
            y_center = float(parts[2])
            width = float(parts[3])
            height = float(parts[4])
        except Exception:
            return line, False, True

        if class_id < 0:
            return line, False, True

        if not (0.0 <= x_center <= 1.0):
            return line, False, True

        if not (0.0 <= y_center <= 1.0):
            return line, False, True

        if not (0.0 < width <= 1.0):
            return line, False, True

        if not (0.0 < height <= 1.0):
            return line, False, True

        bbox_values = parts[:5]
        keypoint_values = parts[5:]

        if len(keypoint_values) != expected_old_keypoint_count * 3:
            return line, False, True

        start = remove_index * 3
        end = start + 3

        if start < 0 or end > len(keypoint_values):
            return line, False, True

        removed_triplet = keypoint_values[start:end]

        try:
            removed_x = float(removed_triplet[0])
            removed_y = float(removed_triplet[1])
            removed_v = int(float(removed_triplet[2]))
        except Exception:
            return line, False, True

        if removed_v not in (0, 1, 2):
            return line, False, True

        logger.info(
            f"🧬 Removing keypoint index {remove_index}: "
            f"x={removed_x}, y={removed_y}, v={removed_v}"
        )

        new_keypoint_values = keypoint_values[:start] + keypoint_values[end:]

        new_parts = bbox_values + new_keypoint_values

        return " ".join(new_parts), True, False

    def collect_dataset_label_files_for_keypoint_migration(self):
        label_files = []

        image_files = getattr(self, "image_files", None)

        if image_files:
            for image_file in image_files:
                label_file = self.get_label_file(image_file)
                if label_file and os.path.exists(label_file):
                    label_files.append(label_file)

        if not label_files:
            start_dir = os.path.dirname(self.current_file) if getattr(self, "current_file", None) else os.getcwd()

            selected_dir = QFileDialog.getExistingDirectory(
                self,
                "Select Dataset Folder For Keypoint Migration",
                start_dir
            )

            if not selected_dir:
                return []

            skip_names = {
                "classes.txt",
                "train.txt",
                "valid.txt",
                "val.txt",
                "test.txt",
                "obj.names",
                "obj.data",
            }

            for root, dirs, files in os.walk(selected_dir):
                if "keypoint_migration_backups" in root:
                    continue

                for file_name in files:
                    if not file_name.lower().endswith(".txt"):
                        continue

                    if file_name.lower() in skip_names:
                        continue

                    label_files.append(os.path.join(root, file_name))

        label_files = sorted(set(label_files))
        return label_files

    def sync_all_keypoint_drawers_to_table(self):
        target_len = self.keypoint_list.rowCount()

        scene = self.screen_view.scene() if hasattr(self, "screen_view") else None
        if scene is None:
            return

        for item in scene.items():
            if not isinstance(item, BoundingBoxDrawer):
                continue

            drawer = getattr(item, "keypoint_drawer", None)
            if drawer is None:
                continue

            while len(drawer.points) < target_len:
                drawer.points.append((0.0, 0.0))

            while len(drawer.visibility_flags) < target_len:
                drawer.visibility_flags.append(0)

            if len(drawer.points) > target_len:
                drawer.points = drawer.points[:target_len]

            if len(drawer.visibility_flags) > target_len:
                drawer.visibility_flags = drawer.visibility_flags[:target_len]

            drawer.update_points()
            drawer.update_class_name_item()

    def reindex_keypoint_table(self):
        for row in range(self.keypoint_list.rowCount()):
            index_item = QTableWidgetItem(str(row))
            index_item.setFlags(Qt.ItemIsEnabled)
            self.keypoint_list.setItem(row, 0, index_item)

    def save_keypoint_list_to_path(self, file_path, show_message=False):
        existing_data = {}
        if os.path.exists(file_path):
            existing_data = read_json_file(file_path, {})

        keypoints = []
        label_to_index = {}

        for row in range(self.keypoint_list.rowCount()):
            label_item = self.keypoint_list.item(row, 1)
            color_item = self.keypoint_list.item(row, 2)
            visible_cb = self.keypoint_list.cellWidget(row, 3)
            ignore_cb = self.keypoint_list.cellWidget(row, 4)

            if not label_item or not color_item or not visible_cb or not ignore_cb:
                continue

            label = label_item.text()
            color = color_item.background().color()

            keypoints.append({
                "label": label,
                "color": [color.red(), color.green(), color.blue(), color.alpha()],
                "visible": visible_cb.isChecked(),
                "ignore": ignore_cb.isChecked()
            })

            label_to_index[label.lower()] = row

        skeleton = existing_data.get("skeleton", getattr(self, "current_skeleton_connections", []))
        skeleton = [
            [int(a), int(b)]
            for a, b in skeleton
            if 0 <= int(a) < len(keypoints) and 0 <= int(b) < len(keypoints) and int(a) != int(b)
        ]

        flip_idx = existing_data.get("flip_idx", list(range(len(keypoints))))
        if not isinstance(flip_idx, list) or len(flip_idx) != len(keypoints):
            flip_idx = list(range(len(keypoints)))

        data = {
            "kpt_shape": [len(keypoints), 3],
            "keypoints": keypoints,
            "skeleton": skeleton,
            "flip_idx": flip_idx
        }

        write_json_file_atomic(file_path, data)
        logger.info(f"Auto-saved keypoint list: {file_path}")

        if show_message:
            QMessageBox.information(self, "Save Successful", f"Saved to {file_path}.")

    def autosave_keypoint_list_json(self):
        file_path = getattr(self, "current_keypoint_json_path", None) or self.get_points_json_path()
        if not file_path:
            return

        try:
            self.save_keypoint_list_to_path(file_path, show_message=False)
        except Exception as e:
            logger.error(f"Failed to auto-save keypoint list: {e}")

    def save_keypoint_list(self):
        settings = QSettings()
        last_dir = settings.value("last_save_dir", os.getcwd())

        file_path, _ = QFileDialog.getSaveFileName(
            self,
            "Save Keypoint List",
            os.path.join(last_dir, "points.json"),
            "JSON Files (*.json);;All Files (*)"
        )

        if not file_path:
            return  # User canceled

        settings.setValue("last_save_dir", os.path.dirname(file_path))

        existing_data = {}
        if os.path.exists(file_path):
            try:
                with open(file_path, "r", encoding="utf-8") as f:
                    loaded = json.load(f)
                if isinstance(loaded, dict):
                    existing_data = loaded
            except Exception:
                existing_data = {}

        keypoints = []
        label_to_index = {}
        for row in range(self.keypoint_list.rowCount()):
            label_item = self.keypoint_list.item(row, 1)
            color_item = self.keypoint_list.item(row, 2)
            checkbox = self.keypoint_list.cellWidget(row, 3)
            ignore_checkbox = self.keypoint_list.cellWidget(row, 4)

            if not label_item or not color_item or not checkbox or not ignore_checkbox:
                continue

            label = label_item.text()
            color = color_item.background().color()
            visible = checkbox.isChecked()
            ignore = ignore_checkbox.isChecked()

            keypoints.append({
                "label": label,
                "color": [color.red(), color.green(), color.blue(), color.alpha()],
                "visible": visible,
                "ignore": ignore
            })

            label_to_index[label.lower()] = row

        existing_skeleton = existing_data.get("skeleton")
        skeleton = []
        skeleton_is_valid = isinstance(existing_skeleton, list)
        if skeleton_is_valid:
            for pair in existing_skeleton:
                try:
                    a = int(pair[0])
                    b = int(pair[1])
                except Exception:
                    skeleton_is_valid = False
                    break

                if (
                    not isinstance(pair, (list, tuple))
                    or len(pair) != 2
                    or not (0 <= a < len(keypoints))
                    or not (0 <= b < len(keypoints))
                ):
                    skeleton_is_valid = False
                    break

                skeleton.append([a, b])

            if not skeleton_is_valid:
                skeleton = []
        existing_flip_idx = existing_data.get("flip_idx")
        flip_idx = []
        flip_idx_is_valid = isinstance(existing_flip_idx, list) and len(existing_flip_idx) == len(keypoints)
        if flip_idx_is_valid:
            for idx in existing_flip_idx:
                try:
                    idx = int(idx)
                except Exception:
                    flip_idx_is_valid = False
                    break

                if not (0 <= idx < len(keypoints)):
                    flip_idx_is_valid = False
                    break

                flip_idx.append(idx)

        if not flip_idx_is_valid:
            # Auto-generate flip_idx based on left/right label names.
            flip_idx = list(range(len(keypoints)))  # fallback to identity
            for i, kp in enumerate(keypoints):
                label = kp["label"].lower()
                if "left" in label:
                    match = label.replace("left", "right")
                elif "right" in label:
                    match = label.replace("right", "left")
                else:
                    continue

                j = label_to_index.get(match)
                if j is not None:
                    flip_idx[i] = j

        data = {
            "kpt_shape": [len(keypoints), 3],
            "keypoints": keypoints,
            "skeleton": skeleton,
            "flip_idx": flip_idx
        }

        # Remove the file before writing.
        if os.path.exists(file_path):
            try:
                os.remove(file_path)
            except Exception as e:
                QMessageBox.warning(self, "Overwrite Failed", f"Could not remove existing file:\n{str(e)}")
                return

        try:
            with open(file_path, "w") as f:
                json.dump(data, f, indent=4, separators=(",", ": "))
            QMessageBox.information(self, "Save Successful", f"Keypoints + skeleton + flip_idx saved to {file_path}.")
        except Exception as e:
            QMessageBox.critical(self, "Save Failed", f"An error occurred while saving:\n{str(e)}")

    def update_keypoint_checkboxes_from_labels(self, label_file_path):
        """
        Parses keypoint data from a YOLO label file without updating the UI.

        Returns:
            List of tuples: [(x, y), ...]
            List of visibility flags: [v, ...]
        """
        if not os.path.exists(label_file_path):
            logger.warning(f"Label file not found: {label_file_path}")
            return [], []

        try:
            with open(label_file_path, "r") as f:
                lines = [line.strip() for line in f if line.strip()]
        except Exception as e:
            logger.error(f"Failed to read label file: {e}")
            return [], []

        if not lines:
            return [], []

        # Parse keypoints from each line (each bbox)
        all_keypoints = []
        all_flags = []

        for line in lines:
            parts = line.split()
            if len(parts) < 6:
                logger.warning("Not enough data in label to parse keypoints.")
                continue

            keypoint_values = parts[5:]  # After class_id xc yc w h
            expected_kpts = self.keypoint_list.rowCount()

            if expected_kpts > 0 and len(keypoint_values) != expected_kpts * 3:
                continue

            if len(keypoint_values) == 0 or len(keypoint_values) % 3 != 0:
                continue

            num_kpts = len(keypoint_values) // 3

            points = []
            flags = []

            for i in range(num_kpts):
                try:
                    x = float(keypoint_values[i * 3])
                    y = float(keypoint_values[i * 3 + 1])
                    v = int(float(keypoint_values[i * 3 + 2]))
                except Exception as e:
                    logger.warning(f"Failed to parse keypoint {i}: {e}")
                    points = []
                    flags = []
                    break

                if v not in (0, 1, 2):
                    logger.warning(f"Skipped label with invalid keypoint visibility: {v}")
                    points = []
                    flags = []
                    break

                if v in (1, 2) and not (0.0 <= x <= 1.0 and 0.0 <= y <= 1.0):
                    logger.warning(f"Skipped label with out-of-range keypoint {i}: x={x}, y={y}, v={v}")
                    points = []
                    flags = []
                    break

                points.append((x, y))
                flags.append(v)

            if points and flags:
                all_keypoints.append(points)
                all_flags.append(flags)

        logger.info(f"Parsed {len(all_keypoints)} bounding box keypoint sets from {os.path.basename(label_file_path)}")
        return all_keypoints, all_flags

    def update_keypoint_checkboxes_from_points(self, points, visibility_flags=None):
        if visibility_flags is None:
            visibility_flags = []

        for i in range(self.keypoint_list.rowCount()):
            visible_cb = self.keypoint_list.cellWidget(i, 3)
            ignore_cb = self.keypoint_list.cellWidget(i, 4)

            if not visible_cb or not ignore_cb:
                continue

            visible_cb.blockSignals(True)
            ignore_cb.blockSignals(True)

            if i < len(visibility_flags):
                v = int(visibility_flags[i])

                if v == 0:
                    visible_cb.setChecked(False)
                    ignore_cb.setChecked(True)
                elif v == 1:
                    visible_cb.setChecked(False)
                    ignore_cb.setChecked(False)
                else:
                    visible_cb.setChecked(True)
                    ignore_cb.setChecked(False)
            else:
                visible_cb.setChecked(True)
                ignore_cb.setChecked(False)

            visible_cb.blockSignals(False)
            ignore_cb.blockSignals(False)

        self.rebind_keypoint_checkbox_signals()

    def update_shading_opacity(self, value):
        self.update_slider_value_labels()

    def update_font_size_display(self, value):
        self.update_slider_value_labels()

    def on_annotation_mode_user_selected(self, *_args):
        if getattr(self, "_annotation_mode_auto_changing", False):
            return

        self._annotation_mode_manual_override = True
        logger.info("Annotation mode manually selected: %s", self.segmentation_mode.currentText())

    def on_segmentation_mode_changed(self, mode=None):
        mode_text = str(mode if mode is not None else self.current_mode()).strip().lower()

        # If switching into keypoint mode, inject ghost points where missing.
        if mode_text == "keypoints":
            expected = self.keypoint_list.rowCount()
            current_bboxes = getattr(
                self,
                "current_bboxes",
                getattr(self, "current_bounding_boxes", [])
            )

            for bbox in current_bboxes or []:
                if not hasattr(bbox, "keypoints"):
                    continue
                if not bbox.keypoints or len(bbox.keypoints) != expected:
                    bbox.keypoints = [(0.0, 0.0, 0)] * expected

    def load_skeleton_from_points_json_data(self, data):
        skeleton = data.get("skeleton", [])

        clean_skeleton = []
        keypoint_count = len(data.get("keypoints", []))

        for pair in skeleton:
            if not isinstance(pair, (list, tuple)) or len(pair) != 2:
                continue

            try:
                a = int(pair[0])
                b = int(pair[1])
            except Exception:
                continue

            if 0 <= a < keypoint_count and 0 <= b < keypoint_count and a != b:
                clean_skeleton.append((a, b))

        self.current_skeleton_connections = clean_skeleton
        KeypointDrawer.SKELETON_CONNECTIONS = clean_skeleton

        logger.info(f"Loaded {len(clean_skeleton)} skeleton connections from points.json")

    def current_mode(self):
        return self.segmentation_mode.currentText().strip().lower()

    def is_boxes_mode(self):
        return self.current_mode() == "boxes"

    def is_segmentation_mode(self):
        return self.current_mode() == "segmentation"

    def is_keypoint_mode(self):
        return self.current_mode() == "keypoints"

    def is_obb_mode(self):
        return self.current_mode() == "obb"

    @staticmethod
    def _keypoint_label_key(label):
        return re.sub(r"[^a-z0-9]+", "", str(label or "").strip().lower())

    @staticmethod
    def _format_keypoint_label(label):
        text = str(label or "").strip()
        if not text:
            return ""
        text = text.replace("_", " ").replace("-", " ")
        text = re.sub(r"\s+", " ", text).strip()
        return " ".join(part[:1].upper() + part[1:].lower() for part in text.split())

    @staticmethod
    def _sanitize_kpt_shape(value):
        if isinstance(value, str):
            try:
                value = yaml.safe_load(value)
            except Exception:
                return None

        if not isinstance(value, (list, tuple)) or not value:
            return None

        try:
            count = int(value[0])
            dims = int(value[1]) if len(value) > 1 else 3
        except Exception:
            return None

        if count <= 0:
            return None

        return [count, max(2, dims)]

    @staticmethod
    def _sanitize_skeleton_pairs(skeleton, keypoint_count, labels=None):
        if isinstance(skeleton, str):
            try:
                skeleton = yaml.safe_load(skeleton)
            except Exception:
                skeleton = None

        if isinstance(skeleton, dict):
            for key in ("skeleton", "connections", "links", "edges", "keypoint_edges"):
                value = skeleton.get(key)
                if value:
                    skeleton = value
                    break

        clean_skeleton = []
        if not isinstance(skeleton, (list, tuple)):
            return clean_skeleton

        label_to_index = {}
        for index, label in enumerate(labels or []):
            label_key = re.sub(r"[^a-z0-9]+", "", str(label or "").strip().lower())
            if label_key:
                label_to_index[label_key] = index

        numeric_pairs = []

        def endpoint_to_index(value):
            if isinstance(value, str):
                label_key = re.sub(r"[^a-z0-9]+", "", value.strip().lower())
                if label_key in label_to_index:
                    return label_to_index[label_key], False

            try:
                return int(value), True
            except Exception:
                return None, False

        for pair in skeleton:
            if isinstance(pair, dict):
                pair = [
                    pair.get("from", pair.get("source", pair.get("start", pair.get("a")))),
                    pair.get("to", pair.get("target", pair.get("end", pair.get("b")))),
                ]

            if not isinstance(pair, (list, tuple)) or len(pair) != 2:
                continue

            a, a_numeric = endpoint_to_index(pair[0])
            b, b_numeric = endpoint_to_index(pair[1])

            if a is None or b is None:
                continue

            if a_numeric and b_numeric:
                numeric_pairs.append([a, b])
                continue

            if 0 <= a < keypoint_count and 0 <= b < keypoint_count and a != b:
                clean_skeleton.append([a, b])

        if numeric_pairs:
            has_zero = any(a == 0 or b == 0 for a, b in numeric_pairs)
            max_index = max(max(a, b) for a, b in numeric_pairs)
            one_based = not has_zero and max_index == keypoint_count

            for a, b in numeric_pairs:
                if one_based:
                    a -= 1
                    b -= 1
                if 0 <= a < keypoint_count and 0 <= b < keypoint_count and a != b:
                    clean_skeleton.append([a, b])

        return clean_skeleton

    def _infer_skeleton_from_keypoint_labels(self, labels):
        labels = [str(label or "").strip() for label in labels or []]
        label_to_index = {}

        for index, label in enumerate(labels):
            label_key = self._keypoint_label_key(label)
            if label_key:
                label_to_index[label_key] = index

        if not label_to_index:
            return []

        skeleton = []
        seen = set()

        def add_pair(first, second):
            first_key = self._keypoint_label_key(first)
            second_key = self._keypoint_label_key(second)
            if first_key not in label_to_index or second_key not in label_to_index:
                return

            a = label_to_index[first_key]
            b = label_to_index[second_key]
            if a == b:
                return

            edge_key = tuple(sorted((a, b)))
            if edge_key in seen:
                return

            seen.add(edge_key)
            skeleton.append([a, b])

        human_pairs = [
            ("left_ankle", "left_knee"),
            ("left_knee", "left_hip"),
            ("right_ankle", "right_knee"),
            ("right_knee", "right_hip"),
            ("left_hip", "right_hip"),
            ("left_shoulder", "left_hip"),
            ("right_shoulder", "right_hip"),
            ("left_shoulder", "right_shoulder"),
            ("left_shoulder", "left_elbow"),
            ("right_shoulder", "right_elbow"),
            ("left_elbow", "left_wrist"),
            ("right_elbow", "right_wrist"),
            ("left_eye", "right_eye"),
            ("nose", "left_eye"),
            ("nose", "right_eye"),
            ("left_eye", "left_ear"),
            ("right_eye", "right_ear"),
            ("left_ear", "left_shoulder"),
            ("right_ear", "right_shoulder"),
        ]

        hand_pairs = [
            ("wrist", "thumb_cmc"),
            ("thumb_cmc", "thumb_mcp"),
            ("thumb_mcp", "thumb_ip"),
            ("thumb_ip", "thumb_tip"),
            ("wrist", "index_mcp"),
            ("index_mcp", "index_pip"),
            ("index_pip", "index_dip"),
            ("index_dip", "index_tip"),
            ("wrist", "middle_mcp"),
            ("middle_mcp", "middle_pip"),
            ("middle_pip", "middle_dip"),
            ("middle_dip", "middle_tip"),
            ("wrist", "ring_mcp"),
            ("ring_mcp", "ring_pip"),
            ("ring_pip", "ring_dip"),
            ("ring_dip", "ring_tip"),
            ("wrist", "pinky_mcp"),
            ("pinky_mcp", "pinky_pip"),
            ("pinky_pip", "pinky_dip"),
            ("pinky_dip", "pinky_tip"),
        ]

        animal_pairs = [
            ("nose", "head"),
            ("head", "withers"),
            ("withers", "tail_base"),
            ("tail_base", "right_hind_hock"),
            ("right_hind_hock", "right_hind_paw"),
            ("tail_base", "left_hind_hock"),
            ("left_hind_hock", "left_hind_paw"),
            ("withers", "right_front_wrist"),
            ("right_front_wrist", "right_front_paw"),
            ("withers", "left_front_wrist"),
            ("left_front_wrist", "left_front_paw"),
        ]

        for first, second in human_pairs + hand_pairs + animal_pairs:
            add_pair(first, second)

        return skeleton

    @staticmethod
    def _sanitize_flip_idx(flip_idx, keypoint_count):
        if isinstance(flip_idx, str):
            try:
                flip_idx = yaml.safe_load(flip_idx)
            except Exception:
                flip_idx = None

        if not isinstance(flip_idx, (list, tuple)) or len(flip_idx) != keypoint_count:
            return None

        clean_flip_idx = []
        for value in flip_idx:
            try:
                index = int(value)
            except Exception:
                return None
            if index < 0 or index >= keypoint_count:
                return None
            clean_flip_idx.append(index)

        return clean_flip_idx

    def _infer_flip_idx_from_labels(self, labels):
        flip_idx = list(range(len(labels)))
        label_to_index = {str(label).strip().lower(): i for i, label in enumerate(labels)}

        for i, label in enumerate(labels):
            label_key = str(label).strip().lower()
            if "left" in label_key:
                match = label_key.replace("left", "right")
            elif "right" in label_key:
                match = label_key.replace("right", "left")
            else:
                continue

            match_index = label_to_index.get(match)
            if match_index is not None:
                flip_idx[i] = match_index

        return flip_idx

    def _rgba_from_value(self, value, fallback=None, alpha=150):
        if isinstance(fallback, QColor):
            fallback_color = fallback
        else:
            fallback_color = QColor(255, 255, 255, alpha)

        if isinstance(value, QColor):
            return [value.red(), value.green(), value.blue(), value.alpha()]

        if isinstance(value, str):
            color = QColor(value)
            if color.isValid():
                color.setAlpha(alpha if color.alpha() == 255 else color.alpha())
                return [color.red(), color.green(), color.blue(), color.alpha()]

        if isinstance(value, (list, tuple)) and len(value) >= 3:
            try:
                rgba = [
                    max(0, min(255, int(value[0]))),
                    max(0, min(255, int(value[1]))),
                    max(0, min(255, int(value[2]))),
                    max(0, min(255, int(value[3]))) if len(value) > 3 else alpha,
                ]
                return rgba
            except Exception:
                pass

        return [
            fallback_color.red(),
            fallback_color.green(),
            fallback_color.blue(),
            fallback_color.alpha(),
        ]

    def _keypoint_style_snapshot(self, existing_data=None):
        by_label = {}
        by_index = {}

        def add_style(index, label, color=None, visible=True, ignore=False):
            style = {
                "color": color,
                "visible": bool(visible),
                "ignore": bool(ignore),
            }
            by_index[int(index)] = style
            label_key = self._keypoint_label_key(label)
            if label_key:
                by_label[label_key] = style

        if isinstance(existing_data, dict):
            for index, kp in enumerate(existing_data.get("keypoints", []) or []):
                if not isinstance(kp, dict):
                    continue
                label = kp.get("label") or kp.get("name") or f"Keypoint {index}"
                add_style(
                    index,
                    label,
                    color=kp.get("color"),
                    visible=kp.get("visible", True),
                    ignore=kp.get("ignore", False),
                )

        try:
            table = getattr(self, "keypoint_list", None)
        except RuntimeError:
            table = None

        if table is not None:
            for row in range(table.rowCount()):
                label_item = table.item(row, 1)
                color_item = table.item(row, 2)
                visible_cb = table.cellWidget(row, 3)
                ignore_cb = table.cellWidget(row, 4)

                label = label_item.text() if label_item else f"Keypoint {row}"
                color = color_item.background().color() if color_item else None
                visible = visible_cb.isChecked() if visible_cb else True
                ignore = ignore_cb.isChecked() if ignore_cb else False
                add_style(row, label, color=color, visible=visible, ignore=ignore)

        return by_label, by_index

    def _build_pose_list_data(self, labels, skeleton=None, flip_idx=None, existing_data=None):
        labels = [self._format_keypoint_label(label) for label in labels if str(label or "").strip()]

        if not labels:
            return None

        keypoint_count = len(labels)
        by_label, by_index = self._keypoint_style_snapshot(existing_data)

        keypoints = []
        for index, label in enumerate(labels):
            label_style = by_label.get(self._keypoint_label_key(label), {})
            index_style = by_index.get(index, {})
            fallback_color = get_color(index, keypoint_count)
            color = self._rgba_from_value(
                label_style.get("color", index_style.get("color")),
                fallback=fallback_color,
            )

            keypoints.append({
                "label": label,
                "color": color,
                "visible": bool(label_style.get("visible", True)),
                "ignore": bool(label_style.get("ignore", False)),
            })

        clean_skeleton = self._sanitize_skeleton_pairs(skeleton, keypoint_count, labels=labels)
        default_labels_key = [self._keypoint_label_key(label) for label in DEFAULT_POSE_KEYPOINT_LABELS]
        labels_key = [self._keypoint_label_key(label) for label in labels]

        if not clean_skeleton:
            clean_skeleton = self._infer_skeleton_from_keypoint_labels(labels)

        if not clean_skeleton and labels_key == default_labels_key:
            clean_skeleton = [list(pair) for pair in DEFAULT_POSE_SKELETON]

        clean_flip_idx = self._sanitize_flip_idx(flip_idx, keypoint_count)
        if clean_flip_idx is None and labels_key == default_labels_key:
            clean_flip_idx = list(DEFAULT_POSE_FLIP_IDX)
        if clean_flip_idx is None:
            clean_flip_idx = self._infer_flip_idx_from_labels(labels)

        return {
            "kpt_shape": [keypoint_count, 3],
            "keypoints": keypoints,
            "skeleton": clean_skeleton,
            "flip_idx": clean_flip_idx,
        }

    def _extract_keypoint_labels_from_value(self, value):
        if isinstance(value, dict):
            for preferred_key in ("0", 0, "names", "labels", "keypoints"):
                if preferred_key in value:
                    labels = self._extract_keypoint_labels_from_value(value.get(preferred_key))
                    if labels:
                        return labels

            sorted_items = sorted(
                value.items(),
                key=lambda item: int(item[0]) if str(item[0]).isdigit() else str(item[0])
            )

            if sorted_items and all(not isinstance(item[1], (list, tuple, dict)) for item in sorted_items):
                return [self._format_keypoint_label(item[1]) for item in sorted_items if str(item[1]).strip()]

            for _key, nested_value in sorted_items:
                labels = self._extract_keypoint_labels_from_value(nested_value)
                if labels:
                    return labels

            return []

        if isinstance(value, (list, tuple)):
            labels = []

            for item in value:
                if isinstance(item, dict):
                    label = item.get("label") or item.get("name") or item.get("keypoint")
                    if label:
                        labels.append(self._format_keypoint_label(label))
                elif isinstance(item, (list, tuple, dict)):
                    nested_labels = self._extract_keypoint_labels_from_value(item)
                    if len(nested_labels) > 1:
                        return nested_labels
                    labels.extend(nested_labels)
                elif str(item).strip():
                    labels.append(self._format_keypoint_label(item))

            return [label for label in labels if label]

        if value is not None and str(value).strip():
            return [self._format_keypoint_label(value)]

        return []

    def _extract_pose_labels_from_mapping(self, mapping):
        if not isinstance(mapping, dict):
            return []

        for key in ("keypoints", "kpt_names", "keypoint_names", "keypoint_labels", "kp_names", "kpts"):
            if key not in mapping:
                continue
            labels = self._extract_keypoint_labels_from_value(mapping.get(key))
            if labels:
                return labels

        return []

    def _extract_pose_skeleton_from_mapping(self, mapping):
        if not isinstance(mapping, dict):
            return None

        for key in (
            "skeleton",
            "pose_skeleton",
            "kpt_skeleton",
            "keypoint_skeleton",
            "keypoint_edges",
            "connections",
            "links",
            "edges",
        ):
            value = mapping.get(key)
            if value:
                return value

        return None

    def _iter_pose_metadata_mappings(self, value, depth=0):
        if not isinstance(value, dict) or depth > 4:
            return

        yield value

        for key in ("args", "train_args", "overrides", "metadata", "yaml", "cfg", "data"):
            child = value.get(key)
            if isinstance(child, dict):
                yield from self._iter_pose_metadata_mappings(child, depth + 1)

    def _read_pose_yaml_candidate(self, data_value, model_path=None):
        if isinstance(data_value, dict):
            return data_value, "model data metadata"

        if not data_value:
            return None, None

        data_path = str(data_value).strip()
        if not data_path.lower().endswith((".yaml", ".yml")):
            return None, None

        candidates = []

        def add_candidate(path):
            path = str(path or "").strip()
            if path and path not in candidates:
                candidates.append(path)

        add_candidate(data_path)

        if model_path:
            model_dir = os.path.dirname(str(model_path))
            if model_dir and not os.path.isabs(data_path):
                add_candidate(os.path.join(model_dir, data_path))

        basename = os.path.basename(data_path)
        if basename and basename != data_path:
            add_candidate(basename)

        for candidate in candidates:
            if os.path.exists(candidate):
                try:
                    with open(candidate, "r", encoding="utf-8") as f:
                        data = yaml.safe_load(f) or {}
                    if isinstance(data, dict):
                        return data, candidate
                except Exception as e:
                    logger.debug(f"Could not read pose YAML {candidate}: {e}")

        try:
            from ultralytics.utils.checks import check_yaml
        except Exception as e:
            logger.debug(f"Ultralytics check_yaml unavailable for pose metadata: {e}")
            return None, None

        for candidate in candidates:
            try:
                resolved = check_yaml(candidate)
            except Exception:
                continue

            if not resolved or not os.path.exists(resolved):
                continue

            try:
                with open(resolved, "r", encoding="utf-8") as f:
                    data = yaml.safe_load(f) or {}
                if isinstance(data, dict):
                    return data, resolved
            except Exception as e:
                logger.debug(f"Could not read resolved pose YAML {resolved}: {e}")

        return None, None

    def extract_pose_schema_from_current_model(self, model_path=None):
        model = getattr(self, "model", None)
        model_path = model_path or getattr(self, "weights_file_path", None) or getattr(self, "loaded_model_path", None)
        mappings = []
        mapping_ids = set()

        def add_mapping(value):
            if isinstance(value, dict):
                for mapping in self._iter_pose_metadata_mappings(value):
                    mapping_id = id(mapping)
                    if mapping_id not in mapping_ids:
                        mapping_ids.add(mapping_id)
                        mappings.append(mapping)

        add_mapping(getattr(model, "overrides", None))
        add_mapping(getattr(model, "ckpt", None))

        model_obj = getattr(model, "model", None)
        add_mapping(getattr(model_obj, "args", None))
        add_mapping(getattr(model_obj, "yaml", None))

        direct_pose_metadata = {}
        for attr_name, key_name in (
            ("kpt_names", "kpt_names"),
            ("keypoint_names", "keypoint_names"),
            ("keypoint_labels", "keypoint_labels"),
            ("skeleton", "skeleton"),
            ("pose_skeleton", "pose_skeleton"),
            ("kpt_skeleton", "kpt_skeleton"),
        ):
            for obj in (model, model_obj):
                if obj is None:
                    continue
                try:
                    value = getattr(obj, attr_name, None)
                except Exception:
                    value = None
                if value:
                    direct_pose_metadata[key_name] = value

        add_mapping(direct_pose_metadata)

        lower_path = str(model_path or "").lower()
        if lower_path.endswith(".engine"):
            add_mapping(self.read_engine_metadata(model_path))

        sidecar_path = str(model_path or "") + ".json" if model_path else ""
        if sidecar_path and os.path.exists(sidecar_path):
            add_mapping(read_json_file(sidecar_path, {}))

        data_mappings = []
        data_sources = []
        for mapping in list(mappings):
            data_value = mapping.get("data") if isinstance(mapping, dict) else None
            data_mapping, source = self._read_pose_yaml_candidate(data_value, model_path=model_path)
            if isinstance(data_mapping, dict):
                data_mappings.append(data_mapping)
                data_sources.append(source)

        labels = []
        kpt_shape = None
        skeleton = None
        flip_idx = None
        source = None

        for mapping in data_mappings + mappings:
            if not labels:
                labels = self._extract_pose_labels_from_mapping(mapping)
                if labels:
                    source = "Ultralytics pose names"

            if kpt_shape is None:
                kpt_shape = self._sanitize_kpt_shape(mapping.get("kpt_shape"))

            if skeleton is None:
                skeleton = self._extract_pose_skeleton_from_mapping(mapping)

            if flip_idx is None and isinstance(mapping.get("flip_idx"), (list, tuple)):
                flip_idx = mapping.get("flip_idx")

        if data_sources and not source:
            source = data_sources[0]

        if kpt_shape is None and labels:
            kpt_shape = [len(labels), 3]

        if kpt_shape is None:
            _task, mode = self.detect_loaded_model_task(model_path)
            if mode != "Keypoints":
                return None
            return None

        keypoint_count = int(kpt_shape[0])
        if keypoint_count <= 0:
            return None

        if not labels and keypoint_count == len(DEFAULT_POSE_KEYPOINT_LABELS):
            labels = list(DEFAULT_POSE_KEYPOINT_LABELS)

        if not labels:
            labels = [f"Keypoint {i}" for i in range(keypoint_count)]

        if len(labels) < keypoint_count:
            labels = labels + [f"Keypoint {i}" for i in range(len(labels), keypoint_count)]
        elif len(labels) > keypoint_count:
            labels = labels[:keypoint_count]

        return {
            "labels": labels,
            "kpt_shape": kpt_shape,
            "skeleton": skeleton,
            "flip_idx": flip_idx,
            "source": source or "model metadata",
        }

    def sync_pose_list_from_current_model(self, model_path=None, write_points_file=True, force=False):
        schema = self.extract_pose_schema_from_current_model(model_path=model_path)
        if not schema:
            return False

        model_path = model_path or getattr(self, "weights_file_path", None) or getattr(self, "loaded_model_path", None)
        model_key = os.path.abspath(str(model_path)) if model_path else ""
        labels = [self._format_keypoint_label(label) for label in schema.get("labels", [])]

        current_labels = []
        table = getattr(self, "keypoint_list", None)
        if table is not None:
            for row in range(table.rowCount()):
                item = table.item(row, 1)
                current_labels.append(item.text() if item else "")

        if not force and model_key and getattr(self, "_last_pose_model_path", None) == model_key:
            return True

        points_path = self.get_points_json_path()
        existing_data = read_json_file(points_path, {}) if points_path and os.path.exists(points_path) else {}

        pose_data = self._build_pose_list_data(
            labels,
            skeleton=schema.get("skeleton"),
            flip_idx=schema.get("flip_idx"),
            existing_data=existing_data,
        )

        if not pose_data:
            return False

        if write_points_file and points_path:
            try:
                write_json_file_atomic(points_path, pose_data)
                self.current_keypoint_json_path = points_path
                logger.info(
                    "Wrote pose list from %s to %s",
                    schema.get("source", "model metadata"),
                    points_path,
                )
            except Exception as e:
                logger.warning(f"Failed writing model pose list to points.json: {e}")

        try:
            if points_path and os.path.exists(points_path):
                self.load_keypoint_list_from_path(points_path)
            else:
                self.load_keypoint_list_from_data(pose_data, source_label="model pose metadata")
        except Exception as e:
            logger.warning(f"Failed loading model pose list into the table: {e}")
            return False

        self._last_pose_model_path = model_key
        return True

    def pose_keypoint_color_qcolor(self, index, alpha=None, fallback=None):
        if isinstance(fallback, QColor):
            color = QColor(fallback)
        else:
            color = QColor(255, 255, 255, 150)

        try:
            index = int(index)
        except Exception:
            index = -1

        table = getattr(self, "keypoint_list", None)
        if table is not None and 0 <= index < table.rowCount():
            color_item = table.item(index, 2)
            if color_item:
                color = QColor(color_item.background().color())

        if alpha is not None:
            try:
                color.setAlpha(max(0, min(255, int(alpha))))
            except Exception:
                pass

        return color

    def pose_keypoint_color_bgr(self, index, alpha=255, fallback=None):
        color = self.pose_keypoint_color_qcolor(index, alpha=alpha, fallback=fallback)
        return (color.blue(), color.green(), color.red())

    def pose_list_is_active_for_current_model(self):
        try:
            if self.keypoint_list.rowCount() <= 0:
                return False
        except Exception:
            return False

        try:
            if self.is_keypoint_mode():
                return True
        except Exception:
            pass

        try:
            _task, mode = self.detect_loaded_model_task(getattr(self, "weights_file_path", None))
            return mode == "Keypoints"
        except Exception:
            return False

    def ensure_pose_list_for_output_dir(self, output_dir):
        output_dir = str(output_dir or "").strip()
        if not output_dir or not self.pose_list_is_active_for_current_model():
            return False

        synced_dirs = getattr(self, "_pose_output_dirs_synced", set())
        normalized_dir = os.path.abspath(output_dir)
        if normalized_dir in synced_dirs:
            return True

        os.makedirs(normalized_dir, exist_ok=True)
        points_path = os.path.join(normalized_dir, "points.json")

        try:
            self.save_keypoint_list_to_path(points_path, show_message=False)
            synced_dirs.add(normalized_dir)
            self._pose_output_dirs_synced = synced_dirs
            logger.info(f"Wrote video pose list to: {points_path}")
            return True
        except Exception as e:
            logger.warning(f"Failed writing video pose list to {points_path}: {e}")
            return False

    def redraw_current_video_overlay(self):
        current_frame = getattr(self, "_last_video_frame_bgr", None)
        if current_frame is None or not isinstance(current_frame, np.ndarray) or current_frame.size == 0:
            return

        try:
            render_start = time.perf_counter()
            overlay_start = time.perf_counter()
            frame_to_show = self.draw_video_overlay_on_frame(
                current_frame,
                getattr(self, "latest_video_overlay", None),
            )
            overlay_ms = (time.perf_counter() - overlay_start) * 1000.0
            self.update_display(cv2.cvtColor(frame_to_show, cv2.COLOR_BGR2RGB))
            render_ms = (time.perf_counter() - render_start) * 1000.0
            self.record_video_display_frame(render_ms=render_ms, overlay_ms=overlay_ms)
        except Exception as e:
            logger.debug(f"Could not redraw video overlay from pose list: {e}")

    @staticmethod
    def annotation_mode_for_model_task(task):
        task = str(task or "").strip().lower()
        if task in {"segment", "seg", "segmentation"}:
            return "Segmentation"
        if task in {"pose", "keypoint", "keypoints"}:
            return "Keypoints"
        if task in {"obb", "oriented", "oriented_bbox", "rotated"}:
            return "OBB"
        if task in {"detect", "detection", "box", "boxes"}:
            return "Boxes"
        return None

    def _task_from_mapping(self, mapping):
        if not isinstance(mapping, dict):
            return None

        for key in ("task", "model_task", "yolo_task"):
            value = mapping.get(key)
            if value:
                return value

        for key in ("args", "train_args", "overrides", "metadata"):
            value = mapping.get(key)
            if isinstance(value, dict):
                task = self._task_from_mapping(value)
                if task:
                    return task

        return None

    def detect_loaded_model_task(self, model_path=None):
        model_path = str(model_path or getattr(self, "weights_file_path", "") or "")

        model = getattr(self, "model", None)
        lower_path = model_path.lower()
        candidates = []
        # Exported backends need their embedded task checked before model.task.
        # Ultralytics must choose the predictor while YOLO(...) is constructed,
        # and a generically named engine such as "last.engine" can otherwise be
        # guessed as detection even though its metadata says segmentation.
        if lower_path.endswith(".engine"):
            candidates.append(self._task_from_mapping(self.read_engine_metadata(model_path)))

        sidecar_path = model_path + ".json" if model_path else ""
        if sidecar_path and os.path.exists(sidecar_path):
            candidates.append(self._task_from_mapping(read_json_file(sidecar_path, {})))

        candidates.extend([
            getattr(model, "task", None),
            getattr(getattr(model, "model", None), "task", None),
            self._task_from_mapping(getattr(model, "overrides", None)),
            self._task_from_mapping(getattr(getattr(model, "model", None), "args", None)),
            self._task_from_mapping(getattr(getattr(model, "model", None), "yaml", None)),
            self._task_from_mapping(getattr(model, "ckpt", None)),
        ])

        for candidate in candidates:
            mode = self.annotation_mode_for_model_task(candidate)
            if mode:
                return str(candidate).strip().lower(), mode

        name = os.path.basename(lower_path)
        if re.search(r"(^|[-_.])seg(ment)?($|[-_.])", name):
            return "segment", "Segmentation"
        if re.search(r"(^|[-_.])pose($|[-_.])", name):
            return "pose", "Keypoints"
        if re.search(r"(^|[-_.])obb($|[-_.])", name):
            return "obb", "OBB"

        if lower_path.endswith(".weights"):
            return "detect", "Boxes"

        return None, None

    def exported_model_task_hint(self, model_path):
        """Return a task that must be supplied while constructing an exported model."""
        model_path = self.normalize_path(model_path)
        if not model_path:
            return None

        task = None
        lower_path = model_path.lower()
        if lower_path.endswith(".engine"):
            task = self._task_from_mapping(self.read_engine_metadata(model_path))

        sidecar_path = model_path + ".json"
        if not task and os.path.exists(sidecar_path):
            task = self._task_from_mapping(read_json_file(sidecar_path, {}))

        if not task:
            name = os.path.basename(lower_path)
            if re.search(r"(^|[-_.])seg(ment)?($|[-_.])", name):
                task = "segment"
            elif re.search(r"(^|[-_.])pose($|[-_.])", name):
                task = "pose"
            elif re.search(r"(^|[-_.])obb($|[-_.])", name):
                task = "obb"

        task = str(task or "").strip().lower()
        aliases = {
            "seg": "segment",
            "segmentation": "segment",
            "detection": "detect",
            "keypoint": "pose",
            "keypoints": "pose",
        }
        task = aliases.get(task, task)
        return task if task in {"detect", "segment", "classify", "pose", "obb", "semantic"} else None

    def create_ultralytics_model(self, model_path):
        """Construct YOLO with an explicit exported-model task when metadata provides one."""
        model_path = self.normalize_path(model_path)
        task = self.exported_model_task_hint(model_path)
        if task:
            logger.info("Loading Ultralytics model as task=%s from %s", task, model_path)
            return YOLO(model_path, task=task)
        return YOLO(model_path)

    def auto_set_annotation_mode_for_model(self, model_path=None, force=False):
        _task, mode = self.detect_loaded_model_task(model_path)
        if not mode:
            logger.info("Could not detect annotation mode from model: %s", model_path)
            return False

        current = self.segmentation_mode.currentText()
        if current == mode and not force:
            self._last_auto_annotation_mode = mode
            return False

        self._annotation_mode_auto_changing = True
        try:
            self.set_annotation_mode(mode)
        finally:
            self._annotation_mode_auto_changing = False

        self._annotation_mode_manual_override = False
        self._last_auto_annotation_mode = mode
        self.statusBar().showMessage(f"Annotation mode set from model: {mode}", 3500)
        return True

    def edit_mode_active(self):
        scene = self.screen_view.scene()
        if scene is None:
            return False

        for item in scene.items():
            if isinstance(item, (BoundingBoxDrawer, SegmentationDrawer, OBBDrawer)):
                if getattr(item, "edit_mode", False):
                    return True
        return False

    #split data ui

    def launch_split_data_ui(self):
        dialog = DatasetSplitDialog(self)
        dialog.exec_()

    def collect_current_tile_images(self, dataset_dir=None):
        dataset_dir = dataset_dir or self.current_dataset_directory()
        if not dataset_dir:
            return []
        dataset_dir = self.normalize_path(dataset_dir)

        try:
            image_files = self.collect_current_dataset_conversion_files()
        except Exception:
            image_files = []

        if not image_files:
            image_files = self.get_image_files(dataset_dir, extensions=DATASET_IMAGE_SUFFIXES)

        clean_files = []
        seen = set()

        def is_generated_tile_output(image_path):
            try:
                relative = os.path.relpath(image_path, dataset_dir).replace("\\", "/")
            except Exception:
                return False
            parts = [part.lower() for part in relative.split("/") if part]
            return any(part.startswith("tiles_") for part in parts[:-1])

        for image_file in image_files:
            image_file = self.normalize_path(image_file)
            if image_file in seen or not os.path.isfile(image_file):
                continue
            if self.is_placeholder_file(image_file):
                continue
            if is_generated_tile_output(image_file):
                continue
            try:
                common_dir = self.normalize_path(os.path.commonpath([dataset_dir, image_file]))
                if common_dir != dataset_dir:
                    continue
            except Exception:
                continue
            clean_files.append(image_file)
            seen.add(image_file)

        return sorted(clean_files)

    def tile_overlap_percent(self):
        widget = getattr(self, "tile_overlap_spinbox", None)
        if widget is not None and hasattr(widget, "value"):
            return max(0, min(90, int(widget.value())))
        return 20

    def tile_min_visible_percent(self):
        widget = getattr(self, "tile_min_visible_spinbox", None)
        if widget is not None and hasattr(widget, "value"):
            return max(1, min(100, int(widget.value())))
        return 25

    def selected_tile_image_format(self):
        combo = getattr(self, "tile_format_combo", None)
        if isinstance(combo, QtWidgets.QComboBox):
            value = str(combo.currentData() or combo.currentText() or ".jpg").strip().lower()
            if value in {"source", "same", "original"}:
                return "source"
            return normalize_image_extension(value)
        return ".jpg"

    def selected_tile_layout_mode(self):
        combo = getattr(self, "tile_layout_combo", None)
        if isinstance(combo, QtWidgets.QComboBox):
            value = str(combo.currentData() or "grid_objects").strip().lower()
            if value in {"grid_objects", "objects", "grid"}:
                return value
        return "grid_objects"

    def tile_keep_empty_enabled(self):
        checkbox = getattr(self, "tile_keep_empty_checkbox", None)
        return bool(checkbox.isChecked()) if checkbox is not None else False

    def tile_pad_edges_enabled(self):
        checkbox = getattr(self, "tile_pad_edges_checkbox", None)
        return bool(checkbox.isChecked()) if checkbox is not None else True

    def crop_images(self):
        active_worker = getattr(self, "_tile_worker", None)
        if active_worker is not None:
            try:
                if active_worker.isRunning():
                    active_worker.cancel()
                    self.statusBar().showMessage("Canceling image tiling...")
                    return
            except RuntimeError:
                self._tile_worker = None

        dataset_dir = self.current_dataset_directory()
        image_files = self.collect_current_tile_images(dataset_dir)
        if not dataset_dir or not image_files:
            QMessageBox.warning(self, "Tile Images", "Open an image dataset before tiling.")
            return

        width = int(self.w_img.value())
        height = int(self.h_img.value())
        overlap_percent = self.tile_overlap_percent()
        min_visible_percent = self.tile_min_visible_percent()
        tile_format = self.selected_tile_image_format()
        tile_layout_mode = self.selected_tile_layout_mode()
        layout_suffix = {
            "grid_objects": "grid_objects",
            "objects": "objects_only",
            "grid": "grid_only",
        }[tile_layout_mode]
        output_directory = os.path.join(
            dataset_dir,
            f"tiles_{width}x{height}_ov{overlap_percent}_vis{min_visible_percent}_{layout_suffix}",
        )

        worker = TileWorker(
            dataset_dir,
            width,
            height,
            overlap_ratio=overlap_percent / 100.0,
            image_files=image_files,
            output_directory=output_directory,
            image_format=tile_format,
            keep_empty_tiles=self.tile_keep_empty_enabled(),
            pad_edges=self.tile_pad_edges_enabled(),
            min_area_ratio=min_visible_percent / 100.0,
            annotation_mode=self.current_mode(),
            tile_layout_mode=tile_layout_mode,
        )
        self._tile_worker = worker
        worker.detailed_progress.connect(self.on_tile_progress)
        worker.completed.connect(self.on_tile_completed)
        worker.failed.connect(self.on_tile_failed)
        worker.finished.connect(lambda worker=worker: self.on_tile_worker_finished(worker))

        button = getattr(self, "crop_img_button", None)
        if isinstance(button, QtWidgets.QPushButton):
            self._tile_button_idle_text = button.text()
            button.setText("Cancel Tiling")
            button.setEnabled(True)

        self.set_label_progress(0, max(1, len(image_files)), value=0, progress_format="Tiling 0/{0}".format(len(image_files)))
        self.statusBar().showMessage(f"Tiling {len(image_files)} current-dataset images to {output_directory}")
        worker.start()

    def on_tile_progress(self, processed, total, tile_count):
        processed = max(0, int(processed))
        total = max(0, int(total))
        tile_count = max(0, int(tile_count))
        self.set_label_progress(
            0,
            max(1, total),
            value=min(processed, max(1, total)),
            progress_format=f"Tiling {processed}/{total} | {tile_count} tiles",
        )
        self.statusBar().showMessage(
            f"Tiling images: {processed}/{total} processed, {tile_count} tiles created"
        )

    def on_tile_completed(self, summary):
        summary = dict(summary or {})
        processed = int(summary.get("processed", 0))
        total = int(summary.get("total", 0))
        tile_count = int(summary.get("tiles", 0))
        failures = list(summary.get("failed", []) or [])
        canceled = bool(summary.get("canceled", False))
        output_directory = summary.get("output_directory", "")

        if canceled:
            self.reset_label_progress(0)
            self.statusBar().showMessage(
                f"Tiling canceled after {processed}/{total} images and {tile_count} tiles.",
                5000,
            )
            return

        self.reset_label_progress(100 if not failures else 0)
        if failures:
            preview = "\n".join(failures[:5])
            more = f"\n...and {len(failures) - 5} more." if len(failures) > 5 else ""
            QMessageBox.warning(
                self,
                "Tile Images",
                (
                    f"Tiling finished with {len(failures)} failed image(s).\n"
                    f"Created {tile_count} tiles from {processed}/{total} images.\n\n"
                    f"{preview}{more}"
                ),
            )
        else:
            QMessageBox.information(
                self,
                "Tiling Complete",
                (
                    f"Created {tile_count} tiles from {processed} image(s).\n\n"
                    f"Output:\n{output_directory}"
                ),
            )
        self.statusBar().showMessage(
            f"Tiling complete: {tile_count} tiles created in {output_directory}",
            7000,
        )

    def on_tile_failed(self, message):
        self.reset_label_progress(0)
        self.statusBar().showMessage("Image tiling failed.", 5000)
        QMessageBox.critical(self, "Tile Images", f"Image tiling failed:\n{message}")

    def on_tile_worker_finished(self, worker):
        button = getattr(self, "crop_img_button", None)
        if isinstance(button, QtWidgets.QPushButton):
            button.setText(getattr(self, "_tile_button_idle_text", "Tile Dataset"))
            button.setEnabled(True)
        self._cleanup_worker_reference("_tile_worker", worker)

    def toggle_roi(self, state, roi_id):
        """Toggle visibility for the specified ROI based on checkbox state."""
        if roi_id == 1:
            if state == Qt.Checked:
                if not hasattr(self, 'roi_item_1') or self.roi_item_1 is None:
                    self.update_roi(1, preserve_polygon=True)  # Create ROI 1 if it doesn't exist
                else:
                    self.roi_item_1.show()
                    self.draw_roi_polygon(1)
            else:
                self.remove_roi(1)
        elif roi_id == 2:
            if state == Qt.Checked:
                if not hasattr(self, 'roi_item_2') or self.roi_item_2 is None:
                    self.update_roi(2, preserve_polygon=True)  # Create ROI 2 if it doesn't exist
                else:
                    self.roi_item_2.show()
                    self.draw_roi_polygon(2)
            else:
                self.remove_roi(2)

    def validate_roi(self):
        """Ensure at least one valid ROI exists before filtering."""

        def is_valid_roi(roi_id):
            """Helper function to check if ROI exists and is visible."""
            roi = getattr(self, f"roi_item_{roi_id}", None)
            try:
                if roi is not None and roi.isVisible():
                    return True
            except RuntimeError:  # Object has been deleted
                setattr(self, f"roi_item_{roi_id}", None)

            polygon = getattr(self, f"roi_polygon_item_{roi_id}", None)
            try:
                if polygon is not None and polygon.isVisible():
                    return True
            except RuntimeError:
                setattr(self, f"roi_polygon_item_{roi_id}", None)

            return bool(self._roi_polygon_points_for_state(str(roi_id)))

        valid_roi_1 = is_valid_roi(1)
        valid_roi_2 = is_valid_roi(2)

        if not (valid_roi_1 or valid_roi_2):
            QMessageBox.warning(self, "No ROI Defined", "Please define and activate at least one ROI before filtering.")
            return False

        if not hasattr(self, 'image_directory') or not self.image_directory:
            QMessageBox.warning(self, "No Directory Selected", "Please select an image directory first.")
            return False

        return True

    def filter_bboxes(self):
        """
        Filter annotations based on active ROIs.
        Supports regular bounding boxes, segmentations, OBBs, and keypoints.
        Keeps only annotations that intersect at least one active ROI.
        """
        if not self.validate_roi():
            return

        # Gather active ROI ids safely. Each id may resolve to a SAM polygon or a rectangle.
        roi_ids = []
        for roi_id, checkbox_name in ((1, "roi_checkbox"), (2, "roi_checkbox_2")):
            checkbox = getattr(self, checkbox_name, None)
            if checkbox is not None and checkbox.isChecked():
                self.update_roi(roi_id, preserve_polygon=True)
                roi_ids.append(roi_id)

        if not roi_ids:
            QMessageBox.warning(self, "No ROI Defined", "Please activate at least one ROI before filtering.")
            return

        total_images = len(self.image_files)
        self.label_progress.setMinimum(0)
        self.label_progress.setMaximum(total_images)
        self.label_progress.setValue(0)

        for idx, image_file in enumerate(self.image_files):
            if self.is_placeholder_file(image_file):
                continue

            pixmap = QPixmap(image_file)
            if pixmap.isNull():
                logger.error(f"Failed to load image: {image_file}")
                continue

            image_width, image_height = pixmap.width(), pixmap.height()

            roi_polygons = self.get_dynamic_roi_polygons(
                roi_ids=roi_ids,
                image_width=image_width,
                image_height=image_height
            )

            if not roi_polygons:
                logger.warning(f"No valid ROI polygons for image: {image_file}")
                continue

            txt_file_path, exists = self.get_label_file(image_file, return_existence=True)
            if not exists:
                logger.warning(f"No annotation file found for {image_file}, skipping.")
                continue

            self.filter_bboxes_in_file(
                txt_file_path=txt_file_path,
                roi_polygons=roi_polygons,
                image_width=image_width,
                image_height=image_height
            )

            self.label_progress.setValue(idx + 1)
            if idx % 5 == 0:
                QtWidgets.QApplication.processEvents()

        QMessageBox.information(self, "Filter Complete", "Annotations outside the ROIs have been processed.")
        self.label_progress.setValue(total_images)

        if getattr(self, "current_file", None) and not self.is_placeholder_file(self.current_file):
            self.refresh_bounding_box_display()

    def get_dynamic_rois(self, roi_items, image_width, image_height):
        """
        Scale ROI rectangles from the currently displayed image space
        into the target image's pixel space.

        Args:
            roi_items: list of visible QGraphicsRectItem ROI objects
            image_width: target image width
            image_height: target image height

        Returns:
            List of (x, y, w, h) tuples in target image coordinates.
        """
        if (
            not hasattr(self, "image")
            or self.image is None
            or self.image.width() <= 0
            or self.image.height() <= 0
        ):
            logger.warning("Cannot scale ROIs because the reference display image is invalid.")
            return []

        ref_width = self.image.width()
        ref_height = self.image.height()

        x_scale = image_width / ref_width
        y_scale = image_height / ref_height

        scaled_rois = []

        for roi_item in roi_items:
            try:
                rect = roi_item.rect()
            except RuntimeError:
                continue

            scaled_x = int(rect.x() * x_scale)
            scaled_y = int(rect.y() * y_scale)
            scaled_w = int(rect.width() * x_scale)
            scaled_h = int(rect.height() * y_scale)

            scaled_rois.append((scaled_x, scaled_y, scaled_w, scaled_h))

        return scaled_rois

    def _roi_polygon_store(self):
        store = getattr(self, "_roi_polygon_points", None)
        if not isinstance(store, dict):
            store = {}
            self._roi_polygon_points = store
        return store

    def _normalize_roi_polygon_points(self, points):
        if not isinstance(points, (list, tuple)):
            return []

        normalized = []
        for point in points:
            try:
                if isinstance(point, dict):
                    x = point.get("x")
                    y = point.get("y")
                else:
                    x, y = point[:2]
                x = max(0.0, min(1.0, float(x)))
                y = max(0.0, min(1.0, float(y)))
                normalized.append((x, y))
            except Exception:
                continue

        cleaned = []
        last = None
        for point in normalized:
            if point == last:
                continue
            cleaned.append(point)
            last = point

        if len(cleaned) > 1 and cleaned[0] == cleaned[-1]:
            cleaned.pop()

        return cleaned if len(cleaned) >= 3 else []

    def _set_roi_polygon_points(self, roi_id, points):
        normalized = self._normalize_roi_polygon_points(points)
        store = self._roi_polygon_store()
        key = str(roi_id)
        if normalized:
            store[key] = normalized
        else:
            store.pop(key, None)
        return normalized

    def _roi_polygon_points_for_state(self, roi_id):
        points = self._roi_polygon_store().get(str(roi_id))
        if not points:
            return []
        return [[round(float(x), 6), round(float(y), 6)] for x, y in points]

    def _roi_checkbox_is_checked(self, roi_id):
        checkbox_name = "roi_checkbox" if int(roi_id) == 1 else "roi_checkbox_2"
        checkbox = getattr(self, checkbox_name, None)
        try:
            return bool(checkbox is not None and checkbox.isChecked())
        except RuntimeError:
            return False

    def get_dynamic_roi_polygons(self, roi_ids, image_width, image_height):
        """
        Return shapely ROI polygons in the target image space.
        SAM-refined polygon ROIs are preferred; rectangle ROIs are used as fallback.
        """
        if (
            not hasattr(self, "image")
            or self.image is None
            or self.image.width() <= 0
            or self.image.height() <= 0
        ):
            logger.warning("Cannot scale ROIs because the reference display image is invalid.")
            return []

        ref_width = max(1, int(self.image.width()))
        ref_height = max(1, int(self.image.height()))
        x_scale = image_width / ref_width
        y_scale = image_height / ref_height

        roi_polygons = []
        for roi_id in roi_ids:
            key = str(roi_id)
            normalized_points = self._roi_polygon_store().get(key)
            if normalized_points and len(normalized_points) >= 3:
                points = [
                    (
                        max(0.0, min(float(image_width), float(x) * image_width)),
                        max(0.0, min(float(image_height), float(y) * image_height)),
                    )
                    for x, y in normalized_points
                ]
                try:
                    poly = Polygon(points)
                    if not poly.is_valid:
                        poly = poly.buffer(0)
                    if not poly.is_empty and poly.is_valid:
                        roi_polygons.append(poly)
                        continue
                except Exception as e:
                    logger.warning(f"Invalid SAM ROI polygon {roi_id}: {e}")

            roi_item = getattr(self, f"roi_item_{roi_id}", None)
            try:
                if roi_item is None or not roi_item.isVisible():
                    continue
                rect = roi_item.rect()
            except RuntimeError:
                setattr(self, f"roi_item_{roi_id}", None)
                continue

            x = float(rect.x()) * x_scale
            y = float(rect.y()) * y_scale
            w = float(rect.width()) * x_scale
            h = float(rect.height()) * y_scale
            if w > 0 and h > 0:
                roi_polygons.append(shapely_box(x, y, x + w, y + h))

        return roi_polygons

    def filter_bboxes_in_file(self, txt_file_path, roi_polygons, image_width, image_height):
        """
        Filter a single YOLO label file against one or more ROI polygons.
        Supports regular bboxes, keypoints, segmentations, and OBBs.
        """
        try:
            rects, segmentations, obbs = self.load_labels(txt_file_path, image_width, image_height)

            kept_labels = []

            # -------------------------------
            # Regular bboxes + keypoint bboxes
            # -------------------------------
            for rect_tuple in rects:
                try:
                    rect = rect_tuple[0]
                    class_id = rect_tuple[1]
                    confidence = rect_tuple[2] if len(rect_tuple) >= 3 else None
                    keypoints = rect_tuple[3] if len(rect_tuple) >= 4 else None

                    poly = shapely_box(
                        rect.x(),
                        rect.y(),
                        rect.x() + rect.width(),
                        rect.y() + rect.height()
                    )

                    if not poly.is_valid:
                        continue

                    if any(poly.intersects(roi_poly) for roi_poly in roi_polygons):
                        bbox = BoundingBox.from_rect(
                            QRectF(rect.x(), rect.y(), rect.width(), rect.height()),
                            image_width,
                            image_height,
                            class_id,
                            confidence
                        )

                        if keypoints:
                            bbox.keypoints = keypoints

                        kept_labels.append(bbox.to_str())

                except Exception as bbox_err:
                    logger.warning(f"Skipping invalid bbox entry in {txt_file_path}: {bbox_err}")

            # -------------------------------
            # Segmentations
            # -------------------------------
            for class_id, points in segmentations:
                try:
                    if not points or len(points) < 3:
                        continue

                    # Convert normalized points -> pixel coordinates for ROI intersection
                    pixel_points = []
                    for x, y in points:
                        px = x * image_width if 0.0 <= x <= 1.0 else x
                        py = y * image_height if 0.0 <= y <= 1.0 else y
                        pixel_points.append((px, py))

                    seg_poly = Polygon(pixel_points)
                    if not seg_poly.is_valid:
                        seg_poly = seg_poly.buffer(0)

                    if seg_poly.is_empty or not seg_poly.is_valid:
                        continue

                    if any(seg_poly.intersects(roi_poly) for roi_poly in roi_polygons):
                        # Save back in normalized coordinates
                        segmentation_flat = []
                        for px, py in pixel_points:
                            segmentation_flat.extend([
                                px / image_width,
                                py / image_height
                            ])

                        bbox = BoundingBox(
                            class_id=class_id,
                            x_center=0,
                            y_center=0,
                            width=0,
                            height=0,
                            segmentation=segmentation_flat
                        )
                        kept_labels.append(bbox.to_str())

                except Exception as seg_err:
                    logger.warning(f"Skipping invalid segmentation in {txt_file_path}: {seg_err}")

            # -------------------------------
            # OBBs
            # -------------------------------
            for class_id, obb_points, angle in obbs:
                try:
                    if not obb_points or len(obb_points) != 4:
                        continue

                    # Convert normalized points -> pixel coordinates for ROI intersection
                    pixel_obb_points = []
                    for x, y in obb_points:
                        px = x * image_width if 0.0 <= x <= 1.0 else x
                        py = y * image_height if 0.0 <= y <= 1.0 else y
                        pixel_obb_points.append((px, py))

                    obb_poly = Polygon(pixel_obb_points)
                    if not obb_poly.is_valid:
                        obb_poly = obb_poly.buffer(0)

                    if obb_poly.is_empty or not obb_poly.is_valid:
                        continue

                    if any(obb_poly.intersects(roi_poly) for roi_poly in roi_polygons):
                        # Save back in normalized coordinates
                        obb_flat = []
                        for px, py in pixel_obb_points:
                            obb_flat.extend([
                                px / image_width,
                                py / image_height
                            ])

                        bbox = BoundingBox(
                            class_id=class_id,
                            x_center=0,
                            y_center=0,
                            width=0,
                            height=0,
                            obb=obb_flat
                        )
                        kept_labels.append(bbox.to_str())

                except Exception as obb_err:
                    logger.warning(f"Skipping invalid OBB in {txt_file_path}: {obb_err}")

            if kept_labels:
                self.save_labels_to_file(txt_file_path, kept_labels, mode="w")
            else:
                open(txt_file_path, "w").close()

        except Exception as e:
            logger.error(f"Error processing {txt_file_path}: {e}")

    def draw_roi(self, width, height, x, y, roi_id):
        """Draw or update the ROI rectangle dynamically on the image."""
        pixmap_width = self.image.width()
        pixmap_height = self.image.height()

        # Constrain ROI to image bounds
        x = max(0, min(x, pixmap_width - width))
        y = max(0, min(y, pixmap_height - height))
        width = min(width, pixmap_width - x)
        height = min(height, pixmap_height - y)

        roi_attr = f'roi_item_{roi_id}'
        roi_item = getattr(self, roi_attr, None)

        # Guard against stale Qt items after scene rebuilds.
        if roi_item is None or sip.isdeleted(roi_item) or roi_item.scene() is None:
            roi_item = QGraphicsRectItem()
            pen = QPen(Qt.yellow if roi_id == 1 else Qt.green)
            pen.setWidth(3)
            roi_item.setPen(pen)
            roi_item.setZValue(70)
            self.screen_view.scene().addItem(roi_item)
            setattr(self, roi_attr, roi_item)

        roi_item.setRect(x, y, width, height)
        roi_item.show()

    def draw_roi_polygon(self, roi_id, points=None):
        """Draw the SAM-refined ROI polygon over the rectangular ROI prompt."""
        points = self._set_roi_polygon_points(roi_id, points) if points is not None else self._roi_polygon_store().get(str(roi_id), [])
        if not points or len(points) < 3:
            return None

        if not hasattr(self, "image") or self.image is None:
            return None

        scene = self.screen_view.scene()
        if scene is None:
            return None

        pixmap_width = max(1, int(self.image.width()))
        pixmap_height = max(1, int(self.image.height()))
        scene_points = [
            QPointF(float(x) * pixmap_width, float(y) * pixmap_height)
            for x, y in points
        ]
        polygon = QPolygonF(scene_points)
        item_attr = f"roi_polygon_item_{roi_id}"
        item = getattr(self, item_attr, None)

        if item is None or sip.isdeleted(item) or item.scene() is None:
            item = QGraphicsPolygonItem()
            pen_color = QColor(255, 220, 0) if int(roi_id) == 1 else QColor(0, 255, 120)
            fill_color = QColor(pen_color)
            fill_color.setAlpha(42)
            pen = QPen(pen_color)
            pen.setWidth(3)
            item.setPen(pen)
            item.setBrush(QBrush(fill_color))
            item.setZValue(75)
            item.setData(0, f"sam_roi_polygon_{roi_id}")
            scene.addItem(item)
            setattr(self, item_attr, item)

        item.setPolygon(polygon)
        item.show()

        roi_item = getattr(self, f"roi_item_{roi_id}", None)
        try:
            if roi_item is not None and not sip.isdeleted(roi_item):
                roi_item.hide()
        except RuntimeError:
            setattr(self, f"roi_item_{roi_id}", None)

        return item

    def clear_roi_polygon(self, roi_id, forget=True):
        """Remove the SAM polygon overlay for an ROI; optionally forget stored points."""
        item_attr = f"roi_polygon_item_{roi_id}"
        item = getattr(self, item_attr, None)
        try:
            if item is not None and not sip.isdeleted(item) and item.scene() is not None:
                item.scene().removeItem(item)
        except RuntimeError:
            pass
        setattr(self, item_attr, None)

        if forget:
            self._roi_polygon_store().pop(str(roi_id), None)
            if hasattr(self, "queue_settings_save"):
                self.queue_settings_save()

            roi_item = getattr(self, f"roi_item_{roi_id}", None)
            try:
                if (
                    self._roi_checkbox_is_checked(roi_id)
                    and roi_item is not None
                    and not sip.isdeleted(roi_item)
                    and roi_item.scene() is not None
                ):
                    roi_item.show()
            except RuntimeError:
                setattr(self, f"roi_item_{roi_id}", None)

    def _current_roi_prompt_bbox_xyxy(self, roi_id):
        roi_item = getattr(self, f"roi_item_{roi_id}", None)
        try:
            if roi_item is None or roi_item.scene() is None:
                self.update_roi(roi_id, preserve_polygon=True)
                roi_item = getattr(self, f"roi_item_{roi_id}", None)
            if roi_item is None:
                return None
            rect = roi_item.rect()
        except RuntimeError:
            setattr(self, f"roi_item_{roi_id}", None)
            return None

        if rect.width() <= 1 or rect.height() <= 1:
            return None

        return [
            int(round(rect.left())),
            int(round(rect.top())),
            int(round(rect.right())),
            int(round(rect.bottom())),
        ]

    def _current_display_image_for_sam_roi(self):
        image = getattr(self, "current_display_image", None)
        if isinstance(image, np.ndarray) and image.size > 0:
            return image

        current_file = getattr(self, "current_file", None)
        if current_file and os.path.exists(current_file):
            image = cv2.imread(current_file, cv2.IMREAD_UNCHANGED)
            if image is not None and image.size > 0:
                return self.ensure_rgb(image)

        return None

    def refine_roi_with_sam(self, roi_id):
        """Use the current ROI rectangle as a SAM3 prompt and replace it with a polygon ROI."""
        checkbox = getattr(self, "roi_checkbox" if int(roi_id) == 1 else "roi_checkbox_2", None)
        if checkbox is not None and not checkbox.isChecked():
            checkbox.setChecked(True)

        if not hasattr(self, "image") or self.image is None:
            QMessageBox.warning(self, "SAM ROI", "Load an image before refining an ROI.")
            return False

        bbox = self._current_roi_prompt_bbox_xyxy(roi_id)
        if bbox is None:
            QMessageBox.warning(self, "SAM ROI", f"ROI {roi_id} needs a valid rectangle first.")
            return False

        image = self._current_display_image_for_sam_roi()
        if image is None:
            QMessageBox.warning(self, "SAM ROI", "Could not read the current image for SAM3.")
            return False

        mask = self.sam_snap_bbox_to_mask(image, bbox, imgsz=self._sam_imgsz())
        if not self.validate_sam_mask_for_bbox(mask, bbox, min_area=12, max_area_multiplier=5.0):
            QMessageBox.warning(self, "SAM ROI", f"SAM3 could not make a usable polygon for ROI {roi_id}.")
            return False

        img_h, img_w = image.shape[:2]
        points = self.mask_to_polygon_points(mask, img_w, img_h, epsilon_ratio=0.001, max_points=220)
        if len(points) < 3:
            QMessageBox.warning(self, "SAM ROI", f"SAM3 mask for ROI {roi_id} was too small or rough to polygonize.")
            return False

        self.draw_roi_polygon(roi_id, points)
        if hasattr(self, "queue_settings_save"):
            self.queue_settings_save()
        logger.info("SAM3 refined ROI %s into a %s-point polygon.", roi_id, len(points))
        return True

    def remove_roi(self, roi_id):
        """Safely remove the specified ROI item from the scene."""
        try:
            if roi_id == 1 and hasattr(self, 'roi_item_1') and self.roi_item_1 is not None:
                if self.roi_item_1.scene() is not None:
                    self.roi_item_1.scene().removeItem(self.roi_item_1)
                self.roi_item_1 = None

            elif roi_id == 2 and hasattr(self, 'roi_item_2') and self.roi_item_2 is not None:
                if self.roi_item_2.scene() is not None:
                    self.roi_item_2.scene().removeItem(self.roi_item_2)
                self.roi_item_2 = None

        except RuntimeError:
            if roi_id == 1:
                self.roi_item_1 = None
            elif roi_id == 2:
                self.roi_item_2 = None
        finally:
            self.clear_roi_polygon(roi_id, forget=False)

    def update_roi(self, roi_id, preserve_polygon=False):
        """Update the ROI rectangle based on the current slider values."""
        if not hasattr(self, 'image') or self.image is None:
            if self.roi_checkbox.isChecked() or self.roi_checkbox_2.isChecked():
                logger.warning("No valid image loaded. ROI cannot be updated.")
            return

        # Read ROI dimensions and offsets from the matching control set.
        if roi_id == 1:
            width_offset = self.width_spin_slider.value() // 2
            height_offset = self.height_spin_slider.value() // 2
            x_offset = self.x_spin_slider.value()
            y_offset = self.y_spin_slider.value()
        elif roi_id == 2:
            width_offset = self.width_spin_slider_2.value() // 2
            height_offset = self.height_spin_slider_2.value() // 2
            x_offset = self.x_spin_slider_2.value()
            y_offset = self.y_spin_slider_2.value()
        else:
            return

        # Anchor ROI offsets around the image center.
        center_x = self.image.width() // 2
        center_y = self.image.height() // 2

        x = center_x - width_offset + x_offset
        y = center_y - height_offset + y_offset

        # Draw or update the selected ROI
        self.draw_roi(width_offset * 2, height_offset * 2, x, y, roi_id)
        if preserve_polygon:
            self.draw_roi_polygon(roi_id)
        else:
            self.clear_roi_polygon(roi_id)

    def on_frame_change(self):
        if hasattr(self, 'current_image_path') and os.path.exists(self.current_image_path):
            self.image = QPixmap(self.current_image_path)

            if not hasattr(self, 'pixmap_item'):
                scene = QGraphicsScene(0, 0, self.image.width(), self.image.height())
                self.pixmap_item = QGraphicsPixmapItem(self.image)
                self.pixmap_item.setTransformationMode(Qt.SmoothTransformation)
                scene.addItem(self.pixmap_item)
                self.set_screen_view_scene_and_rect(scene)
            else:
                self.pixmap_item.setPixmap(self.image)

        if self.roi_checkbox.isChecked():
            self.update_roi(1, preserve_polygon=True)

        if self.roi_checkbox_2.isChecked():
            self.update_roi(2, preserve_polygon=True)

