    def _training_eval_valid_percent(self):
        value = (
            self.settings.get("datasetValidPercent", "20%")
            if isinstance(getattr(self, "settings", None), dict)
            else "20%"
        )
        match = re.search(r"\d+(?:\.\d+)?", str(value))
        try:
            percent = float(match.group(0)) if match else 20.0
        except Exception:
            percent = 20.0
        return max(5.0, min(40.0, percent))

    def _label_path_for_image(self, image_path):
        path = Path(str(image_path))
        candidates = [path.with_suffix(".txt")]
        parts = list(path.parts)
        lowered = [part.lower() for part in parts]
        if "images" in lowered:
            idx = lowered.index("images")
            parts[idx] = "labels"
            candidates.append(Path(*parts).with_suffix(".txt"))
        for candidate in candidates:
            if candidate.exists():
                return str(candidate)
        return str(candidates[0])

    def _training_eval_image_class_ids(self, image_path):
        label_path = self._label_path_for_image(image_path)
        class_ids = set()
        if not label_path or not os.path.exists(label_path):
            return class_ids
        try:
            with open(label_path, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    parts = line.strip().split()
                    if not parts:
                        continue
                    try:
                        class_ids.add(int(float(parts[0])))
                    except Exception:
                        continue
        except Exception:
            return set()
        return class_ids

    def _training_eval_image_class_counts(self, image_path):
        label_path = self._label_path_for_image(image_path)
        counts = Counter()
        if not label_path or not os.path.exists(label_path):
            return counts
        try:
            with open(label_path, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    parts = line.strip().split()
                    if not parts:
                        continue
                    try:
                        counts[int(float(parts[0]))] += 1
                    except Exception:
                        continue
        except Exception:
            return Counter()
        return counts

    def _training_eval_split_class_report(self, train_files, valid_files, class_names=None):
        train_files = [self.normalize_path(path) for path in train_files or [] if path]
        valid_files = [self.normalize_path(path) for path in valid_files or [] if path]
        class_names = list(class_names or [])
        train_counts = Counter()
        valid_counts = Counter()
        for image_path in train_files:
            train_counts.update(self._training_eval_image_class_counts(image_path))
        for image_path in valid_files:
            valid_counts.update(self._training_eval_image_class_counts(image_path))

        class_ids = set(train_counts) | set(valid_counts) | set(range(len(class_names)))
        rows = []
        missing_valid = []
        missing_train = []
        for class_id in sorted(class_ids):
            train_count = int(train_counts.get(class_id, 0))
            valid_count = int(valid_counts.get(class_id, 0))
            total = train_count + valid_count
            if total <= 0:
                continue
            class_name = class_names[class_id] if 0 <= class_id < len(class_names) else str(class_id)
            row = {
                "class_id": int(class_id),
                "class_name": str(class_name),
                "train_labels": train_count,
                "valid_labels": valid_count,
                "total_labels": total,
                "valid_pct": round((valid_count / total) * 100.0, 2) if total else 0.0,
            }
            rows.append(row)
            if train_count > 0 and valid_count == 0:
                missing_valid.append(row)
            if valid_count > 0 and train_count == 0:
                missing_train.append(row)

        overlap = len(set(train_files) & set(valid_files))
        return {
            "train_images": len(train_files),
            "valid_images": len(valid_files),
            "overlap_images": overlap,
            "same_split": bool(train_files and valid_files and set(train_files) == set(valid_files)),
            "rows": rows,
            "missing_valid": missing_valid,
            "missing_train": missing_train,
        }

    def _training_eval_yaml_split_report(self, data_yaml_path, yaml_data=None):
        data_yaml_path = self.normalize_path(data_yaml_path or "")
        if not data_yaml_path or not os.path.exists(data_yaml_path):
            return {}
        try:
            yaml_mtime = os.path.getmtime(data_yaml_path)
        except Exception:
            yaml_mtime = 0.0
        cache = getattr(self, "_training_eval_yaml_split_report_cache", {}) or {}
        cache_key = os.path.normcase(os.path.abspath(data_yaml_path))
        cached = cache.get(cache_key)
        now = time.time()
        if (
            isinstance(cached, dict)
            and float(cached.get("mtime", -1.0)) == float(yaml_mtime)
            and now - float(cached.get("at", 0.0) or 0.0) < 30.0
        ):
            return dict(cached.get("report") or {})
        yaml_data = yaml_data if isinstance(yaml_data, dict) else None
        if yaml_data is None:
            yaml_data, _yaml_dir = self._training_health_parse_data_yaml(data_yaml_path)
        class_names = self._training_eval_yaml_names(yaml_data or {})
        train_files = self._training_eval_yaml_image_files(data_yaml_path, yaml_data, "train")
        valid_files = self._training_eval_yaml_image_files(data_yaml_path, yaml_data, "val")
        report = self._training_eval_split_class_report(train_files, valid_files, class_names)
        cache[cache_key] = {"mtime": yaml_mtime, "at": now, "report": dict(report)}
        self._training_eval_yaml_split_report_cache = cache
        return report

    def _training_eval_train_val_split(self, image_files, valid_percent=None):
        image_files = [self.normalize_path(path) for path in image_files or [] if path]
        image_files = list(dict.fromkeys(image_files))
        if len(image_files) < 2:
            return image_files, []

        valid_percent = self._training_eval_valid_percent() if valid_percent is None else float(valid_percent)
        target_valid = int(round(len(image_files) * (valid_percent / 100.0)))
        target_valid = max(1, min(len(image_files) - 1, target_valid))

        image_classes = {path: self._training_eval_image_class_ids(path) for path in image_files}
        class_counts = Counter()
        for class_ids in image_classes.values():
            class_counts.update(class_ids)

        selected = []
        selected_set = set()
        selected_class_counts = Counter()

        def keeps_training_coverage(path):
            for class_id in image_classes.get(path, set()):
                if class_counts.get(class_id, 0) - selected_class_counts.get(class_id, 0) <= 1:
                    return False
            return True

        def add_image(path):
            if path in selected_set or len(selected) >= target_valid:
                return False
            if not keeps_training_coverage(path):
                return False
            selected.append(path)
            selected_set.add(path)
            selected_class_counts.update(image_classes.get(path, set()))
            return True

        by_rare_class = sorted(class_counts, key=lambda class_id: (class_counts[class_id], class_id))
        for class_id in by_rare_class:
            if class_counts[class_id] < 2:
                continue
            candidates = [
                path for path in image_files
                if path not in selected_set and class_id in image_classes.get(path, set())
            ]
            if not candidates:
                continue
            candidates = [
                path for path in candidates
                if keeps_training_coverage(path)
            ]
            if not candidates:
                continue
            candidates.sort(key=lambda path: (len(image_classes.get(path, set())), path))
            add_image(candidates[0])
            if len(selected) >= target_valid:
                break

        remaining = [
            path for path in image_files
            if path not in selected_set
            and keeps_training_coverage(path)
        ]
        random.Random(0).shuffle(remaining)
        for path in remaining:
            if len(selected) >= target_valid:
                break
            add_image(path)

        def remove_image(path):
            if path not in selected_set:
                return False
            selected_set.remove(path)
            try:
                selected.remove(path)
            except ValueError:
                pass
            for class_id in image_classes.get(path, set()):
                selected_class_counts[class_id] -= 1
                if selected_class_counts[class_id] <= 0:
                    selected_class_counts.pop(class_id, None)
            return True

        def can_remove_without_losing_valid_coverage(path):
            for class_id in image_classes.get(path, set()):
                if class_counts.get(class_id, 0) >= 2 and selected_class_counts.get(class_id, 0) <= 1:
                    return False
            return True

        feasible_classes = [class_id for class_id, count in class_counts.items() if count >= 2]
        for class_id in sorted(feasible_classes, key=lambda cid: (selected_class_counts.get(cid, 0), class_counts[cid], cid)):
            if selected_class_counts.get(class_id, 0) > 0:
                continue
            candidates = [
                path for path in image_files
                if path not in selected_set
                and class_id in image_classes.get(path, set())
                and keeps_training_coverage(path)
            ]
            if not candidates:
                continue
            candidates.sort(
                key=lambda path: (
                    -sum(1 for cid in image_classes.get(path, set()) if selected_class_counts.get(cid, 0) == 0 and class_counts.get(cid, 0) >= 2),
                    len(image_classes.get(path, set())),
                    path,
                )
            )
            if len(selected) < target_valid:
                add_image(candidates[0])
                continue
            removable = [
                path for path in selected
                if can_remove_without_losing_valid_coverage(path)
            ]
            removable.sort(
                key=lambda path: (
                    sum(1 for cid in image_classes.get(path, set()) if selected_class_counts.get(cid, 0) <= 1),
                    len(image_classes.get(path, set())),
                    path,
                )
            )
            if removable and remove_image(removable[0]):
                add_image(candidates[0])

        if not selected:
            fallback = [path for path in image_files if path not in selected_set]
            random.Random(0).shuffle(fallback)
            for path in fallback:
                if add_image(path):
                    break

        valid_set = set(selected)
        train_files = [path for path in image_files if path not in valid_set]
        valid_files = [path for path in image_files if path in valid_set]
        if not train_files:
            train_files, valid_files = image_files[:-1], image_files[-1:]
        return train_files, valid_files

    def _training_eval_percent_value(self, value, default=20.0, minimum=1.0, maximum=100.0):
        match = re.search(r"\d+(?:\.\d+)?", str(value or ""))
        try:
            percent = float(match.group(0)) if match else float(default)
        except Exception:
            percent = float(default)
        return max(float(minimum), min(float(maximum), percent))

    def _training_eval_validation_mode(self, value=None):
        mode = str(
            value
            if value is not None
            else self.settings.get("trainingEvaluatorValidationMode", "auto")
            if isinstance(getattr(self, "settings", None), dict)
            else "auto"
        ).strip().lower()
        aliases = {
            "auto split": "auto",
            "auto_split": "auto",
            "folder": "folder",
            "valid folder": "folder",
            "validation folder": "folder",
            "txt": "txt",
            "valid txt": "txt",
            "valid.txt": "txt",
            "train": "train",
            "train as val": "train",
            "train_as_val": "train",
        }
        return aliases.get(mode, mode if mode in {"auto", "folder", "txt", "train"} else "auto")

    def _training_eval_image_files_from_directory(self, directory):
        directory = self.normalize_path(directory or "")
        if not directory or not os.path.isdir(directory):
            return []
        image_exts = {str(ext).lower() for ext in IMAGE_SUFFIXES}
        files = []
        for root, _dirs, names in os.walk(directory):
            for name in names:
                if os.path.splitext(name)[1].lower() in image_exts:
                    files.append(self.normalize_path(os.path.join(root, name)))
        return sorted(dict.fromkeys(files))

    def _training_eval_read_image_list_file(self, list_path, dataset_dir=""):
        list_path = self.normalize_path(list_path or "")
        if not list_path or not os.path.isfile(list_path):
            return []
        image_exts = {str(ext).lower() for ext in IMAGE_SUFFIXES}
        list_dir = os.path.dirname(list_path)
        dataset_dir = self.normalize_path(dataset_dir or "")
        files = []
        try:
            with open(list_path, "r", encoding="utf-8", errors="ignore") as f:
                lines = list(f)
        except Exception:
            return []

        for line in lines:
            text = str(line or "").strip().strip('"').strip("'")
            if not text or text.startswith("#"):
                continue
            if os.path.isabs(text):
                candidate = self.normalize_path(text)
            else:
                candidate = ""
                for base in (list_dir, dataset_dir):
                    base = self.normalize_path(base or "")
                    if not base:
                        continue
                    possible = self.normalize_path(os.path.join(base, text))
                    if os.path.exists(possible):
                        candidate = possible
                        break
                if not candidate:
                    candidate = self.normalize_path(os.path.join(list_dir, text))
            if os.path.isfile(candidate) and os.path.splitext(candidate)[1].lower() in image_exts:
                files.append(candidate)
        return list(dict.fromkeys(files))

    def _training_eval_sample_images(self, image_files, percent=100.0, seed=0):
        image_files = [self.normalize_path(path) for path in image_files or [] if path]
        image_files = list(dict.fromkeys(image_files))
        if not image_files:
            return []
        percent = self._training_eval_percent_value(percent, default=100.0, minimum=1.0, maximum=100.0)
        if percent >= 99.5:
            return image_files
        count = int(round(len(image_files) * (percent / 100.0)))
        count = max(1, min(len(image_files), count))
        shuffled = list(image_files)
        random.Random(seed).shuffle(shuffled)
        selected = set(shuffled[:count])
        return [path for path in image_files if path in selected]

    def _training_eval_write_image_list(self, path, image_files):
        path = self.normalize_path(path or "")
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            for image_file in image_files or []:
                f.write(os.path.abspath(image_file).replace("\\", "/") + "\n")

    def _training_eval_prepare_validation_files(
        self,
        dataset_dir,
        output_dir,
        source_yaml_path="",
        validation_mode=None,
        validation_source="",
        validation_percent=None,
        validation_source_percent=None,
    ):
        dataset_dir = self.normalize_path(dataset_dir or "")
        source_yaml_path = self.normalize_path(source_yaml_path or "")
        source_yaml_data, source_yaml_dir = (
            self._training_health_parse_data_yaml(source_yaml_path)
            if source_yaml_path and os.path.exists(source_yaml_path)
            else ({}, "")
        )
        if source_yaml_path and not dataset_dir:
            dataset_dir = self._training_health_dataset_dir(source_yaml_path, source_yaml_data, source_yaml_dir)

        output_dir = self.normalize_path(output_dir or source_yaml_dir or dataset_dir)
        if not dataset_dir or not os.path.isdir(dataset_dir):
            raise ValueError("Open or select a dataset folder before preparing obj.yaml.")
        if not output_dir:
            output_dir = dataset_dir
        os.makedirs(output_dir, exist_ok=True)

        source_train_files = []
        source_valid_files = []
        image_files = []
        if source_yaml_path and os.path.exists(source_yaml_path):
            source_train_files = self._training_eval_yaml_image_files(source_yaml_path, source_yaml_data, "train")
            source_valid_files = self._training_eval_yaml_image_files(source_yaml_path, source_yaml_data, "val")
            image_files = list(source_train_files)
            if source_train_files:
                logger.info("Using training images from obj.yaml train list: %s", source_yaml_path)

        if not image_files:
            scanner = ScanAnnotations(self)
            scanner.base_directory = dataset_dir
            image_files = scanner._iter_image_files(dataset_dir)
        if not image_files:
            image_files = self._training_eval_image_files_from_directory(dataset_dir)
        image_files = [self.normalize_path(path) for path in image_files or [] if path]
        image_files = sorted(dict.fromkeys(image_files))
        if not image_files:
            raise ValueError("No dataset images were found for training YAML creation.")

        mode = self._training_eval_validation_mode(validation_mode)
        if source_valid_files:
            combined_files = sorted(dict.fromkeys(
                self.normalize_path(path)
                for path in [*source_train_files, *source_valid_files]
                if path
            ))
            if len(combined_files) > len(image_files):
                image_files = combined_files
                logger.info(
                    "Using obj.yaml train+val union as split source: %s image(s)",
                    len(image_files),
                )
        split_percent = self._training_eval_percent_value(
            validation_percent
            if validation_percent is not None
            else self.settings.get("trainingEvaluatorValidationPercent", self.settings.get("datasetValidPercent", "20%"))
            if isinstance(getattr(self, "settings", None), dict)
            else "20%",
            default=20.0,
            minimum=5.0,
            maximum=50.0,
        )
        source_percent = self._training_eval_percent_value(
            validation_source_percent
            if validation_source_percent is not None
            else self.settings.get("trainingEvaluatorValidationSourcePercent", "100%")
            if isinstance(getattr(self, "settings", None), dict)
            else "100%",
            default=100.0,
            minimum=1.0,
            maximum=100.0,
        )
        validation_source = self.normalize_path(
            validation_source
            or self.settings.get("trainingEvaluatorValidationSource", "")
            if isinstance(getattr(self, "settings", None), dict)
            else ""
        )

        note = ""
        if mode == "folder":
            valid_pool = self._training_eval_image_files_from_directory(validation_source)
            if not valid_pool:
                raise ValueError("Validation folder is empty or missing.")
            valid_files = self._training_eval_sample_images(valid_pool, source_percent, seed=1)
            excluded = set(valid_pool)
            train_files = [path for path in image_files if path not in excluded]
            note = f"Validation uses {len(valid_files)} image(s) from folder ({source_percent:g}% of folder)."
        elif mode == "txt":
            valid_pool = self._training_eval_read_image_list_file(validation_source, dataset_dir)
            if not valid_pool:
                raise ValueError("Validation TXT is empty or missing.")
            valid_files = self._training_eval_sample_images(valid_pool, source_percent, seed=1)
            excluded = set(valid_pool)
            train_files = [path for path in image_files if path not in excluded]
            note = f"Validation uses {len(valid_files)} image(s) from valid.txt ({source_percent:g}% of list)."
        elif mode == "train":
            train_files = list(image_files)
            valid_files = list(image_files)
            note = "Validation uses the training list. Metrics are for smoke-checking only."
        else:
            train_files, valid_files = self._training_eval_train_val_split(image_files, split_percent)
            if not valid_files:
                valid_files = list(train_files)
                note = "Dataset is too small for a holdout split; validation uses the training list."
            else:
                note = f"Validation auto-split uses {len(valid_files)} image(s) ({split_percent:g}%)."

        train_files = [path for path in train_files if path]
        valid_files = [path for path in valid_files if path]
        if not train_files:
            raise ValueError("Validation selection leaves no training images. Choose a smaller validation source.")
        if not valid_files:
            valid_files = list(train_files)

        class_names = self._training_eval_yaml_names(source_yaml_data)
        if not class_names:
            try:
                class_names = list(self.load_classes(data_directory=dataset_dir) or [])
            except Exception:
                class_names = []
        split_class_report = self._training_eval_split_class_report(train_files, valid_files, class_names)

        train_txt_path = os.path.join(output_dir, "train.txt").replace("\\", "/")
        valid_txt_path = os.path.join(output_dir, "valid.txt").replace("\\", "/")
        self._training_eval_write_image_list(train_txt_path, train_files)
        self._training_eval_write_image_list(valid_txt_path, valid_files)

        self.image_directory = dataset_dir
        self.images = image_files
        self.train_valid_output_directory = output_dir
        if isinstance(getattr(self, "settings", None), dict):
            self.settings["trainValidOutputDirectory"] = output_dir

        self.create_and_update_yaml_and_data_files(output_dir, "valid.txt", source_yaml_path=source_yaml_path)
        yaml_path = os.path.join(output_dir, "obj.yaml").replace("\\", "/")
        if not os.path.exists(yaml_path):
            raise ValueError(f"Training YAML was not created:\n{yaml_path}")

        return {
            "yaml_path": self.normalize_path(yaml_path),
            "train_txt_path": self.normalize_path(train_txt_path),
            "valid_txt_path": self.normalize_path(valid_txt_path),
            "train_count": len(train_files),
            "valid_count": len(valid_files),
            "source_count": len(image_files),
            "validation_mode": mode,
            "validation_note": note,
            "split_class_report": split_class_report,
        }

    def ensure_training_evaluator_data_yaml(
        self,
        force=False,
        prepare_validation=False,
        validation_mode=None,
        validation_source="",
        validation_percent=None,
        validation_source_percent=None,
    ):
        self._training_eval_last_validation_prep = {}
        existing_yaml = self.normalize_path(getattr(self, "data_yaml_path", "") or "")
        existing_yaml_data, existing_yaml_dir = (
            self._training_health_parse_data_yaml(existing_yaml)
            if existing_yaml and os.path.exists(existing_yaml)
            else ({}, "")
        )
        if existing_yaml and os.path.exists(existing_yaml) and not prepare_validation:
            refreshed_yaml = self._training_eval_refresh_stale_data_yaml(existing_yaml)
            if refreshed_yaml:
                return refreshed_yaml
            return existing_yaml

        dataset_dir = ""
        if existing_yaml and os.path.exists(existing_yaml):
            dataset_dir = self._training_health_dataset_dir(existing_yaml, existing_yaml_data, existing_yaml_dir)
        if not dataset_dir:
            dataset_dir = self._training_eval_dataset_dir()
        if not dataset_dir:
            raise ValueError("Open or select a dataset folder before preparing training YAML.")

        obj_yaml = self._training_eval_find_obj_yaml(dataset_dir)
        if obj_yaml and not prepare_validation:
            refreshed_yaml = self._training_eval_refresh_stale_data_yaml(obj_yaml)
            if refreshed_yaml:
                return refreshed_yaml
            self._set_training_data_yaml_path(obj_yaml)
            self.queue_settings_save()
            return obj_yaml
        source_yaml_path = existing_yaml if existing_yaml and os.path.exists(existing_yaml) else obj_yaml

        scanner = ScanAnnotations(self)
        scanner.base_directory = dataset_dir
        image_files = []
        if source_yaml_path and os.path.exists(source_yaml_path):
            source_yaml_data, _source_yaml_dir = self._training_health_parse_data_yaml(source_yaml_path)
            image_files = self._training_eval_yaml_image_files(source_yaml_path, source_yaml_data, "train")
        if not image_files:
            image_files = scanner._iter_image_files(dataset_dir)
        if not image_files:
            image_files = self._training_eval_image_files_from_directory(dataset_dir)
        if not image_files:
            raise ValueError("No dataset images were found for training YAML creation.")

        output_dir = getattr(self, "train_valid_output_directory", "")
        if not output_dir and isinstance(getattr(self, "settings", None), dict):
            output_dir = self.settings.get("trainValidOutputDirectory", "")
        output_dir = self.normalize_path(output_dir)
        if not output_dir and source_yaml_path:
            output_dir = os.path.dirname(source_yaml_path)
        if not output_dir:
            output_dir = dataset_dir
        output_dir = self.normalize_path(output_dir)
        os.makedirs(output_dir, exist_ok=True)

        train_txt_path = os.path.join(output_dir, "train.txt").replace("\\", "/")
        valid_txt_path = os.path.join(output_dir, "valid.txt").replace("\\", "/")
        if not os.path.exists(train_txt_path) or force:
            with open(train_txt_path, "w", encoding="utf-8") as f:
                for image_file in image_files:
                    f.write(os.path.abspath(image_file).replace("\\", "/") + "\n")

        self.image_directory = dataset_dir
        self.images = image_files
        self.train_valid_output_directory = output_dir
        if isinstance(getattr(self, "settings", None), dict):
            self.settings["trainValidOutputDirectory"] = output_dir

        if prepare_validation:
            prep = self._training_eval_prepare_validation_files(
                dataset_dir,
                output_dir,
                source_yaml_path=source_yaml_path,
                validation_mode=validation_mode,
                validation_source=validation_source,
                validation_percent=validation_percent,
                validation_source_percent=validation_source_percent,
            )
            self._training_eval_last_validation_prep = prep
            yaml_path = prep.get("yaml_path", "")
            self._set_training_data_yaml_path(yaml_path)
            self.queue_settings_save()
            return yaml_path

        selected_option = "valid.txt" if os.path.exists(valid_txt_path) else "train.txt"
        self.create_and_update_yaml_and_data_files(output_dir, selected_option, source_yaml_path=source_yaml_path)

        yaml_path = os.path.join(output_dir, "obj.yaml").replace("\\", "/")
        if not os.path.exists(yaml_path):
            raise ValueError(f"Training YAML was not created:\n{yaml_path}")

        self._set_training_data_yaml_path(yaml_path)
        self.queue_settings_save()
        return yaml_path

    def _selected_training_weights_path(self):
        for path in (
            getattr(self, "pt_path", None),
            getattr(self, "pretrained_model_path", None),
            getattr(self, "export_model_path", None),
            getattr(self, "model_config_path", None),
        ):
            if path and os.path.exists(path):
                return self.normalize_path(path)
        return ""

    def _effective_eval_weights_path(self, use_training_weights=True, eval_path=""):
        if use_training_weights:
            return self._selected_training_weights_path()
        eval_path = self.normalize_path(eval_path)
        return eval_path if eval_path and os.path.exists(eval_path) else ""

    def inspect_training_eval_weights(self, weights_path):
        info = {
            "path": self.normalize_path(weights_path) if weights_path else "",
            "name": os.path.basename(weights_path) if weights_path else "No weights loaded",
            "task": "",
            "class_count": 0,
            "strides": [8, 16, 32],
            "loaded": False,
            "error": "",
            "model_factor": 1.0,
        }

        name = info["name"].lower()
        if re.search(r"(^|[^a-z])n([^a-z]|$)|nano", name):
            info["model_factor"] = 0.65
        elif re.search(r"(^|[^a-z])s([^a-z]|$)|small", name):
            info["model_factor"] = 0.85
        elif re.search(r"(^|[^a-z])m([^a-z]|$)|medium", name):
            info["model_factor"] = 1.15
        elif re.search(r"(^|[^a-z])l([^a-z]|$)|large", name):
            info["model_factor"] = 1.55
        elif re.search(r"(^|[^a-z])x([^a-z]|$)|xlarge", name):
            info["model_factor"] = 2.1

        if not weights_path:
            info["error"] = "No eval weights selected; using default YOLO stride estimate."
            return info

        if not os.path.exists(weights_path):
            info["error"] = "Eval weights path does not exist."
            return info

        try:
            model = YOLO(weights_path)
            info["loaded"] = True
            info["task"] = str(getattr(model, "task", "") or "")
            model_names = getattr(model, "names", None)
            if isinstance(model_names, (dict, list, tuple)):
                info["class_count"] = len(model_names)

            raw_stride = getattr(getattr(model, "model", None), "stride", None)
            if raw_stride is not None:
                if hasattr(raw_stride, "detach"):
                    raw_stride = raw_stride.detach().cpu().numpy()
                elif hasattr(raw_stride, "cpu"):
                    raw_stride = raw_stride.cpu().numpy()

                strides = np.asarray(raw_stride, dtype=float).reshape(-1).tolist()
                strides = sorted({int(round(value)) for value in strides if value > 0})
                if strides:
                    info["strides"] = strides

            del model
            if torch.cuda.is_available():
                try:
                    torch.cuda.empty_cache()
                except Exception:
                    pass
        except Exception as e:
            info["error"] = f"Could not inspect weights: {e}"

        return info

    def training_eval_task_from_weights(self, weights_path):
        weights_path = self.normalize_path(weights_path or "")
        info = self.inspect_training_eval_weights(weights_path)
        raw_task = str(info.get("task", "") or "").strip().lower()
        aliases = {
            "detect": "detect",
            "detection": "detect",
            "segment": "segment",
            "seg": "segment",
            "segmentation": "segment",
            "classify": "classify",
            "classification": "classify",
            "pose": "pose",
            "keypoint": "pose",
            "keypoints": "pose",
            "obb": "obb",
        }
        task = aliases.get(raw_task, "")
        source = "model metadata" if task else ""

        if not task:
            name = os.path.basename(weights_path).lower()
            if re.search(r"(?:^|[-_.])(?:seg|segment)(?:[-_.]|$)", name):
                task = "segment"
            elif re.search(r"(?:^|[-_.])(?:pose|keypoint|keypoints)(?:[-_.]|$)", name):
                task = "pose"
            elif re.search(r"(?:^|[-_.])obb(?:[-_.]|$)", name):
                task = "obb"
            elif re.search(r"(?:^|[-_.])(?:cls|classify|classification)(?:[-_.]|$)", name):
                task = "classify"
            elif weights_path.lower().endswith((".pt", ".yaml", ".yml")):
                task = "detect"
            if task:
                source = "filename fallback"

        return task, source, info

    def _training_eval_candidate_sizes(self, text, current_size):
        values = []
        for match in re.findall(r"\d+", str(text or "")):
            try:
                values.append(snap_int_to_multiple(int(match), 32, minimum=160, maximum=2048))
            except Exception:
                pass
        if current_size:
            values.append(snap_int_to_multiple(current_size, 32, minimum=160, maximum=2048))
        return sorted(dict.fromkeys(values or [320, 416, 512, 640, 832]))

    def _letterbox_preview_params(self, width, height, target_width, target_height):
        if width <= 0 or height <= 0 or target_width <= 0 or target_height <= 0:
            return 1.0, 0, 0, target_width, target_height

        scale = min(target_width / width, target_height / height)
        new_width = int(round(width * scale))
        new_height = int(round(height * scale))
        pad_x = target_width - new_width
        pad_y = target_height - new_height
        left = int(round(pad_x / 2 - 0.1))
        top = int(round(pad_y / 2 - 0.1))
        return scale, left, top, new_width, new_height

    def _train_eval_label_extent(self, bbox):
        if bbox is None:
            return None

        if getattr(bbox, "segmentation", None):
            pts = bbox.segmentation
            xs = pts[0::2]
            ys = pts[1::2]
        elif getattr(bbox, "obb", None):
            pts = bbox.obb
            xs = pts[0::2]
            ys = pts[1::2]
        else:
            return (
                float(bbox.x_center),
                float(bbox.y_center),
                float(bbox.width),
                float(bbox.height),
            )

        if not xs or not ys:
            return None

        left = max(0.0, min(xs))
        right = min(1.0, max(xs))
        top = max(0.0, min(ys))
        bottom = min(1.0, max(ys))
        width = max(0.0, right - left)
        height = max(0.0, bottom - top)
        return ((left + right) / 2.0, (top + bottom) / 2.0, width, height)

    def _parse_training_eval_bbox(self, line, polygon_preference=None, expected_keypoints=None):
        previous_expected = getattr(BoundingBox, "EXPECTED_KEYPOINT_COUNT", None)
        BoundingBox.EXPECTED_KEYPOINT_COUNT = expected_keypoints or None
        try:
            return BoundingBox.from_str(line, preferred_polygon_type=polygon_preference)
        finally:
            BoundingBox.EXPECTED_KEYPOINT_COUNT = previous_expected

    def _gpu_vram_gb(self):
        if not torch.cuda.is_available():
            return 0.0
        try:
            return float(torch.cuda.get_device_properties(0).total_memory) / (1024 ** 3)
        except Exception:
            try:
                gpus = GPUtil.getGPUs()
                return float(gpus[0].memoryTotal) / 1024.0 if gpus else 0.0
            except Exception:
                return 0.0

    def _looks_like_official_ultralytics_weight(self, weights_path):
        name = os.path.basename(str(weights_path or "")).lower()
        stem = os.path.splitext(name)[0]
        return bool(re.match(r"^yolo(?:v?\d+)?(?:[nslmx])?(?:[-_][a-z0-9]+)*$", stem))

    def recommend_training_optimizer_args(self, total_labels, recommended_row, imbalance_ratio, weight_info, weights_path, task_text):
        weights_path = self.normalize_path(weights_path or "")
        custom_weights = bool(weights_path and not self._looks_like_official_ultralytics_weight(weights_path))
        task_text = str(task_text or "").strip().lower() or "detect"
        total_labels = int(total_labels or 0)
        imbalance_ratio = float(imbalance_ratio or 1.0)
        under_2stride = float((recommended_row or {}).get("under_2stride_pct", 0.0) or 0.0)
        under_stride = float((recommended_row or {}).get("under_stride_pct", 0.0) or 0.0)
        imgsz = int((recommended_row or {}).get("imgsz", 640) or 640)

        if custom_weights:
            optimizer = "AdamW" if total_labels < 1200 or imbalance_ratio >= 8 else "SGD"
            lr0 = 0.0008 if optimizer == "AdamW" else 0.0015
            reason = "fine-tuning custom/previously trained weights"
            warmup_epochs = 2.0
            freeze = 10 if total_labels < 2500 and task_text in {"detect", "segment", "pose", "obb"} else 0
        elif weights_path:
            optimizer = "SGD"
            lr0 = 0.005 if total_labels < 800 else 0.01
            reason = "training from a base/pretrained Ultralytics weight"
            warmup_epochs = 3.0
            freeze = 0
        else:
            optimizer = "SGD"
            lr0 = 0.01
            reason = "training without inspected weights; using conservative base defaults"
            warmup_epochs = 3.0
            freeze = 0

        if total_labels < 300:
            lr0 *= 0.6
            warmup_epochs = max(warmup_epochs, 4.0)
            if custom_weights and task_text in {"detect", "segment", "pose", "obb"}:
                freeze = max(freeze, 15)
        elif total_labels < 1000 and custom_weights:
            lr0 *= 0.8

        if under_stride > 10 or under_2stride > 35:
            lr0 *= 0.75
            freeze = 0

        if imgsz >= 832:
            lr0 *= 0.8

        if task_text in {"pose", "obb"} and custom_weights:
            lr0 *= 0.85
            freeze = min(freeze, 10)

        lr0 = max(0.00015, min(0.012, lr0))
        lrf = 0.01
        close_mosaic = 0 if task_text == "classify" else 10
        momentum = 0.937
        weight_decay = 0.0005
        warmup_momentum = 0.8
        warmup_bias_lr = 0.05 if custom_weights else 0.1

        def fmt(value):
            if isinstance(value, bool):
                return "True" if value else "False"
            if isinstance(value, float):
                return f"{value:.6g}"
            return str(value)

        hyperparams = OrderedDict([
            ("optimizer", optimizer),
            ("lr0", round(float(lr0), 6)),
            ("lrf", lrf),
            ("cos_lr", True),
            ("momentum", momentum),
            ("weight_decay", weight_decay),
            ("warmup_epochs", round(float(warmup_epochs), 2)),
            ("warmup_momentum", warmup_momentum),
            ("warmup_bias_lr", warmup_bias_lr),
            ("close_mosaic", close_mosaic),
        ])
        train_args = [f"{key}={fmt(value)}" for key, value in hyperparams.items()]
        return {
            "hyperparams": dict(hyperparams),
            "train_args": train_args,
            "train_args_text": " ".join(train_args),
            "optimizer_reason": reason,
            "freeze": int(freeze),
            "batch_note": "CUDA detected: computed batch is conservative; batch=-1 can let Ultralytics auto-tune VRAM if you want to probe maximum batch." if torch.cuda.is_available() else "CPU/no CUDA detected: keep batch conservative.",
        }

    def _write_training_recommendation_yaml(self, result):
        rec = (result or {}).get("recommendations", {})
        yaml_path = self.normalize_path(rec.get("data_yaml_path", "") or result.get("data_yaml_path", ""))
        if not yaml_path:
            return ""

        output_dir = os.path.dirname(yaml_path)
        if not output_dir:
            return ""

        payload = {
            "generated_by": "DarkFusion Training Evaluator",
            "generated_at": datetime.now().isoformat(timespec="seconds"),
            "data": yaml_path,
            "task": rec.get("task", "detect"),
            "model": rec.get("weights_path", ""),
            "imgsz": rec.get("imgsz"),
            "batch": rec.get("batch"),
            "epochs": rec.get("epochs"),
            "patience": rec.get("patience"),
            "amp": rec.get("amp"),
            "rect": rec.get("rect"),
            "freeze": rec.get("freeze", 0),
            "train_args": rec.get("train_args", []),
            "hyperparams": rec.get("hyperparams", {}),
            "reason": rec.get("optimizer_reason", ""),
            "size_note": rec.get("size_note", ""),
            "class_risk": (result or {}).get("class_risk_rows", []),
            "split_class_report": (result or {}).get("split_class_report", {}),
            "tune_best_path": (result or {}).get("tune_best_path", ""),
            "tune_best_hyperparameters": (result or {}).get("tune_best_hyperparameters", {}),
            "batch_calibration": (result or {}).get("batch_calibration", {}),
            "batch_calibration_path": (result or {}).get("batch_calibration_path", ""),
        }
        output_path = os.path.join(output_dir, "train_recommendations.yaml").replace("\\", "/")
        try:
            with open(output_path, "w", encoding="utf-8") as f:
                yaml.safe_dump(payload, f, sort_keys=False)
            return output_path
        except Exception as e:
            logger.warning(f"Could not write training recommendation YAML: {e}")
            return ""

    def _training_eval_format_arg_value(self, value):
        if isinstance(value, bool):
            return "True" if value else "False"
        if isinstance(value, float):
            return f"{value:.6g}"
        return str(value)

    def _training_eval_rebuild_train_args(self, recommendations):
        hyperparams = OrderedDict((recommendations or {}).get("hyperparams", {}) or {})
        train_args = [
            f"{key}={self._training_eval_format_arg_value(value)}"
            for key, value in hyperparams.items()
        ]
        recommendations["train_args"] = train_args
        recommendations["train_args_text"] = " ".join(train_args)

    def _training_eval_command_value(self, command, key):
        prefix = f"{key}="
        for part in command or []:
            text = str(part)
            if text.startswith(prefix):
                return text[len(prefix):]
        return ""

    def _training_eval_option_value(self, command, option):
        option = str(option)
        for index, part in enumerate(command or []):
            text = str(part)
            if text == option and index + 1 < len(command):
                return str(command[index + 1])
            if text.startswith(option + "="):
                return text.split("=", 1)[1]
        return ""

    def _training_eval_tune_dir_from_command(self, command):
        project_dir = self._training_eval_command_value(command, "project")
        run_name = self._training_eval_command_value(command, "name")
        if project_dir and run_name:
            return self.normalize_path(os.path.join(project_dir, run_name))
        return ""

    def _training_eval_model_factor_from_path(self, model_path=""):
        name = os.path.splitext(os.path.basename(str(model_path or "")))[0].lower()
        if not name:
            return 1.0
        if re.search(r"(^|[^a-z])x([^a-z]|$)|xlarge", name):
            return 2.1
        if re.search(r"(^|[^a-z])l([^a-z]|$)|large", name):
            return 1.55
        if re.search(r"(^|[^a-z])m([^a-z]|$)|medium", name):
            return 1.15
        if re.search(r"(^|[^a-z])s([^a-z]|$)|small", name):
            return 0.85
        if re.search(r"(^|[^a-z])n([^a-z]|$)|nano", name):
            return 0.65
        return 1.0

    def _training_eval_safe_batch_cap(self, dataset_size=0, model_factor=1.0):
        try:
            model_factor = float(model_factor or 1.0)
        except Exception:
            model_factor = 1.0

        if model_factor >= 2.0:
            max_batch = 8
        elif model_factor >= 1.5:
            max_batch = 16
        else:
            max_batch = 24

        if not torch.cuda.is_available():
            max_batch = min(max_batch, 4)

        try:
            dataset_size = int(dataset_size or 0)
        except Exception:
            dataset_size = 0
        if dataset_size > 0:
            if dataset_size >= 4:
                max_batch = min(max_batch, max(1, dataset_size // 4))
            else:
                max_batch = min(max_batch, dataset_size)
        return max(1, int(max_batch))

    def _training_eval_clamp_batch(self, batch, dataset_size=0, model_factor=1.0):
        try:
            batch = int(float(str(batch).strip()))
        except Exception:
            batch = 4
        batch = max(1, batch)
        return min(batch, self._training_eval_safe_batch_cap(dataset_size, model_factor))

    def _training_eval_setting_bool(self, key, default=False):
        if not isinstance(getattr(self, "settings", None), dict):
            return bool(default)
        return bool(self.settings.get(key, default))

    def _training_eval_setting_int(self, key, default=0, minimum=None, maximum=None):
        value = self.settings.get(key, default) if isinstance(getattr(self, "settings", None), dict) else default
        try:
            value = int(float(str(value).strip()))
        except Exception:
            value = int(default)
        if minimum is not None:
            value = max(int(minimum), value)
        if maximum is not None:
            value = min(int(maximum), value)
        return value

    def _training_eval_effective_batch(self, rec, dataset_size=0, model_factor=1.0):
        if self._training_eval_setting_bool("trainingEvaluatorBatchOverrideEnabled", False):
            requested = self._training_eval_setting_int("trainingEvaluatorBatchOverride", 8, minimum=1, maximum=512)
        else:
            requested = (rec or {}).get(
                "batch",
                getattr(self, "batch_input", None).text() if getattr(self, "batch_input", None) is not None else 4,
            )
        return self._training_eval_clamp_batch(requested, dataset_size, model_factor)

    def _training_eval_effective_validation_batch(self, rec, dataset_size=0, model_factor=1.0):
        # Validation is often used as a quick safety check; keep it much gentler than training.
        return min(self._training_eval_effective_batch(rec, dataset_size, model_factor), 1)

    def _training_eval_cache_arg(self):
        mode = str(
            self.settings.get("trainingEvaluatorCacheMode", "off")
            if isinstance(getattr(self, "settings", None), dict)
            else "off"
        ).strip().lower()
        if mode in {"ram", "memory", "true", "on", "1"}:
            return "cache=ram"
        if mode in {"disk", "ssd"}:
            return "cache=disk"
        return "cache=False"

    def _training_eval_workers_arg(self):
        if self._training_eval_setting_bool("trainingEvaluatorWorkersOverrideEnabled", False):
            workers = self._training_eval_setting_int("trainingEvaluatorWorkersOverride", 0, minimum=0, maximum=32)
        else:
            workers = 0 if sys.platform.startswith("win") else 2
        return f"workers={workers}"

    def _append_ultralytics_memory_guard_args(self, command, use_evaluator_overrides=True):
        keys = {
            str(part).split("=", 1)[0].strip().lower()
            for part in command or []
            if "=" in str(part)
        }
        if "workers" not in keys:
            command.append(self._training_eval_workers_arg() if use_evaluator_overrides else ("workers=0" if sys.platform.startswith("win") else "workers=2"))
        if "cache" not in keys:
            command.append(self._training_eval_cache_arg() if use_evaluator_overrides else "cache=False")
        return command

    def _training_yaml_image_count(self, data_yaml_path):
        data_yaml_path = self.normalize_path(data_yaml_path)
        if not data_yaml_path or not os.path.exists(data_yaml_path):
            return 0

        image_exts = {".jpg", ".jpeg", ".png", ".bmp", ".webp", ".tif", ".tiff"}

        def resolve(value, base_dir):
            value = str(value or "").strip()
            if not value:
                return ""
            return self.normalize_path(value if os.path.isabs(value) else os.path.join(base_dir, value))

        try:
            with open(data_yaml_path, "r", encoding="utf-8", errors="ignore") as f:
                data = yaml.safe_load(f) or {}
        except Exception:
            return 0

        yaml_dir = os.path.dirname(data_yaml_path)
        entries = data.get("train")
        entries = entries if isinstance(entries, list) else [entries]
        count = 0
        for entry in entries:
            path = resolve(entry, yaml_dir)
            if not path:
                continue
            if os.path.isfile(path) and path.lower().endswith(".txt"):
                try:
                    with open(path, "r", encoding="utf-8", errors="ignore") as f:
                        count += sum(1 for line in f if line.strip())
                except Exception:
                    continue
            elif os.path.isdir(path):
                for _root, _dirs, files in os.walk(path):
                    count += sum(1 for name in files if os.path.splitext(name)[1].lower() in image_exts)
            elif os.path.isfile(path) and os.path.splitext(path)[1].lower() in image_exts:
                count += 1
        return count

    def _training_eval_yaml_names(self, yaml_data):
        names = (yaml_data or {}).get("names") if isinstance(yaml_data, dict) else None
        if isinstance(names, dict):
            def sort_key(item):
                key = item[0]
                try:
                    return int(key)
                except Exception:
                    return str(key)
            return [str(value) for _key, value in sorted(names.items(), key=sort_key)]
        if isinstance(names, (list, tuple)):
            return [str(value) for value in names]
        return []

    def _training_eval_yaml_image_files(self, data_yaml_path, yaml_data=None, split="train"):
        data_yaml_path = self.normalize_path(data_yaml_path)
        if not data_yaml_path or not os.path.exists(data_yaml_path):
            return []

        yaml_data = yaml_data if isinstance(yaml_data, dict) else None
        yaml_dir = os.path.dirname(data_yaml_path)
        if yaml_data is None:
            try:
                with open(data_yaml_path, "r", encoding="utf-8", errors="ignore") as f:
                    yaml_data = yaml.safe_load(f) or {}
            except Exception:
                yaml_data = {}

        image_exts = {str(ext).lower() for ext in IMAGE_SUFFIXES}
        dataset_root = self.normalize_path((yaml_data or {}).get("path", "") or "")
        if dataset_root and not os.path.isabs(dataset_root):
            dataset_root = self.normalize_path(os.path.join(yaml_dir, dataset_root))
        if not dataset_root:
            dataset_root = yaml_dir

        def resolve_path(value, base_dir=None):
            value = str(value or "").strip().strip('"').strip("'")
            if not value:
                return ""
            if os.path.isabs(value):
                return self.normalize_path(value)
            for base in (base_dir, dataset_root, yaml_dir):
                base = self.normalize_path(base or "")
                if not base:
                    continue
                candidate = self.normalize_path(os.path.join(base, value))
                if os.path.exists(candidate):
                    return candidate
            return self.normalize_path(os.path.join(dataset_root, value))

        def collect_from_entry(entry, base_dir=None):
            path = resolve_path(entry, base_dir)
            if not path:
                return []
            ext = os.path.splitext(path)[1].lower()
            if os.path.isfile(path) and ext == ".txt":
                files = []
                list_dir = os.path.dirname(path)
                try:
                    with open(path, "r", encoding="utf-8", errors="ignore") as f:
                        for line in f:
                            resolved = resolve_path(line, list_dir)
                            if resolved and os.path.isfile(resolved) and os.path.splitext(resolved)[1].lower() in image_exts:
                                files.append(resolved)
                except Exception:
                    return []
                return files
            if os.path.isdir(path):
                files = []
                for root, _dirs, names in os.walk(path):
                    for name in names:
                        if os.path.splitext(name)[1].lower() in image_exts:
                            files.append(self.normalize_path(os.path.join(root, name)))
                return files
            if os.path.isfile(path) and ext in image_exts:
                return [path]
            return []

        entries = (yaml_data or {}).get(split)
        entries = entries if isinstance(entries, list) else [entries]
        files = []
        for entry in entries:
            files.extend(collect_from_entry(entry))
        return sorted(dict.fromkeys(path for path in files if path))

    def _training_eval_yaml_names(self, yaml_data):
        names = (yaml_data or {}).get("names") if isinstance(yaml_data, dict) else None
        if isinstance(names, dict):
            def sort_key(item):
                key = item[0]
                try:
                    return int(key)
                except Exception:
                    return str(key)
            return [str(value) for _key, value in sorted(names.items(), key=sort_key)]
        if isinstance(names, (list, tuple)):
            return [str(value) for value in names]
        return []

    def _training_eval_yaml_image_files(self, data_yaml_path, yaml_data=None, split="train"):
        data_yaml_path = self.normalize_path(data_yaml_path)
        if not data_yaml_path or not os.path.exists(data_yaml_path):
            return []

        yaml_data = yaml_data if isinstance(yaml_data, dict) else None
        yaml_dir = os.path.dirname(data_yaml_path)
        if yaml_data is None:
            try:
                with open(data_yaml_path, "r", encoding="utf-8", errors="ignore") as f:
                    yaml_data = yaml.safe_load(f) or {}
            except Exception:
                yaml_data = {}

        image_exts = {str(ext).lower() for ext in IMAGE_SUFFIXES}
        dataset_root = self.normalize_path((yaml_data or {}).get("path", "") or "")
        if dataset_root and not os.path.isabs(dataset_root):
            dataset_root = self.normalize_path(os.path.join(yaml_dir, dataset_root))
        if not dataset_root:
            dataset_root = yaml_dir

        def resolve_path(value, base_dir=None):
            value = str(value or "").strip().strip('"').strip("'")
            if not value:
                return ""
            if os.path.isabs(value):
                return self.normalize_path(value)
            for base in (base_dir, dataset_root, yaml_dir):
                base = self.normalize_path(base or "")
                if not base:
                    continue
                candidate = self.normalize_path(os.path.join(base, value))
                if os.path.exists(candidate):
                    return candidate
            return self.normalize_path(os.path.join(dataset_root, value))

        def collect_from_entry(entry, base_dir=None):
            path = resolve_path(entry, base_dir)
            if not path:
                return []
            ext = os.path.splitext(path)[1].lower()
            if os.path.isfile(path) and ext == ".txt":
                files = []
                list_dir = os.path.dirname(path)
                try:
                    with open(path, "r", encoding="utf-8", errors="ignore") as f:
                        for line in f:
                            resolved = resolve_path(line, list_dir)
                            if resolved and os.path.isfile(resolved) and os.path.splitext(resolved)[1].lower() in image_exts:
                                files.append(resolved)
                except Exception:
                    return []
                return files
            if os.path.isdir(path):
                files = []
                for root, _dirs, names in os.walk(path):
                    for name in names:
                        if os.path.splitext(name)[1].lower() in image_exts:
                            files.append(self.normalize_path(os.path.join(root, name)))
                return files
            if os.path.isfile(path) and ext in image_exts:
                return [path]
            return []

        entries = (yaml_data or {}).get(split)
        entries = entries if isinstance(entries, list) else [entries]
        files = []
        for entry in entries:
            files.extend(collect_from_entry(entry))
        return sorted(dict.fromkeys(path for path in files if path))

    def _training_eval_data_yaml_needs_auto_refresh(self, data_yaml_path):
        data_yaml_path = self.normalize_path(data_yaml_path or "")
        if not data_yaml_path or not os.path.exists(data_yaml_path):
            return False
        if os.path.basename(data_yaml_path).lower() != "obj.yaml":
            return False
        settings = getattr(self, "settings", {}) if isinstance(getattr(self, "settings", None), dict) else {}
        if not bool(settings.get("trainingEvaluatorAutoYaml", True)):
            return False
        if self._training_eval_validation_mode() == "train":
            return False

        yaml_data, _yaml_dir = self._training_health_parse_data_yaml(data_yaml_path)
        if not isinstance(yaml_data, dict) or not yaml_data:
            return False

        train_entry = yaml_data.get("train")
        val_entry = yaml_data.get("val")
        if not train_entry:
            return False
        if not val_entry:
            return True
        if str(train_entry).strip().strip('"').strip("'") == str(val_entry).strip().strip('"').strip("'"):
            return True

        train_files = self._training_eval_yaml_image_files(data_yaml_path, yaml_data, "train")
        val_files = self._training_eval_yaml_image_files(data_yaml_path, yaml_data, "val")
        if not val_files:
            return True
        if train_files and set(train_files) == set(val_files):
            return True
        return False

    def _training_eval_refresh_data_yaml_split(
        self,
        data_yaml_path,
        validation_mode=None,
        validation_source="",
        validation_percent=None,
        validation_source_percent=None,
    ):
        data_yaml_path = self.normalize_path(data_yaml_path or "")
        if not data_yaml_path or not os.path.exists(data_yaml_path):
            raise ValueError("Selected obj.yaml does not exist.")

        yaml_data, yaml_dir = self._training_health_parse_data_yaml(data_yaml_path)
        dataset_dir = self._training_health_dataset_dir(data_yaml_path, yaml_data, yaml_dir)
        if not dataset_dir:
            dataset_dir = self._training_eval_dataset_dir()
        if not dataset_dir:
            raise ValueError("Could not resolve the dataset folder from obj.yaml.")

        output_dir = yaml_dir if yaml_dir and os.path.isdir(yaml_dir) else dataset_dir
        prep = self._training_eval_prepare_validation_files(
            dataset_dir,
            output_dir,
            source_yaml_path=data_yaml_path,
            validation_mode=validation_mode,
            validation_source=validation_source,
            validation_percent=validation_percent,
            validation_source_percent=validation_source_percent,
        )
        yaml_path = prep.get("yaml_path", "")
        if yaml_path:
            self._training_eval_last_validation_prep = prep
            self._set_training_data_yaml_path(yaml_path)
            self.queue_settings_save()
            logger.info("Auto-refreshed obj.yaml validation split: %s", yaml_path)
        return yaml_path

    def _training_eval_refresh_stale_data_yaml(self, data_yaml_path):
        if not self._training_eval_data_yaml_needs_auto_refresh(data_yaml_path):
            return ""
        return self._training_eval_refresh_data_yaml_split(
            data_yaml_path,
            validation_mode=self.settings.get("trainingEvaluatorValidationMode", "auto")
            if isinstance(getattr(self, "settings", None), dict)
            else "auto",
            validation_source=self.settings.get("trainingEvaluatorValidationSource", "")
            if isinstance(getattr(self, "settings", None), dict)
            else "",
            validation_percent=self.settings.get("trainingEvaluatorValidationPercent", "20%")
            if isinstance(getattr(self, "settings", None), dict)
            else "20%",
            validation_source_percent=self.settings.get("trainingEvaluatorValidationSourcePercent", "100%")
            if isinstance(getattr(self, "settings", None), dict)
            else "100%",
        )

    def read_training_tune_best_hyperparameters(self, tune_dir):
        tune_dir = self.normalize_path(tune_dir)
        if not tune_dir:
            return {}, ""

        candidates = [
            os.path.join(tune_dir, "best_hyperparameters.yaml"),
            os.path.join(tune_dir, "best_hyperparameters.yml"),
        ]
        for path in candidates:
            path = self.normalize_path(path)
            if not os.path.exists(path):
                continue
            try:
                with open(path, "r", encoding="utf-8") as f:
                    data = yaml.safe_load(f) or {}
                if isinstance(data, dict):
                    cleaned = {
                        str(key): value
                        for key, value in data.items()
                        if not str(key).strip().startswith("#")
                    }
                    return cleaned, path
            except Exception as e:
                logger.warning(f"Could not read tune hyperparameters from {path}: {e}")
        return {}, ""

    def apply_training_tune_best_hyperparameters(self, result, best_hyperparams, source_path=""):
        if not result or not isinstance(best_hyperparams, dict) or not best_hyperparams:
            return False

        rec = result.get("recommendations", {})
        current = OrderedDict(rec.get("hyperparams", {}) or {})
        blocked = {
            "data",
            "model",
            "imgsz",
            "epochs",
            "batch",
            "project",
            "name",
            "amp",
            "rect",
            "resume",
            "freeze",
            "patience",
        }
        for key, value in best_hyperparams.items():
            key = str(key).strip()
            if not key or key.lower() in blocked:
                continue
            current[key] = value
        rec["hyperparams"] = dict(current)
        self._training_eval_rebuild_train_args(rec)
        rec["optimizer_reason"] = f"Ultralytics tuner best hyperparameters loaded from {source_path or 'best_hyperparameters.yaml'}"
        result["tune_best_hyperparameters"] = dict(best_hyperparams)
        result["tune_best_path"] = source_path
        result["training_recommendations_yaml"] = self._write_training_recommendation_yaml(result)
        if isinstance(getattr(self, "settings", None), dict):
            self.settings["trainingEvaluatorUseOptimizedArgs"] = True
        self.training_evaluator_last_result = result
        self.apply_training_evaluation_recommendations(result, apply_weights=False, apply_optimized_args=True)
        return True

    def read_training_batch_calibration(self, output_path):
        output_path = self.normalize_path(output_path)
        if not output_path or not os.path.exists(output_path):
            return {}, ""
        try:
            with open(output_path, "r", encoding="utf-8") as f:
                data = json.load(f) or {}
            if isinstance(data, dict):
                return data, output_path
        except Exception as e:
            logger.warning(f"Could not read batch calibration from {output_path}: {e}")
        return {}, ""

    def apply_training_batch_calibration(self, result, calibration, source_path=""):
        if not result or not isinstance(calibration, dict):
            return False
        if calibration.get("error"):
            return False
        raw_batch = int(calibration.get("batch") or calibration.get("raw_batch") or 0)
        if raw_batch <= 0:
            return False

        rec = result.get("recommendations", {})
        dataset_size = int(calibration.get("dataset_size") or result.get("image_count") or 0)
        model_factor = float((result.get("weight_info", {}) or {}).get("model_factor", 1.0) or 1.0)
        batch = self._training_eval_clamp_batch(raw_batch, dataset_size, model_factor)
        batch_cap = self._training_eval_safe_batch_cap(dataset_size, model_factor)
        rec["batch"] = batch
        note = (
            f"Batch calibrated by Ultralytics auto-batch at imgsz={calibration.get('imgsz')} "
            f"using {calibration.get('fraction', 0.6):.0%} VRAM target."
        )
        if batch != raw_batch:
            note += f" Clamped from {raw_batch} to {batch} to keep at least several batches per epoch."
        rec["batch_note"] = note
        calibration_record = dict(calibration)
        calibration_record["raw_batch"] = int(calibration.get("raw_batch") or raw_batch)
        calibration_record["batch_cap"] = int(calibration.get("batch_cap") or batch_cap)
        calibration_record["batch"] = batch
        result["batch_calibration"] = calibration_record
        result["batch_calibration_path"] = source_path
        result["training_recommendations_yaml"] = self._write_training_recommendation_yaml(result)
        self.training_evaluator_last_result = result
        self.apply_training_evaluation_recommendations(
            result,
            apply_weights=False,
            apply_optimized_args=bool(rec.get("train_args_text")),
        )
        return True

    def evaluate_training_setup(
        self,
        candidate_sizes=None,
        weights_path="",
        use_training_weights=True,
        auto_prepare_yaml=True,
        validation_mode=None,
        validation_source="",
        validation_percent=None,
        validation_source_percent=None,
        progress_callback=None,
    ):
        def report_progress(message):
            if callable(progress_callback):
                try:
                    progress_callback(str(message))
                except Exception:
                    pass

        self._training_eval_last_validation_prep = {}
        report_progress("Preparing dataset YAML and validation split...")
        data_yaml_path = self.normalize_path(getattr(self, "data_yaml_path", "") or "")
        data_yaml_error = ""
        validation_note = ""
        if auto_prepare_yaml:
            try:
                data_yaml_path = self.ensure_training_evaluator_data_yaml(
                    force=False,
                    prepare_validation=True,
                    validation_mode=validation_mode,
                    validation_source=validation_source,
                    validation_percent=validation_percent,
                    validation_source_percent=validation_source_percent,
                )
                prep = getattr(self, "_training_eval_last_validation_prep", {}) or {}
                validation_note = prep.get("validation_note") or "Auto YAML found or created obj.yaml for the current training setup."
            except Exception as e:
                data_yaml_error = str(e)
        elif data_yaml_path and os.path.exists(data_yaml_path):
            validation_note = "Using the selected training YAML as the dataset source."
        elif data_yaml_path and not os.path.exists(data_yaml_path):
            data_yaml_error = "Selected training YAML does not exist."

        report_progress("Resolving dataset paths and classes...")
        yaml_data, yaml_dir = self._training_health_parse_data_yaml(data_yaml_path)
        dataset_dir = self._training_health_dataset_dir(data_yaml_path, yaml_data, yaml_dir) or self._training_eval_dataset_dir()
        if not dataset_dir:
            raise ValueError("Select obj.yaml or open a dataset folder before evaluating training setup.")

        current_size = self._parse_training_imgsz_value(getattr(self, "imgsz_input", None).text() if getattr(self, "imgsz_input", None) is not None else "640")
        candidate_sizes = self._training_eval_candidate_sizes(candidate_sizes, current_size)
        weights_path = self._effective_eval_weights_path(use_training_weights, weights_path)
        report_progress(
            f"Loading checkpoint {os.path.basename(weights_path) if weights_path else 'metadata'}..."
        )
        weight_info = self.inspect_training_eval_weights(weights_path)
        strides = weight_info.get("strides") or [8, 16, 32]
        min_stride = max(1, min(strides))
        task_text = str(
            getattr(self, "task_combobox", None).currentText()
            if getattr(self, "task_combobox", None) is not None
            else ""
        ).strip().lower()
        model_task = str(weight_info.get("task", "") or "").strip().lower()

        # Ultralytics downsamples segmentation targets by mask_ratio while
        # training. A target can therefore be large enough for the detection
        # head but still have too few mask cells to learn a useful outline.
        mask_ratio = 4
        extra_train_args = str(getattr(self, "ultralytics_extra_train_args", "") or "")
        mask_ratio_match = re.search(r"(?:^|\s)mask_ratio\s*=\s*(\d+)", extra_train_args)
        if mask_ratio_match:
            try:
                mask_ratio = max(1, int(mask_ratio_match.group(1)))
            except (TypeError, ValueError):
                mask_ratio = 4

        scanner = getattr(self, "scan_annotations", None)
        if not isinstance(scanner, ScanAnnotations):
            scanner = ScanAnnotations(self)
        scanner.base_directory = dataset_dir
        yaml_names = self._training_eval_yaml_names(yaml_data)
        if yaml_names:
            scanner.valid_classes = yaml_names
            classes_file = data_yaml_path
        else:
            scanner.valid_classes, classes_file = scanner._load_classes(dataset_dir)
        try:
            kpt_shape = yaml_data.get("kpt_shape") if isinstance(yaml_data, dict) else None
            scanner.expected_keypoint_count = int(kpt_shape[0]) if isinstance(kpt_shape, list) and kpt_shape else 0
        except Exception:
            scanner.expected_keypoint_count = 0
        if not scanner.expected_keypoint_count:
            scanner.expected_keypoint_count = scanner._load_expected_keypoint_count(dataset_dir)

        if not scanner.valid_classes:
            raise ValueError("No classes were found. Add classes.txt or select a classes file first.")

        report_progress("Building the dataset image list...")
        image_files = self._training_eval_yaml_image_files(data_yaml_path, yaml_data, "train") if data_yaml_path else []
        if not image_files:
            image_files = scanner._iter_image_files(dataset_dir)
        label_files = []
        for image_file in image_files:
            label_path = self._label_path_for_image(image_file)
            if label_path and os.path.exists(label_path):
                label_files.append(self.normalize_path(label_path))
        if not label_files:
            label_files = scanner._iter_label_files(dataset_dir)
        label_map = {
            os.path.splitext(os.path.basename(path))[0].lower(): path
            for path in label_files
        }

        stats_by_size = {
            size: {
                "labels": 0,
                "tiny4": 0,
                "under_stride": 0,
                "under_2stride": 0,
                "pose_spread_under_stride": 0,
                "min_sides": [],
                "padding_waste": [],
            }
            for size in candidate_sizes
        }
        class_stats_by_size = {
            size: defaultdict(lambda: {
                "labels": 0,
                "tiny4": 0,
                "under_stride": 0,
                "under_2stride": 0,
                "min_sides": [],
            })
            for size in candidate_sizes
        }
        class_counts = Counter()
        annotation_counts = Counter()
        missing_labels = 0
        empty_labels = 0
        total_labels = 0
        pose_labels = 0
        visible_keypoints = 0

        expected_keypoints = scanner.expected_keypoint_count or None
        polygon_preference = self._polygon_label_parse_preference() if hasattr(self, "_polygon_label_parse_preference") else None

        total_images_to_scan = len(image_files)
        report_progress(f"Scanning {total_images_to_scan:,} dataset images...")
        for image_index, image_path in enumerate(image_files, start=1):
            if image_index == 1 or image_index % 100 == 0 or image_index == total_images_to_scan:
                report_progress(
                    f"Scanning dataset image {image_index:,} / {total_images_to_scan:,}..."
                )
            try:
                with Image.open(image_path) as img:
                    img_width, img_height = img.size
            except Exception:
                continue

            for size in candidate_sizes:
                scale, _left, _top, new_width, new_height = self._letterbox_preview_params(
                    img_width,
                    img_height,
                    size,
                    size,
                )
                usable_area = max(1.0, float(new_width * new_height))
                full_area = max(1.0, float(size * size))
                stats_by_size[size]["padding_waste"].append(max(0.0, 1.0 - usable_area / full_area))

            label_path = label_map.get(os.path.splitext(os.path.basename(image_path))[0].lower())
            if not label_path:
                missing_labels += 1
                continue

            try:
                with open(label_path, "r", encoding="utf-8") as f:
                    lines = [line.strip() for line in f if line.strip()]
            except UnicodeDecodeError:
                with open(label_path, "r", encoding="latin-1", errors="ignore") as f:
                    lines = [line.strip() for line in f if line.strip()]
            except Exception:
                continue

            if not lines:
                empty_labels += 1
                continue

            for line in lines:
                bbox = self._parse_training_eval_bbox(line, polygon_preference, expected_keypoints)
                if bbox is None:
                    continue

                extent = self._train_eval_label_extent(bbox)
                if extent is None:
                    continue

                class_counts[int(bbox.class_id)] += 1
                total_labels += 1
                if bbox.keypoints:
                    annotation_counts["pose"] += 1
                    pose_labels += 1
                elif bbox.segmentation:
                    annotation_counts["seg"] += 1
                elif bbox.obb:
                    annotation_counts["obb"] += 1
                else:
                    annotation_counts["bbox"] += 1

                _xc, _yc, norm_width, norm_height = extent
                visible_pose_points = []
                if bbox.keypoints:
                    visible_pose_points = [
                        (float(x), float(y))
                        for x, y, v in bbox.keypoints
                        if int(v) > 0
                    ]
                    visible_keypoints += len(visible_pose_points)

                for size in candidate_sizes:
                    scale, _left, _top, _new_width, _new_height = self._letterbox_preview_params(
                        img_width,
                        img_height,
                        size,
                        size,
                    )
                    scaled_width = norm_width * img_width * scale
                    scaled_height = norm_height * img_height * scale
                    min_side = min(scaled_width, scaled_height)
                    stats = stats_by_size[size]
                    stats["labels"] += 1
                    stats["min_sides"].append(min_side)
                    if min_side < 4:
                        stats["tiny4"] += 1
                    if min_side < min_stride:
                        stats["under_stride"] += 1
                    if min_side < min_stride * 2:
                        stats["under_2stride"] += 1

                    class_stats = class_stats_by_size[size][int(bbox.class_id)]
                    class_stats["labels"] += 1
                    class_stats["min_sides"].append(min_side)
                    if min_side < 4:
                        class_stats["tiny4"] += 1
                    if min_side < min_stride:
                        class_stats["under_stride"] += 1
                    if min_side < min_stride * 2:
                        class_stats["under_2stride"] += 1

                    if visible_pose_points:
                        scaled_points = [
                            (x * img_width * scale, y * img_height * scale)
                            for x, y in visible_pose_points
                        ]
                        xs = [point[0] for point in scaled_points]
                        ys = [point[1] for point in scaled_points]
                        if min(max(xs) - min(xs), max(ys) - min(ys)) < min_stride:
                            stats["pose_spread_under_stride"] += 1

        class_names = {}
        for class_id, count in class_counts.items():
            class_names[class_id] = scanner._class_name_for_index(class_id)

        def percent(count, total):
            return (float(count) / total * 100.0) if total else 0.0

        annotation_task = ""
        if annotation_counts:
            annotation_task = {
                "seg": "segment",
                "bbox": "detect",
                "obb": "obb",
                "pose": "pose",
            }.get(annotation_counts.most_common(1)[0][0], "")
        effective_size_task = model_task or task_text or annotation_task or "detect"
        if annotation_task == "segment" and effective_size_task == "detect":
            # Prefer the labels for size analysis when a generic/mismatched
            # detect fallback was inferred from a filename.
            effective_size_task = "segment"

        candidate_rows = []
        for size in candidate_sizes:
            stats = stats_by_size[size]
            labels = int(stats["labels"])
            min_sides = stats["min_sides"]
            under_stride_pct = percent(stats["under_stride"], labels)
            under_2stride_pct = percent(stats["under_2stride"], labels)
            tiny4_pct = percent(stats["tiny4"], labels)
            pose_spread_pct = percent(stats["pose_spread_under_stride"], pose_labels)
            p10_min_side = float(np.percentile(min_sides, 10)) if min_sides else 0.0
            p25_min_side = float(np.percentile(min_sides, 25)) if min_sides else 0.0
            median_min_side = float(np.median(min_sides)) if min_sides else 0.0
            mask_min_sides = [value / float(mask_ratio) for value in min_sides]
            mask_p10_min_side = float(np.percentile(mask_min_sides, 10)) if mask_min_sides else 0.0
            mask_under_4_pct = percent(sum(value < 4.0 for value in mask_min_sides), labels)
            mask_under_8_pct = percent(sum(value < 8.0 for value in mask_min_sides), labels)
            avg_padding_waste = float(np.mean(stats["padding_waste"])) if stats["padding_waste"] else 0.0
            risky_class_count = 0
            severe_risky_class_count = 0
            weighted_class_stride_risk = 0.0
            for class_stats in class_stats_by_size.get(size, {}).values():
                class_labels = int(class_stats["labels"])
                if class_labels < 3:
                    continue
                class_under_2stride_pct = percent(class_stats["under_2stride"], class_labels)
                if class_under_2stride_pct > 50.0:
                    risky_class_count += 1
                if class_under_2stride_pct > 75.0:
                    severe_risky_class_count += 1
                weighted_class_stride_risk += min(10, class_labels) * (class_under_2stride_pct / 100.0)

            score = 100.0
            score -= tiny4_pct * 3.0
            score -= under_stride_pct * 2.2
            score -= under_2stride_pct * 0.9
            score -= max(0.0, (min_stride * 2.0) - p10_min_side) * 2.5
            score -= risky_class_count * 3.0
            score -= severe_risky_class_count * 4.0
            score -= weighted_class_stride_risk * 0.08
            score -= avg_padding_waste * 8.0
            score -= max(0, size - 640) * 0.025
            if effective_size_task == "segment":
                score -= mask_under_4_pct * 1.5
                score -= mask_under_8_pct * 0.35
                score -= max(0.0, 6.0 - mask_p10_min_side) * 4.0
            candidate_rows.append({
                "imgsz": size,
                "labels": labels,
                "tiny4_pct": round(tiny4_pct, 2),
                "under_stride_pct": round(under_stride_pct, 2),
                "under_2stride_pct": round(under_2stride_pct, 2),
                "pose_spread_under_stride": int(stats["pose_spread_under_stride"]),
                "pose_spread_under_stride_pct": round(pose_spread_pct, 2),
                "p10_min_side": round(p10_min_side, 2),
                "p25_min_side": round(p25_min_side, 2),
                "median_min_side": round(median_min_side, 2),
                "mask_p10_min_side": round(mask_p10_min_side, 2),
                "mask_under_4_pct": round(mask_under_4_pct, 2),
                "mask_under_8_pct": round(mask_under_8_pct, 2),
                "avg_padding_waste": round(avg_padding_waste, 3),
                "risky_class_count": int(risky_class_count),
                "severe_risky_class_count": int(severe_risky_class_count),
                "weighted_class_stride_risk": round(weighted_class_stride_risk, 2),
                "score": round(max(0.0, min(100.0, score)), 2),
            })

        quality_candidates = []
        for row in candidate_rows:
            stride_quality = (
                row["tiny4_pct"] <= 0.5
                and row["under_stride_pct"] <= 2.5
                and row["under_2stride_pct"] <= 12.0
                and row["p10_min_side"] >= min_stride * 2
                and row["risky_class_count"] == 0
            )
            mask_quality = (
                effective_size_task != "segment"
                or (
                    row["mask_under_4_pct"] <= 5.0
                    and row["mask_under_8_pct"] <= 50.0
                    and row["mask_p10_min_side"] >= 6.0
                )
            )
            if stride_quality and mask_quality:
                quality_candidates.append(row)
        if quality_candidates:
            recommended_row = sorted(quality_candidates, key=lambda row: (row["imgsz"], -row["score"]))[0]
        elif candidate_rows:
            recommended_row = max(candidate_rows, key=lambda row: row["score"])
        else:
            recommended_row = {"imgsz": current_size, "avg_padding_waste": 0.0, "under_2stride_pct": 0.0}

        recommended_imgsz = int(recommended_row["imgsz"])
        class_risk_rows = []
        for class_id, stats in class_stats_by_size.get(recommended_imgsz, {}).items():
            labels = int(stats["labels"])
            if labels <= 0:
                continue
            min_sides = stats["min_sides"]
            class_risk_rows.append({
                "class_id": int(class_id),
                "class_name": class_names.get(int(class_id), str(class_id)),
                "labels": labels,
                "tiny4_pct": round(percent(stats["tiny4"], labels), 2),
                "under_stride_pct": round(percent(stats["under_stride"], labels), 2),
                "under_2stride_pct": round(percent(stats["under_2stride"], labels), 2),
                "median_min_side": round(float(np.median(min_sides)) if min_sides else 0.0, 2),
            })
        class_risk_rows.sort(
            key=lambda row: (
                -float(row["under_2stride_pct"]),
                -float(row["under_stride_pct"]),
                float(row["median_min_side"]),
            )
        )

        vram_gb = self._gpu_vram_gb()
        model_factor = float(weight_info.get("model_factor", 1.0) or 1.0)
        size_factor = max(0.35, (recommended_imgsz / 640.0) ** 2)
        if vram_gb > 0:
            raw_batch = int(max(1, min(64, (vram_gb * 1.05) / max(0.25, model_factor * size_factor))))
            if raw_batch >= 16:
                recommended_batch = max(4, (raw_batch // 4) * 4)
            elif raw_batch >= 8:
                recommended_batch = max(2, (raw_batch // 2) * 2)
            else:
                recommended_batch = raw_batch
        else:
            recommended_batch = 4
        raw_recommended_batch = int(recommended_batch)
        recommended_batch = self._training_eval_clamp_batch(raw_recommended_batch, len(image_files), model_factor)
        batch_limit_note = ""
        if recommended_batch != raw_recommended_batch:
            batch_limit_note = (
                f" Batch capped from {raw_recommended_batch} to {recommended_batch} "
                "to keep multiple batches per epoch."
            )

        imbalance_ratio = 1.0
        nonzero_counts = [count for count in class_counts.values() if count > 0]
        if len(nonzero_counts) >= 2 and min(nonzero_counts) > 0:
            imbalance_ratio = max(nonzero_counts) / min(nonzero_counts)

        if total_labels < 500:
            recommended_epochs = 200
        elif total_labels < 2000:
            recommended_epochs = 150
        elif total_labels < 10000:
            recommended_epochs = 100
        else:
            recommended_epochs = 80

        if float(recommended_row.get("under_2stride_pct", 0.0)) > 25:
            recommended_epochs += 25
        if imbalance_ratio >= 8:
            recommended_epochs += 25
        recommended_epochs = int(max(50, min(300, recommended_epochs)))
        recommended_patience = int(max(25, min(80, round(recommended_epochs * 0.32))))

        task_warning = ""
        if model_task and task_text and model_task != task_text:
            task_warning = f"Loaded eval weights are task '{model_task}', while the training panel is set to '{task_text}'."

        rect_recommended = float(recommended_row.get("avg_padding_waste", 0.0)) >= 0.25
        optimizer_rec = self.recommend_training_optimizer_args(
            total_labels,
            recommended_row,
            imbalance_ratio,
            weight_info,
            weights_path,
            task_text or model_task or "detect",
        )

        recommendations = {
            "imgsz": recommended_imgsz,
            "batch": int(recommended_batch),
            "epochs": recommended_epochs,
            "patience": recommended_patience,
            "amp": True,
            "rect": bool(rect_recommended),
            "task": task_text or model_task or "detect",
            "weights_path": weights_path,
            "data_yaml_path": data_yaml_path,
            "hyperparams": optimizer_rec.get("hyperparams", {}),
            "train_args": optimizer_rec.get("train_args", []),
            "train_args_text": optimizer_rec.get("train_args_text", ""),
            "optimizer_reason": optimizer_rec.get("optimizer_reason", ""),
            "freeze": int(optimizer_rec.get("freeze", 0) or 0),
            "batch_note": f"{optimizer_rec.get('batch_note', '')}{batch_limit_note}".strip(),
            "size_note": (
                (
                    f"Segmentation quality target: p10 object min-side is "
                    f"{recommended_row.get('p10_min_side', 0)}px at network input and "
                    f"{recommended_row.get('mask_p10_min_side', 0)} cells after "
                    f"mask_ratio={mask_ratio}; "
                    f"{recommended_row.get('mask_under_4_pct', 0)}% remain below 4 mask cells."
                )
                if effective_size_task == "segment"
                else (
                    f"Quality target: p10 object min-side is {recommended_row.get('p10_min_side', 0)}px "
                    f"against 2x stride={min_stride * 2}px; "
                    f"{recommended_row.get('risky_class_count', 0)} classes remain >50% under 2x stride."
                )
            ),
        }

        validation_prep = getattr(self, "_training_eval_last_validation_prep", {}) or {}
        split_class_report = (
            validation_prep.get("split_class_report")
            if isinstance(validation_prep, dict)
            else {}
        ) or self._training_eval_yaml_split_report(data_yaml_path, yaml_data)

        result = {
            "dataset_dir": dataset_dir,
            "data_yaml_path": data_yaml_path,
            "data_yaml_error": data_yaml_error,
            "validation_note": validation_note,
            "validation_prep": validation_prep,
            "split_class_report": split_class_report,
            "classes_file": classes_file,
            "image_count": len(image_files),
            "label_file_count": len(label_files),
            "missing_labels": missing_labels,
            "empty_labels": empty_labels,
            "total_labels": total_labels,
            "class_counts": dict(sorted((class_names.get(cid, str(cid)), count) for cid, count in class_counts.items())),
            "annotation_counts": dict(annotation_counts),
            "candidate_rows": candidate_rows,
            "class_risk_rows": class_risk_rows[:12],
            "recommended_row": recommended_row,
            "recommendations": recommendations,
            "weight_info": weight_info,
            "stride_min": min_stride,
            "effective_size_task": effective_size_task,
            "mask_ratio": mask_ratio,
            "vram_gb": round(vram_gb, 2),
            "imbalance_ratio": round(imbalance_ratio, 2),
            "pose_labels": pose_labels,
            "visible_keypoints": visible_keypoints,
            "task_warning": task_warning,
        }
        report_progress("Finalizing training recommendations...")
        result["training_recommendations_yaml"] = self._write_training_recommendation_yaml(result)
        report_progress("Dataset scan complete.")
        return result

    def format_training_evaluation_report(self, result):
        if not result:
            return "No evaluation has been run yet."

        rec = result.get("recommendations", {})
        weight_info = result.get("weight_info", {})
        lines = [
            "Training Evaluator",
            "",
            f"Dataset: {result.get('dataset_dir', '')}",
            f"Training YAML: {result.get('data_yaml_path') or 'not selected'}",
            f"Images: {result.get('image_count', 0)}   Label files: {result.get('label_file_count', 0)}   Labels: {result.get('total_labels', 0)}",
            f"Missing labels: {result.get('missing_labels', 0)}   Empty labels: {result.get('empty_labels', 0)}",
            "",
            f"Eval weights: {weight_info.get('name', 'No weights loaded')}",
            f"Task: {weight_info.get('task') or 'unknown'}   Stride: {', '.join(str(s) for s in weight_info.get('strides', []))}",
        ]

        if weight_info.get("error"):
            lines.append(f"Weight note: {weight_info['error']}")
        if result.get("data_yaml_error"):
            lines.append(f"YAML note: {result['data_yaml_error']}")
        if result.get("validation_note"):
            lines.append(f"Validation note: {result['validation_note']}")
        validation_prep = result.get("validation_prep", {}) if isinstance(result.get("validation_prep", {}), dict) else {}
        if validation_prep:
            lines.append(
                f"Split files: train={validation_prep.get('train_count', 0)} "
                f"valid={validation_prep.get('valid_count', 0)}"
            )
        split_report = result.get("split_class_report", {}) if isinstance(result.get("split_class_report", {}), dict) else {}
        if split_report:
            lines.append(
                f"Split coverage: train images={split_report.get('train_images', 0)} "
                f"valid images={split_report.get('valid_images', 0)} "
                f"overlap={split_report.get('overlap_images', 0)}"
            )
            if split_report.get("same_split"):
                lines.append("Split warning: train and validation contain the same images.")
            missing_valid = split_report.get("missing_valid", []) or []
            missing_train = split_report.get("missing_train", []) or []
            if missing_valid:
                preview = ", ".join(
                    f"{row.get('class_name')}({row.get('train_labels', 0)})"
                    for row in missing_valid[:10]
                )
                more = f" +{len(missing_valid) - 10} more" if len(missing_valid) > 10 else ""
                lines.append(f"Classes missing from valid: {preview}{more}")
            if missing_train:
                preview = ", ".join(
                    f"{row.get('class_name')}({row.get('valid_labels', 0)})"
                    for row in missing_train[:10]
                )
                more = f" +{len(missing_train) - 10} more" if len(missing_train) > 10 else ""
                lines.append(f"Classes missing from train: {preview}{more}")
        if result.get("task_warning"):
            lines.append(f"Task warning: {result['task_warning']}")
        if bool(getattr(self, "ultralytics_distill_enabled", False)):
            distill_notes = self._training_eval_distillation_sanity_notes(
                rec.get("weights_path", "") or getattr(self, "model_config_path", "") or getattr(self, "pt_path", ""),
                getattr(self, "ultralytics_distill_model_path", ""),
                getattr(self, "ultralytics_distill_weight", 6.0),
                rec.get("task", ""),
            )
            if distill_notes:
                lines.append("Distillation notes:")
                lines.extend(f"- {note.get('text', '')}" for note in distill_notes if note.get("text"))

        segment_size_analysis = result.get("effective_size_task") == "segment"
        lines.extend([
            "",
            "Candidate sizes",
            (
                "imgsz | score | <4px | <stride | <2*stride | p10 input | p10 mask | mask<4 | mask<8 | padding"
                if segment_size_analysis
                else "imgsz | score | <4px | <stride | <2*stride | p10 min side | risky classes | padding waste"
            ),
        ])

        for row in result.get("candidate_rows", []):
            marker = "*" if int(row.get("imgsz", 0)) == int(rec.get("imgsz", 0)) else " "
            if segment_size_analysis:
                lines.append(
                    f"{marker}{row['imgsz']:>4} | {row['score']:>5.1f} | "
                    f"{row['tiny4_pct']:>5.1f}% | {row['under_stride_pct']:>7.1f}% | "
                    f"{row['under_2stride_pct']:>9.1f}% | {row.get('p10_min_side', 0):>7.1f}px | "
                    f"{row.get('mask_p10_min_side', 0):>6.1f} | "
                    f"{row.get('mask_under_4_pct', 0):>6.1f}% | "
                    f"{row.get('mask_under_8_pct', 0):>6.1f}% | "
                    f"{row['avg_padding_waste'] * 100:>5.1f}%"
                )
            else:
                lines.append(
                    f"{marker}{row['imgsz']:>4} | {row['score']:>5.1f} | "
                    f"{row['tiny4_pct']:>5.1f}% | {row['under_stride_pct']:>7.1f}% | "
                    f"{row['under_2stride_pct']:>9.1f}% | {row.get('p10_min_side', 0):>7.1f}px | "
                    f"{row.get('risky_class_count', 0):>5} | "
                    f"{row['avg_padding_waste'] * 100:>5.1f}%"
                )

        lines.extend([
            "",
            "Recommended training setup",
            f"imgsz={rec.get('imgsz')}   batch={rec.get('batch')}   epochs={rec.get('epochs')}   patience={rec.get('patience')}",
            f"amp=True   rect={rec.get('rect')}   freeze={rec.get('freeze', 0)}   task={rec.get('task')}",
        ])

        if rec.get("weights_path"):
            lines.append(f"weights={rec.get('weights_path')}")
        if rec.get("train_args_text"):
            lines.extend([
                "",
                "Optimized train args",
                str(rec.get("train_args_text")),
            ])
        if rec.get("optimizer_reason"):
            lines.append(f"Optimizer note: {rec.get('optimizer_reason')}")
        if rec.get("size_note"):
            lines.append(f"Size note: {rec.get('size_note')}")
        if rec.get("batch_note"):
            lines.append(f"Batch note: {rec.get('batch_note')}")
        if result.get("batch_calibration_path"):
            lines.append(f"Batch calibration: {result.get('batch_calibration_path')}")
        if result.get("tune_best_path"):
            lines.append(f"Tuned hyperparameters: {result.get('tune_best_path')}")
        if result.get("training_recommendations_yaml"):
            lines.append(f"Recommendation YAML: {result.get('training_recommendations_yaml')}")

        if result.get("class_risk_rows"):
            lines.extend([
                "",
                "Riskiest classes at recommended size",
                "class | labels | <stride | <2*stride | median min side",
            ])
            for row in result["class_risk_rows"][:8]:
                lines.append(
                    f"{row['class_name']} | {row['labels']} | "
                    f"{row['under_stride_pct']:.1f}% | {row['under_2stride_pct']:.1f}% | "
                    f"{row['median_min_side']:.1f}px"
                )

        if result.get("pose_labels", 0):
            rec_row = result.get("recommended_row", {})
            lines.extend([
                "",
                f"Pose labels: {result.get('pose_labels', 0)}   Visible keypoints: {result.get('visible_keypoints', 0)}",
                f"Pose spread under stride at recommended size: {rec_row.get('pose_spread_under_stride_pct', 0):.1f}% ({rec_row.get('pose_spread_under_stride', 0)} labels)",
            ])

        if result.get("class_counts"):
            top_classes = sorted(result["class_counts"].items(), key=lambda item: item[1], reverse=True)[:8]
            lines.extend(["", "Top classes"])
            lines.extend(f"{name}: {count}" for name, count in top_classes)

        if result.get("imbalance_ratio", 1.0) >= 8:
            lines.append("")
            lines.append(f"Class balance note: largest/smallest class ratio is about {result.get('imbalance_ratio')}x.")

        if result.get("vram_gb", 0) > 0:
            lines.append(f"VRAM estimate: {result.get('vram_gb')} GB detected.")
        else:
            lines.append("VRAM estimate: CUDA GPU not detected; batch suggestion is conservative.")

        return "\n".join(lines)

    def apply_training_evaluation_recommendations(self, result, apply_weights=False, apply_optimized_args=True):
        if not result:
            return

        rec = result.get("recommendations", {})
        imgsz = int(rec.get("imgsz", self._parse_training_imgsz_value()))
        batch = int(rec.get("batch", 4))
        epochs = int(rec.get("epochs", 100))
        patience = int(rec.get("patience", 40))

        if getattr(self, "imgsz_input", None) is not None:
            self.imgsz_input.setText(str(imgsz))
        if getattr(self, "batch_input", None) is not None:
            self.batch_input.setText(str(batch))
        if getattr(self, "epochs_input", None) is not None:
            self.epochs_input.setText(str(epochs))

        if getattr(self, "patience_checkbox", None) is not None:
            self.patience_checkbox.setChecked(True)
        if getattr(self, "patience_input", None) is not None:
            self.patience_input.setValue(patience)
        if getattr(self, "amp_true", None) is not None:
            self.amp_true.setChecked(True)
        if getattr(self, "rect_train_checkbox", None) is not None:
            self.rect_train_checkbox.setChecked(bool(rec.get("rect", False)))
        freeze_value = int(rec.get("freeze", 0) or 0)
        if getattr(self, "freeze_checkbox", None) is not None:
            self.freeze_checkbox.setChecked(freeze_value > 0)
        if freeze_value > 0 and getattr(self, "freeze_input", None) is not None:
            self.freeze_input.setValue(freeze_value)

        task = str(rec.get("task", "") or "").strip()
        if task and getattr(self, "task_combobox", None) is not None:
            index = self.task_combobox.findText(task, Qt.MatchFixedString)
            if index >= 0:
                self.task_combobox.setCurrentIndex(index)

        weights_path = self.normalize_path(rec.get("weights_path", ""))
        if apply_weights and weights_path and os.path.exists(weights_path) and weights_path.lower().endswith(".pt"):
            self.pt_path = weights_path
            self.model_config_path = None
            self.pretrained_model_path = None
            if getattr(self, "pt_label", None) is not None:
                self.pt_label.setText(f"Model: {weights_path}")

        data_yaml_path = self.normalize_path(rec.get("data_yaml_path", "") or result.get("data_yaml_path", ""))
        if data_yaml_path and os.path.exists(data_yaml_path):
            self.data_yaml_path = data_yaml_path
            if getattr(self, "yaml_label", None) is not None:
                self.yaml_label.setText(f"Data YAML: {data_yaml_path}")

        optimized_args_text = str(rec.get("train_args_text", "") or "").strip()
        if apply_optimized_args and optimized_args_text:
            self.ultralytics_extra_train_args = optimized_args_text
        elif not apply_optimized_args:
            self.ultralytics_extra_train_args = ""

        self.training_preview_size = (imgsz, imgsz)
        if isinstance(getattr(self, "settings", None), dict):
            self.settings["trainingPreviewImgSize"] = str(imgsz)
            if weights_path:
                self.settings["trainingEvaluatorWeightsPath"] = weights_path
            if data_yaml_path:
                self.settings["ultralyticsDataYamlPath"] = data_yaml_path
            if apply_optimized_args and optimized_args_text:
                self.settings["ultralyticsExtraTrainArgs"] = optimized_args_text
            elif not apply_optimized_args:
                self.settings["ultralyticsExtraTrainArgs"] = ""
        self.queue_settings_save()

    def browse_training_eval_weights(self, line_edit, use_training_weights_checkbox=None):
        file_name = self.open_file_dialog("Select Evaluation Weights", "Model Files (*.pt *.yaml);;All Files (*)")
        if file_name:
            file_name = self.normalize_path(file_name)
            line_edit.setText(file_name)
            if use_training_weights_checkbox is not None:
                use_training_weights_checkbox.setChecked(False)
            self.settings["trainingEvaluatorWeightsPath"] = file_name
            self.settings["trainingEvaluatorUseTrainingWeights"] = False
            self.queue_settings_save()
            return file_name
        return ""

    def _training_eval_run_dir_from_command(self, command):
        output_path = self._training_eval_option_value(command, "--output")
        if output_path:
            return self.normalize_path(os.path.dirname(output_path))

        project_dir = self._training_eval_command_value(command, "project")
        run_name = self._training_eval_command_value(command, "name")
        if project_dir and run_name:
            return self.normalize_path(os.path.join(project_dir, run_name))
        return ""

    def _training_eval_log_path(self, run_dir):
        run_dir = self.normalize_path(run_dir)
        if not run_dir:
            return ""
        return self.normalize_path(os.path.join(run_dir, "darkfusion_console.log"))

    def _training_eval_run_modified_time(self, run_dir):
        run_dir = self.normalize_path(run_dir)
        if not run_dir or not os.path.isdir(run_dir):
            return 0.0
        candidates = [
            run_dir,
            os.path.join(run_dir, "args.yaml"),
            os.path.join(run_dir, "results.csv"),
            os.path.join(run_dir, "darkfusion_console.log"),
            os.path.join(run_dir, "weights", "last.pt"),
            os.path.join(run_dir, "weights", "best.pt"),
        ]
        newest = 0.0
        for path in candidates:
            try:
                if os.path.exists(path):
                    newest = max(newest, os.path.getmtime(path))
            except Exception:
                continue
        return newest

    def _training_eval_candidate_run_roots(self):
        settings = getattr(self, "settings", {}) if isinstance(getattr(self, "settings", None), dict) else {}
        roots = []
        seen = set()

        def add_root(path):
            path = self.normalize_path(path or "")
            if not path:
                return
            try:
                key = os.path.normcase(os.path.abspath(path))
            except Exception:
                key = os.path.normcase(path)
            if key in seen:
                return
            seen.add(key)
            roots.append(path)

        add_root(getattr(self, "runs_directory", ""))
        add_root(settings.get("ultralyticsRunsDirectory", ""))

        saved_run_dir = settings.get("trainingEvaluatorLastRunDir", "")
        if saved_run_dir:
            add_root(os.path.dirname(self.normalize_path(saved_run_dir)))

        data_yaml = self.normalize_path(
            getattr(self, "data_yaml_path", "") or settings.get("ultralyticsDataYamlPath", "")
        )
        if data_yaml:
            add_root(os.path.join(os.path.dirname(data_yaml), "runs"))

        try:
            dataset_dir = self._training_eval_dataset_dir()
        except Exception:
            dataset_dir = ""
        if dataset_dir:
            add_root(os.path.join(dataset_dir, "runs"))
            add_root(os.path.join(dataset_dir, PROJECT_SETTINGS_DIR, "training", "runs"))

        try:
            add_root(self._training_eval_project_dir())
        except Exception:
            pass

        return roots

    def _training_eval_discover_latest_run(self, force=False):
        now = time.time()
        cached = getattr(self, "_training_eval_discovered_run_cache", None)
        if not force and isinstance(cached, dict) and now - float(cached.get("at", 0.0) or 0.0) < 10.0:
            record = cached.get("record") or {}
            run_dir = self.normalize_path(record.get("run_dir", ""))
            if run_dir and os.path.isdir(run_dir):
                return dict(record)
            if not record:
                return {}

        best_dir = ""
        best_time = 0.0
        max_depth = 3
        max_checked = 5000
        checked = 0

        for root in self._training_eval_candidate_run_roots():
            if not root or not os.path.isdir(root):
                continue
            try:
                walker = os.walk(root)
                for current, dirs, files in walker:
                    checked += 1
                    if checked > max_checked:
                        break
                    current = self.normalize_path(current)
                    rel = os.path.relpath(current, root)
                    depth = 0 if rel == "." else rel.count(os.sep) + 1
                    if depth >= max_depth:
                        dirs[:] = []
                    dirs[:] = [
                        d for d in dirs
                        if d.lower() not in {"weights", "__pycache__"} and not d.startswith(".")
                    ]

                    marker_paths = [
                        os.path.join(current, "args.yaml"),
                        os.path.join(current, "results.csv"),
                        os.path.join(current, "weights", "last.pt"),
                        os.path.join(current, "weights", "best.pt"),
                    ]
                    if not any(os.path.exists(path) for path in marker_paths):
                        continue

                    args, _args_path = self._training_eval_read_args_yaml(current)
                    mode = str(args.get("mode", "train") if args else "train").strip().lower()
                    if mode and mode != "train":
                        continue

                    modified = self._training_eval_run_modified_time(current)
                    if modified > best_time:
                        best_time = modified
                        best_dir = current
            except Exception as e:
                logger.debug(f"Could not scan training runs under {root}: {e}")

        if not best_dir:
            self._training_eval_discovered_run_cache = {"at": now, "record": {}}
            return {}
        record = {
            "title": "Discovered Training Run",
            "run_dir": best_dir,
            "log_path": self._training_eval_log_path(best_dir),
            "process": None,
            "pid": None,
        }
        self._training_eval_discovered_run_cache = {"at": now, "record": dict(record)}
        return record

    def _training_eval_record_run(self, title, run_dir, log_path, command=None, process=None):
        run_dir = self.normalize_path(run_dir)
        log_path = self.normalize_path(log_path or self._training_eval_log_path(run_dir))
        record = {
            "title": str(title or "Training"),
            "run_dir": run_dir,
            "log_path": log_path,
            "command": list(command or []),
            "process": process,
            "pid": int(process.pid) if process is not None and getattr(process, "pid", None) else None,
            "started_at": datetime.now().isoformat(timespec="seconds"),
        }
        self.training_evaluator_active_run = record
        self.training_evaluator_last_run = dict(record)
        self._training_eval_discovered_run_cache = None

        if isinstance(getattr(self, "settings", None), dict):
            self.settings["trainingEvaluatorLastRunDir"] = run_dir
            self.settings["trainingEvaluatorLastRunLog"] = log_path
            self.settings["trainingEvaluatorLastRunTitle"] = record["title"]
            command_tokens = [str(part).strip().lower() for part in (command or [])]
            if "train" in command_tokens:
                self.settings["trainingEvaluatorLastTrainingRunDir"] = run_dir
            self.queue_settings_save()
        return record

    def _training_eval_latest_saved_run(self):
        settings = getattr(self, "settings", {}) if isinstance(getattr(self, "settings", None), dict) else {}
        candidates = []
        for record in (
            getattr(self, "training_evaluator_active_run", None),
            getattr(self, "training_evaluator_last_run", None),
        ):
            if isinstance(record, dict) and record.get("run_dir"):
                candidates.append(record)

        saved_run_dir = settings.get("trainingEvaluatorLastRunDir", "")
        if saved_run_dir:
            candidates.append({
                "title": settings.get("trainingEvaluatorLastRunTitle", "Training"),
                "run_dir": saved_run_dir,
                "log_path": settings.get("trainingEvaluatorLastRunLog", ""),
                "process": None,
                "pid": None,
            })

        discovered = self._training_eval_discover_latest_run()
        if discovered:
            candidates.append(discovered)

        valid = []
        for record in candidates:
            run_dir = self.normalize_path(record.get("run_dir", ""))
            if run_dir and os.path.isdir(run_dir):
                clean = dict(record)
                clean["run_dir"] = run_dir
                clean["log_path"] = self.normalize_path(clean.get("log_path") or self._training_eval_log_path(run_dir))
                clean["_modified"] = self._training_eval_run_modified_time(run_dir)
                clean["_active"] = self._training_eval_run_is_active(record)
                valid.append(clean)
        for clean in valid:
            if clean.pop("_active", False):
                clean.pop("_modified", None)
                return clean
        if valid:
            valid.sort(key=lambda item: float(item.get("_modified") or 0.0), reverse=True)
            clean = valid[0]
            clean.pop("_modified", None)
            clean.pop("_active", None)
            return clean
        return {}

    def _training_eval_run_is_active(self, record):
        process = (record or {}).get("process")
        if process is not None:
            try:
                return process.poll() is None
            except Exception:
                pass

        pid = (record or {}).get("pid")
        if pid and psutil is not None:
            try:
                proc = psutil.Process(int(pid))
                if proc.is_running() and proc.status() != psutil.STATUS_ZOMBIE:
                    return True
            except Exception:
                pass

        # Runs launched by an older DarkFusion build have no persisted runner PID.
        # Ultralytics updates the captured progress log continuously, so recent
        # writes provide a cheap, non-blocking way to reattach after an app restart.
        log_path = self.normalize_path(
            (record or {}).get("log_path")
            or self._training_eval_log_path((record or {}).get("run_dir", ""))
        )
        try:
            return bool(log_path and os.path.isfile(log_path) and time.time() - os.path.getmtime(log_path) <= 20.0)
        except Exception:
            return False

    def _training_eval_read_args_yaml(self, run_dir):
        run_dir = self.normalize_path(run_dir)
        args_path = self.normalize_path(os.path.join(run_dir, "args.yaml"))
        if not run_dir or not os.path.exists(args_path):
            return {}, args_path
        try:
            with open(args_path, "r", encoding="utf-8", errors="replace") as f:
                data = yaml.safe_load(f) or {}
            return data if isinstance(data, dict) else {}, args_path
        except Exception as e:
            logger.warning(f"Could not read Ultralytics args from {args_path}: {e}")
            return {}, args_path

    def _training_eval_restore_last_run_setup(self):
        """Return one verified, internally consistent setup from the latest training run."""
        settings = getattr(self, "settings", {}) if isinstance(getattr(self, "settings", None), dict) else {}
        candidate_dirs = []

        def add_run_dir(path):
            path = self.normalize_path(path or "")
            if path and os.path.isdir(path) and path not in candidate_dirs:
                args, _args_path = self._training_eval_read_args_yaml(path)
                if str(args.get("mode", "train") or "train").strip().lower() == "train":
                    candidate_dirs.append(path)

        add_run_dir(settings.get("trainingEvaluatorLastTrainingRunDir", ""))
        for model_path in (
            getattr(self, "pt_path", ""),
            settings.get("ultralyticsPtPath", ""),
            settings.get("trainingEvaluatorWeightsPath", ""),
        ):
            model_path = self.normalize_path(model_path or "")
            parent = os.path.dirname(model_path)
            if os.path.basename(parent).lower() == "weights":
                add_run_dir(os.path.dirname(parent))

        # A validation launch may be the most recently recorded command. Recover
        # its model path from the log, then walk back from weights/*.pt to the
        # training run whose args.yaml is authoritative.
        last_command_run = self.normalize_path(settings.get("trainingEvaluatorLastRunDir", ""))
        last_command_log = self.normalize_path(
            settings.get("trainingEvaluatorLastRunLog", "")
            or self._training_eval_log_path(last_command_run)
        )
        logged_args = self._training_eval_run_args_from_log(last_command_log)
        logged_model = self.normalize_path(str(logged_args.get("model", "") or ""))
        logged_parent = os.path.dirname(logged_model)
        if os.path.basename(logged_parent).lower() == "weights":
            add_run_dir(os.path.dirname(logged_parent))

        discovered = self._training_eval_discover_latest_run(force=True) or {}
        add_run_dir(discovered.get("run_dir", ""))
        if not candidate_dirs:
            return {}

        run_dir = max(candidate_dirs, key=self._training_eval_run_modified_time)
        record = {
            "title": "Restored Training Run",
            "run_dir": run_dir,
            "log_path": self._training_eval_log_path(run_dir),
            "process": None,
            "pid": None,
        }
        if not run_dir:
            return {}

        args, args_path = self._training_eval_read_args_yaml(run_dir)
        if not args:
            return {}

        data_yaml = self.normalize_path(str(args.get("data", "") or ""))
        if data_yaml and not os.path.isabs(data_yaml):
            data_yaml = self.normalize_path(os.path.join(run_dir, data_yaml))
        if not data_yaml or not os.path.isfile(data_yaml):
            data_yaml = ""

        # Prefer the trained best checkpoint, but never select it merely because
        # the file exists. Interrupted writes can leave a large yet invalid .pt.
        model_from_args = self.normalize_path(str(args.get("model", "") or ""))
        candidates = [
            self.normalize_path(os.path.join(run_dir, "weights", "best.pt")),
            self.normalize_path(os.path.join(run_dir, "weights", "last.pt")),
            model_from_args,
        ]
        checkpoint = ""
        weight_info = {}
        seen = set()
        for candidate in candidates:
            key = os.path.normcase(candidate) if candidate else ""
            if not candidate or key in seen or not os.path.isfile(candidate):
                continue
            seen.add(key)
            info = self.inspect_training_eval_weights(candidate)
            if info.get("loaded"):
                checkpoint = candidate
                weight_info = info
                break
            logger.warning(
                "Skipping unusable checkpoint while restoring evaluator setup: %s (%s)",
                candidate,
                info.get("error") or "load failed",
            )

        task = str(args.get("task", "") or weight_info.get("task", "") or "").strip().lower()
        if task not in {"detect", "segment", "classify", "pose", "obb"}:
            task = str(weight_info.get("task", "") or "").strip().lower()

        if checkpoint and data_yaml and isinstance(getattr(self, "settings", None), dict):
            self.settings["trainingEvaluatorLastTrainingRunDir"] = run_dir

        return {
            "record": record,
            "run_dir": run_dir,
            "args_path": args_path,
            "args": args,
            "data_yaml": data_yaml,
            "checkpoint": checkpoint,
            "weight_info": weight_info,
            "task": task,
        }

    def _training_eval_int_value(self, value, default=0):
        try:
            parsed = int(float(str(value).strip()))
            return parsed
        except Exception:
            return int(default)

    def _training_eval_last_completed_epoch(self, rows):
        for row in reversed(rows or []):
            value = self._training_eval_float_value((row or {}).get("epoch", ""))
            if value is not None:
                return max(0, int(value))
        return 0

    def _training_eval_resume_info(self, record=None):
        if isinstance(record, str):
            record = {"run_dir": record}
        record = dict(record or self._training_eval_latest_saved_run() or {})
        run_dir = self.normalize_path(record.get("run_dir", ""))
        log_path = self.normalize_path(record.get("log_path") or self._training_eval_log_path(run_dir))
        info = {
            "status": "none",
            "run_dir": run_dir,
            "log_path": log_path,
            "args": {},
            "args_path": "",
            "last_pt": "",
            "target_epochs": 0,
            "last_epoch": 0,
            "resumable": False,
            "note": "No previous training run is available.",
        }
        if not run_dir or not os.path.isdir(run_dir):
            return info

        args, args_path = self._training_eval_read_args_yaml(run_dir)
        headers, rows, _csv_path = self._training_eval_read_results_csv(run_dir)
        del headers
        last_epoch = self._training_eval_last_completed_epoch(rows)
        target_epochs = self._training_eval_int_value(args.get("epochs", 0), 0)
        last_pt = self.normalize_path(os.path.join(run_dir, "weights", "last.pt"))
        has_last_pt = os.path.exists(last_pt)
        active = self._training_eval_run_is_active(record)
        checkpoint_label = (
            f"epoch {last_epoch}/{target_epochs}" if target_epochs else f"epoch {last_epoch}"
        )
        if active:
            info.update({
                "args": args,
                "args_path": args_path,
                "last_pt": last_pt,
                "target_epochs": target_epochs,
                "last_epoch": last_epoch,
                "exit_code": None,
                "status": "running",
                "note": f"Training is still running at {checkpoint_label}. Live metrics will keep updating.",
            })
            return info

        log_tail = self._training_eval_read_text_tail(log_path, max_chars=60000)
        completed_marker = bool(
            re.search(r"\bepochs completed\b|Results saved to|Exit code:\s*0\b", log_tail, flags=re.IGNORECASE)
        )
        exit_code_match = re.search(r"Exit code:\s*(-?\d+)", log_tail, flags=re.IGNORECASE)
        exit_code = int(exit_code_match.group(1)) if exit_code_match else None
        info.update({
            "args": args,
            "args_path": args_path,
            "last_pt": last_pt,
            "target_epochs": target_epochs,
            "last_epoch": last_epoch,
            "exit_code": exit_code,
        })

        tune_best, tune_best_path = self.read_training_tune_best_hyperparameters(run_dir)
        if tune_best and exit_code in (None, 0):
            info["status"] = "complete"
            info["run_kind"] = "tune"
            info["tune_best_path"] = tune_best_path
            info["note"] = (
                f"Hyperparameter tuning completed successfully. Best settings are available in "
                f"{os.path.basename(tune_best_path)}."
            )
            return info

        if not args:
            info["status"] = "unknown"
            info["note"] = "Last run is missing args.yaml, so DarkFusion cannot safely resume it."
            return info

        if (target_epochs > 0 and last_epoch >= target_epochs) or (completed_marker and not target_epochs):
            info["status"] = "complete"
            info["note"] = f"Last training run completed at {checkpoint_label}. Start Training will create a new run."
            return info

        if has_last_pt:
            info["status"] = "interrupted"
            info["resumable"] = True
            info["note"] = (
                f"Last training run appears interrupted at {checkpoint_label}. "
                "Resume is available from weights/last.pt. Use Resume Last Run to continue it, "
                "or Start Training to start a fresh run on this dataset."
            )
            return info

        if not has_last_pt:
            info["status"] = "interrupted_no_checkpoint"
            info["note"] = (
                f"Last training run appears interrupted at {checkpoint_label}, but weights/last.pt was not found. "
                "Start Training will create a new run."
            )
            return info

        info["status"] = "complete" if last_epoch >= target_epochs > 0 else "unknown"
        info["note"] = f"Last training run status: {checkpoint_label}. Start Training will create a new run."
        return info

    def build_training_evaluator_resume_command(self, run_dir=None):
        info = self._training_eval_resume_info(run_dir or self._training_eval_latest_saved_run())
        if not info.get("resumable"):
            raise ValueError(info.get("note") or "No resumable training run was found.")
        last_pt = self.normalize_path(info.get("last_pt", ""))
        if not last_pt or not os.path.exists(last_pt):
            raise ValueError("Cannot resume because weights/last.pt is missing.")

        args = info.get("args", {}) or {}
        task = str(args.get("task") or "detect").strip().lower()
        if task not in {"detect", "segment", "classify", "pose", "obb"}:
            task = "detect"
        cmd = [
            *self._ultralytics_train_command_prefix(),
            task,
            "train",
            f"model={last_pt}",
            "resume=True",
            "amp=True",
        ]
        self._append_ultralytics_memory_guard_args(cmd)
        return cmd

    def launch_training_evaluator_logged_command(self, command, title="Training Evaluator", run_dir=None):
        if not command:
            raise ValueError("No command to launch.")

        run_dir = self.normalize_path(run_dir or self._training_eval_run_dir_from_command(command))
        if not run_dir:
            run_dir = self.normalize_path(os.path.join(self._training_eval_project_dir(), f"evaluator_run_{datetime.now().strftime('%Y%m%d_%H%M%S')}"))
        os.makedirs(run_dir, exist_ok=True)

        runner_path = os.path.join(APP_DIR, "darkfusion_command_runner.py")
        if not os.path.exists(runner_path):
            return self.launch_training_evaluator_command(command, title=title, keep_open=False), run_dir, ""

        log_path = self._training_eval_log_path(run_dir)
        runner_command = [
            sys.executable,
            runner_path,
            f"--log={log_path}",
            f"--cwd={APP_DIR}",
            "--max-commit-gb=48",
            "--min-system-available-gb=4",
            "--",
            *command,
        ]
        logger.info(f"{title} command: {self._format_command_display(command)}")
        logger.info(f"{title} log: {log_path}")

        kwargs = {
            "cwd": APP_DIR,
            "stdout": subprocess.DEVNULL,
            "stderr": subprocess.DEVNULL,
        }
        if sys.platform.startswith("win"):
            kwargs["creationflags"] = subprocess.CREATE_NEW_PROCESS_GROUP
        process = subprocess.Popen(runner_command, **kwargs)
        return process, run_dir, log_path

    def _training_eval_read_text_tail(self, path, max_chars=160000):
        path = self.normalize_path(path)
        if not path or not os.path.exists(path):
            return ""
        def clean_log_text(text):
            text = re.sub(r"\x1b\[[0-?]*[ -/]*[@-~]", "", str(text))
            return text.replace("\r\n", "\n").replace("\r", "\n")
        try:
            size = os.path.getsize(path)
            with open(path, "rb") as f:
                if size > max_chars:
                    f.seek(max(0, size - max_chars))
                    data = f.read()
                    text = clean_log_text(data.decode("utf-8", errors="replace"))
                    return "... log trimmed to the most recent output ...\n" + text
                return clean_log_text(f.read().decode("utf-8", errors="replace"))
        except Exception as e:
            return f"Could not read log: {e}"

    def _training_eval_read_results_csv(self, run_dir):
        csv_path = self.normalize_path(os.path.join(self.normalize_path(run_dir), "results.csv"))
        if not os.path.exists(csv_path):
            return [], [], ""
        try:
            with open(csv_path, "r", encoding="utf-8", errors="replace", newline="") as f:
                reader = csv.DictReader(f)
                headers = [str(header).strip() for header in (reader.fieldnames or []) if str(header).strip()]
                rows = []
                for row in reader:
                    clean = {}
                    for key, value in (row or {}).items():
                        key = str(key).strip()
                        if key:
                            clean[key] = str(value).strip()
                    if clean:
                        rows.append(clean)
            return headers, rows, csv_path
        except Exception as e:
            logger.warning(f"Could not read Ultralytics results CSV from {csv_path}: {e}")
            return [], [], csv_path

    def _training_eval_float_value(self, value):
        try:
            parsed = float(str(value).strip())
            return parsed if math.isfinite(parsed) else None
        except Exception:
            return None

    def _training_eval_display_metric_headers(self, headers):
        headers = [str(header).strip() for header in headers or [] if str(header).strip()]
        score_headers = [
            header for header in headers
            if header.lower().startswith("metrics/")
            and any(token in header.lower() for token in ("map", "precision", "recall"))
        ]
        loss_headers = [
            header for header in headers
            if "loss" in header.lower()
            and (header.lower().startswith("train/") or header.lower().startswith("val/"))
        ]
        lr_headers = [header for header in headers if header.lower().startswith("lr/")]
        preferred = ["epoch", "time"]
        ordered = []
        for header in preferred + score_headers + loss_headers[:10] + lr_headers[:3]:
            if header in headers and header not in ordered:
                ordered.append(header)
        return ordered or headers[:12]

    def _training_eval_format_csv_value(self, value):
        parsed = self._training_eval_float_value(value)
        if parsed is None:
            return str(value)
        if abs(parsed) >= 1000:
            return f"{parsed:.1f}"
        if abs(parsed) >= 10:
            return f"{parsed:.3f}"
        return f"{parsed:.5f}".rstrip("0").rstrip(".")

    def _training_eval_update_metrics_table(self, table, headers, rows):
        if table is None or sip.isdeleted(table):
            return
        table.setUpdatesEnabled(False)
        try:
            display_headers = self._training_eval_display_metric_headers(headers)
            display_rows = list(rows or [])[-200:]
            table.clear()
            table.setColumnCount(len(display_headers))
            table.setRowCount(len(display_rows))
            table.setHorizontalHeaderLabels(display_headers)
            for row_index, row in enumerate(display_rows):
                for col_index, header in enumerate(display_headers):
                    item = QTableWidgetItem(self._training_eval_format_csv_value(row.get(header, "")))
                    item.setTextAlignment(Qt.AlignCenter)
                    table.setItem(row_index, col_index, item)
            if display_rows:
                table.selectRow(len(display_rows) - 1)
            table.resizeColumnsToContents()
        finally:
            table.setUpdatesEnabled(True)

    def _training_eval_metric_series(self, headers, rows, kind):
        if not rows:
            return []
        palette = [
            QColor("#d8a64f"),
            QColor("#53c7f0"),
            QColor("#7bd88f"),
            QColor("#ff6b7a"),
            QColor("#b98cff"),
            QColor("#f0d264"),
            QColor("#4fd1b8"),
            QColor("#ff9f43"),
        ]
        if kind == "score":
            keys = [
                header for header in headers
                if header.lower().startswith("metrics/")
                and any(token in header.lower() for token in ("map", "precision", "recall"))
            ]
        else:
            keys = [
                header for header in headers
                if "loss" in header.lower()
                and (header.lower().startswith("train/") or header.lower().startswith("val/"))
            ]

        series = []
        for index, key in enumerate(keys[:8]):
            values = [self._training_eval_float_value(row.get(key, "")) for row in rows]
            if any(value is not None for value in values):
                label = key.replace("metrics/", "").replace("train/", "tr/").replace("val/", "val/")
                series.append((label, values, palette[index % len(palette)]))
        return series

    def _training_eval_latest_metric_line(self, headers, rows):
        if not rows:
            return "Waiting for results.csv..."
        latest = rows[-1]
        pieces = []
        for header in self._training_eval_display_metric_headers(headers)[:8]:
            if header in latest:
                pieces.append(f"{header}={self._training_eval_format_csv_value(latest.get(header, ''))}")
        return "Latest: " + "   ".join(pieces) if pieces else f"Rows: {len(rows)}"

    def _training_eval_metric_header(self, headers, required=(), any_of=(), rejected=()):
        for header in headers or []:
            lower = str(header).strip().lower()
            if not lower:
                continue
            if required and not all(token in lower for token in required):
                continue
            if any_of and not any(token in lower for token in any_of):
                continue
            if rejected and any(token in lower for token in rejected):
                continue
            return header
        return ""

    def _training_eval_metric_values_for_header(self, rows, header):
        values = []
        if not header:
            return values
        for row in rows or []:
            values.append(self._training_eval_float_value((row or {}).get(header, "")))
        return values

    def _training_eval_last_number(self, values):
        for value in reversed(values or []):
            if value is not None:
                return float(value)
        return None

    def _training_eval_window_mean(self, values, take_last=True, window=3):
        clean = [float(value) for value in values or [] if value is not None]
        if not clean:
            return None
        window = max(1, min(int(window or 1), len(clean)))
        sample = clean[-window:] if take_last else clean[:window]
        return sum(sample) / len(sample)

    def _training_eval_loss_values(self, headers, rows, prefix):
        keys = [
            header for header in headers or []
            if str(header).lower().startswith(prefix)
            and "loss" in str(header).lower()
        ]
        values = []
        for row in rows or []:
            row_values = [
                self._training_eval_float_value((row or {}).get(header, ""))
                for header in keys
            ]
            row_values = [value for value in row_values if value is not None]
            values.append(sum(row_values) / len(row_values) if row_values else None)
        return values

    def _training_eval_run_args_from_log(self, log_path):
        log_path = self.normalize_path(log_path)
        head_text = ""
        try:
            if log_path and os.path.exists(log_path):
                with open(log_path, "rb") as f:
                    head_text = f.read(60000).decode("utf-8", errors="replace")
        except Exception:
            head_text = ""
        text = head_text + "\n" + self._training_eval_read_text_tail(log_path, max_chars=40000)
        command_text = ""
        for line in text.splitlines():
            if line.startswith("Command:"):
                command_text = line.split("Command:", 1)[1].strip()
        if not command_text:
            return {}
        try:
            tokens = shlex.split(command_text, posix=False)
        except Exception:
            tokens = command_text.split()
        tokens = [str(token).strip().strip('"').strip("'") for token in tokens if str(token).strip()]
        args = {}
        tasks = {"detect", "segment", "classify", "pose", "obb"}
        modes = {"train", "val", "predict", "export", "track", "benchmark", "tune"}
        for index, token in enumerate(tokens[:-1]):
            low = token.lower()
            next_low = tokens[index + 1].lower()
            if low in tasks and next_low in modes:
                args["task"] = low
                args["mode"] = next_low
                break
        for token in tokens:
            if "=" not in token or token.startswith("--"):
                continue
            key, value = token.split("=", 1)
            key = key.strip()
            if key:
                args[key] = value.strip().strip('"').strip("'")
        return args

    def _training_eval_run_args_for_compare(self, run_dir):
        args, _args_path = self._training_eval_read_args_yaml(run_dir)
        if isinstance(args, dict) and args:
            return {str(key): value for key, value in args.items()}
        log_path = self._training_eval_log_path(run_dir)
        return self._training_eval_run_args_from_log(log_path)

    def _training_eval_resolve_compare_path(self, value, base_dir=""):
        value = str(value or "").strip().strip('"').strip("'")
        if not value:
            return ""
        candidates = []
        if os.path.isabs(value):
            candidates.append(value)
        else:
            if base_dir:
                candidates.append(os.path.join(base_dir, value))
            candidates.append(os.path.join(APP_DIR, value))
            candidates.append(os.path.join(os.getcwd(), value))
        for candidate in candidates:
            candidate = self.normalize_path(candidate)
            if os.path.exists(candidate):
                return os.path.normcase(os.path.abspath(candidate))
        return value.replace("\\", "/").lower()

    def _training_eval_compare_arg_match(self, left, right, base_dir="", kind=""):
        left = str(left or "").strip()
        right = str(right or "").strip()
        if not left or not right:
            return False
        if kind in {"data", "model"}:
            left_path = self._training_eval_resolve_compare_path(left, base_dir)
            right_path = self._training_eval_resolve_compare_path(right, base_dir)
            if left_path == right_path:
                return True
            return os.path.basename(left_path).lower() == os.path.basename(right_path).lower()
        return left.lower() == right.lower()

    def _training_eval_parse_all_metric_from_log(self, log_path):
        text = self._training_eval_read_text_tail(log_path, max_chars=120000)
        matches = re.findall(
            r"(?m)^\s*all\s+(\d+)\s+(\d+)\s+([0-9]*\.?[0-9]+)\s+([0-9]*\.?[0-9]+)\s+([0-9]*\.?[0-9]+)\s+([0-9]*\.?[0-9]+)",
            text,
        )
        if not matches:
            return {}
        images, instances, precision, recall, map50, map5095 = matches[-1]
        return {
            "images": int(images),
            "instances": int(instances),
            "precision": float(precision),
            "recall": float(recall),
            "map50": float(map50),
            "map5095": float(map5095),
        }

    def _training_eval_best_metric_snapshot(self, headers, rows):
        if not rows:
            return {}
        map5095_key = self._training_eval_metric_header(headers, required=("metrics/",), any_of=("map50-95", "map50_95"))
        map50_key = self._training_eval_metric_header(headers, required=("metrics/", "map50"), rejected=("50-95", "50_95"))
        precision_key = self._training_eval_metric_header(headers, required=("metrics/", "precision"))
        recall_key = self._training_eval_metric_header(headers, required=("metrics/", "recall"))
        best = None
        best_value = None
        for row in rows or []:
            value = self._training_eval_float_value((row or {}).get(map5095_key, "")) if map5095_key else None
            if value is None:
                continue
            if best is None or value > best_value:
                best = row
                best_value = value
        if not best:
            return {}
        return {
            "epoch": self._training_eval_float_value(best.get("epoch", "")),
            "precision": self._training_eval_float_value(best.get(precision_key, "")) if precision_key else None,
            "recall": self._training_eval_float_value(best.get(recall_key, "")) if recall_key else None,
            "map50": self._training_eval_float_value(best.get(map50_key, "")) if map50_key else None,
            "map5095": best_value,
        }

    def _training_eval_baseline_args_from_result(self, result):
        rec = (result or {}).get("recommendations", {}) if isinstance(result, dict) else {}
        data_yaml = self.normalize_path(rec.get("data_yaml_path", "") or (result or {}).get("data_yaml_path", "") or getattr(self, "data_yaml_path", ""))
        model_path = self.normalize_path(rec.get("weights_path", "") or self._training_eval_model_path(result, prefer_recommendation=True))
        imgsz = str(int(rec.get("imgsz", self._parse_training_imgsz_value()) or self._parse_training_imgsz_value()))
        task = str(rec.get("task") or "detect").strip().lower() or "detect"
        return {
            "task": task,
            "mode": "val",
            "data": data_yaml,
            "model": model_path,
            "imgsz": imgsz,
            "split_fingerprint": self._training_eval_data_split_fingerprint(data_yaml),
        }

    def _training_eval_data_split_fingerprint(self, data_yaml_path):
        data_yaml_path = self.normalize_path(data_yaml_path or "")
        if not data_yaml_path or not os.path.exists(data_yaml_path):
            return ""
        try:
            yaml_data, yaml_dir = self._training_health_parse_data_yaml(data_yaml_path)
            digest = hashlib.sha256()
            digest.update(data_yaml_path.encode("utf-8", errors="ignore"))
            try:
                with open(data_yaml_path, "rb") as f:
                    digest.update(f.read())
            except Exception:
                pass
            dataset_root = self.normalize_path((yaml_data or {}).get("path", "") or yaml_dir)
            if dataset_root and not os.path.isabs(dataset_root):
                dataset_root = self.normalize_path(os.path.join(yaml_dir, dataset_root))
            for split in ("train", "val"):
                digest.update(f"\n[{split}]\n".encode("utf-8"))
                entries = (yaml_data or {}).get(split)
                entries = entries if isinstance(entries, list) else [entries]
                for entry in entries:
                    value = str(entry or "").strip().strip('"').strip("'")
                    if not value:
                        continue
                    path = self.normalize_path(
                        value if os.path.isabs(value) else os.path.join(dataset_root or yaml_dir, value)
                    )
                    digest.update(path.encode("utf-8", errors="ignore"))
                    digest.update(b"\n")
                    # Hash list files sequentially instead of issuing tens of
                    # thousands of os.path.isfile calls for their image paths.
                    if os.path.isfile(path) and os.path.splitext(path)[1].lower() == ".txt":
                        try:
                            with open(path, "rb") as f:
                                while True:
                                    block = f.read(1024 * 1024)
                                    if not block:
                                        break
                                    digest.update(block)
                        except Exception:
                            pass
                    elif os.path.exists(path):
                        try:
                            stat = os.stat(path)
                            digest.update(f"{stat.st_size}:{stat.st_mtime_ns}".encode("ascii"))
                        except Exception:
                            pass
            return digest.hexdigest()[:16]
        except Exception as e:
            logger.debug(f"Could not fingerprint training split {data_yaml_path}: {e}")
            return ""

    def _training_eval_read_baseline_record(self, run_dir):
        path = self.normalize_path(os.path.join(self.normalize_path(run_dir), "baseline_validation.json"))
        if not path or not os.path.exists(path):
            return {}
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f) or {}
            if isinstance(data, dict):
                data["record_path"] = path
                return data
        except Exception as e:
            logger.debug(f"Could not read baseline validation record {path}: {e}")
        return {}

    def _training_eval_write_baseline_validation_record(self, run_dir, command=None, log_path=""):
        run_dir = self.normalize_path(run_dir)
        log_path = self.normalize_path(log_path or self._training_eval_log_path(run_dir))
        args = self._training_eval_run_args_from_log(log_path)
        if str(args.get("mode", "")).lower() != "val":
            return {}
        metrics = self._training_eval_parse_all_metric_from_log(log_path)
        if not metrics:
            return {}
        record = {
            "generated_by": "DarkFusion Training Evaluator",
            "generated_at": datetime.now().isoformat(timespec="seconds"),
            "run_dir": run_dir,
            "log_path": log_path,
            "args": args,
            "split_fingerprint": self._training_eval_data_split_fingerprint(args.get("data", "")),
            "metrics": metrics,
            "command": list(command or []),
        }
        path = os.path.join(run_dir, "baseline_validation.json").replace("\\", "/")
        try:
            with open(path, "w", encoding="utf-8") as f:
                json.dump(record, f, indent=2)
            record["record_path"] = self.normalize_path(path)
            self._training_eval_baseline_validation_cache = {}
            return record
        except Exception as e:
            logger.warning(f"Could not write baseline validation record: {e}")
            return {}

    def _training_eval_baseline_candidate_record(self, run_dir):
        record = self._training_eval_read_baseline_record(run_dir)
        if record:
            return {
                "run_dir": self.normalize_path(record.get("run_dir", "") or run_dir),
                "log_path": self.normalize_path(record.get("log_path", "") or self._training_eval_log_path(run_dir)),
                "args": record.get("args", {}) or {},
                "split_fingerprint": record.get("split_fingerprint", ""),
                "metrics": record.get("metrics", {}) or {},
                "record_path": record.get("record_path", ""),
            }
        log_path = os.path.join(self.normalize_path(run_dir), "darkfusion_console.log")
        if not os.path.exists(log_path):
            return {}
        args = self._training_eval_run_args_from_log(log_path)
        if str(args.get("mode", "")).lower() != "val":
            return {}
        metrics = self._training_eval_parse_all_metric_from_log(log_path)
        if not metrics:
            return {}
        return {
            "run_dir": self.normalize_path(run_dir),
            "log_path": self.normalize_path(log_path),
            "args": args,
            "split_fingerprint": "",
            "metrics": metrics,
        }

    def _training_eval_find_matching_baseline_validation_for_args(self, target_args, reference_run_dir="", reference_time=None):
        target_args = dict(target_args or {})
        target_data = target_args.get("data", "")
        target_model = target_args.get("model", "")
        target_imgsz = str(target_args.get("imgsz", "") or "").strip()
        target_split_fingerprint = str(target_args.get("split_fingerprint", "") or "").strip()
        if not target_split_fingerprint and target_data:
            target_split_fingerprint = self._training_eval_data_split_fingerprint(target_data)
        if not target_data or not target_model or not target_imgsz:
            return {}

        reference_run_dir = self.normalize_path(reference_run_dir)
        reference_time = float(reference_time or (self._training_eval_run_modified_time(reference_run_dir) if reference_run_dir else 0.0) or time.time())
        cache_key = (
            os.path.normcase(os.path.abspath(reference_run_dir)) if reference_run_dir else "current",
            self._training_eval_resolve_compare_path(target_data, APP_DIR),
            self._training_eval_resolve_compare_path(target_model, APP_DIR),
            target_imgsz,
            round(float(reference_time), 3),
        )
        now = time.time()
        cache = getattr(self, "_training_eval_baseline_validation_cache", {}) or {}
        cached = cache.get(cache_key)
        if isinstance(cached, dict) and now - float(cached.get("at", 0.0) or 0.0) < 30.0:
            return dict(cached.get("record") or {})

        best = {}
        best_distance = None
        checked = 0
        max_checked = 5000

        for root in self._training_eval_candidate_run_roots():
            root = self.normalize_path(root)
            if not root or not os.path.isdir(root):
                continue
            try:
                for current, dirs, files in os.walk(root):
                    checked += 1
                    if checked > max_checked:
                        break
                    current = self.normalize_path(current)
                    rel = os.path.relpath(current, root)
                    depth = 0 if rel == "." else rel.count(os.sep) + 1
                    if depth >= 4:
                        dirs[:] = []
                    dirs[:] = [
                        d for d in dirs
                        if d.lower() not in {"weights", "__pycache__"} and not d.startswith(".")
                    ]
                    record = self._training_eval_baseline_candidate_record(current)
                    if not record:
                        continue
                    args = record.get("args", {}) or {}
                    if str(args.get("mode", "")).lower() != "val":
                        continue
                    if not self._training_eval_compare_arg_match(target_data, args.get("data", ""), APP_DIR, kind="data"):
                        continue
                    if not self._training_eval_compare_arg_match(target_model, args.get("model", ""), APP_DIR, kind="model"):
                        continue
                    if str(args.get("imgsz", "")).strip() != target_imgsz:
                        continue
                    record_split_fingerprint = str(record.get("split_fingerprint", "") or args.get("split_fingerprint", "") or "").strip()
                    if target_split_fingerprint and record_split_fingerprint and record_split_fingerprint != target_split_fingerprint:
                        continue
                    metrics = record.get("metrics", {}) or {}
                    log_path = self.normalize_path(record.get("log_path", ""))
                    modified = self._training_eval_run_modified_time(current)
                    if not modified and log_path and os.path.exists(log_path):
                        modified = os.path.getmtime(log_path)
                    if not modified:
                        modified = time.time()
                    distance = abs(modified - reference_time)
                    if best_distance is None or distance < best_distance:
                        best_distance = distance
                        best = dict(record)
            except Exception as e:
                logger.debug(f"Could not scan baseline validation under {root}: {e}")
        cache[cache_key] = {"at": now, "record": dict(best)}
        self._training_eval_baseline_validation_cache = cache
        return best

    def _training_eval_find_matching_baseline_validation(self, train_run_dir, train_args=None):
        train_run_dir = self.normalize_path(train_run_dir)
        train_args = dict(train_args or self._training_eval_run_args_for_compare(train_run_dir) or {})
        return self._training_eval_find_matching_baseline_validation_for_args(
            train_args,
            reference_run_dir=train_run_dir,
        )

    def _training_eval_find_matching_baseline_for_result(self, result):
        return self._training_eval_find_matching_baseline_validation_for_args(
            self._training_eval_baseline_args_from_result(result),
            reference_time=time.time(),
        )

    def _training_eval_format_baseline_status(self, result=None):
        target_args = self._training_eval_baseline_args_from_result(result or {})
        data_yaml = self.normalize_path(target_args.get("data", ""))
        model_path = self.normalize_path(target_args.get("model", ""))
        imgsz = str(target_args.get("imgsz", "") or "").strip()
        if not data_yaml or not model_path or not imgsz:
            return "Baseline: evaluate dataset and select weights first.", ""

        model_name = os.path.basename(model_path) or model_path
        baseline = self._training_eval_find_matching_baseline_validation_for_args(target_args, reference_time=time.time())
        metrics = (baseline or {}).get("metrics", {}) if isinstance(baseline, dict) else {}
        if metrics:
            map5095 = metrics.get("map5095")
            map50 = metrics.get("map50")
            precision = metrics.get("precision")
            recall = metrics.get("recall")
            text = (
                f"Baseline: {model_name} @ {imgsz} | "
                f"mAP50-95 {float(map5095):.3f} | mAP50 {float(map50):.3f} | current"
            )
            tooltip = (
                f"Baseline validation is matched to this model, data YAML, image size, and split.\n"
                f"Precision: {float(precision):.3f}\n"
                f"Recall: {float(recall):.3f}\n"
                f"Run: {baseline.get('run_dir', '')}\n"
                f"Log: {baseline.get('log_path', '')}"
            )
            return text, tooltip

        text = f"Baseline: missing for {model_name} @ {imgsz}. Run Validate Weights."
        tooltip = "No matching validation baseline was found for the current model, obj.yaml split, and image size."
        return text, tooltip

    def _training_eval_update_baseline_widget(self, widgets, result=None):
        widgets = widgets or {}
        label = widgets.get("baseline_label")
        if label is None or sip.isdeleted(label):
            return
        text, tooltip = self._training_eval_format_baseline_status(result or getattr(self, "training_evaluator_last_result", None) or {})
        label.setText(text)
        label.setToolTip(tooltip)

    def _training_eval_baseline_run_name(self, result=None, force_cpu=False):
        rec = (result or {}).get("recommendations", {}) if isinstance(result, dict) else {}
        model_path = self.normalize_path(
            rec.get("weights_path", "") or self._training_eval_model_path(result, prefer_recommendation=True)
        )
        model_stem = os.path.splitext(os.path.basename(str(model_path or "weights")))[0]
        model_stem = re.sub(r"[^a-zA-Z0-9_.-]+", "_", model_stem).strip("._-") or "weights"
        imgsz = str(rec.get("imgsz", "") or self._parse_training_imgsz_value())
        device = "cpu" if force_cpu else "gpu"
        return f"baseline_{device}_{model_stem}_{imgsz}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"

    def _training_eval_run_data_yaml_path(self, run_dir):
        args, _args_path = self._training_eval_read_args_yaml(run_dir)
        data_yaml = self.normalize_path(args.get("data", "") if isinstance(args, dict) else "")
        if data_yaml and os.path.exists(data_yaml):
            return data_yaml
        if data_yaml and not os.path.isabs(data_yaml):
            for base in (APP_DIR, run_dir, os.getcwd()):
                candidate = self.normalize_path(os.path.join(base, data_yaml))
                if os.path.exists(candidate):
                    return candidate
        return ""

    def _training_eval_results_diagnosis(self, headers, rows, run_dir=""):
        if not rows:
            return {
                "state": "idle",
                "title": "Waiting for metrics",
                "detail": "No results.csv rows yet.",
                "issues": [],
            }

        issues = []
        advice = []

        def add(severity, text):
            issues.append({"severity": severity, "text": text})

        train_args = self._training_eval_run_args_for_compare(run_dir) if run_dir else {}
        if train_args and not train_args.get("split_fingerprint") and train_args.get("data"):
            train_args["split_fingerprint"] = self._training_eval_data_split_fingerprint(train_args.get("data", ""))
        data_yaml = self._training_eval_run_data_yaml_path(run_dir)
        split_report = self._training_eval_yaml_split_report(data_yaml) if data_yaml else {}
        if split_report:
            train_images = int(split_report.get("train_images", 0) or 0)
            valid_images = int(split_report.get("valid_images", 0) or 0)
            overlap = int(split_report.get("overlap_images", 0) or 0)
            if not valid_images:
                add("error", "No validation images found")
            elif split_report.get("same_split"):
                add("error", "Train and validation use the same images")
            elif overlap:
                ratio = overlap / max(1, valid_images)
                severity = "error" if ratio >= 0.5 else "warning"
                add(severity, f"{overlap} validation image(s) also appear in train")
            missing_valid = split_report.get("missing_valid", []) or []
            if missing_valid:
                severity = "warning" if len(missing_valid) < max(3, train_images // 20) else "error"
                preview = ", ".join(str(row.get("class_name")) for row in missing_valid[:4])
                add(severity, f"{len(missing_valid)} class(es) missing from validation: {preview}")

        row_count = len(rows)
        map5095_key = self._training_eval_metric_header(headers, required=("metrics/",), any_of=("map50-95", "map50_95"))
        map50_key = self._training_eval_metric_header(headers, required=("metrics/", "map50"), rejected=("50-95", "50_95"))
        precision_key = self._training_eval_metric_header(headers, required=("metrics/", "precision"))
        recall_key = self._training_eval_metric_header(headers, required=("metrics/", "recall"))

        map5095_values = self._training_eval_metric_values_for_header(rows, map5095_key)
        map50_values = self._training_eval_metric_values_for_header(rows, map50_key)
        precision_values = self._training_eval_metric_values_for_header(rows, precision_key)
        recall_values = self._training_eval_metric_values_for_header(rows, recall_key)
        train_loss_values = self._training_eval_loss_values(headers, rows, "train/")
        val_loss_values = self._training_eval_loss_values(headers, rows, "val/")

        last_map5095 = self._training_eval_last_number(map5095_values)
        last_map50 = self._training_eval_last_number(map50_values)
        last_precision = self._training_eval_last_number(precision_values)
        last_recall = self._training_eval_last_number(recall_values)
        best_snapshot = self._training_eval_best_metric_snapshot(headers, rows)
        best_map5095 = best_snapshot.get("map5095")
        best_epoch = best_snapshot.get("epoch")
        baseline_comparison = {}
        if run_dir and best_snapshot:
            baseline = self._training_eval_find_matching_baseline_validation(run_dir, train_args)
            baseline_metrics = (baseline or {}).get("metrics", {}) if isinstance(baseline, dict) else {}
            baseline_map5095 = baseline_metrics.get("map5095")
            if baseline_map5095 is not None and best_map5095 is not None:
                delta = float(best_map5095) - float(baseline_map5095)
                baseline_comparison = {
                    "run_dir": baseline.get("run_dir", ""),
                    "log_path": baseline.get("log_path", ""),
                    "baseline": baseline_metrics,
                    "best": best_snapshot,
                    "delta_map5095": round(delta, 4),
                }
                if delta < -0.005:
                    add("warning", f"Pretrained baseline beats trained best by {abs(delta):.3f} mAP50-95")
                    advice.append("Keep the baseline or restart from the last good checkpoint with a much lower learning rate.")
                elif delta < 0.025:
                    add("info", f"Fine-tune only slightly beats baseline (+{delta:.3f} mAP50-95)")
                    advice.append("Use a short refresh fine-tune and keep best.pt; longer training is unlikely to help without new/cleaner data.")
                else:
                    add("info", f"Fine-tune beats baseline by {delta:.3f} mAP50-95")

        if row_count < 3:
            add("info", "Collecting more epochs before strong diagnosis")

        if row_count >= 4 and last_map5095 is not None:
            if best_map5095 is None:
                best_map5095 = max(value for value in map5095_values if value is not None)
            drop = best_map5095 - last_map5095
            if drop >= 0.15:
                add("error", f"mAP50-95 dropped {drop:.3f} from best")
            elif drop >= 0.07:
                add("warning", f"mAP50-95 dropped {drop:.3f} from best")

        train_start = self._training_eval_window_mean(train_loss_values, take_last=False)
        train_end = self._training_eval_window_mean(train_loss_values, take_last=True)
        val_start = self._training_eval_window_mean(val_loss_values, take_last=False)
        val_end = self._training_eval_window_mean(val_loss_values, take_last=True)
        if row_count >= 5 and None not in (train_start, train_end, val_start, val_end):
            train_improving = train_end < train_start * 0.92
            val_worse = val_end > val_start * 1.10
            if train_improving and val_worse:
                severity = "error" if val_end > val_start * 1.25 else "warning"
                add(severity, "Training loss is falling while validation loss is rising")
            elif last_map50 is not None and last_map50 < 0.30 and train_end >= train_start * 0.97:
                add("warning", "Low mAP with little train-loss improvement")

            early_best = best_epoch is not None and float(best_epoch) <= max(1.0, min(3.0, row_count * 0.2))
            best_drop = (float(best_map5095) - float(last_map5095)) if best_map5095 is not None and last_map5095 is not None else 0.0
            if early_best and best_drop >= 0.05 and (train_improving or val_worse):
                add("warning", "Refresh fine-tune pattern: best validation arrived very early")
                model_arg = str(train_args.get("model", "") or "")
                custom_weights = bool(model_arg and not self._looks_like_official_ultralytics_weight(model_arg))
                refresh_lr = 0.0005 if custom_weights else 0.001
                advice.insert(0,
                    "Refresh fine-tune suggestion: start from the best/current weights with "
                    f"epochs=10-20 patience=5 lr0={refresh_lr:g} lrf=0.05 warmup_epochs=1 "
                    "freeze=10 mosaic=0 close_mosaic=0 cache=False."
                )

        if last_precision is not None and last_recall is not None:
            gap = abs(last_precision - last_recall)
            if gap >= 0.35:
                direction = "recall is low" if last_precision > last_recall else "precision is low"
                add("error", f"Precision/recall imbalance: {direction}")
            elif gap >= 0.20:
                direction = "recall is low" if last_precision > last_recall else "precision is low"
                add("warning", f"Precision/recall imbalance: {direction}")

        if last_map50 is not None and last_map5095 is not None and last_map50 >= 0.45:
            gap = last_map50 - last_map5095
            if gap >= 0.45:
                add("error", f"mAP50 vs mAP50-95 gap is large ({gap:.3f})")
            elif gap >= 0.30:
                add("warning", f"mAP50 vs mAP50-95 gap is wide ({gap:.3f})")

        if row_count >= 5 and last_map50 is not None and last_map5095 is not None:
            if last_map50 < 0.25 and last_map5095 < 0.12:
                add("warning", "Metrics are still very low after several epochs")

        severity_order = {"error": 3, "warning": 2, "info": 1}
        worst = max((severity_order.get(issue.get("severity"), 0) for issue in issues), default=0)
        if worst >= 3:
            state = "error"
            title = "Training needs attention"
        elif worst == 2:
            state = "warning"
            title = "Training watch"
        elif worst == 1:
            state = "info"
            title = "Collecting signal"
        else:
            state = "success"
            title = "Training looks good"

        if not issues and row_count >= 3:
            detail = "Validation, losses, and score curves are not showing obvious problems."
        else:
            detail_parts = [issue["text"] for issue in issues[:2]]
            if advice:
                detail_parts.append(f"Advice: {advice[0]}")
            else:
                detail_parts.extend(issue["text"] for issue in issues[2:3])
            detail = "; ".join(detail_parts)
        return {
            "state": state,
            "title": title,
            "detail": detail,
            "issues": issues,
            "advice": advice,
            "best_metrics": best_snapshot,
            "baseline_comparison": baseline_comparison,
            "split_report": split_report,
            "data_yaml": data_yaml,
        }

    def _training_eval_update_diagnosis_widgets(self, widgets, diagnosis):
        widgets = widgets or {}
        diagnosis = diagnosis or {}
        state = str(diagnosis.get("state") or "idle")
        colors = {
            "success": ("#38d978", "rgba(56, 217, 120, 0.16)"),
            "warning": ("#f0b84c", "rgba(240, 184, 76, 0.16)"),
            "error": ("#ff5c78", "rgba(255, 92, 120, 0.16)"),
            "info": ("#4fa3ff", "rgba(79, 163, 255, 0.16)"),
            "idle": ("#7c8794", "rgba(124, 135, 148, 0.12)"),
        }
        color, background = colors.get(state, colors["idle"])
        panel = widgets.get("diagnosis_panel")
        if panel is not None and not sip.isdeleted(panel):
            panel.setStyleSheet(
                "QFrame#trainingDiagnosisPanel {"
                f"border: 1px solid {color};"
                f"background: {background};"
                "border-radius: 8px;"
                "}"
            )
        light = widgets.get("diagnosis_light")
        if light is not None and not sip.isdeleted(light):
            light.setStyleSheet(
                f"background: {color}; border-radius: 7px; min-width: 14px; max-width: 14px;"
                f"min-height: 14px; max-height: 14px; border: 1px solid {color};"
            )
        title = widgets.get("diagnosis_title")
        if title is not None and not sip.isdeleted(title):
            title.setText(str(diagnosis.get("title") or "Waiting for metrics"))
            title.setStyleSheet(f"font-weight: 800; color: {color};")
        detail = widgets.get("diagnosis_detail")
        if detail is not None and not sip.isdeleted(detail):
            detail.setText(str(diagnosis.get("detail") or ""))
            tooltip_lines = [issue.get("text", "") for issue in diagnosis.get("issues", []) or []]
            tooltip_lines.extend(str(item) for item in diagnosis.get("advice", []) or [] if item)
            detail.setToolTip("\n".join(line for line in tooltip_lines if line))

    def _training_eval_artifact_images(self, run_dir):
        run_dir = self.normalize_path(run_dir)
        if not run_dir or not os.path.isdir(run_dir):
            return []

        paths = []
        for pattern in ("*.png", "*.jpg", "*.jpeg"):
            paths.extend(glob.glob(os.path.join(run_dir, pattern)))

        def priority(path):
            name = os.path.basename(path).lower()
            order = 50
            if name == "results.png":
                order = 0
            elif "confusion_matrix" in name:
                order = 4
            elif "pr_curve" in name:
                order = 8
            elif "f1_curve" in name:
                order = 9
            elif "val_batch" in name and "pred" in name:
                order = 12
            elif "val_batch" in name and "label" in name:
                order = 13
            elif "train_batch" in name:
                order = 16
            return (order, os.path.basename(path).lower())

        return sorted({self.normalize_path(path) for path in paths}, key=priority)

    def _training_eval_set_artifact_preview(self, combo, label):
        if combo is None or label is None or sip.isdeleted(combo) or sip.isdeleted(label):
            return
        path = combo.currentData()
        if not path or not os.path.exists(path):
            label.setText("No visual artifact yet")
            label.setPixmap(QPixmap())
            label.setToolTip("")
            return
        pixmap = QPixmap(path)
        if pixmap.isNull():
            label.setText(f"Could not load {os.path.basename(path)}")
            label.setPixmap(QPixmap())
            label.setToolTip(path)
            return
        label.setText("")
        label.setToolTip("Double-click to open a zoomable viewer.")
        target_size = label.size()
        if target_size.width() < 40 or target_size.height() < 40:
            target_size = QtCore.QSize(520, 260)
        label.setPixmap(pixmap.scaled(target_size, Qt.KeepAspectRatio, Qt.SmoothTransformation))

    def open_training_eval_artifact_viewer(self, path):
        path = self.normalize_path(path)
        if not path or not os.path.exists(path):
            QMessageBox.information(self, "Training Visual", "No visual artifact is selected yet.")
            return
        viewer = TrainingArtifactViewer(
            path,
            self,
            paths=self._training_eval_artifact_images(os.path.dirname(path)),
        )
        viewer.setAttribute(Qt.WA_DeleteOnClose, True)
        if self.styleSheet():
            viewer.setStyleSheet(self.styleSheet())
        if not isinstance(getattr(self, "training_artifact_viewers", None), list):
            self.training_artifact_viewers = []
        self.training_artifact_viewers.append(viewer)

        def cleanup(_obj=None, dialog=viewer):
            try:
                if dialog in self.training_artifact_viewers:
                    self.training_artifact_viewers.remove(dialog)
            except Exception:
                pass

        viewer.destroyed.connect(cleanup)
        viewer.show()
        viewer.raise_()
        viewer.activateWindow()

    def _training_eval_update_artifact_combo(self, combo, label, run_dir):
        if combo is None or label is None or sip.isdeleted(combo) or sip.isdeleted(label):
            return
        images = self._training_eval_artifact_images(run_dir)
        current = combo.currentData()
        existing = [combo.itemData(i) for i in range(combo.count())]
        if images != existing:
            combo.blockSignals(True)
            combo.clear()
            for path in images:
                combo.addItem(os.path.basename(path), path)
            if current and current in images:
                combo.setCurrentIndex(images.index(current))
            elif images:
                combo.setCurrentIndex(0)
            combo.blockSignals(False)
            self._training_eval_set_artifact_preview(combo, label)

    def _training_eval_set_activity_indicator(self, widgets, state="idle", label="", detail=""):
        indicator = (widgets or {}).get("activity_indicator")
        if indicator is not None and not sip.isdeleted(indicator) and hasattr(indicator, "set_state"):
            indicator.set_state(state, label=label, detail=detail)

    def _training_eval_activity_state(self, resume_info=None, message="", has_run=False, has_error=False):
        message_lower = str(message or "").lower()
        resume_info = resume_info or {}
        status = str(resume_info.get("status", "") or "").lower()
        exit_code = resume_info.get("exit_code", None)

        if has_error or "failed" in message_lower or "watch failed" in message_lower:
            return "error", "Error"
        if "running" in message_lower or status == "running":
            return "running", "Working"
        if exit_code not in (None, 0):
            return "error", "Error"
        if status in {"interrupted", "interrupted_no_checkpoint", "unknown"}:
            return "warning", "Needs attention"
        if "finished with exit code 0" in message_lower or status == "complete":
            return "success", "Ready"
        if has_run:
            return "success", "Ready"
        return "idle", "Idle"

    def _training_eval_refresh_run_widgets(
        self,
        widgets,
        run_dir,
        log_path,
        message="",
        include_diagnosis=True,
    ):
        widgets = widgets or {}
        run_dir = self.normalize_path(run_dir)
        log_path = self.normalize_path(log_path or self._training_eval_log_path(run_dir))
        resume_info = self._training_eval_resume_info({"run_dir": run_dir, "log_path": log_path})

        state_label = widgets.get("run_state_label")
        if state_label is not None and not sip.isdeleted(state_label):
            state_label.setText(message or "Run monitor active.")

        has_run = bool(run_dir and os.path.isdir(run_dir))
        state, label = self._training_eval_activity_state(resume_info, message, has_run=has_run)
        self._training_eval_set_activity_indicator(widgets, state, label, message or "")

        run_dir_label = widgets.get("run_dir_label")
        if run_dir_label is not None and not sip.isdeleted(run_dir_label):
            run_dir_label.setText(f"Run: {run_dir}" if run_dir else "Run: waiting for Ultralytics output")

        log_text = widgets.get("log_text")
        if log_text is not None and not sip.isdeleted(log_text):
            try:
                stat = os.stat(log_path)
                log_signature = (int(stat.st_size), int(stat.st_mtime_ns))
            except Exception:
                log_signature = None
            if log_signature and widgets.get("_log_signature") != log_signature:
                content = self._training_eval_read_text_tail(log_path, max_chars=40000)
                log_text.setPlainText(content)
                log_text.moveCursor(QTextCursor.End)
                widgets["_log_signature"] = log_signature

        csv_path = self.normalize_path(os.path.join(run_dir, "results.csv"))
        try:
            stat = os.stat(csv_path)
            csv_signature = (int(stat.st_size), int(stat.st_mtime_ns))
        except Exception:
            csv_signature = None
        metrics_changed = widgets.get("_csv_signature") != csv_signature
        if metrics_changed:
            headers, rows, csv_path = self._training_eval_read_results_csv(run_dir)
            widgets["_metrics_cache"] = (headers, rows, csv_path)
            widgets["_csv_signature"] = csv_signature
        else:
            headers, rows, csv_path = widgets.get("_metrics_cache", ([], [], csv_path if os.path.exists(csv_path) else ""))
        metrics_label = widgets.get("metrics_label")
        if metrics_label is not None and not sip.isdeleted(metrics_label):
            if rows:
                metrics_label.setText(f"{self._training_eval_latest_metric_line(headers, rows)}   ({len(rows)} CSV rows)")
            elif csv_path:
                metrics_label.setText("results.csv exists but has no rows yet.")
            else:
                metrics_label.setText("Waiting for results.csv. Validation runs may only write plots/log output.")
        self._training_eval_update_baseline_widget(widgets)

        resume_note_label = widgets.get("resume_note_label")
        if resume_note_label is not None and not sip.isdeleted(resume_note_label):
            note = str(resume_info.get("note", "") or "")
            if note and resume_info.get("status") in {"interrupted", "interrupted_no_checkpoint", "running"}:
                resume_note_label.setText(note)
                resume_note_label.show()
            else:
                resume_note_label.clear()
                resume_note_label.hide()

        resume_button = widgets.get("resume_button")
        if resume_button is not None and not sip.isdeleted(resume_button):
            resume_button.setEnabled(bool(resume_info.get("resumable")))
            resume_button.setToolTip(str(resume_info.get("note", "") or "Resume the last interrupted training run."))

        if metrics_changed:
            self._training_eval_update_metrics_table(widgets.get("metrics_table"), headers, rows)
        if metrics_changed and include_diagnosis:
            self._training_eval_update_diagnosis_widgets(
                widgets,
                self._training_eval_results_diagnosis(headers, rows, run_dir),
            )

        score_plot = widgets.get("score_plot")
        if metrics_changed and score_plot is not None and not sip.isdeleted(score_plot):
            score_plot.set_series(self._training_eval_metric_series(headers, rows, "score"), "mAP / Precision / Recall", value_range=(0.0, 1.0))

        loss_plot = widgets.get("loss_plot")
        if metrics_changed and loss_plot is not None and not sip.isdeleted(loss_plot):
            loss_plot.set_series(self._training_eval_metric_series(headers, rows, "loss"), "Training / Validation Loss")

        tabs = widgets.get("tabs")
        artifact_combo = widgets.get("artifact_combo")
        charts_tab = widgets.get("charts_tab")
        charts_visible = tabs is None or sip.isdeleted(tabs) or charts_tab is None or tabs.currentWidget() is charts_tab
        now = time.monotonic()
        if charts_visible and now - float(widgets.get("_artifact_refresh_at", 0.0) or 0.0) >= 5.0:
            widgets["_artifact_refresh_at"] = now
            self._training_eval_update_artifact_combo(artifact_combo, widgets.get("artifact_preview"), run_dir)

    def watch_training_evaluator_run(self, process, command, title, run_dir, log_path, widgets=None, status_label=None):
        if process is None:
            return

        self._training_eval_record_run(title, run_dir, log_path, command=command, process=process)
        timer = QTimer(self)
        timer.setInterval(2500)
        if not isinstance(getattr(self, "training_evaluator_run_timers", None), list):
            self.training_evaluator_run_timers = []
        self.training_evaluator_run_timers.append(timer)

        def widget_alive(widget):
            return widget is not None and not sip.isdeleted(widget)

        def poll():
            try:
                exit_code = process.poll()
            except Exception as e:
                timer.stop()
                if timer in self.training_evaluator_run_timers:
                    self.training_evaluator_run_timers.remove(timer)
                if widget_alive(status_label):
                    status_label.setText(f"{title} monitor failed: {e}")
                self._training_eval_set_activity_indicator(widgets, "error", "Error", f"{title} monitor failed")
                return

            running = exit_code is None
            state = f"{title} running..." if running else f"{title} finished with exit code {exit_code}."
            self._training_eval_refresh_run_widgets(widgets, run_dir, log_path, state)
            if widget_alive(status_label):
                status_label.setText(state)
            if not running:
                if exit_code == 0:
                    baseline_record = self._training_eval_write_baseline_validation_record(run_dir, command=command, log_path=log_path)
                    if baseline_record:
                        self._training_eval_update_baseline_widget(widgets)
                timer.stop()
                if timer in self.training_evaluator_run_timers:
                    self.training_evaluator_run_timers.remove(timer)

        timer.timeout.connect(poll)
        timer.start()
        QTimer.singleShot(250, poll)

    def _training_health_run_ultralytics_checks(self, timeout=45):
        command = [
            sys.executable,
            "-c",
            "from ultralytics.utils.checks import collect_system_info; collect_system_info()",
        ]
        try:
            completed = subprocess.run(
                command,
                cwd=APP_DIR,
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=max(5, int(timeout)),
            )
            output = "\n".join(
                part.strip()
                for part in (completed.stdout, completed.stderr)
                if part and part.strip()
            ).strip()
            return completed.returncode == 0, output or "Ultralytics checks completed with no console output."
        except subprocess.TimeoutExpired as e:
            output = "\n".join(
                str(part).strip()
                for part in (getattr(e, "stdout", ""), getattr(e, "stderr", ""))
                if part and str(part).strip()
            ).strip()
            return False, f"Ultralytics checks timed out after {timeout} seconds.\n{output}".strip()
        except Exception as e:
            return False, f"Could not run Ultralytics checks with {sys.executable}: {e}"

    def _training_health_status_line(self, status, label, detail=""):
        icon = {
            "ok": "OK",
            "warn": "WARN",
            "fail": "FAIL",
        }.get(str(status).lower(), "INFO")
        detail = str(detail or "").strip()
        return f"[{icon}] {label}" + (f": {detail}" if detail else "")

    def _training_health_writable_dir(self, directory):
        directory = self.normalize_path(directory or "")
        if not directory or not os.path.isdir(directory):
            return False, "folder not found"
        probe_path = os.path.join(directory, ".darkfusion_health_write_test.tmp")
        try:
            with open(probe_path, "w", encoding="utf-8") as f:
                f.write("ok")
            os.remove(probe_path)
            return True, directory
        except Exception as e:
            try:
                if os.path.exists(probe_path):
                    os.remove(probe_path)
            except Exception:
                pass
            return False, str(e)

    def _training_health_parse_data_yaml(self, data_yaml_path):
        data_yaml_path = self.normalize_path(data_yaml_path or "")
        if not data_yaml_path or not os.path.exists(data_yaml_path):
            return {}, ""
        try:
            with open(data_yaml_path, "r", encoding="utf-8", errors="ignore") as f:
                data = yaml.safe_load(f) or {}
            return data if isinstance(data, dict) else {}, os.path.dirname(data_yaml_path)
        except Exception:
            return {}, os.path.dirname(data_yaml_path)

    def _training_health_dataset_dir(self, data_yaml_path="", yaml_data=None, yaml_dir=""):
        data_yaml_path = self.normalize_path(data_yaml_path or "")
        yaml_data = yaml_data if isinstance(yaml_data, dict) else {}
        yaml_dir = self.normalize_path(yaml_dir or (os.path.dirname(data_yaml_path) if data_yaml_path else ""))

        candidates = []
        for value in (
            yaml_data.get("path"),
            getattr(self, "image_directory", None),
            getattr(self, "output_path", None),
            yaml_dir,
        ):
            value = self.normalize_path(value or "")
            if not value:
                continue
            if not os.path.isabs(value) and yaml_dir:
                value = self.normalize_path(os.path.join(yaml_dir, value))
            if os.path.isdir(value):
                candidates.append(value)

        return candidates[0] if candidates else (yaml_dir if yaml_dir and os.path.isdir(yaml_dir) else "")

    def _training_health_find_classes_file(self, dataset_dir="", data_yaml_path="", yaml_data=None):
        yaml_data = yaml_data if isinstance(yaml_data, dict) else {}
        names = yaml_data.get("names")
        if isinstance(names, (list, tuple, dict)) and names:
            return "", f"names found in YAML ({len(names)} classes)"

        candidates = []
        for directory in (
            dataset_dir,
            os.path.dirname(self.normalize_path(data_yaml_path or "")),
            getattr(self, "image_directory", None),
            getattr(self, "output_path", None),
            APP_DIR,
        ):
            directory = self.normalize_path(directory or "")
            if directory:
                candidates.append(os.path.join(directory, "classes.txt"))

        for path in candidates:
            if path and os.path.exists(path):
                return self.normalize_path(path), "classes.txt found"
        return "", "classes.txt missing and YAML names not found"

    def _training_health_find_points_file(self, dataset_dir="", model_path="", data_yaml_path=""):
        candidates = []
        for directory in (
            dataset_dir,
            os.path.dirname(self.normalize_path(data_yaml_path or "")),
            os.path.dirname(self.normalize_path(model_path or "")),
            getattr(self, "image_directory", None),
            getattr(self, "output_path", None),
            APP_DIR,
        ):
            directory = self.normalize_path(directory or "")
            if directory:
                candidates.extend([
                    os.path.join(directory, "points.json"),
                    os.path.join(directory, PROJECT_SETTINGS_DIR, "points.json"),
                ])

        seen = set()
        for path in candidates:
            key = os.path.normcase(self.normalize_path(path))
            if key in seen:
                continue
            seen.add(key)
            if os.path.exists(path):
                return self.normalize_path(path)
        return ""

    def _training_health_engine_paths(self, model_path="", data_yaml_path="", runs_dir=""):
        roots = []
        for path in (
            model_path,
            getattr(self, "weights_file_path", None),
            getattr(self, "loaded_model_path", None),
        ):
            path = self.normalize_path(path or "")
            if path.lower().endswith(".engine") and os.path.exists(path):
                roots.append(path)
            elif path and os.path.isdir(path):
                roots.append(path)
            elif path:
                parent = os.path.dirname(path)
                if parent:
                    roots.append(parent)

        for directory in (
            runs_dir,
            os.path.dirname(self.normalize_path(data_yaml_path or "")),
            os.path.join(APP_DIR, "weights"),
            APP_DIR,
        ):
            directory = self.normalize_path(directory or "")
            if directory:
                roots.append(directory)

        engines = []
        seen_roots = set()
        for root in roots:
            root = self.normalize_path(root)
            if not root:
                continue
            if os.path.isfile(root) and root.lower().endswith(".engine"):
                engines.append(root)
                continue
            if not os.path.isdir(root):
                continue
            root_key = os.path.normcase(os.path.abspath(root))
            if root_key in seen_roots:
                continue
            seen_roots.add(root_key)
            try:
                engines.extend(self.normalize_path(path) for path in glob.glob(os.path.join(root, "*.engine")))
            except Exception:
                continue

        seen = set()
        unique = []
        for path in engines:
            key = os.path.normcase(os.path.abspath(path))
            if key not in seen and os.path.exists(path):
                seen.add(key)
                unique.append(path)
        return unique

    def build_training_health_report(self, data_yaml_path="", model_path="", pretrained_path="", runs_dir="", task="detect"):
        data_yaml_path = self.normalize_path(data_yaml_path or getattr(self, "data_yaml_path", "") or "")
        model_path = self.normalize_path(model_path or getattr(self, "pt_path", "") or getattr(self, "model_config_path", "") or "")
        pretrained_path = self.normalize_path(pretrained_path or getattr(self, "pretrained_model_path", "") or "")
        runs_dir = self.normalize_path(runs_dir or getattr(self, "runs_directory", "") or "")
        task = str(task or "detect").strip().lower()

        lines = [
            "DarkFusion Training Health Check",
            f"Python: {sys.executable}",
            f"Time: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
            "",
            "Core Checks",
        ]

        cuda_ok = bool(torch.cuda.is_available())
        lines.append(self._training_health_status_line("ok" if cuda_ok else "warn", "CUDA available", str(cuda_ok)))
        if cuda_ok:
            try:
                gpu_name = torch.cuda.get_device_name(0)
                props = torch.cuda.get_device_properties(0)
                total_gb = float(getattr(props, "total_memory", 0) or 0) / (1024 ** 3)
                lines.append(self._training_health_status_line("ok", "GPU", f"{gpu_name} ({total_gb:.1f} GB VRAM)"))
            except Exception as e:
                lines.append(self._training_health_status_line("warn", "GPU name/VRAM", str(e)))
        else:
            lines.append(self._training_health_status_line("warn", "GPU", "training will run on CPU or fail for CUDA-only paths"))

        torch_cuda_version = getattr(torch.version, "cuda", None) or "not built with CUDA"
        lines.append(self._training_health_status_line("ok" if torch_cuda_version != "not built with CUDA" else "warn", "PyTorch CUDA version", torch_cuda_version))

        try:
            import ultralytics
            lines.append(self._training_health_status_line("ok", "Ultralytics import", getattr(ultralytics, "__version__", "unknown")))
        except Exception as e:
            lines.append(self._training_health_status_line("fail", "Ultralytics import", str(e)))

        yaml_data, yaml_dir = self._training_health_parse_data_yaml(data_yaml_path)
        dataset_dir = self._training_health_dataset_dir(data_yaml_path, yaml_data, yaml_dir)

        if data_yaml_path:
            lines.append(self._training_health_status_line("ok" if os.path.exists(data_yaml_path) else "fail", "Data YAML", data_yaml_path))
        else:
            lines.append(self._training_health_status_line("warn", "Data YAML", "not selected"))

        if model_path:
            lines.append(self._training_health_status_line("ok" if os.path.exists(model_path) else "fail", "Model", model_path))
        else:
            lines.append(self._training_health_status_line("warn", "Model", "not selected"))

        if model_path.lower().endswith((".yaml", ".yml")) and pretrained_path:
            lines.append(self._training_health_status_line("ok" if os.path.exists(pretrained_path) else "fail", "Pretrained weights", pretrained_path))

        if bool(getattr(self, "ultralytics_distill_enabled", False)):
            distill_path = self.normalize_path(getattr(self, "ultralytics_distill_model_path", "") or "")
            if not self.ultralytics_version_at_least("8.4.77"):
                lines.append(self._training_health_status_line("fail", "Knowledge Distillation", "requires Ultralytics v8.4.77+"))
            elif distill_path and (os.path.exists(distill_path) or self._looks_like_ultralytics_model_reference(distill_path)):
                lines.append(self._training_health_status_line("ok", "Knowledge Distillation teacher", distill_path))
            elif distill_path:
                lines.append(self._training_health_status_line("fail", "Knowledge Distillation teacher", f"missing: {distill_path}"))
            else:
                lines.append(self._training_health_status_line("fail", "Knowledge Distillation teacher", "enabled but no teacher model selected"))
            if task != "detect":
                lines.append(self._training_health_status_line("warn", "Knowledge Distillation task", "Ultralytics benchmarks detect first; this task is less validated"))
        else:
            lines.append(self._training_health_status_line("ok", "Knowledge Distillation", "off"))

        if dataset_dir:
            writable, detail = self._training_health_writable_dir(dataset_dir)
            lines.append(self._training_health_status_line("ok" if writable else "fail", "Writable dataset folder", detail))
        else:
            lines.append(self._training_health_status_line("warn", "Writable dataset folder", "dataset folder could not be resolved"))

        if runs_dir:
            writable, detail = self._training_health_writable_dir(runs_dir)
            lines.append(self._training_health_status_line("ok" if writable else "warn", "Writable runs folder", detail))
        else:
            lines.append(self._training_health_status_line("warn", "Writable runs folder", "not selected; Ultralytics will choose default project path"))

        classes_path, classes_detail = self._training_health_find_classes_file(dataset_dir, data_yaml_path, yaml_data)
        lines.append(self._training_health_status_line("ok" if classes_path or "names found" in classes_detail else "fail", "Classes", classes_path or classes_detail))

        points_path = self._training_health_find_points_file(dataset_dir, model_path, data_yaml_path)
        points_required = task in {"pose", "keypoint", "keypoints"}
        points_status = "ok" if points_path else ("fail" if points_required else "warn")
        points_detail = points_path or ("required for pose training" if points_required else "not found; only needed for pose/keypoints")
        lines.append(self._training_health_status_line(points_status, "points.json", points_detail))

        engines = self._training_health_engine_paths(model_path, data_yaml_path, runs_dir)
        if engines:
            preview = ", ".join(os.path.basename(path) for path in engines[:5])
            if len(engines) > 5:
                preview += f", +{len(engines) - 5} more"
            lines.append(self._training_health_status_line("ok", "TensorRT engines", preview))
        else:
            lines.append(self._training_health_status_line("warn", "TensorRT engines", "none found near selected model, runs folder, or app weights"))

        lines.extend(["", "Ultralytics yolo checks"])
        yolo_ok, yolo_output = self._training_health_run_ultralytics_checks()
        lines.append(self._training_health_status_line("ok" if yolo_ok else "fail", "Ultralytics checks command", "completed" if yolo_ok else "failed"))
        lines.append("")
        lines.append(yolo_output)
        return "\n".join(lines)

    def _ensure_validation_review_dock(self):
        dock = getattr(self, "validation_review_dock", None)
        if dock is not None and not sip.isdeleted(dock):
            return dock

        dock = QtWidgets.QDockWidget("Validation Review", self)
        dock.setObjectName("validationReviewDock")
        dock.setAllowedAreas(Qt.LeftDockWidgetArea | Qt.RightDockWidgetArea)
        dock.setFeatures(
            QtWidgets.QDockWidget.DockWidgetClosable
            | QtWidgets.QDockWidget.DockWidgetMovable
            | QtWidgets.QDockWidget.DockWidgetFloatable
        )
        panel = QtWidgets.QWidget()
        panel_layout = QtWidgets.QVBoxLayout(panel)
        panel_layout.setContentsMargins(10, 10, 10, 10)
        panel_layout.setSpacing(8)

        self.validation_review_position_label = QtWidgets.QLabel("0 / 0")
        self.validation_review_position_label.setStyleSheet("font-weight: 800;")
        self.validation_review_detail_label = QtWidgets.QLabel("No validation issue selected.")
        self.validation_review_detail_label.setWordWrap(True)
        self.validation_review_detail_label.setTextInteractionFlags(Qt.TextSelectableByMouse)
        panel_layout.addWidget(self.validation_review_position_label)
        panel_layout.addWidget(self.validation_review_detail_label)

        panel_layout.addWidget(QtWidgets.QLabel("Legend"))
        self.validation_review_gt_checkbox = QtWidgets.QCheckBox("■  Ground truth")
        self.validation_review_gt_checkbox.setChecked(True)
        self.validation_review_gt_checkbox.setStyleSheet("color: #45d483; font-weight: 700;")
        self.validation_review_pred_checkbox = QtWidgets.QCheckBox("■  Prediction")
        self.validation_review_pred_checkbox.setChecked(True)
        self.validation_review_pred_checkbox.setStyleSheet("color: #ff5968; font-weight: 700;")
        missed_label = QtWidgets.QLabel("■  Missed label")
        missed_label.setStyleSheet("color: #ff9f43; font-weight: 700;")
        weak_label = QtWidgets.QLabel("■  Weak match")
        weak_label.setStyleSheet("color: #f0d264; font-weight: 700;")
        panel_layout.addWidget(self.validation_review_gt_checkbox)
        panel_layout.addWidget(self.validation_review_pred_checkbox)
        panel_layout.addWidget(missed_label)
        panel_layout.addWidget(weak_label)
        panel_layout.addStretch(1)

        navigation = self._row_layout(6)
        previous_button = QtWidgets.QPushButton("Previous Issue")
        next_button = QtWidgets.QPushButton("Next Issue")
        navigation.addWidget(previous_button)
        navigation.addWidget(next_button)
        panel_layout.addLayout(navigation)
        keep_button = QtWidgets.QPushButton("Keep Label / Model Was Wrong")
        edit_button = QtWidgets.QPushButton("Edit Label")
        quarantine_button = QtWidgets.QPushButton("Quarantine Image")
        ignore_button = QtWidgets.QPushButton("Ignore Issue")
        back_button = QtWidgets.QPushButton("Back to Dataset")
        panel_layout.addWidget(keep_button)
        panel_layout.addWidget(edit_button)
        panel_layout.addWidget(quarantine_button)
        panel_layout.addWidget(ignore_button)
        panel_layout.addWidget(back_button)

        dock.setWidget(panel)
        self.addDockWidget(Qt.RightDockWidgetArea, dock)
        self.validation_review_dock = dock
        self.register_dock_context_help(
            dock,
            "Validation Review dock",
            (
                "Explains the currently selected validation problem and lets you compare "
                "ground truth with predictions, navigate issues, edit or keep labels, "
                "quarantine images, and return to the dataset."
            ),
            "11-review-the-trained-model",
        )
        dock.hide()

        previous_button.clicked.connect(lambda: self.navigate_validation_review_issue(-1))
        next_button.clicked.connect(lambda: self.navigate_validation_review_issue(1))
        keep_button.clicked.connect(lambda: self.set_current_validation_review_status("reviewed"))
        ignore_button.clicked.connect(lambda: self.set_current_validation_review_status("ignored"))
        edit_button.clicked.connect(lambda: self.screen_view.setFocus() if getattr(self, "screen_view", None) is not None else None)
        quarantine_button.clicked.connect(self.quarantine_current_validation_review_image)
        back_button.clicked.connect(self.close_validation_review_mode)
        self.validation_review_gt_checkbox.toggled.connect(lambda _checked: self._draw_validation_review_overlay_on_main())
        self.validation_review_pred_checkbox.toggled.connect(lambda _checked: self._draw_validation_review_overlay_on_main())
        return dock

    def _clear_validation_review_overlay_on_main(self):
        scene = self.screen_view.scene() if getattr(self, "screen_view", None) is not None else None
        if scene is None:
            return
        for item in list(scene.items()):
            try:
                if item.data(0) == "darkfusion_validation_review":
                    scene.removeItem(item)
            except Exception:
                continue

    def _add_validation_review_graphic(self, item, color, tooltip=""):
        item.setData(0, "darkfusion_validation_review")
        item.setZValue(100000)
        item.setFlag(QGraphicsItem.ItemIsSelectable, False)
        item.setAcceptedMouseButtons(Qt.NoButton)
        item.setPen(QPen(color, 3))
        fill = QColor(color)
        fill.setAlpha(38)
        item.setBrush(QBrush(fill))
        if tooltip:
            item.setToolTip(tooltip)
        self.screen_view.scene().addItem(item)

    def _draw_validation_review_object_on_main(self, value, color, task, tooltip=""):
        if not isinstance(value, dict):
            return
        scene = self.screen_view.scene()
        width = max(1.0, float(scene.sceneRect().width()))
        height = max(1.0, float(scene.sceneRect().height()))
        points = [
            QPointF(float(point[0]) * width, float(point[1]) * height)
            for point in value.get("points", []) or []
            if isinstance(point, (list, tuple)) and len(point) >= 2
        ]
        if len(points) >= 3 and task in {"segment", "obb"}:
            self._add_validation_review_graphic(QGraphicsPolygonItem(QPolygonF(points)), color, tooltip)
        else:
            bounds = list(value.get("bbox", []) or [])
            if len(bounds) >= 4:
                rect = QRectF(
                    float(bounds[0]) * width,
                    float(bounds[1]) * height,
                    max(1.0, (float(bounds[2]) - float(bounds[0])) * width),
                    max(1.0, (float(bounds[3]) - float(bounds[1])) * height),
                )
                self._add_validation_review_graphic(QGraphicsRectItem(rect), color, tooltip)
        if task == "pose":
            radius = max(3.0, min(width, height) / 220.0)
            for point in value.get("keypoints", []) or []:
                if len(point) < 2 or (len(point) >= 3 and float(point[2]) <= 0):
                    continue
                ellipse = QGraphicsEllipseItem(
                    float(point[0]) * width - radius,
                    float(point[1]) * height - radius,
                    radius * 2,
                    radius * 2,
                )
                self._add_validation_review_graphic(ellipse, color, tooltip)

    def _draw_validation_review_overlay_on_main(self):
        self._clear_validation_review_overlay_on_main()
        issue = getattr(self, "validation_review_current_issue", None)
        if not isinstance(issue, dict) or getattr(self, "screen_view", None) is None:
            return
        scene = self.screen_view.scene()
        if scene is None:
            return
        task = str(issue.get("task", "detect") or "detect")
        issue_type = str(issue.get("type", "") or "")
        if getattr(self, "validation_review_gt_checkbox", None) is None or self.validation_review_gt_checkbox.isChecked():
            color = QColor("#ff9f43") if issue_type == "false_negative" else QColor("#45d483")
            self._draw_validation_review_object_on_main(
                issue.get("ground_truth"),
                color,
                task,
                "Validation ground truth",
            )
        if getattr(self, "validation_review_pred_checkbox", None) is None or self.validation_review_pred_checkbox.isChecked():
            color = QColor("#f0d264") if issue_type in {"weak_localization", "poor_keypoints"} else QColor("#ff5968")
            self._draw_validation_review_object_on_main(
                issue.get("prediction"),
                color,
                task,
                "Validation prediction",
            )
        scene.update()

    @staticmethod
    def _validation_review_issue_guidance(issue_type):
        return {
            "false_positive": (
                "Red is a model prediction with no matching saved segment. If the object is real, "
                "add or correct its dataset label. If it is not real, the saved label is fine and "
                "the model made the mistake."
            ),
            "false_negative": (
                "Orange is a saved dataset segment the model missed. Keep it when the label is "
                "correct; edit or remove it only when the saved annotation is wrong."
            ),
            "wrong_class": (
                "The prediction overlaps a saved annotation but uses a different class. Check and "
                "correct the dataset class only if the saved class is wrong."
            ),
            "weak_localization": (
                "The saved annotation and prediction match, but their shapes overlap poorly. "
                "Compare both outlines and refine the dataset segment only when necessary."
            ),
            "duplicate_prediction": (
                "The model predicted the same labeled object more than once. This is usually a "
                "model error; verify the saved dataset segment before changing it."
            ),
            "poor_keypoints": (
                "The predicted keypoints disagree with the saved keypoints. Inspect the saved "
                "points and move only those that are actually incorrect."
            ),
        }.get(str(issue_type or ""), "Compare the saved annotation with the model prediction before editing.")

    def _write_active_validation_review_report(self):
        path = self.normalize_path(getattr(self, "validation_review_report_path", ""))
        report = getattr(self, "validation_review_report", None)
        if not path or not isinstance(report, dict):
            return False
        temporary = f"{path}.tmp"
        try:
            with open(temporary, "w", encoding="utf-8") as handle:
                json.dump(report, handle, indent=2)
            os.replace(temporary, path)
            return True
        except Exception as e:
            logger.warning("Could not update validation review report %s: %s", path, e)
            return False

    def _show_validation_review_issue(self, index):
        issues = list(getattr(self, "validation_review_queue", []) or [])
        if not issues:
            return False
        index = max(0, min(len(issues) - 1, int(index)))
        issue = issues[index]
        image_path = self.normalize_path(issue.get("image_path", ""))
        if not image_path or not os.path.isfile(image_path):
            self.statusBar().showMessage(f"Review image is missing: {image_path}", 5000)
            return False
        self.validation_review_index = index
        self.validation_review_current_issue = issue
        self.current_file = image_path
        queue_images = list(getattr(self, "validation_review_image_files", []) or [])
        try:
            self.current_img_index = queue_images.index(image_path)
        except ValueError:
            self.current_img_index = 0
        self.display_image(image_path, rebuild_preview=True)
        self._draw_validation_review_overlay_on_main()
        dock = self._ensure_validation_review_dock()
        dock.show()
        issue_name = str(issue.get("type", "") or "").replace("_", " ").title()
        confidence = issue.get("confidence")
        overlap = issue.get("iou")
        details = [
            issue_name,
            f"Task: {issue.get('task', '')}",
            f"Class: {issue.get('class_name', '')}",
            f"Image: {os.path.basename(image_path)}",
            f"Label: {os.path.basename(str(issue.get('label_path', '') or ''))}",
        ]
        if confidence is not None:
            details.append(f"Confidence: {float(confidence):.3f}")
        if overlap is not None:
            details.append(f"Overlap: {float(overlap):.3f}")
        if issue.get("detail"):
            details.extend(["", str(issue.get("detail"))])
        details.extend(["", self._validation_review_issue_guidance(issue.get("type"))])
        self.validation_review_position_label.setText(f"Issue {index + 1} / {len(issues)}")
        self.validation_review_detail_label.setText("\n".join(details))
        self.statusBar().showMessage(f"Validation review: {issue_name}", 3000)
        return True

    def open_validation_review_issue_in_labeler(self, issue, report_path="", queue=None):
        if not isinstance(issue, dict):
            return False
        requested_image_path = self.normalize_path(issue.get("image_path", ""))
        if not requested_image_path or not os.path.isfile(requested_image_path):
            QMessageBox.warning(
                getattr(self, "training_evaluator_dialog", None) or self,
                "Validation Review Image Missing",
                (
                    "This report does not contain a usable dataset image path:\n\n"
                    f"{requested_image_path or '(empty path)'}\n\n"
                    "Run Analyze Errors again to rebuild the report with real dataset paths."
                ),
            )
            return False
        issues = [item for item in list(queue or []) if isinstance(item, dict)]
        if issue not in issues:
            issues.insert(0, issue)
        if not issues:
            return False
        if not isinstance(getattr(self, "_validation_review_restore_state", None), dict):
            self._validation_review_restore_state = {
                "image_files": list(getattr(self, "image_files", []) or []),
                "filtered_image_files": list(getattr(self, "filtered_image_files", []) or []),
                "current_file": getattr(self, "current_file", ""),
                "current_img_index": int(getattr(self, "current_img_index", 0) or 0),
                "image_directory": getattr(self, "image_directory", ""),
            }
        self.validation_review_queue = issues
        self.validation_review_report_path = self.normalize_path(report_path)
        try:
            with open(self.validation_review_report_path, "r", encoding="utf-8", errors="replace") as handle:
                self.validation_review_report = json.load(handle)
        except Exception:
            self.validation_review_report = {"issues": issues}
        self.validation_review_image_files = list(dict.fromkeys(
            self.normalize_path(item.get("image_path", ""))
            for item in issues
            if item.get("image_path") and os.path.isfile(self.normalize_path(item.get("image_path", "")))
        ))
        self.filtered_image_files = list(self.validation_review_image_files)
        self.update_list_view(self.filtered_image_files)
        target_id = str(issue.get("id", ""))
        target_index = next(
            (index for index, item in enumerate(issues) if str(item.get("id", "")) == target_id),
            0,
        )
        self._ensure_validation_review_dock()
        if not self._show_validation_review_issue(target_index):
            return False

        # The Training window is modeless but normally covers the main labeler.
        # Move it out of the way and explicitly focus the labeler so opening an
        # issue has an immediate, visible result.
        training_dialog = getattr(self, "training_evaluator_dialog", None)
        if training_dialog is not None and not sip.isdeleted(training_dialog):
            training_dialog.hide()
        if self.isMinimized():
            self.showNormal()
        else:
            self.show()
        self.raise_()
        self.activateWindow()
        dock = self._ensure_validation_review_dock()
        dock.show()
        dock.raise_()
        return True

    def navigate_validation_review_issue(self, offset):
        issues = list(getattr(self, "validation_review_queue", []) or [])
        if not issues:
            return False
        current = int(getattr(self, "validation_review_index", 0) or 0)
        return self._show_validation_review_issue(max(0, min(len(issues) - 1, current + int(offset))))

    def set_current_validation_review_status(self, status):
        issue = getattr(self, "validation_review_current_issue", None)
        if not isinstance(issue, dict):
            return False
        issue["review_status"] = str(status)
        report = getattr(self, "validation_review_report", {}) or {}
        issue_id = str(issue.get("id", ""))
        for saved_issue in report.get("issues", []) or []:
            if str(saved_issue.get("id", "")) == issue_id:
                saved_issue["review_status"] = str(status)
                break
        saved = self._write_active_validation_review_report()
        self.statusBar().showMessage(f"Validation issue marked {status}.", 2500)
        if saved:
            self.navigate_validation_review_issue(1)
        return saved

    def quarantine_current_validation_review_image(self):
        issue = getattr(self, "validation_review_current_issue", None)
        if not isinstance(issue, dict):
            return False
        image_path = self.normalize_path(issue.get("image_path", ""))
        if not image_path or not os.path.isfile(image_path):
            return False
        reply = QMessageBox.question(
            self,
            "Quarantine Image",
            (
                "Move this image and its matching label into a recoverable "
                "darkfusion_quarantine folder?\n\n"
                f"{image_path}"
            ),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if reply != QMessageBox.Yes:
            return False
        dataset_dir = self.normalize_path(getattr(self, "image_directory", "") or os.path.dirname(image_path))
        quarantine_dir = self.normalize_path(os.path.join(dataset_dir, "darkfusion_quarantine"))
        os.makedirs(quarantine_dir, exist_ok=True)
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")

        def unique_target(source):
            name = os.path.basename(source)
            candidate = os.path.join(quarantine_dir, name)
            if os.path.exists(candidate):
                stem, suffix = os.path.splitext(name)
                candidate = os.path.join(quarantine_dir, f"{stem}_{timestamp}{suffix}")
            return self.normalize_path(candidate)

        moved = []
        try:
            for source in (image_path, self._label_path_for_image(image_path)):
                if source and os.path.isfile(source):
                    target = unique_target(source)
                    shutil.move(source, target)
                    moved.append({"from": source, "to": target})
            manifest_path = os.path.join(quarantine_dir, "manifest.jsonl")
            with open(manifest_path, "a", encoding="utf-8") as handle:
                handle.write(json.dumps({
                    "at": datetime.now().isoformat(timespec="seconds"),
                    "issue_id": issue.get("id"),
                    "files": moved,
                }) + "\n")
        except Exception as e:
            QMessageBox.warning(self, "Quarantine Image", f"Could not quarantine the image:\n{e}")
            return False
        issue["review_status"] = "quarantined"
        issue["quarantined_files"] = moved
        self.set_current_validation_review_status("quarantined")
        return True

    def close_validation_review_mode(self):
        self._clear_validation_review_overlay_on_main()
        dock = getattr(self, "validation_review_dock", None)
        if dock is not None and not sip.isdeleted(dock):
            dock.hide()
        restore = getattr(self, "_validation_review_restore_state", None)
        if isinstance(restore, dict):
            self.image_files = list(restore.get("image_files", []) or [])
            self.filtered_image_files = list(restore.get("filtered_image_files", []) or [])
            self.image_directory = restore.get("image_directory", getattr(self, "image_directory", ""))
            self.update_list_view(self.filtered_image_files)
            previous_file = self.normalize_path(restore.get("current_file", ""))
            if previous_file and os.path.isfile(previous_file):
                self.current_file = previous_file
                self.current_img_index = int(restore.get("current_img_index", 0) or 0)
                self.display_image(previous_file, rebuild_preview=True)
        self._validation_review_restore_state = None
        self.validation_review_queue = []
        self.validation_review_current_issue = None
        self.statusBar().showMessage("Returned to the previous dataset view.", 2500)

    def open_training_evaluator_dialog(self):
        existing = getattr(self, "training_evaluator_dialog", None)
        if existing is not None and not sip.isdeleted(existing):
            existing.show()
            existing.raise_()
            existing.activateWindow()
            return

        dialog = QtWidgets.QDialog(self)
        dialog.setWindowTitle("Ultralytics Trainer / Exporter")
        dialog.setAttribute(Qt.WA_DeleteOnClose, True)
        dialog.setSizeGripEnabled(True)
        dialog.setMinimumSize(560, 420)
        dialog.resize(900, 660)
        if self.styleSheet():
            dialog.setStyleSheet(self.styleSheet())

        outer_layout = QtWidgets.QVBoxLayout(dialog)
        outer_layout.setContentsMargins(12, 12, 12, 12)
        outer_layout.setSpacing(8)

        body_scroll = QtWidgets.QScrollArea(dialog)
        body_scroll.setFrameShape(QtWidgets.QFrame.NoFrame)
        body_scroll.setWidgetResizable(True)
        body_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        body_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        body_scroll.setSizeAdjustPolicy(QtWidgets.QAbstractScrollArea.AdjustIgnored)
        body_scroll.setMinimumSize(0, 0)
        body_scroll.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Expanding)

        body_widget = QtWidgets.QWidget(body_scroll)
        body_widget.setMinimumSize(0, 0)
        body_widget.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Preferred)

        layout = QtWidgets.QVBoxLayout(body_widget)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(10)
        layout.setSizeConstraint(QtWidgets.QLayout.SetNoConstraint)

        title = QtWidgets.QLabel("Training")
        title.setStyleSheet("font-size: 15px; font-weight: 700;")
        layout.addWidget(title)

        controls = QtWidgets.QGridLayout()
        controls.setHorizontalSpacing(8)
        controls.setVerticalSpacing(8)

        restored_setup = self._training_eval_restore_last_run_setup()
        restored_args = restored_setup.get("args", {}) if isinstance(restored_setup, dict) else {}
        restored_checkpoint = self.normalize_path(restored_setup.get("checkpoint", ""))
        restored_data_yaml = self.normalize_path(restored_setup.get("data_yaml", ""))
        restored_run_dir = self.normalize_path(restored_setup.get("run_dir", ""))

        use_training_weights = QtWidgets.QCheckBox("Use Train Setup")
        use_training_weights.setChecked(True)
        use_training_weights.setToolTip("When checked, evaluation inspects the model selected in Train Setup.")
        eval_weights_edit = QtWidgets.QLineEdit(
            restored_checkpoint or self.settings.get("trainingEvaluatorWeightsPath", "")
        )
        eval_weights_edit.setPlaceholderText("Optional eval weights path")
        eval_weights_edit.setToolTip("Optional .pt or model .yaml used only for evaluator stride/task inspection.")
        browse_weights_btn = QtWidgets.QPushButton("Browse")

        current_model_path = self.normalize_path(
            restored_checkpoint
            or getattr(self, "model_config_path", None)
            or getattr(self, "pt_path", None)
            or self.settings.get("ultralyticsModelConfigPath", "")
            or self.settings.get("ultralyticsPtPath", "")
            or ""
        )
        current_pretrained_path = self.normalize_path(
            getattr(self, "pretrained_model_path", None)
            or self.settings.get("ultralyticsPretrainedModelPath", "")
            or ""
        )
        current_distill_path = self.normalize_path(
            getattr(self, "ultralytics_distill_model_path", None)
            or self.settings.get("ultralyticsDistillModelPath", "")
            or ""
        )
        current_data_yaml = self.normalize_path(
            restored_data_yaml
            or getattr(self, "data_yaml_path", None)
            or self.settings.get("ultralyticsDataYamlPath", "")
            or ""
        )
        if not current_data_yaml:
            current_data_yaml = self.autoload_training_data_yaml_for_dataset(self._training_eval_dataset_dir())
        current_runs_dir = self.normalize_path(
            restored_args.get("project", "")
            or (os.path.dirname(restored_run_dir) if restored_run_dir else "")
            or getattr(self, "runs_directory", "")
            or self.settings.get("ultralyticsRunsDirectory", "")
            or self._training_eval_project_dir()
        )

        setup_group = QtWidgets.QGroupBox("Train Setup")
        setup_layout = QtWidgets.QGridLayout(setup_group)
        setup_layout.setContentsMargins(10, 14, 10, 10)
        setup_layout.setHorizontalSpacing(8)
        setup_layout.setVerticalSpacing(8)

        data_yaml_edit = QtWidgets.QLineEdit(current_data_yaml)
        data_yaml_edit.setPlaceholderText("Dataset YAML")
        data_yaml_edit.setToolTip("Ultralytics data YAML used for training.")
        browse_data_yaml_btn = QtWidgets.QPushButton("YAML")
        browse_data_yaml_btn.setToolTip("Choose the training data YAML.")

        train_model_edit = QtWidgets.QLineEdit(current_model_path)
        train_model_edit.setPlaceholderText("Model .pt or model .yaml")
        train_model_edit.setToolTip("Choose a .pt model, or a model .yaml with optional pretrained weights.")
        browse_train_model_btn = QtWidgets.QPushButton("Model")
        browse_train_model_btn.setToolTip("Choose a .pt weights file or model .yaml.")

        pretrained_edit = QtWidgets.QLineEdit(current_pretrained_path)
        pretrained_edit.setPlaceholderText("Optional pretrained .pt for model YAML")
        pretrained_edit.setToolTip("Used only when the model field is a model .yaml.")
        browse_pretrained_btn = QtWidgets.QPushButton("Pretrained")
        browse_pretrained_btn.setToolTip("Choose pretrained weights for transfer learning from a model YAML.")
        clear_pretrained_btn = QtWidgets.QPushButton("Clear")
        clear_pretrained_btn.setToolTip("Clear optional pretrained transfer weights.")

        runs_dir_edit = QtWidgets.QLineEdit(current_runs_dir)
        runs_dir_edit.setPlaceholderText("Defaults to the dataset runs folder")
        runs_dir_edit.setToolTip("Optional run folder. Leave blank to use the active dataset's runs folder.")
        browse_runs_dir_btn = QtWidgets.QPushButton("Browse")
        browse_runs_dir_btn.setToolTip("Choose a custom runs folder, or leave blank for the dataset default.")

        current_size = self._parse_training_imgsz_value(
            restored_args.get(
                "imgsz",
                self.settings.get("trainingPreviewImgSize", self.settings.get("ultralyticsTrainImgSize", "640")),
            )
        )
        imgsz_spin = QtWidgets.QSpinBox()
        imgsz_spin.setRange(160, 2048)
        imgsz_spin.setSingleStep(32)
        imgsz_spin.setValue(current_size)
        imgsz_spin.setToolTip("Training image size used by evaluator commands.")

        def _setting_int_value(name, default, minimum=1, maximum=10000):
            try:
                value = int(float(str(self.settings.get(name, default)).strip()))
            except Exception:
                value = int(default)
            return max(int(minimum), min(int(maximum), value))

        train_batch_spin = QtWidgets.QSpinBox()
        train_batch_spin.setRange(1, 512)
        restored_batch = self._training_eval_int_value(restored_args.get("batch"), 0)
        train_batch_spin.setValue(
            max(1, min(512, restored_batch))
            if restored_batch > 0
            else _setting_int_value("ultralyticsTrainBatch", 8, 1, 512)
        )
        train_batch_spin.setToolTip("Requested training batch. DarkFusion still clamps unsafe values.")

        train_epochs_spin = QtWidgets.QSpinBox()
        train_epochs_spin.setRange(1, 10000)
        restored_epochs = self._training_eval_int_value(restored_args.get("epochs"), 0)
        train_epochs_spin.setValue(
            max(1, min(10000, restored_epochs))
            if restored_epochs > 0
            else _setting_int_value("ultralyticsTrainEpochs", 50, 1, 10000)
        )
        train_epochs_spin.setToolTip("Number of epochs for Start Training.")

        task_setup_combo = QtWidgets.QComboBox()
        for task_name in ("detect", "segment", "classify", "pose", "obb"):
            task_setup_combo.addItem(task_name)
        current_task = str(
            restored_setup.get("task", "")
            or (getattr(self, "task_combobox", None).currentText()
            if getattr(self, "task_combobox", None) is not None
            else self.settings.get("ultralyticsTask", "detect"))
        ).strip().lower()
        task_index = task_setup_combo.findText(current_task, Qt.MatchFixedString)
        task_setup_combo.setCurrentIndex(task_index if task_index >= 0 else 0)

        train_rect_checkbox = QtWidgets.QCheckBox("Rect")
        train_rect_checkbox.setChecked(bool(restored_args.get("rect", self.settings.get("ultralyticsRect", False))))
        train_rect_checkbox.setToolTip("Use rectangular training batches.")
        duplicate_labels_checkbox = QtWidgets.QCheckBox("Keep Duplicate Labels")
        duplicate_labels_checkbox.setChecked(bool(self.settings.get("ultralyticsKeepDuplicateLabels", False)))
        duplicate_labels_checkbox.setToolTip("Disable Ultralytics duplicate-label row removal through the DarkFusion wrapper.")

        distill_checkbox = QtWidgets.QCheckBox("Distill")
        distill_checkbox.setChecked(bool(self.settings.get("ultralyticsDistillEnabled", False)))
        distill_checkbox.setToolTip("Use Ultralytics Knowledge Distillation. Requires Ultralytics v8.4.77+ and a larger teacher .pt model.")
        distill_model_edit = QtWidgets.QLineEdit(current_distill_path)
        distill_model_edit.setPlaceholderText("Teacher model .pt, e.g. yolo26s.pt")
        distill_model_edit.setToolTip("Teacher model used as distill_model during training. Detect is benchmarked first; other tasks are supported by Ultralytics but less validated.")
        browse_distill_btn = QtWidgets.QPushButton("Teacher")
        browse_distill_btn.setToolTip("Choose a larger teacher .pt model for Knowledge Distillation.")
        clear_distill_btn = QtWidgets.QPushButton("Clear")
        clear_distill_btn.setToolTip("Disable and clear the teacher model.")
        distill_weight_spin = QtWidgets.QDoubleSpinBox()
        distill_weight_spin.setRange(0.0, 10.0)
        distill_weight_spin.setSingleStep(0.1)
        distill_weight_spin.setDecimals(2)
        distill_weight_spin.setValue(float(self.settings.get("ultralyticsDistillWeight", 6.0) or 6.0))
        distill_weight_spin.setMaximumWidth(82)
        distill_weight_spin.setToolTip("Ultralytics distillation loss weight, passed as dis=.")

        train_patience_checkbox = QtWidgets.QCheckBox("Patience")
        restored_patience = self._training_eval_int_value(restored_args.get("patience"), 0)
        train_patience_checkbox.setChecked(
            restored_patience > 0 or bool(self.settings.get("ultralyticsPatienceEnabled", False))
        )
        train_patience_spin = QtWidgets.QSpinBox()
        train_patience_spin.setRange(1, 10000)
        train_patience_spin.setValue(
            max(1, min(10000, restored_patience))
            if restored_patience > 0
            else _setting_int_value("ultralyticsPatience", 40, 1, 10000)
        )
        train_patience_spin.setToolTip("Early-stop patience.")

        train_freeze_checkbox = QtWidgets.QCheckBox("Freeze")
        restored_freeze = self._training_eval_int_value(restored_args.get("freeze"), 0)
        train_freeze_checkbox.setChecked(
            restored_freeze > 0 or bool(self.settings.get("ultralyticsFreezeEnabled", False))
        )
        train_freeze_spin = QtWidgets.QSpinBox()
        train_freeze_spin.setRange(0, 1000)
        train_freeze_spin.setValue(
            max(0, min(1000, restored_freeze))
            if restored_freeze > 0
            else _setting_int_value("ultralyticsFreeze", 0, 0, 1000)
        )
        train_freeze_spin.setToolTip("Freeze first N layers.")

        extra_args_edit = QtWidgets.QLineEdit(str(self.settings.get("ultralyticsExtraTrainArgs", "") or ""))
        extra_args_edit.setPlaceholderText("Optional extra Ultralytics args, e.g. cos_lr=True close_mosaic=10")
        extra_args_edit.setToolTip("Extra key=value args. Protected args like data/model/batch/amp/resume are ignored.")

        validation_mode_combo = QtWidgets.QComboBox()
        validation_mode_combo.setToolTip("Choose how evaluator-managed obj.yaml creates valid.txt.")
        validation_mode_combo.addItem("Auto Split", "auto")
        validation_mode_combo.addItem("Valid Folder", "folder")
        validation_mode_combo.addItem("Valid TXT", "txt")
        validation_mode_combo.addItem("Train as Val", "train")
        validation_mode_index = validation_mode_combo.findData(
            self._training_eval_validation_mode(self.settings.get("trainingEvaluatorValidationMode", "auto"))
        )
        validation_mode_combo.setCurrentIndex(validation_mode_index if validation_mode_index >= 0 else 0)

        validation_percent_combo = QtWidgets.QComboBox()
        validation_percent_combo.setToolTip("Percent of training images held out for valid.txt when Auto Split is used.")
        for percent_text in ("5%", "10%", "15%", "20%", "25%", "30%", "40%", "50%"):
            validation_percent_combo.addItem(percent_text)
        validation_percent_text = str(
            self.settings.get("trainingEvaluatorValidationPercent", self.settings.get("datasetValidPercent", "20%"))
            or "20%"
        )
        validation_percent_index = validation_percent_combo.findText(validation_percent_text, Qt.MatchFixedString)
        validation_percent_combo.setCurrentIndex(validation_percent_index if validation_percent_index >= 0 else 3)

        validation_source_edit = QtWidgets.QLineEdit(str(self.settings.get("trainingEvaluatorValidationSource", "") or ""))
        validation_source_edit.setPlaceholderText("Optional validation folder or valid.txt")
        validation_source_edit.setToolTip("Used only when Validation is set to Valid Folder or Valid TXT.")
        browse_validation_source_btn = QtWidgets.QPushButton("Source")
        browse_validation_source_btn.setToolTip("Choose validation folder or valid.txt.")
        validation_source_percent_combo = QtWidgets.QComboBox()
        validation_source_percent_combo.setToolTip("Percent of the selected validation source to write into valid.txt.")
        for percent_text in ("100%", "75%", "50%", "25%", "10%"):
            validation_source_percent_combo.addItem(percent_text)
        validation_source_percent_text = str(self.settings.get("trainingEvaluatorValidationSourcePercent", "100%") or "100%")
        validation_source_percent_index = validation_source_percent_combo.findText(validation_source_percent_text, Qt.MatchFixedString)
        validation_source_percent_combo.setCurrentIndex(validation_source_percent_index if validation_source_percent_index >= 0 else 0)

        for path_edit in (
            eval_weights_edit,
            data_yaml_edit,
            train_model_edit,
            pretrained_edit,
            runs_dir_edit,
            distill_model_edit,
            validation_source_edit,
            extra_args_edit,
        ):
            path_edit.setMinimumWidth(0)
            path_edit.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)

        data_row = self._row_layout(8)
        data_row.addWidget(data_yaml_edit, 1)
        data_row.addWidget(browse_data_yaml_btn)
        model_row = self._row_layout(8)
        model_row.addWidget(train_model_edit, 1)
        model_row.addWidget(browse_train_model_btn)
        pretrained_row = self._row_layout(8)
        pretrained_row.addWidget(pretrained_edit, 1)
        pretrained_row.addWidget(browse_pretrained_btn)
        pretrained_row.addWidget(clear_pretrained_btn)
        runs_row = self._row_layout(8)
        runs_row.addWidget(runs_dir_edit, 1)
        runs_row.addWidget(browse_runs_dir_btn)

        setup_layout.addWidget(QtWidgets.QLabel("Data"), 0, 0)
        setup_layout.addLayout(data_row, 0, 1, 1, 3)
        setup_layout.addWidget(QtWidgets.QLabel("Model"), 1, 0)
        setup_layout.addLayout(model_row, 1, 1, 1, 3)
        setup_layout.addWidget(QtWidgets.QLabel("Transfer"), 2, 0)
        setup_layout.addLayout(pretrained_row, 2, 1, 1, 3)
        setup_layout.addWidget(QtWidgets.QLabel("Runs"), 3, 0)
        setup_layout.addLayout(runs_row, 3, 1, 1, 3)
        setup_layout.addWidget(QtWidgets.QLabel("Task"), 4, 0)
        setup_layout.addWidget(task_setup_combo, 4, 1)
        setup_layout.addWidget(QtWidgets.QLabel("ImgSz"), 4, 2)
        setup_layout.addWidget(imgsz_spin, 4, 3)
        setup_layout.addWidget(QtWidgets.QLabel("Batch"), 5, 0)
        setup_layout.addWidget(train_batch_spin, 5, 1)
        setup_layout.addWidget(QtWidgets.QLabel("Epochs"), 5, 2)
        setup_layout.addWidget(train_epochs_spin, 5, 3)

        advanced_train_row = self._row_layout(8)
        advanced_train_row.addWidget(train_rect_checkbox)
        advanced_train_row.addWidget(duplicate_labels_checkbox)
        advanced_train_row.addWidget(train_patience_checkbox)
        advanced_train_row.addWidget(train_patience_spin)
        advanced_train_row.addWidget(train_freeze_checkbox)
        advanced_train_row.addWidget(train_freeze_spin)
        advanced_train_row.addStretch(1)
        setup_layout.addLayout(advanced_train_row, 6, 0, 1, 4)

        distill_row = self._row_layout(8)
        distill_row.addWidget(distill_checkbox)
        distill_row.addWidget(distill_model_edit, 1)
        distill_row.addWidget(browse_distill_btn)
        distill_row.addWidget(clear_distill_btn)
        distill_row.addWidget(QtWidgets.QLabel("dis"))
        distill_row.addWidget(distill_weight_spin)
        setup_layout.addWidget(QtWidgets.QLabel("KD"), 7, 0)
        setup_layout.addLayout(distill_row, 7, 1, 1, 3)

        setup_layout.addWidget(QtWidgets.QLabel("Extra"), 8, 0)
        setup_layout.addWidget(extra_args_edit, 8, 1, 1, 3)
        validation_row = self._row_layout(8)
        validation_row.addWidget(validation_mode_combo)
        validation_row.addWidget(validation_percent_combo)
        validation_row.addWidget(validation_source_edit, 1)
        validation_row.addWidget(browse_validation_source_btn)
        validation_row.addWidget(validation_source_percent_combo)
        setup_layout.addWidget(QtWidgets.QLabel("Valid"), 9, 0)
        setup_layout.addLayout(validation_row, 9, 1, 1, 3)
        setup_layout.setColumnStretch(1, 1)
        setup_layout.setColumnStretch(3, 1)
        layout.addWidget(setup_group)

        candidates_edit = QtWidgets.QLineEdit(str(self.settings.get("trainingEvaluatorCandidates", "320,416,512,640,832")))
        candidates_edit.setPlaceholderText("Candidate sizes, e.g. 320,416,512,640,832")
        candidates_edit.setMinimumWidth(0)
        candidates_edit.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
        always_preview_checkbox = QtWidgets.QCheckBox("Train View")
        always_preview_checkbox.setChecked(self.is_training_preview_always_on())
        always_preview_checkbox.setToolTip("Toggle read-only train-size preview while browsing images.")
        auto_yaml_checkbox = QtWidgets.QCheckBox("Auto YAML")
        auto_yaml_checkbox.setChecked(bool(self.settings.get("trainingEvaluatorAutoYaml", True)))
        auto_yaml_checkbox.setToolTip("If Data is empty, find or create obj.yaml for the current dataset. Existing Data YAML is preserved.")
        optimized_args_checkbox = QtWidgets.QCheckBox("Optimized Args")
        optimized_args_checkbox.setChecked(bool(self.settings.get("trainingEvaluatorUseOptimizedArgs", True)))
        optimized_args_checkbox.setToolTip("Apply evaluator-recommended optimizer, learning-rate, warmup, and scheduler args to training.")
        probe_epochs_spin = QtWidgets.QSpinBox()
        probe_epochs_spin.setRange(1, 20)
        probe_epochs_spin.setValue(int(self.settings.get("trainingEvaluatorProbeEpochs", 5) or 5))
        probe_epochs_spin.setToolTip("Epochs per Ultralytics tuning trial.")
        tune_iterations_spin = QtWidgets.QSpinBox()
        tune_iterations_spin.setRange(1, 300)
        tune_iterations_spin.setValue(int(self.settings.get("trainingEvaluatorTuneIterations", 10) or 10))
        tune_iterations_spin.setToolTip("Number of Ultralytics tuning trials. Total work is trials multiplied by epochs per trial.")
        ray_tune_checkbox = QtWidgets.QCheckBox("Ray Tune")
        ray_tune_checkbox.setChecked(bool(self.settings.get("trainingEvaluatorUseRayTune", False)))
        ray_tune_checkbox.setEnabled(self._ray_tune_available())
        ray_tune_checkbox.setToolTip(
            "Use Ultralytics Ray Tune. Install with: pip install \"ray[tune]\""
            if not self._ray_tune_available()
            else "Use Ray Tune instead of the built-in tuner. DarkFusion allocates one CUDA GPU per trial when available."
        )
        tune_distill_checkbox = QtWidgets.QCheckBox("Tune Distill")
        tune_distill_checkbox.setChecked(bool(self.settings.get("trainingEvaluatorTuneDistill", False)))
        tune_distill_checkbox.setToolTip(
            "Experimental: include the selected distill_model in each hyperparameter tuning trial. "
            "Usually tune first, then train with distillation."
        )
        batch_override_checkbox = QtWidgets.QCheckBox("Batch")
        batch_override_checkbox.setChecked(bool(self.settings.get("trainingEvaluatorBatchOverrideEnabled", False)))
        batch_override_checkbox.setToolTip(
            "Override evaluator batch. Training is clamped to DarkFusion's safety cap; validation is capped to 1."
        )
        batch_override_spin = QtWidgets.QSpinBox()
        batch_override_spin.setRange(1, 512)
        batch_override_spin.setValue(_setting_int_value("trainingEvaluatorBatchOverride", int(train_batch_spin.value()), 1, 512))
        batch_override_spin.setMaximumWidth(82)
        workers_override_checkbox = QtWidgets.QCheckBox("Set Workers")
        restored_workers_present = "workers" in restored_args and restored_args.get("workers") is not None
        workers_override_checkbox.setChecked(
            restored_workers_present or bool(self.settings.get("trainingEvaluatorWorkersOverrideEnabled", True))
        )
        workers_override_checkbox.setToolTip("Override Ultralytics dataloader workers. 0 is safest on Windows.")
        workers_override_spin = QtWidgets.QSpinBox()
        workers_override_spin.setRange(0, 32)
        restored_workers = self._training_eval_int_value(restored_args.get("workers"), 0)
        workers_override_spin.setValue(
            max(0, min(32, restored_workers))
            if restored_workers_present
            else int(self.settings.get("trainingEvaluatorWorkersOverride", 0 if sys.platform.startswith("win") else 2) or 0)
        )
        workers_override_spin.setMaximumWidth(70)
        cache_mode_combo = QtWidgets.QComboBox()
        cache_mode_combo.setToolTip("Dataset cache mode. Off is safest; RAM is fastest but can consume lots of memory.")
        cache_mode_combo.addItem("Cache Off", "off")
        cache_mode_combo.addItem("Cache RAM", "ram")
        cache_mode_combo.addItem("Cache Disk", "disk")
        restored_cache = restored_args.get("cache") if "cache" in restored_args else None
        if isinstance(restored_cache, str) and restored_cache.strip().lower() in {"disk", "ram"}:
            cache_mode = restored_cache.strip().lower()
        elif restored_cache is True:
            cache_mode = "ram"
        elif restored_cache is False:
            cache_mode = "off"
        else:
            cache_mode = str(self.settings.get("trainingEvaluatorCacheMode", "off")).lower()
        cache_index = cache_mode_combo.findData(cache_mode)
        cache_mode_combo.setCurrentIndex(cache_index if cache_index >= 0 else 0)

        controls.addWidget(QtWidgets.QLabel("Candidates"), 0, 0)
        controls.addWidget(candidates_edit, 0, 1)
