        tune_row.addWidget(tune_iterations_spin)
        tune_row.addWidget(ray_tune_checkbox)
        tune_row.addWidget(tune_distill_checkbox)
        tune_row.addStretch(1)
        controls.addLayout(tune_row, 1, 2)
        override_row = self._row_layout(8)
